// ========================================================================

function ensureDirectory(
    directory
) {
    try {
        fs.mkdirSync(
            directory,
            {
                recursive: true
            }
        );

        return true;
    } catch (error) {
        console.error(
            "[TürkAI] Klasör oluşturulamadı:",
            directory,
            error.message
        );

        return false;
    }
}


for (
    const directory
    of ALL_DIRECTORIES
) {
    ensureDirectory(
        directory
    );
}


