// ========================================================================
// 008 — SAFE ENV
// ========================================================================

function safeEnv(
    key,
    fallback = ""
) {
    try {
        const value =
            process.env[key];

        if (
            value ===
            undefined ||
            value ===
            null
        ) {
            return fallback;
        }

        return String(
            value
        );
    } catch {
        return fallback;
    }
}


// ========================================================================
// 009 — STRING HELPERS
// ========================================================================

function safeString(
    value,
    fallback = ""
) {
    if (
        value ===
        null ||
        value ===
        undefined
    ) {
        return fallback;
    }

    try {
        return String(
            value
        );
    } catch {
        return fallback;
    }
}


function cleanText(
    value,
    maxLength = 10000
) {
    return safeString(
        value
    )
        .replace(
            /\u0000/g,
            ""
        )
        .replace(
            /\r\n/g,
            "\n"
        )
        .slice(
            0,
            Math.max(
                1,
                maxLength
            )
        );
}


function normalizeText(
    value
) {
    return cleanText(
        value,
        100000
    )
        .normalize(
            "NFKC"
        )
        .toLocaleLowerCase(
            "tr-TR"
        )
        .replace(
            /\s+/g,
            " "
        )
        .trim();
}


function trimText(
    value,
    maxLength = 5000
) {
    return cleanText(
        value,
        maxLength
    ).trim();
}


// ========================================================================
// 010 — NUMBER HELPERS
// ========================================================================

function toNumber(
    value,
    fallback = 0
) {
    const number =
        Number(
            value
        );

    return Number.isFinite(
        number
    )
        ? number
        : fallback;
}


function clamp(
    value,
    minimum,
    maximum
) {
    const number =
        toNumber(
            value,
            minimum
        );

    return Math.min(
        Math.max(
            number,
            minimum
        ),
        maximum
    );
}


function toInteger(
    value,
    fallback = 0
) {
    return Math.trunc(
        toNumber(
            value,
            fallback
        )
    );
}


// ========================================================================
// 011 — BOOLEAN HELPERS
// ========================================================================

function toBoolean(
    value,
    fallback = false
) {
    if (
        typeof value ===
        "boolean"
    ) {
        return value;
    }

    if (
        typeof value ===
        "number"
    ) {
        return value !== 0;
    }

    const normalized =
        normalizeText(
            value
        );

    if (
        [
            "true",
            "1",
            "yes",
            "evet",
            "aktif",
            "on"
        ].includes(
            normalized
        )
    ) {
        return true;
    }

    if (
        [
            "false",
            "0",
            "no",
            "hayır",
            "pasif",
            "off"
        ].includes(
            normalized
        )
    ) {
        return false;
    }

    return fallback;
}


// ========================================================================
// 012 — ARRAY HELPERS
// ========================================================================

function ensureArray(
    value
) {
    return Array.isArray(
        value
    )
        ? value
        : [];
}


function uniqueArray(
    array
) {
    return [
        ...new Set(
            ensureArray(
                array
            )
        )
    ];
}


function chunkArray(
    array,
    size
) {
    const input =
        ensureArray(
            array
        );

    const result =
        [];

    const chunkSize =
        Math.max(
            1,
            toInteger(
                size,
                1
            )
        );

    for (
        let i = 0;
        i <
            input.length;
        i +=
            chunkSize
    ) {
        result.push(
            input.slice(
                i,
                i +
                    chunkSize
            )
        );
    }

    return result;
}


// ========================================================================
// 013 — OBJECT HELPERS
// ========================================================================

function clone(
    value
) {
    if (
        value ===
        undefined
    ) {
        return undefined;
    }

    try {
        return JSON.parse(
            JSON.stringify(
                value
            )
        );
    } catch {
        return value;
    }
}


function isObject(
    value
) {
    return Boolean(
        value &&
        typeof value ===
            "object" &&
        !Array.isArray(
            value
        )
    );
}


function mergeObjects(
    first,
    second
) {
    return {
        ...(isObject(first)
            ? first
            : {}),
        ...(isObject(second)
            ? second
            : {})
    };
}


// ========================================================================
// 014 — ID HELPERS
// ========================================================================

function createId(
    prefix = "id"
) {
    return (
        safeString(
            prefix,
            "id"
        )
        .replace(
            /[^a-zA-Z0-9_-]/g,
            ""
        ) +
        "_" +
        Date.now().toString(
            36
        ) +
        "_" +
        crypto
            .randomBytes(
                8
            )
            .toString(
                "hex"
            )
    );
}


function createShortId() {
    return crypto
        .randomBytes(
            8
        )
        .toString(
            "hex"
        );
}


// ========================================================================
// 015 — DATE HELPERS
// ========================================================================

function nowISO() {
    return new Date()
        .toISOString();
}


function nowTimestamp() {
    return Date.now();
}


function todayKey() {
    return new Date()
        .toLocaleDateString(
            "en-CA",
            {
                timeZone:
                    SERVER_TIMEZONE
            }
        );
}


function dateKey(
    date
) {
    const input =
        date
            ? new Date(
                date
            )
            : new Date();

    if (
        Number.isNaN(
            input.getTime()
        )
    ) {
        return todayKey();
    }

    return input
        .toLocaleDateString(
            "en-CA",
            {
                timeZone:
                    SERVER_TIMEZONE
            }
        );
}


// ========================================================================
// 016 — JSON READ
// ========================================================================

function readJSON(
    filePath,
    fallback = null
) {
    try {
        if (
            !fs.existsSync(
                filePath
            )
        ) {
            return clone(
                fallback
            );
        }

        const content =
            fs.readFileSync(
                filePath,
                "utf8"
            );

        if (
            !content.trim()
        ) {
            return clone(
                fallback
            );
        }

        return JSON.parse(
            content
        );
    } catch (error) {
        appendLog(
            ERROR_LOG_FILE,
            "[JSON_READ_ERROR] " +
                filePath +
                " :: " +
                error.message
        );

        return clone(
            fallback
        );
    }
}


// ========================================================================
// 017 — JSON WRITE
// ========================================================================

function writeJSON(
    filePath,
    value
) {
    try {
        ensureDirectory(
            path.dirname(
                filePath
            )
        );

        const temporary =
            filePath +
            ".tmp";

        const serialized =
            JSON.stringify(
                value,
                null,
                2
            );

        fs.writeFileSync(
            temporary,
            serialized,
            {
                encoding:
                    "utf8"
            }
        );

        fs.renameSync(
            temporary,
            filePath
        );

        return true;
    } catch (error) {
        appendLog(
            ERROR_LOG_FILE,
            "[JSON_WRITE_ERROR] " +
                filePath +
                " :: " +
                error.message
        );

        return false;
    }
}


// ========================================================================
// 018 — APPEND LOG
// ========================================================================

function appendLog(
    filePath,
    message
) {
    try {
        ensureDirectory(
            path.dirname(
                filePath
            )
        );

        const line =
            `[${nowISO()}] ${safeString(
                message
            )}\n`;

        fs.appendFileSync(
            filePath,
            line,
            {
                encoding:
                    "utf8"
            }
        );

        return true;
    } catch {
        return false;
    }
}


// ========================================================================
// 019 — SYSTEM LOG OBJECT
// ========================================================================

function systemLog(
    event,
    data = {}
) {
    const record = {
        id:
            createId(
                "log"
            ),

        event:
            safeString(
                event
            ),

        timestamp:
            nowISO(),

        data:
            clone(
                data
            )
    };

    appendLog(
        SYSTEM_LOG_FILE,
        JSON.stringify(
            record
        )
    );

    return record;
}


