// 028 — CORS
// ========================================================================

app.use(
    (
        req,
        res,
        next
    ) => {
        res.setHeader(
            "Access-Control-Allow-Origin",
            "*"
        );

        res.setHeader(
            "Access-Control-Allow-Headers",
            "Content-Type, Authorization, X-API-Key, X-TurkAI-Admin-Key, X-User-ID"
        );

        res.setHeader(
            "Access-Control-Allow-Methods",
            "GET, POST, PUT, PATCH, DELETE, OPTIONS"
        );

        if (
            req.method ===
            "OPTIONS"
        ) {
            return res
                .status(
                    204
                )
                .end();
        }

        next();
    }
);


