// ========================================================================
// 031 — REQUEST COUNTER
// ========================================================================

app.use(
    (
        req,
        res,
        next
    ) => {
        runtime.requests++;

        runtime.activeRequests++;

        const started =
            Date.now();

        res.on(
            "finish",
            () => {
                runtime.activeRequests =
                    Math.max(
                        0,
                        runtime.activeRequests -
                            1
                    );

                const duration =
                    Date.now() -
                    started;

                if (
                    res.statusCode >=
                    200 &&
                    res.statusCode <
                    400
                ) {
                    runtime.successfulRequests++;
                } else {
                    runtime.failedRequests++;
                }

                if (
                    req.url
                ) {
                    appendLog(
                        SYSTEM_LOG_FILE,
                        JSON.stringify(
                            {
                                requestId:
                                    req.turkaiRequestId,

                                method:
                                    req.method,

                                path:
                                    req.originalUrl,

                                status:
                                    res.statusCode,

                                duration
                            }
                        )
                    );
                }
            }
        );

        next();
    }
);


