// ========================================================================
// 034 — USER NORMALIZATION
// ========================================================================

function normalizeUserId(
    userId
) {
    const value =
        safeString(
            userId
        )
            .trim()
            .slice(
                0,
                200
            );

    return (
        value ||
        "guest"
    );
}


// ========================================================================
// 035 — SAFE USER NAME
// ========================================================================

function normalizeUserName(
    name
) {
    const value =
        cleanText(
            name,
            200
        )
            .replace(
                /\s+/g,
                " "
            )
            .trim();

    return (
        value ||
        "TürkAI Kullanıcısı"
    );
}


// ========================================================================
// 036 — DEFAULT USER
// ========================================================================

function createDefaultUser(
    userId,
    name = ""
) {
    const normalizedId =
        normalizeUserId(
            userId
        );

    return {
        id:
            normalizedId,

        name:
            normalizeUserName(
                name
            ),

        plan:
            "free",

        language:
            "tr",

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        active:
            true,

        messageCount:
            0,

        memoryCount:
            0
    };
}


// ========================================================================
// 037 — ENSURE USER
// ========================================================================

function ensureUser(
    userId,
    name = ""
) {
    const id =
        normalizeUserId(
            userId
        );

    if (
        !users[id]
    ) {
        users[id] =
            createDefaultUser(
                id,
                name
            );

        writeJSON(
            USERS_FILE,
            users
        );
    }

    if (
        name &&
        normalizeUserName(
            name
        ) !==
            users[id].name
    ) {
        users[id].name =
            normalizeUserName(
                name
            );

        users[id].updatedAt =
            nowISO();

        writeJSON(
            USERS_FILE,
            users
        );
    }

    return users[id];
}


// ========================================================================
// 038 — USER GET
// ========================================================================

function getUser(
    userId
) {
    return ensureUser(
        userId
    );
}


// ========================================================================
// 039 — SESSION ID
// ========================================================================

function normalizeSessionId(
    sessionId
) {
    const value =
        safeString(
            sessionId
        )
            .replace(
                /[^a-zA-Z0-9_-]/g,
                ""
            )
            .slice(
                0,
                150
            );

    return (
        value ||
        createId(
            "session"
        )
    );
}


// ========================================================================
// 040 — CREATE SESSION
// ========================================================================

function createSession(
    userId,
    title = "Yeni sohbet"
) {
    const normalizedUser =
        normalizeUserId(
            userId
        );

    ensureUser(
        normalizedUser
    );

    const sessionId =
        createId(
            "session"
        );

    const session = {
        id:
            sessionId,

        userId:
            normalizedUser,

        title:
            cleanText(
                title,
                200
            ),

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        messages:
            [],

        messageCount:
            0
    };

    sessions[
        sessionId
    ] =
        session;

    writeJSON(
        SESSIONS_FILE,
        sessions
    );

    return session;
}


// ========================================================================
// 041 — GET SESSION
// ========================================================================

function getSession(
    sessionId,
    userId
) {
    const id =
        normalizeSessionId(
            sessionId
        );

    const session =
        sessions[id];

    if (
        !session
    ) {
        return null;
    }

    if (
        session.userId !==
        normalizeUserId(
            userId
        )
    ) {
        return null;
    }

    return session;
}


