// ========================================================================
// 098 — SOCKET FOUNDATION
// ========================================================================

if (
    io
) {
    io.on(
        "connection",
        socket => {
            runtime.activeSockets++;

            socket.turkai =
                {
                    connectedAt:
                        nowISO(),

                    userId:
                        "guest"
                };

            socket.emit(
                "turkai:connected",
                {
                    success:
                        true,

                    server:
                        SERVER_NAME,

                    version:
                        SERVER_VERSION
                }
            );

            socket.on(
                "turkai:identify",
                payload => {
                    const userId =
                        normalizeUserId(
                            payload &&
                            payload.userId
                        );

                    ensureUser(
                        userId,
                        payload &&
                        payload.name
                    );

                    socket.turkai
                        .userId =
                        userId;

                    try {
                        socket.join(
                            `turkai:user:${userId}`
                        );
                    } catch {
                        // devam
                    }

                    socket.emit(
                        "turkai:identified",
                        {
                            success:
                                true,

                            userId
                        }
                    );
                }
            );

            socket.on(
                "turkai:memory:search",
                payload => {
                    const result =
                        searchAnswerMemory(
                            payload &&
                            payload.userId ||
                                "guest",
                            payload &&
                            payload.question ||
                                "",
                            {
                                limit:
                                    payload &&
                                    payload.limit
                            }
                        );

                    socket.emit(
                        "turkai:memory:result",
                        result
                    );
                }
            );

            socket.on(
                "turkai:memory:save",
                payload => {
                    const result =
                        saveAnswerToMemory(
                            payload &&
                            payload.userId ||
                                "guest",
                            payload &&
                            payload.question ||
                                "",
                            payload &&
                            payload.answer ||
                                "",
                            payload ||
                                {}
                        );

                    socket.emit(
                        "turkai:memory:saved",
                        result
                    );
                }
            );

            socket.on(
                "disconnect",
                () => {
                    runtime.activeSockets =
                        Math.max(
                            0,
                            runtime.activeSockets -
                                1
                        );
                }
            );
        }
    );
}


