// ========================================================================
// 208 — PROVIDER COOLDOWN HELPER
// ========================================================================

function isAIProviderAvailable2(
    providerId
) {
    const provider =
        AI_PROVIDERS_2[
            providerId
        ];

    if (!provider) {
        return false;
    }

    if (
        !provider.enabled
    ) {
        return false;
    }

    if (
        Number(
            provider.cooldownUntil
        ) >
        Date.now()
    ) {
        return false;
    }

    if (
        provider.type !==
        "local" &&
        !provider.apiKey
    ) {
        return false;
    }

    return true;
}


// ========================================================================
// 209 — PROVIDER COOLDOWN
// ========================================================================

function cooldownAIProvider2(
    providerId,
    milliseconds =
        30000
) {
    const provider =
        AI_PROVIDERS_2[
            providerId
        ];

    if (!provider) {
        return;
    }

    provider.cooldownUntil =
        Date.now() +
        Math.max(
            1000,
            Number(
                milliseconds
            ) || 30000
        );
}


// ========================================================================
// 210 — PROVIDER METRICS
// ========================================================================

function getAIProviderMetrics2(
    providerId
) {
    const provider =
        AI_PROVIDERS_2[
            providerId
        ];

    if (!provider) {
        return null;
    }

    const averageLatency =
        provider.successes
            ? provider.latencyTotal /
                provider.successes
            : 0;

    return {
        id:
            provider.id,

        name:
            provider.name,

        enabled:
            provider.enabled,

        available:
            isAIProviderAvailable2(
                provider.id
            ),

        model:
            provider.model,

        requests:
            provider.requests,

        successes:
            provider.successes,

        failures:
            provider.failures,

        averageLatencyMS:
            Math.round(
                averageLatency
            ),

        cooldownUntil:
            provider.cooldownUntil
                ? new Date(
                    provider.cooldownUntil
                ).toISOString()
                : null,

        lastError:
            provider.lastError,

        lastSuccessAt:
            provider.lastSuccessAt,

        lastFailureAt:
            provider.lastFailureAt
    };
}


// ========================================================================
// 211 — ALL PROVIDER METRICS
// ========================================================================

function getAllAIProviderMetrics2() {
    return Object.keys(
        AI_PROVIDERS_2
    ).map(
        getAIProviderMetrics2
    );
}


