// ========================================================================
// 213 — LANGUAGE DETECTION
// ========================================================================

function detectLanguageAI2(
    text
) {
    const raw =
        safeString(
            text
        );

    if (!raw.trim()) {
        return "tr";
    }

    const value =
        normalizeText(
            raw
        );

    const score =
        {};

    for (
        const language
        of Object.keys(
            AI_LANGUAGE_SIGNATURES_2
        )
    ) {
        score[language] =
            0;
    }

    for (
        const [
            language,
            signatures
        ]
        of Object.entries(
            AI_LANGUAGE_SIGNATURES_2
        )
    ) {
        for (
            const signature
            of signatures
        ) {
            const normalizedSignature =
                normalizeText(
                    signature
                );

            if (
                value.includes(
                    normalizedSignature
                )
            ) {
                score[language]++;
            }
        }
    }

    if (
        /[ğüşçıöİı]/i.test(
            raw
        )
    ) {
        score.tr +=
            5;
    }

    if (
        /[а-яё]/i.test(
            raw
        )
    ) {
        score.ru +=
            10;
    }

    if (
        /[\u0600-\u06ff]/.test(
            raw
        )
    ) {
        score.ar +=
            10;
    }

    let selected =
        "tr";

    let selectedScore =
        score.tr || 0;

    for (
        const [
            language,
            valueScore
        ]
        of Object.entries(
            score
        )
    ) {
        if (
            valueScore >
            selectedScore
        ) {
            selected =
                language;

            selectedScore =
                valueScore;
        }
    }

    return selected;
}


