// ========================================================================
// 217 — INTENT DETECTION
// ========================================================================

function detectIntentAI2(
    text
) {
    const raw =
        safeString(
            text
        );

    const value =
        normalizeText(
            raw
        );

    if (!value) {
        return {
            intent:
                "empty",

            confidence:
                1,

            current:
                false,

            research:
                false,

            coding:
                false,

            math:
                false
        };
    }

    const hasAny =
        patterns =>
            patterns.some(
                pattern =>
                    value.includes(
                        normalizeText(
                            pattern
                        )
                    )
            );

    const current =
        hasAny(
            AI_CURRENT_KEYWORDS_2
        );

    const research =
        hasAny(
            AI_RESEARCH_KEYWORDS_2
        );

    const coding =
        hasAny(
            AI_CODING_KEYWORDS_2
        );

    let intent =
        "general";

    let confidence =
        0.55;

    if (
        coding
    ) {
        intent =
            "coding";

        confidence =
            0.96;
    } else if (
        current &&
        (
            research ||
            value.length >
                25
        )
    ) {
        intent =
            "current";

        confidence =
            0.92;
    } else if (
        research
    ) {
        intent =
            "research";

        confidence =
            0.92;
    } else if (
        hasAny(
            [
                "hava durumu",
                "hava nasıl",
                "kaç derece",
                "sıcaklık",
                "yağmur",
                "kar yağacak",
                "weather"
            ]
        )
    ) {
        intent =
            "weather";

        confidence =
            0.96;
    } else if (
        hasAny(
            [
                "dolar",
                "euro",
                "sterlin",
                "döviz",
                "kur",
                "usd",
                "eur",
                "gbp",
                "kaç tl"
            ]
        )
    ) {
        intent =
            "currency";

        confidence =
            0.95;
    } else if (
        hasAny(
            [
                "altın",
                "gram altın",
                "ons altın",
                "gold"
            ]
        )
    ) {
        intent =
            "gold";

        confidence =
            0.95;
    } else if (
        hasAny(
            [
                "merhaba",
                "selam",
                "sa",
                "naber",
                "hey"
            ]
        )
    ) {
        intent =
            "greeting";

        confidence =
            0.98;
    } else if (
        hasAny(
            [
                "sen kimsin",
                "adın ne",
                "hangi yapay zeka",
                "hangi modelsin",
                "ne yapabiliyorsun"
            ]
        )
    ) {
        intent =
            "identity";

        confidence =
            0.98;
    } else if (
        hasAny(
            [
                "teşekkür",
                "sağ ol",
                "eyvallah",
                "thanks"
            ]
        )
    ) {
        intent =
            "thanks";

        confidence =
            0.98;
    } else if (
        hasAny(
            [
                "görüşürüz",
                "hoşça kal",
                "bay bay",
                "bye"
            ]
        )
    ) {
        intent =
            "farewell";

        confidence =
            0.98;
    } else if (
        hasAny(
            [
                "yardım",
                "yardımcı ol",
                "nasıl kullanılır",
                "özelliklerin"
            ]
        )
    ) {
        intent =
            "help";

        confidence =
            0.93;
    }

    return {
        intent,

        confidence,

        current,

        research,

        coding,

        math:
            isSimpleMathAI2(
                raw
            )
    };
}


// ========================================================================
// 218 — CURRENT QUESTION
// ========================================================================

function isCurrentQuestionAI2(
    text
) {
    const value =
        normalizeText(
            text
        );

    if (!value) {
        return false;
    }

    for (
        const keyword
        of AI_CURRENT_KEYWORDS_2
    ) {
        if (
            value.includes(
                normalizeText(
                    keyword
                )
            )
        ) {
            return true;
        }
    }

    if (
        /\b\d{1,2}[./-]\d{1,2}[./-]\d{2,4}\b/
            .test(
                value
            )
    ) {
        return true;
    }

    if (
        /\b(?:19|20)\d{2}\b/.test(
            value
        ) &&
        /\b(?:fiyat|sonuç|haber|durum|başkan|bakan|kur|skor)\b/i
            .test(
                value
            )
    ) {
        return true;
    }

    return false;
}


