// ========================================================================

function estimateAITokens2(
    text
) {
    const value =
        safeString(
            text
        );

    if (!value) {
        return 0;
    }

    return Math.max(
        1,
        Math.ceil(
            value.length /
            4
        )
    );
}


// ========================================================================
// 228 — CHAT CACHE KEY
// ========================================================================

function createAIChatCacheKey2(
    options = {}
) {
    const source = {
        userId:
            normalizeUserId(
                options.userId ||
                "guest"
            ),

        message:
            normalizeText(
                options.message ||
                ""
            ),

        language:
            safeString(
                options.language ||
                "tr"
            ),

        model:
            safeString(
                options.model ||
                ""
            ),

        system:
            safeString(
                options.system ||
                ""
            ),

        history:
            ensureArray(
                options.history
            )
                .slice(
                    -10
                )
                .map(
                    item => ({
                        role:
                            item.role,

                        content:
                            normalizeText(
                                item.content
                            )
                    })
                )
    };

    return crypto
        .createHash(
            "sha256"
        )
        .update(
            JSON.stringify(
                source
            ),
            "utf8"
        )
        .digest(
            "hex"
        );
}


// ========================================================================
// 229 — GET CACHE
// ========================================================================

function getAIChatCache2(
    key
) {
    const cached =
        AI_CACHE_2.get(
            key
        );

    if (!cached) {
        AI_STATE_2
            .cacheMisses++;

        return null;
    }

    if (
        Date.now() -
        cached.createdAt >
        AI_CONFIG_2.cacheTTLMS
    ) {
        AI_CACHE_2.delete(
            key
        );

        AI_STATE_2
            .cacheMisses++;

        return null;
    }

    AI_STATE_2
        .cacheHits++;

    return cached;
}


// ========================================================================
// 230 — SET CACHE
// ========================================================================

function setAIChatCache2(
    key,
    value
) {
    if (
        AI_CACHE_2.size >=
        AI_CONFIG_2.maxCacheEntries
    ) {
        const oldest =
            AI_CACHE_2.keys()
                .next()
                .value;

        if (
            oldest
        ) {
            AI_CACHE_2.delete(
                oldest
            );
        }
    }

    AI_CACHE_2.set(
        key,
        {
            ...clone(
                value
            ),

            createdAt:
                Date.now()
        }
    );
}


// ========================================================================
// 231 — USER CHAT SESSION
// ========================================================================

function getOrCreateAISession2(
    userId,
    sessionId
) {
    const normalizedUser =
        normalizeUserId(
            userId
        );

    const requestedId =
        sessionId
            ? normalizeSessionId(
                sessionId
            )
            : null;

    if (
        requestedId
    ) {
        const existing =
            getSession(
                requestedId,
                normalizedUser
            );

        if (
            existing
        ) {
            AI_SESSION_CACHE_2.set(
                requestedId,
                existing
            );

            return existing;
        }
    }

    const session =
        createSession(
            normalizedUser,
            "Yeni sohbet"
        );

    AI_SESSION_CACHE_2.set(
        session.id,
        session
    );

    return session;
}


