// 232 — SESSION HISTORY
// ========================================================================

function getAISessionHistory2(
    session
) {
    if (
        !session
    ) {
        return [];
    }

    return ensureArray(
        session.messages
    )
        .slice(
            -AI_CONFIG_2
                .maxHistoryMessages
        )
        .map(
            message => ({
                role:
                    safeString(
                        message.role ||
                        "user"
                    ),

                content:
                    cleanText(
                        message.content ||
                        "",
                        12000
                    )
            })
        );
}


// ========================================================================
// 233 — ADD CHAT MESSAGE
// ========================================================================

function addAISessionMessage2(
    session,
    role,
    content,
    metadata = {}
) {
    if (
        !session
    ) {
        return null;
    }

    const message = {
        id:
            createId(
                "chatmsg"
            ),

        role:
            safeString(
                role ||
                "user"
            ),

        content:
            cleanText(
                content,
                30000
            ),

        createdAt:
            nowISO(),

        metadata:
            clone(
                metadata
            )
    };

    if (
        !Array.isArray(
            session.messages
        )
    ) {
        session.messages =
            [];
    }

    session.messages.push(
        message
    );

    if (
        session.messages.length >
        200
    ) {
        session.messages =
            session.messages.slice(
                -200
            );
    }

    session.messageCount =
        session.messages.length;

    session.updatedAt =
        nowISO();

    sessions[
        session.id
    ] =
        session;

    writeJSON(
        SESSIONS_FILE,
        sessions
    );

    AI_SESSION_CACHE_2.set(
        session.id,
        session
    );

    return message;
}


// ========================================================================
// 234 — SYSTEM PROMPT
// ========================================================================

function buildAISystemPrompt2(
    options = {}
) {
    const language =
        safeString(
            options.language ||
            "tr"
        );

    const coding =
        Boolean(
            options.coding
        );

    const research =
        Boolean(
            options.research
        );

    const userName =
        safeString(
            options.userName
        );

    const base = [
        "Sen TürkAI adlı yapay zeka sistemisin.",
        "Kullanıcıya doğal, anlaşılır ve yararlı cevaplar ver.",
        "Kullanıcının dilini mümkün olduğunca koru.",
        `Yanıt dili: ${language}.`,
        "Bilmediğin bilgileri uydurma.",
        "Güncel bilgi gerekiyorsa araştırma motorunun kullanılmasına izin ver.",
        "Kod istendiğinde çalışabilir ve düzenli kod üret.",
        "Güvenlik açısından şüpheli veya zararlı işlemleri kolaylaştırma.",
        "Gereksiz tekrar yapma.",
        "Kullanıcının sorusuna doğrudan cevap ver."
    ];

    if (
        userName
    ) {
        base.push(
            `Kullanıcının adı: ${userName}.`
        );
    }

    if (
        coding
    ) {
        base.push(
            "Bu konuşmada kodlama bağlamı aktif.",
            "Kod verirken gerekli dosya ve yerleştirme bilgisini açık yaz.",
            "Kod içinde gereksiz sahte özellik üretme."
        );
    }

    if (
        research
    ) {
        base.push(
            "Bu konuşmada güncel/araştırma bağlamı aktif.",
            "Kaynaklardan gelen veriler ile model bilgisini birbirine karıştırma."
        );
    }

    return base.join(
        "\n"
    );
}


// ========================================================================
// 235 — CONTEXT BUILDER
// ========================================================================

function buildAIContext2(
    options = {}
) {
    const contextParts =
        [];

    const memoryResult =
        options.memoryResult;

    if (
        memoryResult &&
        memoryResult.hit &&
        memoryResult.answer
    ) {
        contextParts.push(
            "İlgili önceki cevap:",
            cleanText(
                memoryResult.answer,
                12000
            )
        );
    }

    const externalContext =
        safeString(
            options.externalContext
        );

    if (
        externalContext
    ) {
        contextParts.push(
            "Harici bağlam:",
            cleanText(
                externalContext,
                20000
            )
        );
    }

    const fileContext =
        safeString(
            options.fileContext
        );

    if (
        fileContext
    ) {
        contextParts.push(
            "Dosya bağlamı:",
            cleanText(
                fileContext,
                20000
            )
        );
    }

    if (
        !contextParts.length
    ) {
        return "";
    }

    return contextParts.join(
        "\n"
    );
}


// ========================================================================
// 236 — BUILD MESSAGES
// ========================================================================

function buildAIProviderMessages2(
    options = {}
) {
    const messages =
        [];

    messages.push({
        role:
            "system",

        content:
            buildAISystemPrompt2(
                options
            )
    });

    const context =
        buildAIContext2(
            options
        );

    if (
        context
    ) {
        messages.push({
            role:
                "system",

            content:
                context
        });
    }

    const history =
        ensureArray(
            options.history
        )
            .slice(
                -AI_CONFIG_2
                    .maxHistoryMessages
            );

    for (
        const item
        of history
    ) {
        const role =
            [
                "system",
                "user",
                "assistant"
            ].includes(
                safeString(
                    item.role
                )
            )
                ? item.role
                : "user";

        const content =
            cleanText(
                item.content ||
                "",
                12000
            );

        if (
            !content
        ) {
            continue;
        }

        messages.push({
            role,
            content
        });
    }

    messages.push({
        role:
            "user",

        content:
            cleanText(
                options.message ||
                "",
                12000
            )
    });

    return messages;
}


// ========================================================================
// 237 — GENERIC FETCH WITH TIMEOUT
// ========================================================================

async function aiFetch2(
    url,
    options = {},
    timeout =
        AI_CONFIG_2.providerTimeoutMS
) {
    const controller =
        new AbortController();

    const timer =
        setTimeout(
            () => {
                controller.abort();
            },
            timeout
        );

    const started =
        Date.now();

    try {
        const response =
            await fetch(
                url,
                {
                    ...options,
                    signal:
                        controller.signal
                }
            );

        return {
            response,

            latency:
                Date.now() -
                started
        };
    } finally {
        clearTimeout(
            timer
        );
    }
}


// ========================================================================
// 238 — OPENAI COMPATIBLE PROVIDER
// ========================================================================

async function callOpenAICompatibleAI2(
    providerId,
    messages,
    options = {}
) {
    const provider =
        AI_PROVIDERS_2[
            providerId
        ];

    if (
        !provider
    ) {
        throw new Error(
            "provider_not_found"
        );
    }

    if (
        !isAIProviderAvailable2(
            providerId
        )
    ) {
        throw new Error(
            "provider_unavailable"
        );
    }

    provider.requests++;

    AI_STATE_2
        .providerCalls++;

    const started =
        Date.now();

    try {
        const headers = {
            "Content-Type":
                "application/json",

            Authorization:
                `Bearer ${provider.apiKey}`
        };

        if (
            providerId ===
            "openrouter"
        ) {
            headers[
                "HTTP-Referer"
            ] =
                process.env
                    .TURKAI_SITE_URL ||
                "https://turkai-6.onrender.com";

            headers[
                "X-Title"
            ] =
                "TürkAI";
        }

        const body = {
            model:
                options.model ||
                provider.model,

            messages,

            temperature:
                Number(
                    options.temperature ??
                    AI_CONFIG_2.temperature
                ),

            top_p:
                Number(
                    options.topP ??
                    AI_CONFIG_2.topP
                ),

            max_tokens:
                Number(
                    options.maxTokens ||
                    4096
                )
        };

        const result =
            await aiFetch2(
                provider.endpoint,
                {
                    method:
                        "POST",

                    headers,

                    body:
                        JSON.stringify(
                            body
                        )
                }
            );

        const response =
            result.response;

        const text =
            await response
                .text();

        if (
            !response.ok
        ) {
            provider.failures++;

            provider.lastFailureAt =
                nowISO();

            provider.lastError =
                cleanText(
                    text,
                    2000
                );

            AI_STATE_2
                .providerFailures++;

            if (
                response.status ===
                    401 ||
                response.status ===
                    403
            ) {
                cooldownAIProvider2(
                    providerId,
                    5 *
                    60 *
                    1000
                );
            } else if (
                response.status ===
                    429
            ) {
                cooldownAIProvider2(
                    providerId,
                    60 *
                    1000
                );
            }

            throw new Error(
                `${providerId}_http_${response.status}`
            );
        }

        let data;

        try {
            data =
                JSON.parse(
                    text
                );
        } catch {
            throw new Error(
                `${providerId}_invalid_json`
            );
        }

        const content =
            data &&
            data.choices &&
            data.choices[0] &&
            data.choices[0].message &&
            data.choices[0].message.content;

        const answer =
            cleanAIResponse2(
                content
            );

        if (
            !answer
        ) {
            throw new Error(
                `${providerId}_empty_response`
            );
        }

        provider.successes++;

        provider.latencyTotal +=
            Date.now() -
            started;

        provider.lastSuccessAt =
            nowISO();

        provider.lastError =
            null;

        AI_STATE_2
            .providerSuccesses++;

        return {
            success:
                true,

            provider:
                providerId,

            model:
                body.model,

            answer,

            usage:
                data.usage ||
                null,

            raw:
                {
                    id:
                        data.id ||
                        null,

                    object:
                        data.object ||
                        null,

                    finishReason:
                        data.choices &&
                        data.choices[0] &&
                        data.choices[0]
                            .finish_reason ||
                        null
                },

            latency:
                Date.now() -
                started
        };
    } catch (
        error
    ) {
        provider.latencyTotal +=
            Date.now() -
            started;

        throw error;
    }
}


// ========================================================================
// 239 — GEMINI PROVIDER
// ========================================================================

async function callGeminiAI2(
    messages,
    options = {}
) {
    const provider =
        AI_PROVIDERS_2.gemini;

    if (
        !isAIProviderAvailable2(
            "gemini"
        )
    ) {
        throw new Error(
            "gemini_unavailable"
        );
    }

    provider.requests++;

    AI_STATE_2
        .providerCalls++;

    const model =
        options.model ||
        provider.model;

    const endpoint =
        `${provider.endpoint}/models/${encodeURIComponent(
            model
        )}:generateContent?key=${encodeURIComponent(
            provider.apiKey
        )}`;

    const contents =
        [];

    let systemText =
        "";

    for (
        const message
        of messages
    ) {
        if (
            message.role ===
            "system"
        ) {
            systemText +=
                cleanText(
                    message.content,
                    15000
                ) +
                "\n";

            continue;
        }

        contents.push({
            role:
                message.role ===
                "assistant"
                    ? "model"
                    : "user",

            parts: [
                {
                    text:
                        cleanText(
                            message.content,
                            12000
                        )
                }
            ]
        });
    }

    const body = {
        contents,

        generationConfig: {
            temperature:
                Number(
                    options.temperature ??
                    AI_CONFIG_2.temperature
                ),

            topP:
                Number(
                    options.topP ??
                    AI_CONFIG_2.topP
                ),

            maxOutputTokens:
                Number(
                    options.maxTokens ||
                    4096
                )
        }
    };

    if (
        systemText
    ) {
        body.systemInstruction = {
            parts: [
                {
                    text:
                        systemText
                }
            ]
        };
    }

    const started =
        Date.now();

    try {
        const result =
            await aiFetch2(
                endpoint,
                {
                    method:
                        "POST",

                    headers: {
                        "Content-Type":
                            "application/json"
                    },

                    body:
                        JSON.stringify(
                            body
                        )
                }
            );

        const response =
            result.response;

        const text =
            await response
                .text();

        if (
            !response.ok
        ) {
            provider.failures++;

            provider.lastFailureAt =
                nowISO();

            provider.lastError =
                cleanText(
                    text,
                    2000
                );

            AI_STATE_2
                .providerFailures++;

            if (
                response.status ===
                429
            ) {
                cooldownAIProvider2(
                    "gemini",
                    60 *
                    1000
                );
            }

            throw new Error(
                `gemini_http_${response.status}`
            );
        }

        let data;

        try {
            data =
                JSON.parse(
                    text
                );
        } catch {
            throw new Error(
                "gemini_invalid_json"
            );
        }

        const parts =
            data &&
            data.candidates &&
            data.candidates[0] &&
            data.candidates[0].content &&
            data.candidates[0].content.parts;

        const answer =
            Array.isArray(
                parts
            )
                ? parts
                    .map(
                        part =>
                            safeString(
                                part.text
                            )
                    )
                    .join(
                        "\n"
                    )
                : "";

        const cleaned =
            cleanAIResponse2(
                answer
            );

        if (
            !cleaned
        ) {
            throw new Error(
                "gemini_empty_response"
            );
        }

        provider.successes++;

        provider.latencyTotal +=
            Date.now() -
            started;

        provider.lastSuccessAt =
            nowISO();

        provider.lastError =
            null;

        AI_STATE_2
            .providerSuccesses++;

        return {
            success:
                true,

            provider:
                "gemini",

            model,

            answer:
                cleaned,

            usage:
                data.usageMetadata ||
                null,

            latency:
                Date.now() -
                started
        };
    } catch (
        error
    ) {
        throw error;
    }
}


// ========================================================================
// 240 — LOCAL AI ENGINE
// ========================================================================

function generateLocalAI2(
    options = {}
) {
    const message =
        cleanText(
            options.message ||
            "",
            12000
        );

    const intent =
        options.intent ||
        detectIntentAI2(
            message
        );

    if (
        intent.math ||
        isSimpleMathAI2(
            message
        )
    ) {
        const expression =
            extractMathExpressionAI2(
                message
            );

        const result =
            expression
                ? evaluateSimpleMathAI2(
                    expression
                )
                : null;

        if (
            result !==
            null
        ) {
            AI_STATE_2
                .mathRequests++;

            return {
                success:
                    true,

                provider:
                    "local",

                model:
                    "turkai-local-math",

                answer:
                    `Sonuç: ${Number(
                        result.toFixed(
                            10
                        )
                    )}`,

                local:
                    true,

                reason:
                    "math"
            };
        }
    }

    switch (
        intent.intent
    ) {
        case "greeting":
            return {
                success:
                    true,

                provider:
                    "local",

                model:
                    "turkai-local",

                answer:
                    randomAIResponse2(
                        "greeting"
                    ),

                local:
                    true,

                reason:
                    "greeting"
            };

        case "identity":
            return {
                success:
                    true,

                provider:
                    "local",

                model:
                    "turkai-local",

                answer:
                    randomAIResponse2(
                        "identity"
                    ),

                local:
                    true,

                reason:
                    "identity"
            };

        case "thanks":
            return {
                success:
                    true,

                provider:
                    "local",

                model:
                    "turkai-local",

                answer:
                    randomAIResponse2(
                        "thanks"
                    ),

                local:
                    true,

                reason:
                    "thanks"
            };

        case "farewell":
            return {
                success:
                    true,

                provider:
                    "local",

                model:
                    "turkai-local",

                answer:
                    randomAIResponse2(
                        "farewell"
                    ),

                local:
                    true,

                reason:
                    "farewell"
            };

        case "help":
            return {
                success:
                    true,

                provider:
                    "local",

                model:
                    "turkai-local",

                answer:
                    randomAIResponse2(
                        "help"
                    ),

                local:
                    true,

                reason:
                    "help"
            };

        default:
            break;
    }

    if (
        options.memoryResult &&
        options.memoryResult.hit &&
        options.memoryResult.answer
    ) {
        return {
            success:
                true,

            provider:
                "memory",

            model:
                "turkai-memory",

            answer:
                cleanAIResponse2(
                    options.memoryResult.answer
                ),

            memory:
                true,

            local:
                true,

            reason:
                "memory"
        };
    }

    return {
        success:
            true,

        provider:
            "local",

        model:
            "turkai-local",

        answer:
            "Bu soruyu yerel motorla doğrudan cevaplayamadım. Daha kapsamlı bir yanıt için uygun AI sağlayıcısı veya araştırma motoru kullanılabilir.",

        local:
            true,

        reason:
            "fallback"
    };
}


// ========================================================================
// 241 — PROVIDER CALL
// ========================================================================

async function callAIProvider2(
    providerId,
    options = {}
) {
    const messages =
        buildAIProviderMessages2(
            options
        );

    if (
        providerId ===
        "local"
    ) {
        return generateLocalAI2(
            options
        );
    }

    if (
        [
            "groq",
            "cerebras",
            "openrouter"
        ].includes(
            providerId
        )
    ) {
        return callOpenAICompatibleAI2(
            providerId,
            messages,
            options
        );
    }

    if (
        providerId ===
        "gemini"
    ) {
        return callGeminiAI2(
            messages,
            options
        );
    }

    throw new Error(
        "unknown_provider"
    );
}


// ========================================================================
// 242 — PROVIDER ORDER
// ========================================================================

function resolveAIProviderOrder2(
    options = {}
) {
    const requested =
        safeString(
            options.provider ||
            ""
        )
            .trim()
            .toLowerCase();

    if (
        requested &&
        AI_PROVIDERS_2[
            requested
        ]
    ) {
        return [
            requested
        ];
    }

    const model =
        safeString(
            options.model ||
            ""
        )
            .toLowerCase();

    if (
        model
    ) {
        const matched =
            Object.values(
                AI_PROVIDERS_2
            )
            .find(
                provider =>
                    provider.model
                        .toLowerCase() ===
                    model
            );

        if (
            matched
        ) {
            return [
                matched.id
            ];
        }
    }

    return AI_PROVIDER_ORDER_2
        .filter(
            providerId =>
                isAIProviderAvailable2(
                    providerId
                )
        );
}


// ========================================================================
// 243 — RESPONSE QUALITY CHECK
// ========================================================================

function validateAIResponse2(
    result,
    options = {}
) {
    if (
        !result ||
        !result.answer
    ) {
        return {
            valid:
                false,

            reason:
                "empty"
        };
    }

    const answer =
        cleanAIResponse2(
            result.answer
        );

    if (
        answer.length <
        1
    ) {
        return {
            valid:
                false,

            reason:
                "empty"
        };
    }

    if (
        answer.length >
        AI_CONFIG_2
            .maxResponseCharacters
    ) {
        return {
            valid:
                false,

            reason:
                "too_long"
        };
    }

    if (
        answer ===
        safeString(
            options.message
        )
    ) {
        return {
            valid:
                false,

            reason:
                "echo"
        };
    }

    return {
        valid:
            true,

        answer
    };
}


// ========================================================================
// 244 — MEMORY LOOKUP
// ========================================================================

function lookupAnswerMemoryAI2(
    userId,
    message
) {
    if (
        !AI_CONFIG_2
            .enableMemory ||
        !memorySettings.enabled
    ) {
        return {
            hit:
                false,

            answer:
                null
        };
    }

    AI_STATE_2
        .memoryLookups++;

    try {
        const result =
            searchAnswerMemory(
                userId,
                message,
                {
                    limit:
                        5,

                    minimumScore:
                        AI_CONFIG_2
                            .minimumMemoryScore
                }
            );

        if (
            result &&
            result.hit &&
            result.answer
        ) {
            AI_STATE_2
                .memoryHits++;

            return result;
        }

        AI_STATE_2
            .memoryMisses++;

        return (
            result || {
                hit:
                    false,

                answer:
                    null
            }
        );
    } catch (
        error
    ) {
        appendLog(
            ERROR_LOG_FILE,
            "[AI_MEMORY_LOOKUP] " +
                error.message
        );

        AI_STATE_2
            .memoryMisses++;

        return {
            hit:
                false,

            answer:
                null
        };
    }
}


// ========================================================================
// 245 — SAVE AI ANSWER TO MEMORY
// ========================================================================

function saveAIAnswerMemory2(
    userId,
    question,
    answer,
    metadata = {}
) {
    if (
        !AI_CONFIG_2
            .saveAnswersToMemory
    ) {
        return {
            saved:
                false,

            reason:
                "disabled"
        };
    }

    try {
        const result =
            saveAnswerToMemory(
                userId,
                question,
                answer,
                {
                    source:
                        metadata.source ||
                        "ai",

                    model:
                        metadata.model,

                    language:
                        metadata.language ||
                        "tr",

                    quality:
                        metadata.quality,

                    verified:
                        metadata.verified,

                    useful:
                        metadata.useful,

                    tags:
                        metadata.tags
                }
            );

        if (
            result &&
            result.saved
        ) {
            AI_STATE_2
                .memorySaves++;
        }

        return result;
    } catch (
        error
    ) {
        appendLog(
            ERROR_LOG_FILE,
            "[AI_MEMORY_SAVE] " +
                error.message
        );

        return {
            saved:
                false,

            error:
                error.message
        };
    }
}


// ========================================================================
// 246 — AI FALLBACK GENERATOR
// ========================================================================

async function generateAIFallback2(
    options = {}
) {
    const providers =
        resolveAIProviderOrder2(
            options
        );

    if (
        !providers.includes(
            "local"
        )
    ) {
        providers.push(
            "local"
        );
    }

    let lastError =
        null;

    for (
        const providerId
        of providers
    ) {
        if (
            providerId !==
                "local" &&
            !isAIProviderAvailable2(
                providerId
            )
        ) {
            continue;
        }

        for (
            let attempt = 0;
            attempt <=
                AI_CONFIG_2
                    .maxRetriesPerProvider;
            attempt++
        ) {
            if (
                attempt >
                0
            ) {
                AI_STATE_2
                    .retries++;
            }

            try {
                const result =
                    await callAIProvider2(
                        providerId,
                        options
                    );

                const validation =
                    validateAIResponse2(
                        result,
                        options
                    );

                if (
                    !validation.valid
                ) {
                    throw new Error(
                        `invalid_ai_response:${validation.reason}`
                    );
                }

                if (
                    providerId ===
                    "local" &&
                    result.reason ===
                    "fallback"
                ) {
                    AI_STATE_2
                        .localFallbacks++;
                }

                return {
                    ...result,

                    answer:
                        validation.answer,

                    attempts:
                        attempt +
                        1
                };
            } catch (
                error
            ) {
                lastError =
                    error;

                if (
                    providerId !==
                    "local"
                ) {
                    AI_STATE_2
                        .providerFailures++;
                }

                if (
                    attempt <
                    AI_CONFIG_2
                        .maxRetriesPerProvider
                ) {
                    await new Promise(
                        resolve =>
                            setTimeout(
                                resolve,
                                500
                            )
                    );
                }
            }
        }
    }

    throw (
        lastError ||
        new Error(
            "all_ai_providers_failed"
        )
    );
}


// ========================================================================
// 247 — SMART CHAT EXECUTION
// ========================================================================

async function runAIChat2(
    options = {}
) {
    const started =
        Date.now();

    const userId =
        normalizeUserId(
            options.userId ||
            "guest"
        );

    const message =
        cleanText(
            options.message ||
            "",
            12000
        );

    if (
        !message.trim()
    ) {
        return {
            success:
                false,

            error:
                "message_required"
        };
    }

    AI_STATE_2
        .requests++;

    AI_STATE_2
        .currentRequests++;

    AI_STATE_2
        .lastRequestAt =
        nowISO();

    const requestId =
        createId(
            "aireq"
        );

    AI_ACTIVE_REQUESTS_2.set(
        requestId,
        {
            requestId,

            userId,

            startedAt:
                started
        }
    );

    runtime.chat++;

    try {
        const language =
            safeString(
                options.language ||
                detectLanguageAI2(
                    message
                )
            );

        const intent =
            detectIntentAI2(
                message
            );

        const current =
            isCurrentQuestionAI2(
                message
            );

        const research =
            needsResearchAI2(
                message
            );

        const coding =
            needsCodingAI2(
                message
            );

        if (
            coding
        ) {
            AI_STATE_2
                .codingRequests++;
        }

        if (
            research
        ) {
            AI_STATE_2
                .researchRequests++;
        }

        if (
            current
        ) {
            AI_STATE_2
                .currentRequests++;
        }

        const session =
            getOrCreateAISession2(
                userId,
                options.sessionId
            );

        const history =
            getAISessionHistory2(
                session
            );

        const memoryResult =
            lookupAnswerMemoryAI2(
                userId,
                message
            );

        // ================================================================
        // EXACT / HIGH CONFIDENCE MEMORY
        // ================================================================

        if (
            memoryResult &&
            memoryResult.hit &&
            memoryResult.answer &&
            options.ignoreMemory !==
                true
        ) {
            addAISessionMessage2(
                session,
                "user",
                message
            );

            addAISessionMessage2(
                session,
                "assistant",
                memoryResult.answer,
                {
                    source:
                        "answer-memory"
                }
            );

            AI_STATE_2
                .successfulRequests++;

            const latency =
                Date.now() -
                started;

            AI_STATE_2
                .totalLatencyMS +=
                latency;

            AI_STATE_2
                .averageLatencyMS =
                AI_STATE_2
                    .totalLatencyMS /
                AI_STATE_2
                    .successfulRequests;

            AI_STATE_2
                .lastSuccessAt =
                nowISO();

            return {
                success:
                    true,

                requestId,

                sessionId:
                    session.id,

                answer:
                    memoryResult.answer,

                provider:
                    "memory",

                model:
                    "turkai-memory",

                language,

                intent,

                current,

                needsResearch:
                    research,

                needsCoding:
                    coding,

                memory:
                    {
                        hit:
                            true,

                        memoryId:
                            memoryResult
                                .record &&
                            memoryResult
                                .record
                                .id
                    },

                latency
            };
        }

        const cacheKey =
            createAIChatCacheKey2(
                {
                    userId,

                    message,

                    language,

                    model:
                        options.model,

                    system:
                        options.system,

                    history
                }
            );

        const cached =
            options.skipCache
                ? null
                : getAIChatCache2(
                    cacheKey
                );

        if (
            cached &&
            cached.answer
        ) {
            addAISessionMessage2(
                session,
                "user",
                message
            );

            addAISessionMessage2(
                session,
                "assistant",
                cached.answer,
                {
                    source:
                        "cache",

                    model:
                        cached.model
                }
            );

            AI_STATE_2
                .successfulRequests++;

            const latency =
                Date.now() -
                started;

            AI_STATE_2
                .totalLatencyMS +=
                latency;

            AI_STATE_2
                .averageLatencyMS =
                AI_STATE_2
                    .totalLatencyMS /
                AI_STATE_2
                    .successfulRequests;

            return {
                ...cached,

                success:
                    true,

                requestId,

                sessionId:
                    session.id,

                cache:
                    {
                        hit:
                            true
                    },

                latency
            };
        }

        // ================================================================
        // LOCAL SPECIAL CASES
        // ================================================================

        if (
            intent.intent ===
            "greeting" ||
            intent.intent ===
            "identity" ||
            intent.intent ===
            "thanks" ||
            intent.intent ===
            "farewell" ||
            intent.intent ===
            "help" ||
            intent.math
        ) {
            const local =
                generateLocalAI2(
                    {
                        message,

                        intent,

                        memoryResult
                    }
                );

            if (
                local &&
                local.answer
            ) {
                addAISessionMessage2(
                    session,
                    "user",
                    message
                );

                addAISessionMessage2(
                    session,
                    "assistant",
                    local.answer,
                    {
                        source:
                            "local",

                        reason:
                            local.reason
                    }
                );

                if (
                    AI_CONFIG_2
                        .saveAnswersToMemory &&
                    ![
                        "greeting",
                        "thanks",
                        "farewell"
                    ].includes(
                        intent.intent
                    )
                ) {
                    saveAIAnswerMemory2(
                        userId,
                        message,
                        local.answer,
                        {
                            source:
                                "local",

                            model:
                                local.model,

                            language,

                            quality:
                                0.70
                        }
                    );
                }

                const localResult = {
                    success:
                        true,

                    requestId,

                    sessionId:
                        session.id,

                    answer:
                        local.answer,

                    provider:
                        local.provider,

                    model:
                        local.model,

                    local:
                        true,

                    language,

                    intent,

                    current,

                    needsResearch:
                        research,

                    needsCoding:
                        coding,

                    memory:
                        {
                            hit:
                                false
                        },

                    latency:
                        Date.now() -
                        started
                };

                AI_STATE_2
                    .successfulRequests++;

                const localLatency =
                    Date.now() -
                    started;

                AI_STATE_2
                    .totalLatencyMS +=
                    localLatency;

                AI_STATE_2
                    .averageLatencyMS =
                    AI_STATE_2
                        .totalLatencyMS /
                    AI_STATE_2
                        .successfulRequests;

                AI_STATE_2
                    .lastSuccessAt =
                    nowISO();

                setAIChatCache2(
                    cacheKey,
                    localResult
                );

                return localResult;
            }
        }

        const user =
            getUser(
                userId
            );

        const externalContext =
            safeString(
                options.externalContext
            );

        const fileContext =
            safeString(
                options.fileContext
            );

        const providerResult =
            await generateAIFallback2(
                {
                    userId,

                    message,

                    language,

                    intent,

                    current,

                    research,

                    coding,

                    userName:
                        user.name,

                    history,

                    memoryResult,

                    externalContext,

                    fileContext,

                    system:
                        options.system,

                    model:
                        options.model,

                    provider:
                        options.provider,

                    temperature:
                        options.temperature,

                    topP:
                        options.topP,

                    maxTokens:
                        options.maxTokens
                }
            );

        let answer =
            cleanAIResponse2(
                providerResult.answer
            );

        if (
            !answer
        ) {
            throw new Error(
                "empty_final_answer"
            );
        }

        addAISessionMessage2(
            session,
            "user",
            message
        );

        addAISessionMessage2(
            session,
            "assistant",
            answer,
            {
                source:
                    providerResult.provider,

                model:
                    providerResult.model,

                language
            }
        );

        // ================================================================
        // SAVE ANSWER TO MEMORY
        // ================================================================

        let memorySave =
            null;

        if (
            AI_CONFIG_2
                .saveAnswersToMemory &&
            answer.length >=
                memorySettings
                    .minimumAnswerLength &&
            ![
                "greeting",
                "farewell",
                "thanks"
            ].includes(
                intent.intent
            )
        ) {
            memorySave =
                saveAIAnswerMemory2(
                    userId,
                    message,
                    answer,
                    {
                        source:
                            providerResult.provider,

                        model:
                            providerResult.model,

                        language,

                        quality:
                            providerResult
                                .provider ===
                                "local"
                                ? 0.65
                                : 0.85,

                        useful:
                            true
                    }
                );
        }

        const latency =
            Date.now() -
            started;

        AI_STATE_2
            .successfulRequests++;

        AI_STATE_2
            .totalLatencyMS +=
            latency;

        AI_STATE_2
            .averageLatencyMS =
            AI_STATE_2
                .totalLatencyMS /
            AI_STATE_2
                .successfulRequests;

        AI_STATE_2
            .lastSuccessAt =
            nowISO();

        const result = {
            success:
                true,

            requestId,

            sessionId:
                session.id,

            answer,

            provider:
                providerResult.provider,

            model:
                providerResult.model,

            language,

            intent,

            current,

            needsResearch:
                research,

            needsCoding:
                coding,

            memory:
                {
                    hit:
                        false,

                    saved:
                        Boolean(
                            memorySave &&
                            memorySave.saved
                        )
                },

            usage:
                providerResult.usage ||
                null,

            local:
                Boolean(
                    providerResult.local
                ),

            latency
        };

        setAIChatCache2(
            cacheKey,
            result
        );

        return result;
    } catch (
        error
    ) {
        AI_STATE_2
            .failedRequests++;

        AI_STATE_2
            .lastFailureAt =
            nowISO();

        runtime.errors++;

        appendLog(
            ERROR_LOG_FILE,
            JSON.stringify(
                {
                    type:
                        "ai_chat_error",

                    requestId,

                    userId,

                    message:
                        message.slice(
                            0,
                            500
                        ),

                    error:
                        error.message
                }
            )
        );

        return {
            success:
                false,

            requestId,

            error:
                "ai_generation_failed",

            message:
                error.message,

            latency:
                Date.now() -
                started
        };
    } finally {
        AI_ACTIVE_REQUESTS_2.delete(
            requestId
        );

        AI_STATE_2
            .currentRequests =
            Math.max(
                0,
                AI_STATE_2
                    .currentRequests -
                    1
            );
    }
}


// ========================================================================
// 248 — CHAT HANDLER
// ========================================================================

async function handleAIChatRequest2(
    req,
    res
) {
    const body =
        req.body ||
        {};

    const result =
        await runAIChat2(
            {
                userId:
                    body.userId ||
                    req.headers[
                        "x-user-id"
                    ] ||
                    "guest",

                sessionId:
                    body.sessionId,

                message:
                    body.message ||
                    body.prompt ||
                    "",

                language:
                    body.language,

                model:
                    body.model,

                provider:
                    body.provider,

                temperature:
                    body.temperature,

                topP:
                    body.topP,

                maxTokens:
                    body.maxTokens,

                skipCache:
                    toBoolean(
                        body.skipCache,
                        false
                    ),

                ignoreMemory:
                    toBoolean(
                        body.ignoreMemory,
                        false
                    ),

                externalContext:
                    body.externalContext,

                fileContext:
                    body.fileContext,

                system:
                    body.system
            }
        );

    return res.status(
        result.success
            ? 200
            : 500
    ).json(
        result
    );
}


// ========================================================================
// 249 — CHAT ENDPOINT
// ========================================================================

app.post(
    "/api/chat",
    handleAIChatRequest2
);


