app.post(
    "/api/chat/session",
    (
        req,
        res
    ) => {
        const body =
            req.body ||
            {};

        const session =
            getOrCreateAISession2(
                body.userId ||
                    "guest",
                null
            );

        if (
            body.title
        ) {
            session.title =
                cleanText(
                    body.title,
                    200
                );

            session.updatedAt =
                nowISO();

            sessions[
                session.id
            ] =
                session;

            writeJSON(
                SESSIONS_FILE,
                sessions
            );
        }

        return res.status(
            201
        ).json({
            success:
                true,

            session
        });
    }
);


// ========================================================================
// 262 — GET SESSION
// ========================================================================

app.get(
    "/api/chat/session/:sessionId",
    (
        req,
        res
    ) => {
        const userId =
            normalizeUserId(
                req.query.userId ||
                "guest"
            );

        const session =
            getSession(
                req.params.sessionId,
                userId
            );

        if (
            !session
        ) {
            return res.status(
                404
            ).json({
                success:
                    false,

                error:
                    "session_not_found"
            });
        }

        return res.json({
            success:
                true,

            session
        });
    }
);


// ========================================================================
// 263 — SESSION MESSAGE
// ========================================================================

app.post(
    "/api/chat/session/:sessionId/message",
    (
        req,
        res
    ) => {
        const body =
            req.body ||
            {};

        const userId =
            normalizeUserId(
                body.userId ||
                "guest"
            );

        const session =
            getSession(
                req.params.sessionId,
                userId
            );

        if (
            !session
        ) {
            return res.status(
                404
            ).json({
                success:
                    false,

                error:
                    "session_not_found"
            });
        }

        const role =
            [
                "system",
                "user",
                "assistant"
            ].includes(
                safeString(
                    body.role
                )
            )
                ? body.role
                : "user";

        const content =
            cleanText(
                body.content ||
                body.message ||
                "",
                30000
            );

        if (
            !content
        ) {
            return res.status(
                400
            ).json({
                success:
                    false,

                error:
                    "content_required"
            });
        }

        const message =
            addAISessionMessage2(
                session,
                role,
                content
            );

        return res.status(
            201
        ).json({
            success:
                true,

            message,

            session
        });
    }
);


// ========================================================================
// 264 — SESSION DELETE
// ========================================================================

app.delete(
    "/api/chat/session/:sessionId",
    (
        req,
        res
    ) => {
        const userId =
            normalizeUserId(
                req.query.userId ||
                "guest"
            );

        const session =
            getSession(
                req.params.sessionId,
                userId
            );

        if (
            !session
        ) {
            return res.status(
                404
            ).json({
                success:
                    false,

                error:
                    "session_not_found"
            });
        }

        delete sessions[
            session.id
        ];

        AI_SESSION_CACHE_2.delete(
            session.id
        );

        writeJSON(
            SESSIONS_FILE,
            sessions
        );

        return res.json({
            success:
                true,

            deleted:
                session.id
        });
    }
);


