// ========================================================================

app.post(
    "/api/ai/provider/test",
    async (
        req,
        res
    ) => {
        const body =
            req.body ||
            {};

        const provider =
            safeString(
                body.provider ||
                ""
            ).toLowerCase();

        if (
            !AI_PROVIDERS_2[
                provider
            ]
        ) {
            return res.status(
                400
            ).json({
                success:
                    false,

                error:
                    "unknown_provider"
            });
        }

        const message =
            safeString(
                body.message ||
                "Merhaba TürkAI."
            );

        const started =
            Date.now();

        try {
            const result =
                await callAIProvider2(
                    provider,
                    {
                        userId:
                            body.userId ||
                            "developer",

                        message,

                        language:
                            "tr",

                        history:
                            [],

                        memoryResult:
                            null,

                        model:
                            body.model,

                        maxTokens:
                            300
                    }
                );

            return res.json({
                success:
                    true,

                provider,

                result,

                latency:
                    Date.now() -
                    started
            });
        } catch (
            error
        ) {
            return res.status(
                502
            ).json({
                success:
                    false,

                provider,

                error:
                    error.message,

                latency:
                    Date.now() -
                    started
            });
        }
    }
);


