// ========================================================================
// 273 — AI SESSION SUMMARY
// ========================================================================

app.get(
    "/api/chat/session/:sessionId/summary",
    (
        req,
        res
    ) => {
        const userId =
            normalizeUserId(
                req.query.userId ||
                "guest"
            );

        const session =
            getSession(
                req.params.sessionId,
                userId
            );

        if (
            !session
        ) {
            return res.status(
                404
            ).json({
                success:
                    false,

                error:
                    "session_not_found"
            });
        }

        const messages =
            ensureArray(
                session.messages
            );

        const userMessages =
            messages.filter(
                item =>
                    item.role ===
                    "user"
            );

        const assistantMessages =
            messages.filter(
                item =>
                    item.role ===
                    "assistant"
            );

        const recent =
            messages
                .slice(
                    -10
                )
                .map(
                    item => ({
                        role:
                            item.role,

                        content:
                            cleanText(
                                item.content,
                                2000
                            )
                    })
                );

        return res.json({
            success:
                true,

            sessionId:
                session.id,

            userMessages:
                userMessages.length,

            assistantMessages:
                assistantMessages.length,

            messageCount:
                messages.length,

            recent
        });
    }
);


