function getAIStyleInstruction2(
    style
) {
    const id =
        safeString(
            style ||
            "normal"
        )
            .toLowerCase();

    return (
        AI_CHAT_STYLES_2[
            id
        ] &&
        AI_CHAT_STYLES_2[
            id
        ].instruction
    ) ||
        AI_CHAT_STYLES_2
            .normal
            .instruction;
}


// ========================================================================
// 278 — STYLE CHAT
// ========================================================================

app.post(
    "/api/chat/style",
    async (
        req,
        res
    ) => {
        const body =
            req.body ||
            {};

        const style =
            getAIStyleInstruction2(
                body.style
            );

        const system =
            safeString(
                body.system
            );

        const merged =
            [
                style,
                system
            ]
                .filter(
                    Boolean
                )
                .join(
                    "\n"
                );

        const result =
            await runAIChat2(
                {
                    userId:
                        body.userId ||
                        "guest",

                    sessionId:
                        body.sessionId,

                    message:
                        body.message ||
                        "",

                    language:
                        body.language,

                    provider:
                        body.provider,

                    model:
                        body.model,

                    temperature:
                        body.temperature,

                    maxTokens:
                        body.maxTokens,

                    system:
                        merged
                }
            );

        return res.json(
            result
        );
    }
);


