// ========================================================================
// 287 — PROVIDER COOLDOWN CLEANUP
// ========================================================================

const aiProviderCleanupTimer2 =
    setInterval(
        () => {
            const now =
                Date.now();

            for (
                const provider
                of Object.values(
                    AI_PROVIDERS_2
                )
            ) {
                if (
                    provider.cooldownUntil &&
                    provider.cooldownUntil <=
                    now
                ) {
                    provider.cooldownUntil =
                        0;
                }
            }
        },
        10000
    );


// ========================================================================
// 288 — CHAT SOCKET.IO
// ========================================================================

if (
    io
) {
    io.on(
        "connection",
        socket => {
            socket.on(
                "turkai:chat",
                async payload => {
                    try {
                        const data =
                            payload ||
                            {};

                        const result =
                            await runAIChat2(
                                {
                                    userId:
                                        data.userId ||
                                        "guest",

                                    sessionId:
                                        data.sessionId,

                                    message:
                                        data.message ||
                                        "",

                                    language:
                                        data.language,

                                    provider:
                                        data.provider,

                                    model:
                                        data.model,

                                    temperature:
                                        data.temperature,

                                    maxTokens:
                                        data.maxTokens
                                }
                            );

                        socket.emit(
                            "turkai:chat:result",
                            result
                        );
                    } catch (
                        error
                    ) {
                        socket.emit(
                            "turkai:chat:error",
                            {
                                success:
                                    false,

                                error:
                                    error.message
                            }
                        );
                    }
                }
            );

            socket.on(
                "turkai:ai:status",
                () => {
                    socket.emit(
                        "turkai:ai:status",
                        getAISummary2()
                    );
                }
            );
        }
    );
}


