// ========================================================================
// 311 — CATEGORY DETECTOR
// ========================================================================

function detectResearchCategory3(
    query
) {
    const value =
        normalizeText(
            query
        );

    if (
        !value
    ) {
        return "general";
    }

    let selected =
        "general";

    let bestScore =
        0;

    for (
        const [
            category,
            words
        ]
        of Object.entries(
            RESEARCH_CATEGORIES_3
        )
    ) {
        if (
            category ===
            "general"
        ) {
            continue;
        }

        let score =
            0;

        for (
            const word
            of words
        ) {
            if (
                value.includes(
                    normalizeText(
                        word
                    )
                )
            ) {
                score++;
            }
        }

        if (
            score >
            bestScore
        ) {
            bestScore =
                score;

            selected =
                category;
        }
    }

    if (
        categoryIsCurrent3(
            value
        )
    ) {
        if (
            selected ===
            "general"
        ) {
            selected =
                "news";
        }
    }

    return selected;
}


// ========================================================================
// 312 — CURRENT DETECTOR
// ========================================================================

function categoryIsCurrent3(
    query
) {
    const value =
        normalizeText(
            query
        );

    const words = [
        "bugün",
        "şu an",
        "şuan",
        "şimdi",
        "güncel",
        "son durum",
        "son dakika",
        "en son",
        "bu hafta",
        "bu ay",
        "dün",
        "yarın",
        "latest",
        "today",
        "current",
        "currently",
        "recent",
        "right now"
    ];

    return words.some(
        word =>
            value.includes(
                normalizeText(
                    word
                )
            )
    );
}


// ========================================================================
// 313 — QUERY CLEANER
// ========================================================================

function cleanResearchQuery3(
    query
) {
    let value =
        cleanText(
            query,
            RESEARCH_CONFIG_3
                .maxQueryLength
        );

    value =
        value
            .replace(
                /https?:\/\/\S+/gi,
                ""
            )
            .replace(
                /\s+/g,
                " "
            )
            .trim();

    value =
        value.replace(
            /^(araştır|ara|bak|bul|search|research)\s*[:,-]?\s*/i,
            ""
        );

    return value;
}


// ========================================================================
// 314 — URL DETECTOR
// ========================================================================

function extractResearchURL3(
    text
) {
    const value =
        safeString(
            text
        );

    const match =
        value.match(
            /https?:\/\/[^\s<>"']+/i
        );

    return match
        ? match[0]
        : null;
}


// ========================================================================
// 315 — SEARCH QUERY VARIANTS
// ========================================================================

function createResearchQueryVariants3(
    query,
    category
) {
    const base =
        cleanResearchQuery3(
            query
        );

    if (
        !base
    ) {
        return [];
    }

    const variants =
        [
            base
        ];

    if (
        category ===
        "news"
    ) {
        variants.push(
            `${base} son gelişmeler`
        );

        variants.push(
            `${base} haber`
        );
    }

    if (
        category ===
        "technology"
    ) {
        variants.push(
            `${base} teknoloji`
        );

        variants.push(
            `${base} official`
        );
    }

    if (
        category ===
        "science"
    ) {
        variants.push(
            `${base} bilimsel`
        );

        variants.push(
            `${base} research`
        );
    }

    if (
        category ===
        "finance"
    ) {
        variants.push(
            `${base} finans`
        );

        variants.push(
            `${base} market`
        );
    }

    if (
        category ===
        "education"
    ) {
        variants.push(
            `${base} eğitim`
        );
    }

    if (
        category ===
        "security"
    ) {
        variants.push(
            `${base} security`
        );

        variants.push(
            `${base} CVE`
        );
    }

    if (
        category ===
        "gaming"
    ) {
        variants.push(
            `${base} gaming`
        );
    }

    if (
        category ===
        "shopping"
    ) {
        variants.push(
            `${base} fiyat`
        );
    }

    if (
        category ===
        "politics"
    ) {
        variants.push(
            `${base} official`
        );
    }

    return uniqueArray(
        variants
    ).slice(
        0,
        RESEARCH_CONFIG_3
            .maxQueryVariants
    );
}


// ========================================================================
// 316 — QUERY HASH
// ========================================================================

function createResearchHash3(
    query,
    options = {}
) {
    const payload = {
        query:
            normalizeText(
                query
            ),

        language:
            safeString(
                options.language ||
                "tr"
            ),

        category:
            safeString(
                options.category ||
                ""
            ),

        maxSources:
            Number(
                options.maxSources ||
                8
            )
    };

    return crypto
        .createHash(
            "sha256"
        )
        .update(
            JSON.stringify(
                payload
            ),
            "utf8"
        )
        .digest(
            "hex"
        );
}


// ========================================================================
// 317 — RESEARCH CACHE GET
// ========================================================================

function getResearchCache3(
    key
) {
    if (
        !researchSettings3.cache
    ) {
        RESEARCH_STATE_3
            .cacheMisses++;

        return null;
    }

    const memory =
        researchMemoryCache3.get(
            key
        );

    if (
        memory
    ) {
        if (
            Date.now() -
            memory.createdAt <=
            RESEARCH_CONFIG_3
                .cacheTTLMS
        ) {
            RESEARCH_STATE_3
                .cacheHits++;

            return memory.value;
        }

        researchMemoryCache3.delete(
            key
        );
    }

    const persistent =
        researchCache3[
            key
        ];

    if (
        persistent
    ) {
        const created =
            Number(
                persistent.createdAt
            ) || 0;

        if (
            Date.now() -
            created <=
            RESEARCH_CONFIG_3
                .cacheTTLMS
        ) {
            researchMemoryCache3.set(
                key,
                {
                    createdAt:
                        created,

                    value:
                        persistent.value
                }
            );

            RESEARCH_STATE_3
                .cacheHits++;

            return persistent.value;
        }

        delete researchCache3[
            key
        ];
    }

    RESEARCH_STATE_3
        .cacheMisses++;

    return null;
}


// ========================================================================
// 318 — RESEARCH CACHE SET
// ========================================================================

function setResearchCache3(
    key,
    value
) {
    if (
        !RESEARCH_CONFIG_3
            .saveCache
    ) {
        return;
    }

    const entry = {
        createdAt:
            Date.now(),

        value:
            clone(
                value
            )
    };

    researchMemoryCache3.set(
        key,
        entry
    );

    researchCache3[
        key
    ] =
        entry;

    const keys =
        Object.keys(
            researchCache3
        );

    if (
        keys.length >
        RESEARCH_CONFIG_3
            .maxCacheEntries
    ) {
        const removeCount =
            keys.length -
            RESEARCH_CONFIG_3
                .maxCacheEntries;

        keys
            .slice(
                0,
                removeCount
            )
            .forEach(
                cacheKey => {
                    delete researchCache3[
                        cacheKey
                    ];
                }
            );
    }

    writeJSON(
        RESEARCH_CACHE_FILE_3,
        researchCache3
    );
}


