function clearResearchCache3() {
    const size =
        Object.keys(
            researchCache3
        ).length;

    researchCache3 =
        {};

    researchMemoryCache3.clear();

    writeJSON(
        RESEARCH_CACHE_FILE_3,
        researchCache3
    );

    return {
        success:
            true,

        cleared:
            size
    };
}


// ========================================================================
// 356 — RESEARCH CACHE CLEANUP
// ========================================================================

function cleanupResearchCache3() {
    const now =
        Date.now();

    let removed =
        0;

    for (
        const [
            key,
            entry
        ]
        of Object.entries(
            researchCache3
        )
    ) {
        const created =
            Number(
                entry &&
                entry.createdAt
            ) || 0;

        if (
            now -
            created >
            RESEARCH_CONFIG_3
                .cacheTTLMS
        ) {
            delete researchCache3[
                key
            ];

            researchMemoryCache3.delete(
                key
            );

            removed++;
        }
    }

    if (
        removed
    ) {
        writeJSON(
            RESEARCH_CACHE_FILE_3,
            researchCache3
        );
    }

    return {
        success:
            true,

        removed
    };
}


// ========================================================================
// 357 — RESEARCH HISTORY CLEAR
// ========================================================================

function clearResearchHistory3() {
    const count =
        researchHistory3.length;

    researchHistory3 =
        [];

    writeJSON(
        RESEARCH_HISTORY_FILE_3,
        researchHistory3
    );

    return {
        success:
            true,

        cleared:
            count
    };
}


// ========================================================================
// 358 — RESEARCH HISTORY SEARCH
// ========================================================================

function searchResearchHistory3(
    query,
    limit = 50
) {
    const value =
        normalizeText(
            query
        );

    if (
        !value
    ) {
        return [];
    }

    return researchHistory3
        .filter(
            item =>
                normalizeText(
                    item.query
                ).includes(
                    value
                )
        )
        .slice(
            -Math.min(
                Math.max(
                    Number(
                        limit
                    ) || 50,
                    1
                ),
                500
            )
        )
        .reverse();
}


