// ========================================================================
// 399 — RESEARCH RUNTIME RULES
// ========================================================================

const RESEARCH_ACTIONS_3 = [
    "search",
    "search-current",
    "search-news",
    "search-technology",
    "search-science",
    "search-finance",
    "search-education",
    "search-security",
    "search-gaming",
    "search-shopping",
    "search-politics",
    "direct-url",
    "wikipedia",
    "duckduckgo",
    "cache-read",
    "cache-write",
    "history-read",
    "history-write",
    "source-score",
    "source-rank",
    "source-deduplicate",
    "source-hydrate",
    "summary",
    "context",
    "export",
    "health",
    "diagnostics"
];

const RESEARCH_ROLES_3 = [
    "guest",
    "free",
    "pro",
    "plus",
    "ultra",
    "developer"
];

const RESEARCH_TYPES_3 = [
    "general",
    "news",
    "technology",
    "science",
    "finance",
    "education",
    "security",
    "gaming",
    "shopping",
    "politics"
];

const RESEARCH_DECISIONS_3 = [
    "allow",
    "cache",
    "search",
    "hydrate",
    "rank",
    "audit"
];

const RESEARCH_RUNTIME_RULES_3 =
    [];

for (
    const action
    of RESEARCH_ACTIONS_3
) {
    for (
        const role
        of RESEARCH_ROLES_3
    ) {
        for (
            const type
            of RESEARCH_TYPES_3
        ) {
            for (
                const decision
                of RESEARCH_DECISIONS_3
            ) {
                RESEARCH_RUNTIME_RULES_3
                    .push(
                        {
                            id:
                                RESEARCH_RUNTIME_RULES_3
                                    .length +
                                1,

                            action,

                            role,

                            type,

                            decision,

                            enabled:
                                true
                        }
                    );
            }
        }
    }
}


