function getResearchAIContext3(
    result
) {
    if (
        !result
    ) {
        return "";
    }

    return buildResearchContext3(
        result
    );
}


// ========================================================================
// 410 — RESEARCH RESULT VALIDATION
// ========================================================================

function validateResearchResult3(
    result
) {
    if (
        !result
    ) {
        return {
            valid:
                false,

            reason:
                "result_missing"
        };
    }

    if (
        !Array.isArray(
            result.sources
        )
    ) {
        return {
            valid:
                false,

            reason:
                "sources_missing"
        };
    }

    if (
        result.sources.length >
        RESEARCH_CONFIG_3
            .absoluteMaxSources
    ) {
        return {
            valid:
                false,

            reason:
                "too_many_sources"
        };
    }

    return {
        valid:
            true,

        sourceCount:
            result.sources.length
    };
}


// ========================================================================
// 411 — RESEARCH FALLBACK MESSAGE
// ========================================================================

function createResearchFallback3(
    query
) {
    return {
        success:
            false,

        query:
            cleanResearchQuery3(
                query
            ),

        category:
            detectResearchCategory3(
                query
            ),

        current:
            categoryIsCurrent3(
                query
            ),

        sources:
            [],

        summary:
            "Araştırma motoru şu anda kullanılabilir bir kaynak döndürmedi.",

        context:
            "",

        fallback:
            true
    };
}


// ========================================================================
// 412 — SAFE EXECUTE RESEARCH
// ========================================================================

async function safeExecuteResearch3(
    query,
    options = {}
) {
    try {
        const result =
            await executeResearch(
                query,
                options
            );

        const validation =
            validateResearchResult3(
                result
            );

        if (
            !validation.valid
        ) {
            return createResearchFallback3(
                query
            );
        }

        return result;
    } catch (
        error
    ) {
        appendLog(
            ERROR_LOG_FILE,
            JSON.stringify(
                {
                    type:
                        "research_error",

                    query:
                        cleanText(
                            query,
                            1000
                        ),

                    error:
                        error.message
                }
            )
        );

        return {
            ...createResearchFallback3(
                query
            ),

            error:
                error.message
        };
    }
}


// ========================================================================
// 413 — AI RESEARCH DECISION
// ========================================================================

function shouldResearchAutomatically3(
    message
) {
    const value =
        normalizeText(
            message
        );

    if (
        !value
    ) {
        return false;
    }

    if (
        typeof needsResearchAI2 ===
        "function"
    ) {
        try {
            if (
                needsResearchAI2(
                    value
                )
            ) {
                return true;
            }
        } catch {
            // devam
        }
    }

    return (
        categoryIsCurrent3(
            value
        ) ||
        detectResearchCategory3(
            value
        ) !==
            "general"
    );
}


// ========================================================================
// 414 — AI RESEARCH ROUTER
// ========================================================================

async function routeResearchForAI3(
    message,
    options = {}
) {
    if (
        !shouldResearchAutomatically3(
            message
        )
    ) {
        return {
            needed:
                false,

            result:
                null
        };
    }

    const result =
        await safeExecuteResearch3(
            message,
            options
        );

    return {
        needed:
            true,

        result
    };
}


