async function researchWithMemory3(
    userId,
    question,
    options = {}
) {
    let memory =
        null;

    try {
        if (
            typeof searchAnswerMemory ===
            "function"
        ) {
            memory =
                searchAnswerMemory(
                    userId ||
                        "guest",
                    question,
                    {
                        minimumScore:
                            0.80
                    }
                );
        }
    } catch {
        memory =
            null;
    }

    const result =
        await safeExecuteResearch3(
            question,
            options
        );

    return {
        memory,

        research:
            result,

        combinedContext:
            [
                memory &&
                memory.hit &&
                memory.answer
                    ? `Önceki hafıza cevabı:\n${memory.answer}`
                    : "",

                result &&
                result.context
                    ? `Web araştırması:\n${result.context}`
                    : ""
            ]
                .filter(
                    Boolean
                )
                .join(
                    "\n\n"
                )
    };
}


