const GOLD_HISTORY_4 = [];

const MARKET_CACHE_4 = new Map();
const MARKET_HISTORY_4 = [];


/* -------------------------------------------------------
   4.1 - GENERIC ENGINE HELPERS
------------------------------------------------------- */

function marketSetError4(type, error) {
    MARKET_STATE_4.lastError = {
        type: safeString(type, 100),
        message: safeString(
            error && error.message
                ? error.message
                : String(error || "Bilinmeyen hata"),
            500
        ),
        at: nowISO()
    };
}

function marketRecordRequest4(type, success) {
    MARKET_STATE_4.requests += 1;
    MARKET_STATE_4.activeRequests = Math.max(
        0,
        MARKET_STATE_4.activeRequests - 1
    );

    if (success) {
        MARKET_STATE_4.successfulRequests += 1;
    } else {
        MARKET_STATE_4.failedRequests += 1;
    }

    if (type === "weather") {
        MARKET_STATE_4.weatherRequests += 1;
        MARKET_STATE_4.lastWeatherRequestAt = nowISO();
    }

    if (type === "currency") {
        MARKET_STATE_4.currencyRequests += 1;
        MARKET_STATE_4.lastCurrencyRequestAt = nowISO();
    }

    if (type === "gold") {
        MARKET_STATE_4.goldRequests += 1;
        MARKET_STATE_4.lastGoldRequestAt = nowISO();
    }

    if (type === "market") {
        MARKET_STATE_4.marketRequests += 1;
        MARKET_STATE_4.lastMarketRequestAt = nowISO();
    }
}

function marketCacheGet4(cache, key, ttl) {
    const item = cache.get(key);

    if (!item) {
        return null;
    }

    const age = Date.now() - item.createdAt;

    if (age > ttl) {
        cache.delete(key);
        return null;
    }

    return clone(item.value);
}

function marketCacheSet4(cache, key, value, extra = {}) {
    cache.set(key, {
        createdAt: Date.now(),
        value: clone(value),
        ...extra
    });

    return value;
}

function marketCacheClear4(cache) {
    cache.clear();
}

function marketCleanText4(value, max = 500) {
    return cleanText(safeString(value, max));
}

function marketNormalizeCode4(value) {
    return marketCleanText4(value, 10).trim().toUpperCase();
}

function marketRound4(value, decimals = 2) {
    const number = Number(value);

    if (!Number.isFinite(number)) {
        return null;
    }

    const power = 10 ** decimals;
    return Math.round(number * power) / power;
}

function marketFormatNumber4(value, decimals = 2) {
    const number = Number(value);

    if (!Number.isFinite(number)) {
        return "-";
    }

    return new Intl.NumberFormat("tr-TR", {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals
    }).format(number);
}

function marketFormatTRY4(value) {
    return `${marketFormatNumber4(value, 2)} ₺`;
}

function marketSleep4(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

async function marketFetchJSON4(url, options = {}) {
    const controller = new AbortController();

    const timeoutMs = Number.isFinite(Number(options.timeoutMs))
        ? Number(options.timeoutMs)
        : 10000;

    const timeout = setTimeout(() => {
        controller.abort();
    }, timeoutMs);

    try {
        const response = await fetch(url, {
            method: options.method || "GET",
            headers: {
                "Accept": "application/json",
                "User-Agent": "TurkAI/40.0",
                ...(options.headers || {})
            },
            body: options.body,
            signal: controller.signal
        });

        const text = await response.text();

        let data = null;

        try {
            data = text ? JSON.parse(text) : null;
        } catch (parseError) {
            throw new Error(
                `JSON parse edilemedi: HTTP ${response.status}`
            );
        }

        if (!response.ok) {
            const message =
                data?.reason ||
                data?.error ||
                data?.message ||
                `HTTP ${response.status}`;

            throw new Error(message);
        }

        return data;
    } finally {
        clearTimeout(timeout);
    }
}

function marketSafeURL4(value) {
    try {
        const url = new URL(value);

        if (!["http:", "https:"].includes(url.protocol)) {
            return null;
        }

        return url.toString();
    } catch {
        return null;
    }
}


