function getWeatherCodeInfo4(code) {
    return (
        WEATHER_CODES_4[Number(code)] || {
            description: "Bilinmeyen hava koşulu",
            short: "Bilinmiyor",
            icon: "unknown"
        }
    );
}

function getWeatherTemperatureLabel4(temp) {
    const number = Number(temp);

    if (!Number.isFinite(number)) {
        return "-";
    }

    if (number >= 35) {
        return "Çok sıcak";
    }

    if (number >= 28) {
        return "Sıcak";
    }

    if (number >= 20) {
        return "Ilık";
    }

    if (number >= 10) {
        return "Serin";
    }

    if (number >= 0) {
        return "Soğuk";
    }

    return "Dondurucu soğuk";
}


/* -------------------------------------------------------
   4.4 - WEATHER QUERY PARSER
------------------------------------------------------- */

function parseWeatherQuery4(query) {
    const text = marketCleanText4(query, 500);

    let city = findTurkeyCity4(text);

    if (!city) {
        const patterns = [
            /([a-zçğıöşüİĞÜŞÖÇA-Z\-]+)\s+(?:hava|hava durumu|sıcaklık)/i,
            /(?:hava|hava durumu|sıcaklık)\s+(?:nasıl|kaç|nedir|durumu)?\s*([a-zçğıöşüİĞÜŞÖÇA-Z\-]+)/i,
            /([a-zçğıöşüİĞÜŞÖÇA-Z\-]+)\s+(?:için|icin)\s+(?:hava|hava durumu)/i
        ];

        for (const regex of patterns) {
            const match = text.match(regex);

            if (match?.[1]) {
                city = findTurkeyCity4(match[1]);

                if (city) {
                    break;
                }
            }
        }
    }

    const daysMatch = text.match(
        /(\d+)\s*(?:gün|gun)\s*(?:sonra|boyunca|lük|luk)?/i
    );

    const days = daysMatch
        ? clamp(Number(daysMatch[1]), 1, MARKET_CONFIG_4.weather.maxForecastDays)
        : MARKET_CONFIG_4.weather.defaultForecastDays;

    const wantsHourly =
        /saat|saatlik|bu akşam|aksam|gece|öğlen|oglen|sabah/i.test(text);

    const wantsDaily =
        /gün|gun|yarın|yarin|hafta|haftalık|haftalik|5 gün|7 gün/i.test(text);

    const wantsRain =
        /yağmur|yagmur|yağış|yagis|sağanak|saganak/i.test(text);

    const wantsTemperature =
        /sıcak|sicak|derece|kaç derece|kaç °c|°c/i.test(text);

    return {
        query: text,
        city,
        days,
        wantsHourly,
        wantsDaily,
        wantsRain,
        wantsTemperature
    };
}


/* -------------------------------------------------------
   4.5 - WEATHER GEOCODING
------------------------------------------------------- */

async function geocodeWeatherCity4(cityName) {
    const cleanCity = marketCleanText4(cityName, 100);

    if (!cleanCity) {
        throw new Error("Şehir adı boş.");
    }

    const localCity = findTurkeyCity4(cleanCity);

    if (localCity) {
        return {
            name: localCity.name,
            country: localCity.country,
            latitude: localCity.lat,
            longitude: localCity.lon,
            source: "turkey-city-database"
        };
    }

    const cacheKey = normalizeText(cleanCity);

    const cached = marketCacheGet4(
        WEATHER_CITY_CACHE_4,
        cacheKey,
        MARKET_CONFIG_4.weather.cacheTTL * 4
    );

    if (cached) {
        return cached;
    }

    const url =
        `${MARKET_CONFIG_4.weather.geocodingBase}` +
        `?name=${encodeURIComponent(cleanCity)}` +
        `&count=${MARKET_CONFIG_4.weather.maxResults}` +
        `&language=tr` +
        `&format=json`;

    const data = await marketFetchJSON4(url, {
        timeoutMs: MARKET_CONFIG_4.weather.timeoutMs
    });

    const results = Array.isArray(data?.results)
        ? data.results
        : [];

    if (!results.length) {
        throw new Error(`"${cleanCity}" için şehir bulunamadı.`);
    }

    const turkeyResult =
        results.find(item => item.country_code === "TR") ||
        results[0];

    const location = {
        name: turkeyResult.name || cleanCity,
        country: turkeyResult.country || "",
        admin1: turkeyResult.admin1 || "",
        latitude: Number(turkeyResult.latitude),
        longitude: Number(turkeyResult.longitude),
        timezone: turkeyResult.timezone || "Europe/Istanbul",
        source: "open-meteo-geocoding"
    };

    marketCacheSet4(
        WEATHER_CITY_CACHE_4,
        cacheKey,
        location
    );

    return location;
}


/* -------------------------------------------------------
   4.6 - WEATHER FORECAST REQUEST
------------------------------------------------------- */

function buildWeatherForecastURL4(latitude, longitude, days = 5) {
    const safeDays = clamp(
        Number(days) || 5,
        1,
        MARKET_CONFIG_4.weather.maxForecastDays
    );

    const params = new URLSearchParams({
        latitude: String(latitude),
        longitude: String(longitude),

        current: [
            "temperature_2m",
            "relative_humidity_2m",
            "apparent_temperature",
            "is_day",
            "precipitation",
            "rain",
            "showers",
            "snowfall",
            "weather_code",
            "cloud_cover",
            "pressure_msl",
            "surface_pressure",
            "wind_speed_10m",
            "wind_direction_10m",
            "wind_gusts_10m"
        ].join(","),

        hourly: [
            "temperature_2m",
            "relative_humidity_2m",
            "apparent_temperature",
            "precipitation_probability",
            "precipitation",
            "rain",
            "showers",
            "snowfall",
            "weather_code",
            "cloud_cover",
            "visibility",
            "wind_speed_10m",
            "wind_direction_10m",
            "wind_gusts_10m"
        ].join(","),

        daily: [
            "weather_code",
            "temperature_2m_max",
            "temperature_2m_min",
            "apparent_temperature_max",
            "apparent_temperature_min",
            "sunrise",
            "sunset",
            "daylight_duration",
            "sunshine_duration",
            "precipitation_sum",
            "rain_sum",
            "showers_sum",
            "snowfall_sum",
            "precipitation_probability_max",
            "wind_speed_10m_max",
            "wind_gusts_10m_max",
            "wind_direction_10m_dominant"
        ].join(","),

        timezone: "auto",
        forecast_days: String(safeDays),
        temperature_unit: "celsius",
        wind_speed_unit: "kmh",
        precipitation_unit: "mm"
    });

    return `${MARKET_CONFIG_4.weather.forecastBase}?${params.toString()}`;
}


/* -------------------------------------------------------
   4.7 - WEATHER NORMALIZATION
------------------------------------------------------- */

function normalizeWeatherCurrent4(raw, location) {
    const current = raw?.current || {};
    const info = getWeatherCodeInfo4(current.weather_code);

    return {
        location: {
            name: location.name,
            country: location.country,
            admin1: location.admin1 || "",
            latitude: Number(location.latitude),
            longitude: Number(location.longitude)
        },

        time: current.time || null,
        isDay: Number(current.is_day) === 1,

        temperature: marketRound4(current.temperature_2m, 1),
        apparentTemperature: marketRound4(current.apparent_temperature, 1),
        humidity: marketRound4(current.relative_humidity_2m, 0),

        precipitation: marketRound4(current.precipitation, 1),
        rain: marketRound4(current.rain, 1),
        showers: marketRound4(current.showers, 1),
        snowfall: marketRound4(current.snowfall, 1),

        cloudCover: marketRound4(current.cloud_cover, 0),

        pressure: marketRound4(current.pressure_msl, 1),

        wind: {
            speed: marketRound4(current.wind_speed_10m, 1),
            direction: marketRound4(current.wind_direction_10m, 0),
            gusts: marketRound4(current.wind_gusts_10m, 1)
        },

        weatherCode: Number(current.weather_code),
        weather: info,

        temperatureLabel: getWeatherTemperatureLabel4(
            current.temperature_2m
        )
    };
}

function normalizeWeatherHourly4(raw) {
    const hourly = raw?.hourly || {};

    const times = Array.isArray(hourly.time)
        ? hourly.time
        : [];

    return times.slice(
        0,
        MARKET_CONFIG_4.weather.defaultHourlyHours
    ).map((time, index) => {
        const info = getWeatherCodeInfo4(
            hourly.weather_code?.[index]
        );

        return {
            time,

            temperature: marketRound4(
                hourly.temperature_2m?.[index],
                1
            ),

            apparentTemperature: marketRound4(
                hourly.apparent_temperature?.[index],
                1
            ),

            humidity: marketRound4(
                hourly.relative_humidity_2m?.[index],
                0
            ),

            precipitationProbability:
                marketRound4(
                    hourly.precipitation_probability?.[index],
                    0
                ),

            precipitation: marketRound4(
                hourly.precipitation?.[index],
                1
            ),

            rain: marketRound4(
                hourly.rain?.[index],
                1
            ),

            showers: marketRound4(
                hourly.showers?.[index],
                1
            ),

            snowfall: marketRound4(
                hourly.snowfall?.[index],
                1
            ),

            cloudCover: marketRound4(
                hourly.cloud_cover?.[index],
                0
            ),

            visibility: marketRound4(
                hourly.visibility?.[index],
                0
            ),

            windSpeed: marketRound4(
                hourly.wind_speed_10m?.[index],
                1
            ),

            windDirection: marketRound4(
                hourly.wind_direction_10m?.[index],
                0
            ),

            windGusts: marketRound4(
                hourly.wind_gusts_10m?.[index],
                1
            ),

            weatherCode: Number(
                hourly.weather_code?.[index]
            ),

            weather: info
        };
    });
}

function normalizeWeatherDaily4(raw) {
    const daily = raw?.daily || {};

    const times = Array.isArray(daily.time)
        ? daily.time
        : [];

    return times.map((date, index) => {
        const info = getWeatherCodeInfo4(
            daily.weather_code?.[index]
        );

        return {
            date,

            temperatureMax: marketRound4(
                daily.temperature_2m_max?.[index],
                1
            ),

            temperatureMin: marketRound4(
                daily.temperature_2m_min?.[index],
                1
            ),

            apparentTemperatureMax: marketRound4(
                daily.apparent_temperature_max?.[index],
                1
            ),

            apparentTemperatureMin: marketRound4(
                daily.apparent_temperature_min?.[index],
                1
            ),

            precipitation: marketRound4(
                daily.precipitation_sum?.[index],
                1
            ),

            rain: marketRound4(
                daily.rain_sum?.[index],
                1
            ),

            showers: marketRound4(
                daily.showers_sum?.[index],
                1
            ),

            snowfall: marketRound4(
                daily.snowfall_sum?.[index],
                1
            ),

            precipitationProbability: marketRound4(
                daily.precipitation_probability_max?.[index],
                0
            ),

            windMax: marketRound4(
                daily.wind_speed_10m_max?.[index],
                1
            ),

            windGustsMax: marketRound4(
                daily.wind_gusts_10m_max?.[index],
                1
            ),

            windDirection: marketRound4(
                daily.wind_direction_10m_dominant?.[index],
                0
            ),

            sunrise: daily.sunrise?.[index] || null,
            sunset: daily.sunset?.[index] || null,

            daylightSeconds: marketRound4(
                daily.daylight_duration?.[index],
                0
            ),

            sunshineSeconds: marketRound4(
                daily.sunshine_duration?.[index],
                0
            ),

            weatherCode: Number(
                daily.weather_code?.[index]
            ),

            weather: info
        };
    });
}


/* -------------------------------------------------------
   4.8 - WEATHER ALERT / SUMMARY ENGINE
------------------------------------------------------- */

function createWeatherAlerts4(current, daily) {
    const alerts = [];

    if (!current) {
        return alerts;
    }

    const temp = Number(current.temperature);

    if (Number.isFinite(temp)) {
        if (temp >= 35) {
            alerts.push({
                type: "heat",
                level: "high",
                title: "Yüksek sıcaklık",
                message: "Sıcaklık çok yüksek."
            });
        }

        if (temp <= 0) {
            alerts.push({
                type: "cold",
                level: "high",
                title: "Don riski",
                message: "Sıcaklık 0°C veya altında."
            });
        }
    }

    const wind = Number(current?.wind?.gusts);

    if (Number.isFinite(wind) && wind >= 60) {
        alerts.push({
            type: "wind",
            level: "high",
            title: "Kuvvetli rüzgâr",
            message: "Rüzgâr hamleleri yüksek seviyede."
        });
    }

    const code = Number(current.weatherCode);

    if ([95, 96, 99].includes(code)) {
        alerts.push({
            type: "storm",
            level: "high",
            title: "Fırtına",
            message: "Gök gürültülü fırtına koşulları görülüyor."
        });
    }

    const nextRain = Array.isArray(daily)
        ? daily.slice(0, 3).some(
            item =>
                Number(item.precipitationProbability) >= 70
        )
        : false;

    if (nextRain) {
        alerts.push({
            type: "rain",
            level: "medium",
            title: "Yağış ihtimali",
            message: "Önümüzdeki günlerde yüksek yağış ihtimali bulunuyor."
        });
    }

    return alerts;
}

function createWeatherSummary4(result) {
    const current = result.current;

    if (!current) {
        return "Hava durumu verisi bulunamadı.";
    }

    const temp = Number(current.temperature);
    const feels = Number(current.apparentTemperature);

    let summary =
        `${result.location.name} için hava ${current.weather.description.toLowerCase()}. ` +
        `Sıcaklık ${marketFormatNumber4(temp, 1)}°C.`;

    if (Number.isFinite(feels)) {
        summary +=
            ` Hissedilen sıcaklık ${marketFormatNumber4(feels, 1)}°C.`;
    }

    if (Number.isFinite(Number(current.humidity))) {
        summary +=
            ` Nem %${marketFormatNumber4(current.humidity, 0)}.`;
    }

    if (
        Number.isFinite(Number(current.wind?.speed))
    ) {
        summary +=
            ` Rüzgâr ${marketFormatNumber4(
                current.wind.speed,
                1
            )} km/sa.`;
    }

    return summary;
}


/* -------------------------------------------------------
   4.9 - MAIN WEATHER ENGINE
------------------------------------------------------- */

async function getWeatherByCoordinates4(
    latitude,
    longitude,
    options = {}
) {
    const lat = Number(latitude);
    const lon = Number(longitude);
    const days = clamp(
        Number(options.days) || 5,
        1,
        MARKET_CONFIG_4.weather.maxForecastDays
    );

    if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
        throw new Error("Geçersiz koordinat.");
    }

    if (lat < -90 || lat > 90) {
        throw new Error("Enlem geçersiz.");
    }

    if (lon < -180 || lon > 180) {
        throw new Error("Boylam geçersiz.");
    }

    const cacheKey =
        `coords:${lat.toFixed(4)}:${lon.toFixed(4)}:${days}`;

    const cached = marketCacheGet4(
        WEATHER_CACHE_4,
        cacheKey,
        MARKET_CONFIG_4.weather.cacheTTL
    );

    if (cached) {
        MARKET_STATE_4.weatherCacheHits += 1;
        return cached;
    }

    const url = buildWeatherForecastURL4(
        lat,
        lon,
        days
    );

    const raw = await marketFetchJSON4(url, {
        timeoutMs: MARKET_CONFIG_4.weather.timeoutMs
    });

    const location = {
        name:
            options.city ||
            `Koordinat ${lat.toFixed(2)}, ${lon.toFixed(2)}`,
        country: options.country || "",
        admin1: options.admin1 || "",
        latitude: lat,
        longitude: lon
    };

    const result = {
        provider: "Open-Meteo",
        generatedAt: nowISO(),

        location,

        timezone: raw.timezone || "Europe/Istanbul",

        current: normalizeWeatherCurrent4(
            raw,
            location
        ),

        hourly: normalizeWeatherHourly4(raw),

        daily: normalizeWeatherDaily4(raw),

        alerts: [],

        units: {
            temperature: "°C",
            windSpeed: "km/sa",
            precipitation: "mm",
            pressure: "hPa"
        }
    };

    result.alerts = createWeatherAlerts4(
        result.current,
        result.daily
    );

    result.summary = createWeatherSummary4(result);

    marketCacheSet4(
        WEATHER_CACHE_4,
        cacheKey,
        result
    );

    WEATHER_HISTORY_4.unshift({
        id: createShortId(),
        createdAt: nowISO(),
        location: clone(location),
        summary: result.summary
    });

    if (WEATHER_HISTORY_4.length > 200) {
        WEATHER_HISTORY_4.length = 200;
    }

    return result;
}

async function getWeatherByCity4(city, options = {}) {
    const location = await geocodeWeatherCity4(city);

    return getWeatherByCoordinates4(
        location.latitude,
        location.longitude,
        {
            ...options,
            city: location.name,
            country: location.country,
            admin1: location.admin1 || ""
        }
    );
}

async function searchWeather4(query, options = {}) {
    const parsed = parseWeatherQuery4(query);

    if (!parsed.city) {
        throw new Error(
            "Hava durumu için şehir adı bulunamadı."
        );
    }

    const result = await getWeatherByCity4(
        parsed.city.name,
        {
            days: parsed.days,
            ...options
        }
    );

    return {
        ...result,
        query: parsed
    };
}


/* -------------------------------------------------------
   4.10 - WEATHER SMART ANSWER
------------------------------------------------------- */

function weatherToText4(result) {
    if (!result) {
        return "Hava durumu verisi bulunamadı.";
    }

    const current = result.current || {};

    const lines = [];

    lines.push(
        `${result.location?.name || "Konum"}: ` +
        `${marketFormatNumber4(current.temperature, 1)}°C`
    );

    if (current.apparentTemperature !== null) {
        lines.push(
            `Hissedilen: ` +
            `${marketFormatNumber4(
                current.apparentTemperature,
                1
            )}°C`
        );
    }

    if (current.weather?.description) {
        lines.push(
            `Durum: ${current.weather.description}`
        );
    }

    if (current.humidity !== null) {
        lines.push(
            `Nem: %${marketFormatNumber4(
                current.humidity,
                0
            )}`
        );
    }

    if (current.wind?.speed !== null) {
        lines.push(
            `Rüzgâr: ${marketFormatNumber4(
                current.wind.speed,
                1
            )} km/sa`
        );
    }

    if (Array.isArray(result.alerts) && result.alerts.length) {
        lines.push(
            `Uyarılar: ${result.alerts
                .map(item => item.title)
                .join(", ")}`
        );
    }

    return lines.join("\n");
}


