app.get("/api/market/health", async (req, res) => {
    const started = Date.now();

    const result = {
        success: true,
        healthy: true,
        responseTimeMs: 0,
        services: {
            weather: {
                healthy: false
            },
            currency: {
                healthy: false
            },
            gold: {
                healthy: false
            }
        }
    };

    try {
        const weather =
            await getWeatherByCity4(
                "Konya",
                {
                    days: 1
                }
            );

        result.services.weather = {
            healthy: Boolean(weather?.current),
            provider:
                MARKET_CONFIG_4.weather.provider
        };
    } catch (error) {
        result.services.weather = {
            healthy: false,
            error: error.message
        };
        result.healthy = false;
    }

    try {
        const currency =
            await convertCurrency4(
                1,
                "USD",
                "TRY"
            );

        result.services.currency = {
            healthy:
                Number.isFinite(
                    Number(currency?.rate)
                ),
            provider:
                MARKET_CONFIG_4.currency.provider
        };
    } catch (error) {
        result.services.currency = {
            healthy: false,
            error: error.message
        };
        result.healthy = false;
    }

    try {
        const gold =
            await getGoldSpotUSD4();

        result.services.gold = {
            healthy:
                Boolean(gold?.available),
            configured:
                Boolean(
                    process.env.GOLD_API_URL
                ),
            provider:
                gold?.provider || null,
            message:
                gold?.message || null
        };

        /*
          Gold sağlayıcısı kurulu değilse tüm market
          motorunu unhealthy saymıyoruz.
        */
    } catch (error) {
        result.services.gold = {
            healthy: false,
            error: error.message
        };
    }

    result.responseTimeMs =
        Date.now() - started;

    res.status(
        result.healthy ? 200 : 503
    ).json(result);
});

