/* -------------------------------------------------------
   4.29 - AUTO MARKET DETECTOR
------------------------------------------------------- */

function shouldUseMarketEngine4(text) {
    if (!MARKET_CONFIG_4.market.autoDetect) {
        return false;
    }

    const intent = detectMarketIntent4(text);

    return intent.intent !== "none";
}

async function autoMarketAnswer4(text, options = {}) {
    if (!shouldUseMarketEngine4(text)) {
        return {
            used: false,
            type: "none",
            text: null
        };
    }

    try {
        const result =
            await runMarketQuery4(
                text,
                options
            );

        return {
            used: true,
            success: true,
            ...result
        };
    } catch (error) {
        return {
            used: true,
            success: false,
            type: "error",
            text:
                "Market verisine ulaşırken hata oluştu.",
            error:
                error.message
        };
    }
}


