/* -------------------------------------------------------
   4.32 - CACHE CLEANER
------------------------------------------------------- */

function cleanupMarketCaches4() {
    const now = Date.now();

    const cleanMap = (
        cache,
        ttl
    ) => {
        for (const [
            key,
            item
        ] of cache.entries()) {

            if (
                !item ||
                !item.createdAt ||
                now - item.createdAt > ttl
            ) {
                cache.delete(key);
            }
        }
    };

    cleanMap(
        WEATHER_CACHE_4,
        MARKET_CONFIG_4.weather.cacheTTL
    );

    cleanMap(
        WEATHER_CITY_CACHE_4,
        MARKET_CONFIG_4.weather.cacheTTL * 4
    );

    cleanMap(
        CURRENCY_CACHE_4,
        MARKET_CONFIG_4.currency.cacheTTL
    );

    cleanMap(
        GOLD_CACHE_4,
        MARKET_CONFIG_4.gold.cacheTTL
    );

    cleanMap(
        MARKET_CACHE_4,
        MARKET_CONFIG_4.market.cacheTTL
    );
}

const MARKET_CLEANER_TIMER_4 =
    setInterval(
        cleanupMarketCaches4,
        60 * 1000
    );

if (
    MARKET_CLEANER_TIMER_4 &&
    typeof MARKET_CLEANER_TIMER_4.unref === "function"
) {
    MARKET_CLEANER_TIMER_4.unref();
}


/* -------------------------------------------------------
   4.33 - HISTORY LIMITER
------------------------------------------------------- */

function cleanupMarketHistory4() {
    while (
        WEATHER_HISTORY_4.length > 200
    ) {
        WEATHER_HISTORY_4.pop();
    }

    while (
        CURRENCY_HISTORY_4.length > 200
    ) {
        CURRENCY_HISTORY_4.pop();
    }

    while (
        GOLD_HISTORY_4.length > 200
    ) {
        GOLD_HISTORY_4.pop();
    }

    while (
        MARKET_HISTORY_4.length >
        MARKET_CONFIG_4.market.historyLimit
    ) {
        MARKET_HISTORY_4.pop();
    }
}

const MARKET_HISTORY_TIMER_4 =
    setInterval(
        cleanupMarketHistory4,
        5 * 60 * 1000
    );

if (
    MARKET_HISTORY_TIMER_4 &&
    typeof MARKET_HISTORY_TIMER_4.unref === "function"
) {
    MARKET_HISTORY_TIMER_4.unref();
}


/* -------------------------------------------------------
   4.34 - OPTIONAL AI BRIDGE
------------------------------------------------------- */

async function enrichAIWithMarket4(
    userText,
    options = {}
) {
    const text = marketCleanText4(
        userText,
        1500
    );

    if (
        !text ||
        !shouldUseMarketEngine4(text)
    ) {
        return {
            used: false,
            context: "",
            data: null
        };
    }

    const result =
        await autoMarketAnswer4(
            text,
            options
        );

    if (
        !result.used ||
        !result.success
    ) {
        return {
            used: true,
            context: "",
            data: result
        };
    }

    const context = [
        "TürkAI Market Engine sonucu:",
        `Tür: ${result.type}`,
        `Özet: ${result.text}`,
        `Veri: ${JSON.stringify(
            result.data
        )}`
    ].join("\n");

    return {
        used: true,
        context,
        data: result
    };
}

serverState.market.aiBridge = {
    shouldUse:
        shouldUseMarketEngine4,

    answer:
        autoMarketAnswer4,

    enrich:
        enrichAIWithMarket4
};


