/* -------------------------------------------------------
   5.3 - SAFE FILENAME ENGINE
------------------------------------------------------- */

function sanitizeFileName5(value) {
    let name =
        safeString(
            value,
            255
        );

    name = name
        .replace(/[<>:"/\\|?*\x00-\x1F]/g, "_")
        .replace(/\.\./g, "_")
        .replace(/\s+/g, " ")
        .trim();

    if (!name) {
        name =
            `turkai-file-${Date.now()}`;
    }

    if (
        name === "." ||
        name === ".."
    ) {
        name =
            `turkai-file-${Date.now()}`;
    }

    if (
        name.length > 180
    ) {
        const extension =
            path.extname(name);

        const base =
            path.basename(
                name,
                extension
            );

        name =
            base.slice(
                0,
                Math.max(
                    1,
                    180 - extension.length
                )
            ) +
            extension;
    }

    return name;
}

function getSafeExtension5(fileName) {
    return path
        .extname(
            safeString(
                fileName,
                255
            )
        )
        .toLowerCase();
}

function isBlockedExtension5(fileName) {
    const extension =
        getSafeExtension5(
            fileName
        );

    return FILE_MEDIA_CONFIG_5
        .security
        .blockedExtensions
        .includes(extension);
}

function isAllowedExtension5(fileName) {
    const extension =
        getSafeExtension5(
            fileName
        );

    return FILE_MEDIA_CONFIG_5
        .upload
        .allowedExtensions
        .includes(extension);
}

function isSafeFileName5(fileName) {
    const original =
        safeString(
            fileName,
            255
        );

    if (!original) {
        return false;
    }

    if (
        FILE_MEDIA_CONFIG_5
            .security
            .rejectTraversal
    ) {
        if (
            original.includes("..") ||
            original.includes("/") ||
            original.includes("\\")
        ) {
            return false;
        }
    }

    if (
        isBlockedExtension5(
            original
        )
    ) {
        return false;
    }

    return true;
}


/* -------------------------------------------------------
   5.4 - FILE TYPE DETECTION
------------------------------------------------------- */

function detectFileCategory5(fileName, mimeType = "") {
    const extension =
        getSafeExtension5(
            fileName
        );

    const mime =
        safeString(
            mimeType,
            150
        ).toLowerCase();

    if (
        FILE_MEDIA_CONFIG_5
            .media
            .imageExtensions
            .includes(extension) ||
        mime.startsWith("image/")
    ) {
        return "image";
    }

    if (
        FILE_MEDIA_CONFIG_5
            .media
            .videoExtensions
            .includes(extension) ||
        mime.startsWith("video/")
    ) {
        return "video";
    }

    if (
        FILE_MEDIA_CONFIG_5
            .media
            .audioExtensions
            .includes(extension) ||
        mime.startsWith("audio/")
    ) {
        return "audio";
    }

    if (
        FILE_MEDIA_CONFIG_5
            .media
            .documentExtensions
            .includes(extension) ||
        mime.startsWith("text/") ||
        mime === "application/pdf"
    ) {
        return "document";
    }

    const codeExtensions = [
        ".js",
        ".ts",
        ".jsx",
        ".tsx",
        ".py",
        ".java",
        ".c",
        ".h",
        ".cpp",
        ".hpp",
        ".cs",
        ".go",
        ".rs",
        ".php",
        ".rb",
        ".swift",
        ".kt",
        ".kts",
        ".sql",
        ".sh",
        ".ps1",
        ".bat",
        ".cmd",
        ".html",
        ".htm",
        ".css",
        ".scss",
        ".sass",
        ".less",
        ".json",
        ".xml",
        ".yaml",
        ".yml"
    ];

    if (
        codeExtensions.includes(
            extension
        )
    ) {
        return "code";
    }

    return "other";
}

function isTextLikeFile5(fileName, mimeType = "") {
    const extension =
        getSafeExtension5(
            fileName
        );

    const textExtensions = [
        ".txt",
        ".md",
        ".json",
        ".csv",
        ".xml",
        ".yaml",
        ".yml",
        ".log",
        ".js",
        ".ts",
        ".jsx",
        ".tsx",
        ".html",
        ".htm",
        ".css",
        ".scss",
        ".sass",
        ".less",
        ".py",
        ".java",
        ".c",
        ".h",
        ".cpp",
        ".hpp",
        ".cs",
        ".go",
        ".rs",
        ".php",
        ".rb",
        ".swift",
        ".kt",
        ".kts",
        ".sql",
        ".sh",
        ".ps1",
        ".bat",
        ".cmd",
        ".ini",
        ".conf"
    ];

    if (
        textExtensions.includes(
            extension
        )
    ) {
        return true;
    }

    return (
        safeString(
            mimeType,
            150
        )
            .toLowerCase()
            .startsWith("text/")
    );
}


/* -------------------------------------------------------
   5.5 - MIME DETECTION
------------------------------------------------------- */

const FILE_MIME_MAP_5 = {
    ".txt": "text/plain",
    ".md": "text/markdown",
    ".json": "application/json",
    ".csv": "text/csv",
    ".xml": "application/xml",
    ".yaml": "application/yaml",
    ".yml": "application/yaml",
    ".js": "text/javascript",
    ".ts": "text/typescript",
    ".html": "text/html",
    ".htm": "text/html",
    ".css": "text/css",
    ".py": "text/x-python",
    ".java": "text/x-java",
    ".c": "text/x-c",
    ".h": "text/x-c",
    ".cpp": "text/x-c++",
    ".hpp": "text/x-c++",
    ".cs": "text/plain",
    ".go": "text/plain",
    ".rs": "text/plain",
    ".php": "text/plain",
    ".rb": "text/plain",
    ".swift": "text/plain",
    ".kt": "text/plain",
    ".sql": "application/sql",
    ".sh": "text/x-shellscript",
    ".ps1": "text/plain",
    ".bat": "text/plain",
    ".cmd": "text/plain",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".webp": "image/webp",
    ".gif": "image/gif",
    ".bmp": "image/bmp",
    ".svg": "image/svg+xml",
    ".mp4": "video/mp4",
    ".webm": "video/webm",
    ".mov": "video/quicktime",
    ".mkv": "video/x-matroska",
    ".avi": "video/x-msvideo",
    ".mp3": "audio/mpeg",
    ".wav": "audio/wav",
    ".ogg": "audio/ogg",
    ".m4a": "audio/mp4",
    ".pdf": "application/pdf"
};

function detectMime5(fileName, suppliedMime = "") {
    const provided =
        safeString(
            suppliedMime,
            150
        ).trim();

    if (provided) {
        return provided;
    }

    return (
        FILE_MIME_MAP_5[
            getSafeExtension5(
                fileName
            )
        ] ||
        "application/octet-stream"
    );
}


/* -------------------------------------------------------
   5.6 - USER STORAGE
------------------------------------------------------- */

function normalizeFileUserId5(userId) {
    const source =
        safeString(
            userId || "anonymous",
            120
        );

    return (
        source
            .replace(
                /[^a-zA-Z0-9_-]/g,
                "_"
            )
            .slice(
                0,
                80
            ) ||
        "anonymous"
    );
}

function getFileUserDirectory5(userId) {
    const normalized =
        normalizeFileUserId5(
            userId
        );

    const directory =
        path.join(
            FILE_MEDIA_USERS_5,
            normalized
        );

    fs.mkdirSync(
        directory,
        {
            recursive: true
        }
    );

    return directory;
}

function getFileUserTrashDirectory5(userId) {
    const normalized =
        normalizeFileUserId5(
            userId
        );

    const directory =
        path.join(
            FILE_MEDIA_TRASH_5,
            normalized
        );

    fs.mkdirSync(
        directory,
        {
            recursive: true
        }
    );

    return directory;
}


/* -------------------------------------------------------
   5.7 - STORAGE PATH PROTECTION
------------------------------------------------------- */

function resolveInsideDirectory5(
    baseDirectory,
    fileName
) {
    const base =
        path.resolve(
            baseDirectory
        );

    const target =
        path.resolve(
            baseDirectory,
            fileName
        );

    if (
        target !== base &&
        !target.startsWith(
            base + path.sep
        )
    ) {
        throw new Error(
            "Güvenli dosya yolu doğrulaması başarısız."
        );
    }

    return target;
}


/* -------------------------------------------------------
   5.8 - FILE ID
------------------------------------------------------- */

function createFileId5() {
    return (
        `file_5_${Date.now()}_` +
        `${createShortId()}_` +
        `${Math.random()
            .toString(36)
            .slice(2, 8)}`
    );
}


/* -------------------------------------------------------
   5.9 - FILE HASH
------------------------------------------------------- */

function createFileHash5(buffer) {
    const cryptoModule =
        require("crypto");

    return cryptoModule
        .createHash("sha256")
        .update(buffer)
        .digest("hex");
}


/* -------------------------------------------------------
   5.10 - FILE MAGIC BYTES
------------------------------------------------------- */

function detectBufferSignature5(buffer) {
    if (!Buffer.isBuffer(buffer)) {
        return "unknown";
    }

    if (
        buffer.length >= 8 &&
        buffer[0] === 0x89 &&
        buffer[1] === 0x50 &&
        buffer[2] === 0x4E &&
        buffer[3] === 0x47
    ) {
        return "png";
    }

    if (
        buffer.length >= 3 &&
        buffer[0] === 0xFF &&
        buffer[1] === 0xD8 &&
        buffer[2] === 0xFF
    ) {
        return "jpeg";
    }

    if (
        buffer.length >= 6 &&
        buffer.toString(
            "ascii",
            0,
            6
        ) === "GIF89a"
    ) {
        return "gif";
    }

    if (
        buffer.length >= 6 &&
        buffer.toString(
            "ascii",
            0,
            6
        ) === "GIF87a"
    ) {
        return "gif";
    }

    if (
        buffer.length >= 4 &&
        buffer.toString(
            "ascii",
            0,
            4
        ) === "%PDF"
    ) {
        return "pdf";
    }

    if (
        buffer.length >= 4 &&
        buffer.toString(
            "ascii",
            0,
            4
        ) === "RIFF"
    ) {
        if (
            buffer.length >= 12 &&
            buffer.toString(
                "ascii",
                8,
                12
            ) === "WEBP"
        ) {
            return "webp";
        }

        if (
            buffer.length >= 12 &&
            buffer.toString(
                "ascii",
                8,
                12
            ) === "WAVE"
        ) {
            return "wav";
        }
    }

    if (
        buffer.length >= 4 &&
        buffer.toString(
            "ascii",
            0,
            4
        ) === "OggS"
    ) {
        return "ogg";
    }

    if (
        buffer.length >= 3 &&
        buffer.toString(
            "ascii",
            0,
            3
        ) === "ID3"
    ) {
        return "mp3";
    }

    return "unknown";
}


/* -------------------------------------------------------
   5.11 - FILE VALIDATION
------------------------------------------------------- */

function validateUploadedBuffer5(
    fileName,
    buffer,
    mimeType = ""
) {
    if (!Buffer.isBuffer(buffer)) {
        throw new Error(
            "Geçerli dosya verisi bulunamadı."
        );
    }

    if (
        buffer.length <= 0
    ) {
        throw new Error(
            "Boş dosya yüklenemez."
        );
    }

    const maxBytes =
        FILE_MEDIA_CONFIG_5
            .upload
            .maxFileSizeMB *
        1024 *
        1024;

    if (
        buffer.length > maxBytes
    ) {
        throw new Error(
            `Dosya boyutu ${FILE_MEDIA_CONFIG_5.upload.maxFileSizeMB} MB sınırını aşıyor.`
        );
    }

    if (
        !isSafeFileName5(
            fileName
        )
    ) {
        throw new Error(
            "Dosya adı güvenlik kontrolünden geçemedi."
        );
    }

    if (
        FILE_MEDIA_CONFIG_5
            .security
            .blockExecutables &&
        isBlockedExtension5(
            fileName
        )
    ) {
        throw new Error(
            "Bu dosya türünün yüklenmesine izin verilmiyor."
        );
    }

    if (
        !isAllowedExtension5(
            fileName
        )
    ) {
        throw new Error(
            `Desteklenmeyen dosya türü: ${getSafeExtension5(fileName)}`
        );
    }

    return {
        valid: true,
        size: buffer.length,
        category:
            detectFileCategory5(
                fileName,
                mimeType
            ),
        mime:
            detectMime5(
                fileName,
                mimeType
            ),
        signature:
            detectBufferSignature5(
                buffer
            )
    };
}


/* -------------------------------------------------------
   5.12 - METADATA BUILDER
------------------------------------------------------- */

function createFileRecord5(options = {}) {
    const userId =
        normalizeFileUserId5(
            options.userId
        );

    const fileName =
        sanitizeFileName5(
            options.originalName ||
            options.fileName ||
            "turkai-file"
        );

    const mime =
        detectMime5(
            fileName,
            options.mimeType
        );

    const category =
        detectFileCategory5(
            fileName,
            mime
        );

    const fileId =
        createFileId5();

    const storedName =
        `${fileId}${getSafeExtension5(fileName)}`;

    return {
        id: fileId,

        userId,

        originalName: fileName,
        storedName,

        mimeType: mime,

        category,

        size:
            Number(
                options.size || 0
            ),

        hash:
            options.hash ||
            null,

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        status:
            "ready",

        source:
            options.source ||
            "upload",

        path:
            options.path ||
            null,

        relativePath:
            options.relativePath ||
            null,

        textExtracted:
            false,

        textLength:
            0,

        metadata: {
            signature:
                options.signature ||
                "unknown"
        },

        tags:
            Array.isArray(options.tags)
                ? uniqueArray(
                    options.tags
                ).slice(0, 30)
                : []
    };
}


/* -------------------------------------------------------
   5.13 - TEXT EXTRACTION
------------------------------------------------------- */

async function extractTextFromFile5(
    filePath,
    record
) {
    if (
        !record ||
        !isTextLikeFile5(
            record.originalName,
            record.mimeType
        )
    ) {
        return {
            success: false,
            text: "",
            length: 0
        };
    }

    try {
        const maxTextBytes =
            5 * 1024 * 1024;

        const stat =
            await fs.promises.stat(
                filePath
            );

        if (
            stat.size >
            maxTextBytes
        ) {
            return {
                success: false,
                text: "",
                length: 0,
                reason:
                    "text-too-large"
            };
        }

        const raw =
            await fs.promises.readFile(
                filePath,
                "utf8"
            );

        const cleaned =
            raw
                .replace(
                    /\u0000/g,
                    ""
                )
                .slice(
                    0,
                    2_000_000
                );

        record.textExtracted = true;
        record.textLength =
            cleaned.length;

        return {
            success: true,
            text: cleaned,
            length:
                cleaned.length
        };
    } catch (error) {
        return {
            success: false,
            text: "",
            length: 0,
            reason:
                error.message
        };
    }
}


/* -------------------------------------------------------
   5.14 - INDEX HELPERS
------------------------------------------------------- */

function getFileRecord5(fileId) {
    const id =
        safeString(
            fileId,
            200
        );

    return (
        FILE_MEDIA_INDEX_5.find(
            item =>
                item &&
                item.id === id
        ) || null
    );
}

function addFileRecord5(record) {
    FILE_MEDIA_INDEX_5.unshift(
        record
    );

    if (
        FILE_MEDIA_INDEX_5.length >
        FILE_MEDIA_CONFIG_5
            .storage
            .indexLimit
    ) {
        FILE_MEDIA_INDEX_5 =
            FILE_MEDIA_INDEX_5.slice(
                0,
                FILE_MEDIA_CONFIG_5
                    .storage
                    .indexLimit
            );
    }
}

function removeFileRecord5(fileId) {
    const index =
        FILE_MEDIA_INDEX_5.findIndex(
            item =>
                item &&
                item.id === fileId
        );

    if (
        index === -1
    ) {
        return null;
    }

    const removed =
        FILE_MEDIA_INDEX_5.splice(
            index,
            1
        )[0];

    return removed || null;
}

function listUserFiles5(
    userId,
    options = {}
) {
    const normalized =
        normalizeFileUserId5(
            userId
        );

    const category =
        safeString(
            options.category,
            50
        ).toLowerCase();

    const search =
        normalizeText(
            safeString(
                options.search,
                200
            )
        );

    let files =
        FILE_MEDIA_INDEX_5.filter(
            item =>
                item &&
                item.userId === normalized
        );

    if (category) {
        files =
            files.filter(
                item =>
                    item.category === category
            );
    }

    if (search) {
        files =
            files.filter(
                item =>
                    normalizeText(
                        item.originalName
                    ).includes(search)
            );
    }

    const limit =
        clamp(
            Number(
                options.limit
            ) || 100,
            1,
            500
        );

    return files
        .slice(0, limit)
        .map(
            item => clone(item)
        );
}


/* -------------------------------------------------------
   5.15 - HISTORY
------------------------------------------------------- */

function addFileHistory5(
    action,
    record,
    extra = {}
) {
    FILE_MEDIA_HISTORY_5.unshift({
        id:
            createShortId(),

        action:
            safeString(
                action,
                80
            ),

        fileId:
            record?.id ||
            null,

        userId:
            record?.userId ||
            null,

        fileName:
            record?.originalName ||
            null,

        createdAt:
            nowISO(),

        ...extra
    });

    if (
        FILE_MEDIA_HISTORY_5.length >
        FILE_MEDIA_CONFIG_5
            .storage
            .historyLimit
    ) {
        FILE_MEDIA_HISTORY_5 =
            FILE_MEDIA_HISTORY_5.slice(
                0,
                FILE_MEDIA_CONFIG_5
                    .storage
                    .historyLimit
            );
    }
}


/* -------------------------------------------------------
   5.16 - ACTUAL FILE STORAGE
------------------------------------------------------- */

async function storeFileBuffer5(options = {}) {
    FILE_MEDIA_STATE_5.activeJobs += 1;

    try {
        const userId =
            normalizeFileUserId5(
                options.userId
            );

        const originalName =
            sanitizeFileName5(
                options.originalName ||
                options.fileName
            );

        const buffer =
            options.buffer;

        const mimeType =
            safeString(
                options.mimeType,
                150
            );

        const validation =
            validateUploadedBuffer5(
                originalName,
                buffer,
                mimeType
            );

        const directory =
            getFileUserDirectory5(
                userId
            );

        const record =
            createFileRecord5({
                userId,

                originalName,

                mimeType:
                    validation.mime,

                size:
                    validation.size,

                hash:
                    createFileHash5(
                        buffer
                    ),

                signature:
                    validation.signature,

                source:
                    options.source ||
                    "upload"
            });

        const targetPath =
            resolveInsideDirectory5(
                directory,
                record.storedName
            );

        record.path =
            targetPath;

        record.relativePath =
            path.relative(
                FILE_MEDIA_ROOT_5,
                targetPath
            );

        await fs.promises.writeFile(
            targetPath,
            buffer
        );

        const textResult =
            await extractTextFromFile5(
                targetPath,
                record
            );

        record.textExtracted =
            textResult.success;

        record.textLength =
            textResult.length;

        addFileRecord5(
            record
        );

        addFileHistory5(
            "upload",
            record
        );

        FILE_MEDIA_STATS_5.uploaded += 1;

        FILE_MEDIA_STATS_5.totalBytes +=
            buffer.length;

        FILE_MEDIA_STATE_5.uploads += 1;

        FILE_MEDIA_STATE_5.bytesUploaded +=
            buffer.length;

        FILE_MEDIA_STATE_5.lastUploadAt =
            nowISO();

        const category =
            record.category;

        if (category === "image") {
            FILE_MEDIA_STATE_5.imageFiles += 1;
        } else if (category === "video") {
            FILE_MEDIA_STATE_5.videoFiles += 1;
        } else if (category === "audio") {
            FILE_MEDIA_STATE_5.audioFiles += 1;
        } else if (category === "document") {
            FILE_MEDIA_STATE_5.documentFiles += 1;
        } else if (category === "code") {
            FILE_MEDIA_STATE_5.codeFiles += 1;
        } else {
            FILE_MEDIA_STATE_5.otherFiles += 1;
        }

        saveFileMediaPersistentState5();

        return {
            success: true,

            record:
                clone(record),

            extractedText:
                textResult.success
                    ? textResult.text
                    : "",

            extractedTextLength:
                textResult.length
        };

    } catch (error) {
        FILE_MEDIA_STATE_5.failedUploads += 1;

        FILE_MEDIA_STATE_5.lastError = {
            message:
                safeString(
                    error.message,
                    500
                ),
            at:
                nowISO()
        };

        throw error;

    } finally {
        FILE_MEDIA_STATE_5.activeJobs =
            Math.max(
                0,
                FILE_MEDIA_STATE_5.activeJobs - 1
            );
    }
}


/* -------------------------------------------------------
   5.17 - BASE64 UPLOAD
------------------------------------------------------- */

function parseBase64Data5(value) {
    const text =
        safeString(
            value,
            FILE_MEDIA_CONFIG_5
                .upload
                .maxBase64SizeMB *
                1024 *
                1024 *
                2
        );

    if (!text) {
        throw new Error(
            "Base64 verisi boş."
        );
    }

    let mime =
        "application/octet-stream";

    let base64 =
        text;

    const dataUriMatch =
        text.match(
            /^data:([^;]+);base64,(.+)$/s
        );

    if (dataUriMatch) {
        mime =
            dataUriMatch[1];

        base64 =
            dataUriMatch[2];
    }

    base64 =
        base64
            .replace(
                /\s+/g,
                ""
            );

    if (
        !/^[A-Za-z0-9+/=]+$/.test(
            base64
        )
    ) {
        throw new Error(
            "Geçersiz Base64 verisi."
        );
    }

    const buffer =
        Buffer.from(
            base64,
            "base64"
        );

    const maxBytes =
        FILE_MEDIA_CONFIG_5
            .upload
            .maxBase64SizeMB *
        1024 *
        1024;

    if (
        buffer.length >
        maxBytes
    ) {
        throw new Error(
            `Base64 dosyası ${FILE_MEDIA_CONFIG_5.upload.maxBase64SizeMB} MB sınırını aşıyor.`
        );
    }

    return {
        buffer,
        mime
    };
}


/* -------------------------------------------------------
   5.18 - UPLOAD FROM JSON
------------------------------------------------------- */

async function uploadBase64File5(
    userId,
    fileName,
    base64Data,
    mimeType
) {
    const parsed =
        parseBase64Data5(
            base64Data
        );

    return storeFileBuffer5({
        userId,
        originalName:
            fileName,
        buffer:
            parsed.buffer,
        mimeType:
            mimeType ||
            parsed.mime,
        source:
            "base64"
    });
}


/* -------------------------------------------------------
   5.19 - BUFFER CLONE / READ
------------------------------------------------------- */

async function readStoredFileBuffer5(record) {
    if (
        !record ||
        !record.path
    ) {
        throw new Error(
            "Dosya kaydı veya yolu bulunamadı."
        );
    }

    const expectedRoot =
        path.resolve(
            FILE_MEDIA_USERS_5
        );

    const resolvedPath =
        path.resolve(
            record.path
        );

    if (
        !resolvedPath.startsWith(
            expectedRoot + path.sep
        )
    ) {
        throw new Error(
            "Dosya yolu güvenli değil."
        );
    }

    return fs.promises.readFile(
        resolvedPath
    );
}


/* -------------------------------------------------------
   5.20 - DELETE FILE
------------------------------------------------------- */

async function deleteStoredFile5(
    userId,
    fileId,
    options = {}
) {
    FILE_MEDIA_STATE_5.activeJobs += 1;

    try {
        const record =
            getFileRecord5(
                fileId
            );

        if (!record) {
            throw new Error(
                "Dosya bulunamadı."
            );
        }

        const normalizedUser =
            normalizeFileUserId5(
                userId
            );

        if (
            record.userId !==
            normalizedUser
        ) {
            throw new Error(
                "Bu dosyayı silme yetkiniz yok."
            );
        }

        const trash =
            Boolean(
                options.trash
            );

        if (
            record.path &&
            fs.existsSync(
                record.path
            )
        ) {
            if (trash) {
                const trashDirectory =
                    getFileUserTrashDirectory5(
                        normalizedUser
                    );

                const trashName =
                    `${Date.now()}_${record.storedName}`;

                const trashPath =
                    resolveInsideDirectory5(
                        trashDirectory,
                        trashName
                    );

                await fs.promises.rename(
                    record.path,
                    trashPath
                );
            } else {
                await fs.promises.unlink(
                    record.path
                );
            }
        }

        const removed =
            removeFileRecord5(
                fileId
            );

        if (!removed) {
            throw new Error(
                "Dosya kaydı silinemedi."
            );
        }

        addFileHistory5(
            "delete",
            removed,
            {
                trash
            }
        );

        FILE_MEDIA_STATS_5.deleted += 1;

        FILE_MEDIA_STATS_5.totalBytes =
            Math.max(
                0,
                Number(
                    FILE_MEDIA_STATS_5.totalBytes
                ) -
                Number(
                    removed.size || 0
                )
            );

        FILE_MEDIA_STATE_5.deletedFiles += 1;

        FILE_MEDIA_STATE_5.bytesDeleted +=
            Number(
                removed.size || 0
            );

        FILE_MEDIA_STATE_5.lastDeleteAt =
            nowISO();

        saveFileMediaPersistentState5();

        return {
            success: true,
            removed:
                clone(removed),
            trash
        };

    } catch (error) {
        FILE_MEDIA_STATE_5.lastError = {
            message:
                error.message,
            at:
                nowISO()
        };

        throw error;

    } finally {
        FILE_MEDIA_STATE_5.activeJobs =
            Math.max(
                0,
                FILE_MEDIA_STATE_5.activeJobs - 1
            );
    }
}


/* -------------------------------------------------------
   5.21 - FILE SEARCH
------------------------------------------------------- */

function searchStoredFiles5(
    userId,
    query,
    options = {}
) {
    const normalizedUser =
        normalizeFileUserId5(
            userId
        );

    const normalizedQuery =
        normalizeText(
            safeString(
                query,
                300
            )
        );

    let result =
        FILE_MEDIA_INDEX_5.filter(
            item =>
                item &&
                item.userId ===
                    normalizedUser
        );

    if (
        normalizedQuery
    ) {
        result =
            result.filter(
                item => {
                    const haystack =
                        normalizeText(
                            [
                                item.originalName,
                                item.category,
                                item.mimeType,
                                ...(item.tags || [])
                            ].join(" ")
                        );

                    return haystack.includes(
                        normalizedQuery
                    );
                }
            );
    }

    if (
        options.category
    ) {
        result =
            result.filter(
                item =>
                    item.category ===
                    safeString(
                        options.category,
                        50
                    ).toLowerCase()
            );
    }

    if (
        options.extension
    ) {
        const extension =
            safeString(
                options.extension,
                20
            ).toLowerCase();

        result =
            result.filter(
                item =>
                    getSafeExtension5(
                        item.originalName
                    ) === extension
            );
    }

    return result
        .slice(
            0,
            clamp(
                Number(
                    options.limit
                ) || 100,
                1,
                500
            )
        )
        .map(
            item => clone(item)
        );
}


/* -------------------------------------------------------
   5.22 - USER STORAGE STATS
------------------------------------------------------- */

function getUserFileStats5(userId) {
    const files =
        listUserFiles5(
            userId,
            {
                limit: 500
            }
        );

    const result = {
        userId:
            normalizeFileUserId5(
                userId
            ),

        files:
            files.length,

        totalBytes:
            files.reduce(
                (
                    total,
                    item
                ) =>
                    total +
                    Number(
                        item.size || 0
                    ),
                0
            ),

        categories: {
            image: 0,
            video: 0,
            audio: 0,
            document: 0,
            code: 0,
            other: 0
        },

        latest:
            files
                .slice(
                    0,
                    10
                )
    };

    for (const file of files) {
        if (
            result.categories[
                file.category
            ] !== undefined
        ) {
            result.categories[
                file.category
            ] += 1;
        }
    }

    return result;
}


/* -------------------------------------------------------
   5.23 - DUPLICATE FILE SEARCH
------------------------------------------------------- */

function findDuplicateFile5(
    userId,
    hash
) {
    const normalizedUser =
        normalizeFileUserId5(
            userId
        );

    const targetHash =
        safeString(
            hash,
            200
        );

    return (
        FILE_MEDIA_INDEX_5.find(
            item =>
                item &&
                item.userId ===
                    normalizedUser &&
                item.hash ===
                    targetHash
        ) || null
    );
}


/* -------------------------------------------------------
   5.24 - MEDIA SUMMARY
------------------------------------------------------- */

function createMediaSummary5(
    record
) {
    if (!record) {
        return null;
    }

    return {
        id:
            record.id,

        name:
            record.originalName,

        type:
            record.category,

        mimeType:
            record.mimeType,

        extension:
            getSafeExtension5(
                record.originalName
            ),

        size:
            record.size,

        createdAt:
            record.createdAt,

        readableSize:
            formatFileSize5(
                record.size
            )
    };
}

function formatFileSize5(bytes) {
    const size =
        Number(bytes);

    if (
        !Number.isFinite(size) ||
        size <= 0
    ) {
        return "0 B";
    }

    const units = [
        "B",
        "KB",
        "MB",
        "GB",
        "TB"
    ];

    const index =
        Math.min(
            Math.floor(
                Math.log(size) /
                Math.log(1024)
            ),
            units.length - 1
        );

    const value =
        size /
        (1024 ** index);

    const decimals =
        index === 0
            ? 0
            : index === 1
                ? 1
                : 2;

    return (
        `${value.toFixed(
            decimals
        )} ${units[index]}`
    );
}


/* -------------------------------------------------------
   5.25 - OPTIONAL MULTER ENGINE
------------------------------------------------------- */

let FILE_MEDIA_MULTER_5 = null;

try {
    if (
        typeof multer !== "undefined" &&
        multer
    ) {
        const multerStorage =
            multer.memoryStorage();

        FILE_MEDIA_MULTER_5 =
            multer({
                storage:
                    multerStorage,

                limits: {
                    fileSize:
                        FILE_MEDIA_CONFIG_5
                            .upload
                            .maxFileSizeMB *
                        1024 *
                        1024,

                    files:
                        FILE_MEDIA_CONFIG_5
                            .upload
                            .maxFilesPerRequest
                },

                fileFilter: (
                    req,
                    file,
                    callback
                ) => {
                    try {
                        if (
                            !isSafeFileName5(
                                file.originalname
                            )
                        ) {
                            return callback(
                                new Error(
                                    "Güvensiz dosya adı."
                                )
                            );
                        }

                        if (
                            !isAllowedExtension5(
                                file.originalname
                            )
                        ) {
                            return callback(
                                new Error(
                                    "Bu dosya türüne izin verilmiyor."
                                )
                            );
                        }

                        return callback(
                            null,
                            true
                        );

                    } catch (error) {
                        return callback(
                            error
                        );
                    }
                }
            });
    }
} catch (error) {
    FILE_MEDIA_MULTER_5 = null;
}


