app.post(
    "/api/files/upload",
    async (req, res) => {
        FILE_MEDIA_STATE_5.requests += 1;

        try {
            const userId =
                safeString(
                    req.body?.userId ||
                    req.body?.user ||
                    "anonymous",
                    120
                );

            const fileName =
                safeString(
                    req.body?.fileName ||
                    req.body?.name ||
                    "",
                    255
                );

            const data =
                req.body?.data ||
                req.body?.base64 ||
                "";

            if (!fileName) {
                throw new Error(
                    "fileName gerekli."
                );
            }

            if (!data) {
                throw new Error(
                    "data veya base64 gerekli."
                );
            }

            const result =
                await uploadBase64File5(
                    userId,
                    fileName,
                    data,
                    req.body?.mimeType
                );

            FILE_MEDIA_STATE_5.successfulRequests += 1;

            res.json({
                success: true,

                file:
                    createMediaSummary5(
                        result.record
                    ),

                record:
                    result.record,

                extractedText:
                    result.extractedText,

                extractedTextLength:
                    result.extractedTextLength
            });

        } catch (error) {
            FILE_MEDIA_STATE_5.failedRequests += 1;

            FILE_MEDIA_STATE_5.lastError = {
                message:
                    safeString(
                        error.message,
                        500
                    ),
                at:
                    nowISO()
            };

            res.status(400).json({
                success: false,
                error:
                    error.message
            });
        }
    }
);


/* -------------------------------------------------------
   5.27 - MULTIPART UPLOAD ROUTE
------------------------------------------------------- */

if (FILE_MEDIA_MULTER_5) {
    app.post(
        "/api/files/upload/multipart",
        FILE_MEDIA_MULTER_5.array(
            "files",
            FILE_MEDIA_CONFIG_5
                .upload
                .maxFilesPerRequest
        ),
        async (req, res) => {
            FILE_MEDIA_STATE_5.requests += 1;

            try {
                const userId =
                    safeString(
                        req.body?.userId ||
                        req.body?.user ||
                        "anonymous",
                        120
                    );

                const files =
                    Array.isArray(
                        req.files
                    )
                        ? req.files
                        : [];

                if (!files.length) {
                    throw new Error(
                        "Dosya seçilmedi."
                    );
                }

                const uploaded = [];
                const errors = [];

                for (const file of files) {
                    try {
                        const result =
                            await storeFileBuffer5({
                                userId,

                                originalName:
                                    file.originalname,

                                buffer:
                                    file.buffer,

                                mimeType:
                                    file.mimetype,

                                source:
                                    "multipart"
                            });

                        uploaded.push(
                            result.record
                        );

                    } catch (error) {
                        errors.push({
                            file:
                                file.originalname,

                            error:
                                error.message
                        });
                    }
                }

                FILE_MEDIA_STATE_5.successfulRequests += 1;

                res.json({
                    success:
                        uploaded.length > 0,

                    uploaded:
                        uploaded.map(
                            createMediaSummary5
                        ),

                    records:
                        uploaded,

                    errors,

                    count:
                        uploaded.length
                });

            } catch (error) {
                FILE_MEDIA_STATE_5.failedRequests += 1;

                res.status(400).json({
                    success: false,
                    error:
                        error.message
                });
            }
        }
    );
}


