/* -------------------------------------------------------
   5.45 - STORAGE CLEANUP
------------------------------------------------------- */

async function cleanupOldFiles5(
    options = {}
) {
    const retentionDays =
        clamp(
            Number(
                options.retentionDays
            ) ||
            FILE_MEDIA_CONFIG_5
                .storage
                .retentionDays,
            1,
            3650
        );

    const cutoff =
        Date.now() -
        retentionDays *
        24 *
        60 *
        60 *
        1000;

    const candidates =
        FILE_MEDIA_INDEX_5.filter(
            item => {
                const created =
                    Date.parse(
                        item.createdAt
                    );

                return (
                    Number.isFinite(
                        created
                    ) &&
                    created < cutoff
                );
            }
        );

    let deleted = 0;

    for (
        const record of candidates
    ) {
        try {
            await deleteStoredFile5(
                record.userId,
                record.id,
                {
                    trash:
                        false
                }
            );

            deleted += 1;

        } catch (error) {
            FILE_MEDIA_STATE_5.lastError = {
                message:
                    error.message,
                at:
                    nowISO()
            };
        }
    }

    return {
        success: true,
        deleted,
        checked:
            candidates.length,
        retentionDays
    };
}


