async function getAIFileContext5(
    userId,
    fileId,
    options = {}
) {
    const record =
        getFileRecord5(
            fileId
        );

    if (!record) {
        throw new Error(
            "Dosya bulunamadı."
        );
    }

    const normalizedUser =
        normalizeFileUserId5(
            userId
        );

    if (
        record.userId !==
        normalizedUser
    ) {
        throw new Error(
            "Bu dosyaya erişim yetkiniz yok."
        );
    }

    const result = {
        file:
            clone(record),

        text:
            "",

        usableForAI:
            false
    };

    if (
        isTextLikeFile5(
            record.originalName,
            record.mimeType
        )
    ) {
        const textResult =
            await extractTextFromFile5(
                record.path,
                record
            );

        if (textResult.success) {
            const maxChars =
                clamp(
                    Number(
                        options.maxChars
                    ) || 100000,
                    1000,
                    300000
                );

            result.text =
                textResult.text.slice(
                    0,
                    maxChars
                );

            result.usableForAI =
                true;
        }
    }

    return result;
}

app.get(
    "/api/files/:fileId/ai-context",
    async (req, res) => {
        try {
            const userId =
                safeString(
                    req.query.userId ||
                    req.query.user ||
                    "anonymous",
                    120
                );

            const result =
                await getAIFileContext5(
                    userId,
                    req.params.fileId,
                    {
                        maxChars:
                            req.query.maxChars
                    }
                );

            res.json({
                success: true,
                ...result
            });

        } catch (error) {
            res.status(400).json({
                success: false,
                error:
                    error.message
            });
        }
    }
);

serverState.files.ai =
    {
        context:
            getAIFileContext5
    };


