/* ======================================================
   6.53 - SOCKET.IO TASK EVENTS
====================================================== */

if (
    typeof io !== "undefined" &&
    io
) {
    io.on(
        "connection",
        socket => {

            socket.on(
                "turkai:task:list",
                payload => {
                    try {
                        const tasks =
                            task6List(
                                payload?.userId ||
                                "anonymous",
                                {
                                    status:
                                        payload?.status,

                                    type:
                                        payload?.type,

                                    search:
                                        payload?.search,

                                    limit:
                                        payload?.limit
                                }
                            );

                        socket.emit(
                            "turkai:task:list:result",
                            {
                                success:
                                    true,

                                tasks
                            }
                        );

                    } catch (error) {
                        socket.emit(
                            "turkai:task:list:result",
                            {
                                success:
                                    false,

                                error:
                                    error.message
                            }
                        );
                    }
                }
            );


            socket.on(
                "turkai:task:create",
                payload => {
                    try {
                        const task =
                            task6Create({
                                ...payload,
                                userId:
                                    payload?.userId ||
                                    "anonymous"
                            });

                        socket.emit(
                            "turkai:task:create:result",
                            {
                                success:
                                    true,

                                task
                            }
                        );

                    } catch (error) {
                        socket.emit(
                            "turkai:task:create:result",
                            {
                                success:
                                    false,

                                error:
                                    error.message
                            }
                        );
                    }
                }
            );


            socket.on(
                "turkai:task:complete",
                payload => {
                    try {
                        const task =
                            task6Complete(
                                payload?.userId ||
                                "anonymous",

                                payload?.taskId
                            );

                        socket.emit(
                            "turkai:task:complete:result",
                            {
                                success:
                                    true,

                                task
                            }
                        );

                    } catch (error) {
                        socket.emit(
                            "turkai:task:complete:result",
                            {
                                success:
                                    false,

                                error:
                                    error.message
                            }
                        );
                    }
                }
            );


            socket.on(
                "turkai:task:summary",
                payload => {
                    try {
                        const summary =
                            task6BuildSummary(
                                payload?.userId ||
                                "anonymous"
                            );

                        socket.emit(
                            "turkai:task:summary:result",
                            {
                                success:
                                    true,

                                summary
                            }
                        );

                    } catch (error) {
                        socket.emit(
                            "turkai:task:summary:result",
                            {
                                success:
                                    false,

                                error:
                                    error.message
                            }
                        );
                    }
                }
            );


            socket.on(
                "turkai:task:scheduler",
                async () => {
                    try {
                        const result =
                            await task6SchedulerTick();

                        socket.emit(
                            "turkai:task:scheduler:result",
                            result
                        );

                    } catch (error) {
                        socket.emit(
                            "turkai:task:scheduler:result",
                            {
                                success:
                                    false,

                                error:
                                    error.message
                            }
                        );
                    }
                }
            );
        }
    );
}


