/* ======================================================
   6.59 - STARTUP INDEX SYNC
====================================================== */

function task6RebuildGlobalIndex() {
    const rebuilt = [];

    for (
        const [
            userId,
            tasks
        ] of TASK_USER_CACHE_6.entries()
    ) {
        if (
            !Array.isArray(
                tasks
            )
        ) {
            continue;
        }

        for (
            const task of tasks
        ) {
            if (
                task &&
                task.id
            ) {
                rebuilt.push(
                    clone(task)
                );
            }
        }
    }

    if (
        rebuilt.length
    ) {
        TASK_GLOBAL_INDEX_6 =
            rebuilt;
    }

    writeJSON(
        TASK_GLOBAL_INDEX_FILE_6,
        TASK_GLOBAL_INDEX_6
    );

    return {
        success:
            true,

        tasks:
            TASK_GLOBAL_INDEX_6.length
    };
}


