/* ======================================================
   7.5 - USER FILES
====================================================== */

function plan7NormalizeUserId(
    userId
) {
    return (
        safeString(
            userId ||
            "anonymous",
            120
        )
            .replace(
                /[^a-zA-Z0-9_-]/g,
                "_"
            )
            .slice(
                0,
                80
            ) ||
        "anonymous"
    );
}

function plan7UserDirectory(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const directory =
        path.join(
            PLAN_USERS_ROOT_7,
            normalized
        );

    fs.mkdirSync(
        directory,
        {
            recursive:
                true
        }
    );

    return directory;
}

function plan7UserProfileFile(
    userId
) {
    return path.join(
        plan7UserDirectory(
            userId
        ),
        "profile.json"
    );
}

function plan7UserSubscriptionFile(
    userId
) {
    return path.join(
        plan7UserDirectory(
            userId
        ),
        "subscription.json"
    );
}

function plan7UserHistoryFile(
    userId
) {
    return path.join(
        plan7UserDirectory(
            userId
        ),
        "history.json"
    );
}

function plan7UserUsageFile(
    userId,
    period = null
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const key =
        period ||
        todayKey().slice(
            0,
            7
        );

    const usageDirectory =
        path.join(
            PLAN_USAGE_ROOT_7,
            normalized
        );

    fs.mkdirSync(
        usageDirectory,
        {
            recursive:
                true
        }
    );

    return path.join(
        usageDirectory,
        `${key}.json`
    );
}


/* ======================================================
   7.6 - PLAN HELPERS
====================================================== */

function plan7NormalizePlanId(
    planId
) {
    const value =
        safeString(
            planId ||
            "free",
            50
        ).trim().toLowerCase();

    return Object.prototype.hasOwnProperty.call(
        TURKAI_PLANS_7,
        value
    )
        ? value
        : "free";
}

function plan7GetPlan(
    planId
) {
    const normalized =
        plan7NormalizePlanId(
            planId
        );

    return clone(
        TURKAI_PLANS_7[
            normalized
        ]
    );
}

function plan7GetAllPlans(
    options = {}
) {
    const includeInternal =
        Boolean(
            options.includeInternal
        );

    return Object.values(
        TURKAI_PLANS_7
    )
        .filter(
            plan => {
                if (
                    includeInternal
                ) {
                    return true;
                }

                return (
                    plan.id !==
                        "developer"
                );
            }
        )
        .map(
            plan =>
                clone(plan)
        );
}

function plan7PlanOrder(
    planId
) {
    const order = [
        "free",
        "pro",
        "plus",
        "ultra",
        "developer"
    ];

    return order.indexOf(
        plan7NormalizePlanId(
            planId
        )
    );
}

function plan7IsUpgrade(
    from,
    to
) {
    return (
        plan7PlanOrder(to) >
        plan7PlanOrder(from)
    );
}

function plan7IsDowngrade(
    from,
    to
) {
    return (
        plan7PlanOrder(to) <
        plan7PlanOrder(from)
    );
}


/* ======================================================
   7.7 - BILLING PERIOD
====================================================== */

function plan7NormalizeBillingPeriod(
    period
) {
    const value =
        safeString(
            period ||
            "monthly",
            30
        ).toLowerCase();

    return (
        value === "annual" ||
        value === "yearly"
    )
        ? "annual"
        : "monthly";
}

function plan7GetPrice(
    planId,
    period
) {
    const plan =
        plan7GetPlan(
            planId
        );

    const billing =
        plan7NormalizeBillingPeriod(
            period
        );

    if (
        billing === "annual"
    ) {
        return Number(
            plan.priceAnnual
        ) || 0;
    }

    return Number(
        plan.priceMonthly
    ) || 0;
}


/* ======================================================
   7.8 - SUBSCRIPTION MODEL
====================================================== */

function plan7CreateSubscription(
    userId,
    options = {}
) {
    const normalizedUser =
        plan7NormalizeUserId(
            userId
        );

    const planId =
        plan7NormalizePlanId(
            options.planId
        );

    const period =
        plan7NormalizeBillingPeriod(
            options.billingPeriod
        );

    const now =
        new Date();

    const expires =
        new Date(
            now.getTime()
        );

    if (
        period === "annual"
    ) {
        expires.setFullYear(
            expires.getFullYear() + 1
        );
    } else {
        expires.setMonth(
            expires.getMonth() + 1
        );
    }

    return {
        id:
            `sub7_${Date.now()}_${createShortId()}`,

        userId:
            normalizedUser,

        planId,

        billingPeriod:
            period,

        status:
            "active",

        startedAt:
            now.toISOString(),

        expiresAt:
            expires.toISOString(),

        cancelledAt:
            null,

        cancelAtPeriodEnd:
            false,

        autoRenew:
            true,

        price:
            plan7GetPrice(
                planId,
                period
            ),

        currency:
            PLAN_ENGINE_CONFIG_7
                .currency,

        provider:
            PLAN_ENGINE_CONFIG_7
                .billing
                .provider,

        providerSubscriptionId:
            null,

        metadata:
            isObject(
                options.metadata
            )
                ? clone(
                    options.metadata
                )
                : {}
    };
}


/* ======================================================
   7.9 - DEFAULT USER PROFILE
====================================================== */

function plan7CreateDefaultProfile(
    userId,
    options = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    return {
        userId:
            normalized,

        displayName:
            safeString(
                options.displayName ||
                "",
                120
            ),

        email:
            safeString(
                options.email ||
                "",
                200
            ),

        planId:
            "free",

        role:
            "user",

        locale:
            "tr-TR",

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        flags: {
            verified:
                false,

            developer:
                false,

            staff:
                false
        },

        metadata:
            {}
    };
}

function plan7GetProfile(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    let profile =
        readJSON(
            plan7UserProfileFile(
                normalized
            ),
            null
        );

    if (
        !isObject(profile)
    ) {
        profile =
            plan7CreateDefaultProfile(
                normalized
            );

        writeJSON(
            plan7UserProfileFile(
                normalized
            ),
            profile
        );
    }

    return profile;
}

function plan7SaveProfile(
    userId,
    profile
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const safeProfile = {
        ...plan7CreateDefaultProfile(
            normalized
        ),
        ...clone(
            profile
        ),

        userId:
            normalized,

        updatedAt:
            nowISO()
    };

    writeJSON(
        plan7UserProfileFile(
            normalized
        ),
        safeProfile
    );

    return safeProfile;
}


/* ======================================================
   7.10 - SUBSCRIPTION GETTER
====================================================== */

function plan7GetSubscription(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    let subscription =
        readJSON(
            plan7UserSubscriptionFile(
                normalized
            ),
            null
        );

    if (
        !isObject(subscription)
    ) {
        subscription =
            plan7CreateSubscription(
                normalized,
                {
                    planId:
                        "free",

                    billingPeriod:
                        "monthly"
                }
            );

        subscription.provider =
            "local";

        writeJSON(
            plan7UserSubscriptionFile(
                normalized
            ),
            subscription
        );

        const profile =
            plan7GetProfile(
                normalized
            );

        if (
            !profile.planId
        ) {
            profile.planId =
                "free";

            plan7SaveProfile(
                normalized,
                profile
            );
        }
    }

    return subscription;
}


/* ======================================================
   7.11 - SUBSCRIPTION EXPIRY
====================================================== */

function plan7RefreshSubscriptionStatus(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const subscription =
        plan7GetSubscription(
            normalized
        );

    if (
        subscription.planId ===
        "free"
    ) {
        return subscription;
    }

    const expires =
        Date.parse(
            subscription.expiresAt ||
            ""
        );

    if (
        Number.isFinite(expires) &&
        expires <= Date.now() &&
        subscription.status === "active"
    ) {
        subscription.status =
            "expired";

        subscription.planId =
            "free";

        subscription.cancelledAt =
            nowISO();

        writeJSON(
            plan7UserSubscriptionFile(
                normalized
            ),
            subscription
        );

        const profile =
            plan7GetProfile(
                normalized
            );

        profile.planId =
            "free";

        plan7SaveProfile(
            normalized,
            profile
        );
    }

    return subscription;
}


/* ======================================================
   7.12 - FEATURE ACCESS
====================================================== */

function plan7HasFeature(
    userId,
    feature
) {
    const subscription =
        plan7RefreshSubscriptionStatus(
            userId
        );

    const plan =
        plan7GetPlan(
            subscription.planId
        );

    const key =
        safeString(
            feature,
            100
        );

    if (
        key === "chat"
    ) {
        return true;
    }

    return Boolean(
        plan[key]
    );
}

function plan7GetEntitlements(
    userId
) {
    const subscription =
        plan7RefreshSubscriptionStatus(
            userId
        );

    const plan =
        plan7GetPlan(
            subscription.planId
        );

    const entitlements = {};

    for (
        const feature of Object.keys(
            PLAN_FEATURES_7
        )
    ) {
        entitlements[feature] =
            Boolean(
                plan[feature]
            );
    }

    entitlements.messageLimit =
        Number(
            plan.messageLimit
        ) || 0;

    entitlements.imageDailyLimit =
        Number(
            plan.imageDailyLimit
        ) || 0;

    entitlements.videoDailyLimit =
        Number(
            plan.videoDailyLimit
        ) || 0;

    entitlements.researchLimit =
        Number(
            plan.researchLimit
        ) || 0;

    entitlements.fileUploadLimit =
        Number(
            plan.fileUploadLimit
        ) || 0;

    entitlements.maxFileSizeMB =
        Number(
            plan.maxFileSizeMB
        ) || 0;

    return {
        plan:
            clone(plan),

        subscription:
            clone(subscription),

        entitlements
    };
}


/* ======================================================
   7.13 - USAGE PERIOD
====================================================== */

function plan7UsagePeriodKey(
    date = new Date()
) {
    return (
        date
            .toISOString()
            .slice(
                0,
                10
            )
    );
}

function plan7DailyKey(
    date = new Date()
) {
    return (
        date
            .toISOString()
            .slice(
                0,
                10
            )
    );
}


/* ======================================================
   7.14 - DEFAULT USAGE
====================================================== */

function plan7CreateDefaultUsage(
    userId
) {
    return {
        userId:
            plan7NormalizeUserId(
                userId
            ),

        period:
            plan7UsagePeriodKey(),

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        messages: {
            used:
                0
        },

        research: {
            used:
                0
        },

        files: {
            uploaded:
                0,

            bytes:
                0
        },

        images: {
            used:
                0,

            date:
                plan7DailyKey()
        },

        videos: {
            used:
                0,

            date:
                plan7DailyKey()
        },

        api: {
            used:
                0
        },

        other: {},

        history: []
    };
}


/* ======================================================
   7.15 - USAGE LOAD
====================================================== */

function plan7GetUsage(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const period =
        plan7UsagePeriodKey();

    const file =
        plan7UserUsageFile(
            normalized,
            period
        );

    let usage =
        readJSON(
            file,
            null
        );

    if (
        !isObject(usage)
    ) {
        usage =
            plan7CreateDefaultUsage(
                normalized
            );

        writeJSON(
            file,
            usage
        );
    }

    if (
        usage.period !==
        period
    ) {
        usage =
            plan7CreateDefaultUsage(
                normalized
            );

        writeJSON(
            file,
            usage
        );
    }

    const today =
        plan7DailyKey();

    if (
        usage.images?.date !== today
    ) {
        usage.images = {
            used:
                0,

            date:
                today
        };
    }

    if (
        usage.videos?.date !== today
    ) {
        usage.videos = {
            used:
                0,

            date:
                today
        };
    }

    return usage;
}

function plan7SaveUsage(
    userId,
    usage
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    usage.updatedAt =
        nowISO();

    writeJSON(
        plan7UserUsageFile(
            normalized,
            usage.period ||
                plan7UsagePeriodKey()
        ),
        usage
    );

    return usage;
}


/* ======================================================
   7.16 - USAGE LIMIT RESOLUTION
====================================================== */

function plan7GetUsageLimit(
    userId,
    resource
) {
    const subscription =
        plan7RefreshSubscriptionStatus(
            userId
        );

    const plan =
        plan7GetPlan(
            subscription.planId
        );

    const limits = {
        messages:
            Number(
                plan.messageLimit
            ) || 0,

        research:
            Number(
                plan.researchLimit
            ) || 0,

        image:
            Number(
                plan.imageDailyLimit
            ) || 0,

        images:
            Number(
                plan.imageDailyLimit
            ) || 0,

        video:
            Number(
                plan.videoDailyLimit
            ) || 0,

        videos:
            Number(
                plan.videoDailyLimit
            ) || 0,

        uploads:
            Number(
                plan.fileUploadLimit
            ) || 0,

        api:
            plan.apiAccess
                ? Number(
                    plan.messageLimit
                ) * 2
                : 0
    };

    return (
        limits[
            safeString(
                resource,
                50
            )
        ] ??
        0
    );
}

function plan7GetUsageValue(
    usage,
    resource
) {
    switch (
        safeString(
            resource,
            50
        )
    ) {
        case "messages":
            return Number(
                usage.messages?.used
            ) || 0;

        case "research":
            return Number(
                usage.research?.used
            ) || 0;

        case "image":
        case "images":
            return Number(
                usage.images?.used
            ) || 0;

        case "video":
        case "videos":
            return Number(
                usage.videos?.used
            ) || 0;

        case "uploads":
            return Number(
                usage.files?.uploaded
            ) || 0;

        case "api":
            return Number(
                usage.api?.used
            ) || 0;

        default:
            return Number(
                usage.other?.[
                    resource
                ]
            ) || 0;
    }
}


/* ======================================================
   7.17 - USAGE CHECK
====================================================== */

function plan7CheckUsage(
    userId,
    resource,
    amount = 1
) {
    PLAN_ENGINE_STATE_7
        .usageChecks += 1;

    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const safeAmount =
        Math.max(
            0,
            Number(
                amount
            ) || 0
        );

    const usage =
        plan7GetUsage(
            normalized
        );

    const limit =
        plan7GetUsageLimit(
            normalized,
            resource
        );

    const used =
        plan7GetUsageValue(
            usage,
            resource
        );

    const remaining =
        Math.max(
            0,
            limit - used
        );

    const allowed =
        limit === 0
            ? false
            : used +
                    safeAmount <=
                limit;

    if (
        !allowed
    ) {
        PLAN_ENGINE_STATE_7
            .usageLimitHits += 1;
    }

    return {
        userId:
            normalized,

        resource:
            safeString(
                resource,
                50
            ),

        requested:
            safeAmount,

        used,

        limit,

        remaining,

        allowed,

        unlimited:
            false
    };
}


/* ======================================================
   7.18 - USAGE CONSUME
====================================================== */

function plan7ConsumeUsage(
    userId,
    resource,
    amount = 1,
    metadata = {}
) {
    PLAN_ENGINE_STATE_7
        .usageConsumes += 1;

    const check =
        plan7CheckUsage(
            userId,
            resource,
            amount
        );

    if (
        !check.allowed
    ) {
        return {
            success:
                false,

            ...check,

            reason:
                "usage-limit"
        };
    }

    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const safeAmount =
        Math.max(
            0,
            Number(
                amount
            ) || 0
        );

    const usage =
        plan7GetUsage(
            normalized
        );

    const resourceKey =
        safeString(
            resource,
            50
        );

    if (
        resourceKey ===
        "messages"
    ) {
        usage.messages.used +=
            safeAmount;
    } else if (
        resourceKey ===
        "research"
    ) {
        usage.research.used +=
            safeAmount;
    } else if (
        resourceKey ===
            "image" ||
        resourceKey ===
            "images"
    ) {
        usage.images.used +=
            safeAmount;
    } else if (
        resourceKey ===
            "video" ||
        resourceKey ===
            "videos"
    ) {
        usage.videos.used +=
            safeAmount;
    } else if (
        resourceKey ===
        "uploads"
    ) {
        usage.files.uploaded +=
            safeAmount;
    } else if (
        resourceKey ===
        "api"
    ) {
        usage.api.used +=
            safeAmount;
    } else {
        usage.other[
            resourceKey
        ] =
            Number(
                usage.other[
                    resourceKey
                ]
            ) +
            safeAmount;
    }

    usage.history.unshift({
        id:
            `use7_${createShortId()}`,

        resource:
            resourceKey,

        amount:
            safeAmount,

        createdAt:
            nowISO(),

        metadata:
            isObject(
                metadata
            )
                ? clone(
                    metadata
                )
                : {}
    });

    if (
        usage.history.length >
        PLAN_ENGINE_CONFIG_7
            .usage
            .historyLimit
    ) {
        usage.history =
            usage.history.slice(
                0,
                PLAN_ENGINE_CONFIG_7
                    .usage
                    .historyLimit
            );
    }

    plan7SaveUsage(
        normalized,
        usage
    );

    PLAN_ENGINE_STATE_7
        .lastUsageAt =
        nowISO();

    PLAN_GLOBAL_STATS_7
        .usageConsumes +=
        1;

    writeJSON(
        PLAN_GLOBAL_STATS_FILE_7,
        PLAN_GLOBAL_STATS_7
    );

    return {
        success:
            true,

        ...plan7CheckUsage(
            normalized,
            resource,
            0
        ),

        consumed:
            safeAmount
    };
}


/* ======================================================
   7.19 - USAGE SUMMARY
====================================================== */

function plan7UsageSummary(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const subscription =
        plan7RefreshSubscriptionStatus(
            normalized
        );

    const plan =
        plan7GetPlan(
            subscription.planId
        );

    const usage =
        plan7GetUsage(
            normalized
        );

    return {
        userId:
            normalized,

        plan:
            {
                id:
                    plan.id,

                name:
                    plan.displayName
            },

        period:
            usage.period,

        messages: {
            used:
                usage.messages.used,

            limit:
                plan.messageLimit,

            remaining:
                Math.max(
                    0,
                    plan.messageLimit -
                        usage.messages.used
                )
        },

        research: {
            used:
                usage.research.used,

            limit:
                plan.researchLimit,

            remaining:
                Math.max(
                    0,
                    plan.researchLimit -
                        usage.research.used
                )
        },

        images: {
            used:
                usage.images.used,

            limit:
                plan.imageDailyLimit,

            remaining:
                Math.max(
                    0,
                    plan.imageDailyLimit -
                        usage.images.used
                ),

            date:
                usage.images.date
        },

        videos: {
            used:
                usage.videos.used,

            limit:
                plan.videoDailyLimit,

            remaining:
                Math.max(
                    0,
                    plan.videoDailyLimit -
                        usage.videos.used
                ),

            date:
                usage.videos.date
        },

        files: {
            uploaded:
                usage.files.uploaded,

            limit:
                plan.fileUploadLimit,

            remaining:
                Math.max(
                    0,
                    plan.fileUploadLimit -
                        usage.files.uploaded
                ),

            bytes:
                usage.files.bytes
        },

        api: {
            used:
                usage.api.used,

            limit:
                plan.apiAccess
                    ? plan.messageLimit * 2
                    : 0
        }
    };
}


/* ======================================================
   7.20 - SUBSCRIPTION SAVE
====================================================== */

function plan7SaveSubscription(
    userId,
    subscription
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    writeJSON(
        plan7UserSubscriptionFile(
            normalized
        ),
        subscription
    );

    const profile =
        plan7GetProfile(
            normalized
        );

    profile.planId =
        subscription.planId;

    profile.updatedAt =
        nowISO();

    plan7SaveProfile(
        normalized,
        profile
    );

    return subscription;
}


/* ======================================================
   7.21 - PLAN CHANGE HISTORY
====================================================== */

function plan7AddHistory(
    userId,
    action,
    extra = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const item = {
        id:
            `planhist7_${createShortId()}`,

        userId:
            normalized,

        action:
            safeString(
                action,
                100
            ),

        createdAt:
            nowISO(),

        ...clone(
            extra
        )
    };

    const userHistory =
        readJSON(
            plan7UserHistoryFile(
                normalized
            ),
            []
        );

    const safeHistory =
        Array.isArray(
            userHistory
        )
            ? userHistory
            : [];

    safeHistory.unshift(
        item
    );

    writeJSON(
        plan7UserHistoryFile(
            normalized
        ),
        safeHistory.slice(
            0,
            1000
        )
    );

    PLAN_GLOBAL_HISTORY_7.unshift(
        item
    );

    if (
        PLAN_GLOBAL_HISTORY_7.length >
        5000
    ) {
        PLAN_GLOBAL_HISTORY_7 =
            PLAN_GLOBAL_HISTORY_7.slice(
                0,
                5000
            );
    }

    writeJSON(
        PLAN_GLOBAL_HISTORY_FILE_7,
        PLAN_GLOBAL_HISTORY_7
    );

    return item;
}


/* ======================================================
   7.22 - SUBSCRIPTION CHANGE
====================================================== */

function plan7ChangePlan(
    userId,
    newPlanId,
    options = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const targetPlan =
        plan7NormalizePlanId(
            newPlanId
        );

    const currentSubscription =
        plan7RefreshSubscriptionStatus(
            normalized
        );

    const currentPlan =
        currentSubscription.planId;

    if (
        currentPlan ===
        targetPlan
    ) {
        return {
            success:
                true,

            changed:
                false,

            subscription:
                clone(
                    currentSubscription
                ),

            message:
                "Kullanıcı zaten bu planda."
        };
    }

    /*
       Güvenlik:
       frontend doğrudan developer / ultra yetkisi
       veremez.
    */
    if (
        targetPlan ===
        "developer" &&
        !options.allowDeveloper
    ) {
        throw new Error(
            "Developer planı doğrudan etkinleştirilemez."
        );
    }

    if (
        targetPlan ===
        "ultra" &&
        PLAN_ENGINE_CONFIG_7
            .security
            .allowSelfUltra ===
            false &&
        options.paymentConfirmed !== true
    ) {
        throw new Error(
            "Ultra planı ödeme doğrulaması bekliyor."
        );
    }

    const upgrading =
        plan7IsUpgrade(
            currentPlan,
            targetPlan
        );

    const downgrading =
        plan7IsDowngrade(
            currentPlan,
            targetPlan
        );

    const billingPeriod =
        plan7NormalizeBillingPeriod(
            options.billingPeriod
        );

    const subscription =
        plan7CreateSubscription(
            normalized,
            {
                planId:
                    targetPlan,

                billingPeriod,

                metadata:
                    options.metadata
            }
        );

    subscription.previousPlan =
        currentPlan;

    subscription.changeType =
        upgrading
            ? "upgrade"
            : downgrading
                ? "downgrade"
                : "change";

    if (
        options.paymentConfirmed ===
        true
    ) {
        subscription.provider =
            PLAN_ENGINE_CONFIG_7
                .billing
                .provider;
    } else {
        subscription.provider =
            "local-pending";
    }

    plan7SaveSubscription(
        normalized,
        subscription
    );

    if (
        upgrading
    ) {
        PLAN_ENGINE_STATE_7
            .upgradedSubscriptions +=
            1;

        PLAN_GLOBAL_STATS_7
            .upgrades +=
            1;
    }

    if (
        downgrading
    ) {
        PLAN_ENGINE_STATE_7
            .downgradedSubscriptions +=
            1;

        PLAN_GLOBAL_STATS_7
            .downgrades +=
            1;
    }

    PLAN_ENGINE_STATE_7
        .lastPlanChangeAt =
        nowISO();

    plan7AddHistory(
        normalized,
        "plan_changed",
        {
            from:
                currentPlan,

            to:
                targetPlan,

            changeType:
                subscription.changeType,

            billingPeriod
        }
    );

    writeJSON(
        PLAN_GLOBAL_STATS_FILE_7,
        PLAN_GLOBAL_STATS_7
    );

    return {
        success:
            true,

        changed:
            true,

        previousPlan:
            currentPlan,

        plan:
            clone(
                plan7GetPlan(
                    targetPlan
                )
            ),

        subscription:
            clone(
                subscription
            )
    };
}


/* ======================================================
   7.23 - SUBSCRIPTION CREATE
====================================================== */

function plan7ActivateSubscription(
    userId,
    planId,
    options = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const target =
        plan7NormalizePlanId(
            planId
        );

    const current =
        plan7GetSubscription(
            normalized
        );

    if (
        current &&
        current.planId ===
        target &&
        current.status ===
            "active"
    ) {
        return {
            success:
                true,

            changed:
                false,

            subscription:
                clone(current)
        };
    }

    const result =
        plan7ChangePlan(
            normalized,
            target,
            {
                ...options,

                paymentConfirmed:
                    options.paymentConfirmed ===
                    true
            }
        );

    PLAN_ENGINE_STATE_7
        .createdSubscriptions +=
        1;

    PLAN_GLOBAL_STATS_7
        .subscriptions +=
        1;

    writeJSON(
        PLAN_GLOBAL_STATS_FILE_7,
        PLAN_GLOBAL_STATS_7
    );

    return result;
}


/* ======================================================
   7.24 - CANCEL SUBSCRIPTION
====================================================== */

function plan7CancelSubscription(
    userId,
    options = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const subscription =
        plan7RefreshSubscriptionStatus(
            normalized
        );

    if (
        subscription.planId ===
        "free"
    ) {
        return {
            success:
                true,

            changed:
                false,

            message:
                "Free plan zaten iptal edilemez."
        };
    }

    const immediate =
        Boolean(
            options.immediate
        );

    if (
        immediate
    ) {
        subscription.planId =
            "free";

        subscription.status =
            "cancelled";

        subscription.cancelledAt =
            nowISO();

        subscription.cancelAtPeriodEnd =
            false;

        plan7SaveSubscription(
            normalized,
            subscription
        );

        const profile =
            plan7GetProfile(
                normalized
            );

        profile.planId =
            "free";

        plan7SaveProfile(
            normalized,
            profile
        );

    } else {
        subscription.cancelAtPeriodEnd =
            true;

        subscription.autoRenew =
            false;

        subscription.status =
            "active";

        subscription.cancelledAt =
            nowISO();

        writeJSON(
            plan7UserSubscriptionFile(
                normalized
            ),
            subscription
        );
    }

    PLAN_ENGINE_STATE_7
        .cancelledSubscriptions +=
        1;

    PLAN_GLOBAL_STATS_7
        .cancellations +=
        1;

    PLAN_ENGINE_STATE_7
        .lastPlanChangeAt =
        nowISO();

    plan7AddHistory(
        normalized,
        "subscription_cancelled",
        {
            immediate
        }
    );

    writeJSON(
        PLAN_GLOBAL_STATS_FILE_7,
        PLAN_GLOBAL_STATS_7
    );

    return {
        success:
            true,

        immediate,

        subscription:
            clone(
                subscription
            )
    };
}


/* ======================================================
   7.25 - BILLING ORDER
====================================================== */

function plan7CreateBillingOrder(
    userId,
    planId,
    period = "monthly",
    options = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const targetPlan =
        plan7NormalizePlanId(
            planId
        );

    const billingPeriod =
        plan7NormalizeBillingPeriod(
            period
        );

    const price =
        plan7GetPrice(
            targetPlan,
            billingPeriod
        );

    const order = {
        id:
            `order7_${Date.now()}_${createShortId()}`,

        userId:
            normalized,

        planId:
            targetPlan,

        billingPeriod,

        amount:
            price,

        currency:
            PLAN_ENGINE_CONFIG_7
                .currency,

        status:
            price === 0
                ? "free"
                : "pending",

        provider:
            PLAN_ENGINE_CONFIG_7
                .billing
                .provider,

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        paidAt:
            null,

        metadata:
            isObject(
                options.metadata
            )
                ? clone(
                    options.metadata
                )
                : {}
    };

    PLAN_BILLING_ORDERS_7.unshift(
        order
    );

    if (
        PLAN_BILLING_ORDERS_7.length >
        5000
    ) {
        PLAN_BILLING_ORDERS_7 =
            PLAN_BILLING_ORDERS_7.slice(
                0,
                5000
            );
    }

    writeJSON(
        PLAN_BILLING_ORDERS_FILE_7,
        PLAN_BILLING_ORDERS_7
    );

    PLAN_ENGINE_STATE_7
        .billingOrders +=
        1;

    PLAN_ENGINE_STATE_7
        .lastBillingAt =
        nowISO();

    plan7AddHistory(
        normalized,
        "billing_order_created",
        {
            orderId:
                order.id,

            planId:
                targetPlan,

            amount:
                price,

            billingPeriod
        }
    );

    return clone(
        order
    );
}


/* ======================================================
   7.26 - BILLING PAYMENT SIMULATION
====================================================== */

function plan7SimulatePayment(
    orderId,
    options = {}
) {
    const id =
        safeString(
            orderId,
            200
        );

    const index =
        PLAN_BILLING_ORDERS_7.findIndex(
            item =>
                item &&
                item.id ===
                    id
        );

    if (
        index === -1
    ) {
        throw new Error(
            "Billing siparişi bulunamadı."
        );
    }

    const order =
        PLAN_BILLING_ORDERS_7[
            index
        ];

    if (
        order.status ===
        "paid"
    ) {
        return {
            success:
                true,

            order:
                clone(order),

            alreadyPaid:
                true
        };
    }

    if (
        order.amount > 0 &&
        options.confirm !== true
    ) {
        throw new Error(
            "Test ödeme için confirm=true gerekli."
        );
    }

    order.status =
        "paid";

    order.paidAt =
        nowISO();

    order.updatedAt =
        nowISO();

    PLAN_BILLING_ORDERS_7[
        index
    ] =
        order;

    writeJSON(
        PLAN_BILLING_ORDERS_FILE_7,
        PLAN_BILLING_ORDERS_7
    );

    PLAN_ENGINE_STATE_7
        .simulatedPayments +=
        1;

    return {
        success:
            true,

        order:
            clone(order)
    };
}


/* ======================================================
   7.27 - PAYMENT CONFIRMED PLAN ACTIVATION
====================================================== */

function plan7ActivatePaidOrder(
    orderId
) {
    const order =
        PLAN_BILLING_ORDERS_7.find(
            item =>
                item &&
                item.id ===
                    safeString(
                        orderId,
                        200
                    )
        );

    if (!order) {
        throw new Error(
            "Sipariş bulunamadı."
        );
    }

    if (
        order.status !==
            "paid" &&
        order.amount > 0
    ) {
        throw new Error(
            "Ödeme doğrulanmadan plan etkinleştirilemez."
        );
    }

    const result =
        plan7ActivateSubscription(
            order.userId,
            order.planId,
            {
                billingPeriod:
                    order.billingPeriod,

                paymentConfirmed:
                    true,

                metadata: {
                    orderId:
                        order.id,

                    provider:
                        order.provider
                }
            }
        );

    order.status =
        "activated";

    order.updatedAt =
        nowISO();

    writeJSON(
        PLAN_BILLING_ORDERS_FILE_7,
        PLAN_BILLING_ORDERS_7
    );

    return {
        success:
            true,

        order:
            clone(order),

        activation:
            result
    };
}


/* ======================================================
   7.28 - PLAN COMPARISON
====================================================== */

function plan7ComparePlans(
    options = {}
) {
    const includeInternal =
        Boolean(
            options.includeInternal
        );

    const plans =
        plan7GetAllPlans(
            {
                includeInternal
            }
        );

    const featureKeys =
        Object.keys(
            PLAN_FEATURES_7
        );

    return {
        generatedAt:
            nowISO(),

        currency:
            PLAN_ENGINE_CONFIG_7
                .currency,

        plans:
            plans.map(
                plan => ({
                    id:
                        plan.id,

                    name:
                        plan.displayName,

                    priceMonthly:
                        plan.priceMonthly,

                    priceAnnual:
                        plan.priceAnnual,

                    annualDiscountPercent:
                        plan.annualDiscountPercent,

                    messageLimit:
                        plan.messageLimit,

                    imageDailyLimit:
                        plan.imageDailyLimit,

                    videoDailyLimit:
                        plan.videoDailyLimit,

                    features:
                        Object.fromEntries(
                            featureKeys.map(
                                key => [
                                    key,
                                    Boolean(
                                        plan[key]
                                    )
                                ]
                            )
                        ),

                    status:
                        plan.status ||
                        "active"
                })
            )
    };
}


/* ======================================================
   7.29 - ACCOUNT SNAPSHOT
====================================================== */

function plan7GetAccountSnapshot(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const profile =
        plan7GetProfile(
            normalized
        );

    const subscription =
        plan7RefreshSubscriptionStatus(
            normalized
        );

    const plan =
        plan7GetPlan(
            subscription.planId
        );

    const usage =
        plan7UsageSummary(
            normalized
        );

    const entitlements =
        plan7GetEntitlements(
            normalized
        );

    return {
        user: {
            userId:
                normalized,

            displayName:
                profile.displayName,

            email:
                profile.email,

            role:
                profile.role,

            locale:
                profile.locale,

            createdAt:
                profile.createdAt
        },

        plan:
            clone(plan),

        subscription:
            clone(subscription),

        usage,

        entitlements:
            entitlements.entitlements,

        flags:
            clone(
                profile.flags || {}
            ),

        generatedAt:
            nowISO()
    };
}


/* ======================================================
   7.30 - ACCOUNT FEATURE MAP
====================================================== */

function plan7BuildFeatureMap(
    userId
) {
    const snapshot =
        plan7GetAccountSnapshot(
            userId
        );

    const result = {};

    for (
        const [
            key,
            feature
        ] of Object.entries(
            PLAN_FEATURES_7
        )
    ) {
        result[key] = {
            enabled:
                Boolean(
                    snapshot
                        .entitlements[
                            key
                        ]
                ),

            label:
                feature.label,

            description:
                feature.description
        };
    }

    return {
        plan:
            snapshot.plan.id,

        planName:
            snapshot.plan.displayName,

        features:
            result
    };
}


/* ======================================================
   7.31 - ACCOUNT PROFILE UPDATE
====================================================== */

function plan7UpdateProfile(
    userId,
    updates = {}
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const profile =
        plan7GetProfile(
            normalized
        );

    if (
        updates.displayName !==
        undefined
    ) {
        profile.displayName =
            safeString(
                updates.displayName,
                120
            ).trim();
    }

    if (
        updates.email !==
        undefined
    ) {
        profile.email =
            safeString(
                updates.email,
                200
            ).trim();
    }

    if (
        updates.locale !==
        undefined
    ) {
        profile.locale =
            safeString(
                updates.locale,
                20
            ).trim();
    }

    if (
        isObject(
            updates.metadata
        )
    ) {
        profile.metadata =
            {
                ...profile.metadata,
                ...clone(
                    updates.metadata
                )
            };
    }

    plan7SaveProfile(
        normalized,
        profile
    );

    plan7AddHistory(
        normalized,
        "profile_updated"
    );

    return clone(
        profile
    );
}


/* ======================================================
   7.32 - RESOURCE ACCESS HELPER
====================================================== */

function plan7RequireFeature(
    userId,
    feature
) {
    const allowed =
        plan7HasFeature(
            userId,
            feature
        );

    if (!allowed) {
        throw new Error(
            `Bu özellik mevcut planınızda aktif değil: ${feature}`
        );
    }

    return {
        allowed:
            true,

        feature:
            safeString(
                feature,
                100
            )
    };
}


