/* ======================================================
   7.45 - SUBSCRIPTION UPGRADE
====================================================== */

app.post(
    "/api/account/upgrade",
    (req, res) => {
        PLAN_ENGINE_STATE_7
            .requests += 1;

        try {
            const userId =
                req.body.userId ||
                "anonymous";

            const targetPlan =
                req.body.planId ||
                "pro";

            const order =
                plan7CreateBillingOrder(
                    userId,
                    targetPlan,
                    req.body.billingPeriod ||
                        "monthly",
                    {
                        metadata:
                            {
                                source:
                                    "upgrade"
                            }
                    }
                );

            /*
               Free planlar için direkt aktifleşme.
               Ücretli planlar ödeme bekler.
            */
            if (
                order.amount === 0
            ) {
                const activation =
                    plan7ActivateSubscription(
                        userId,
                        targetPlan,
                        {
                            billingPeriod:
                                order.billingPeriod,

                            paymentConfirmed:
                                true
                        }
                    );

                PLAN_ENGINE_STATE_7
                    .successfulRequests +=
                    1;

                return res.json({
                    success:
                        true,

                    order,

                    activation
                });
            }

            PLAN_ENGINE_STATE_7
                .successfulRequests +=
                1;

            return res.json({
                success:
                    true,

                pendingPayment:
                    true,

                order,

                message:
                    "Plan değişimi ödeme doğrulamasından sonra etkinleşecektir."
            });

        } catch (error) {
            PLAN_ENGINE_STATE_7
                .failedRequests +=
                1;

            res.status(400).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    }
);


