/* ======================================================
   7.58 - PLAN GATE MIDDLEWARE FACTORY
====================================================== */

function plan7FeatureGate(
    feature
) {
    return (
        req,
        res,
        next
    ) => {
        try {
            const userId =
                req.body?.userId ||
                req.query?.userId ||
                req.headers[
                    "x-user-id"
                ] ||
                "anonymous";

            plan7RequireFeature(
                userId,
                feature
            );

            req.turkAIPlan =
                plan7GetAccountSnapshot(
                    userId
                );

            next();

        } catch (error) {
            res.status(403).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    };
}

serverState.planFeatureGate7 =
    plan7FeatureGate;


/* ======================================================
   7.59 - USAGE MIDDLEWARE FACTORY
====================================================== */

function plan7UsageGate(
    resource,
    amount = 1
) {
    return (
        req,
        res,
        next
    ) => {
        try {
            const userId =
                req.body?.userId ||
                req.query?.userId ||
                req.headers[
                    "x-user-id"
                ] ||
                "anonymous";

            const check =
                plan7CheckUsage(
                    userId,
                    resource,
                    amount
                );

            if (
                !check.allowed
            ) {
                return res.status(
                    429
                ).json({
                    success:
                        false,

                    error:
                        "Kullanım limiti doldu.",

                    ...check
                });
            }

            req.turkAIUsage =
                check;

            return next();

        } catch (error) {
            return res.status(
                400
            ).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    };
}

serverState.planUsageGate7 =
    plan7UsageGate;


