function plan7ResetDailyUsage(
    userId
) {
    const normalized =
        plan7NormalizeUserId(
            userId
        );

    const usage =
        plan7GetUsage(
            normalized
        );

    const today =
        plan7DailyKey();

    usage.images = {
        used:
            0,

        date:
            today
    };

    usage.videos = {
        used:
            0,

        date:
            today
    };

    usage.updatedAt =
        nowISO();

    plan7SaveUsage(
        normalized,
        usage
    );

    return usage;
}

