/* ======================================================
   8.5 - USER DIRECTORY HELPERS
====================================================== */

function security8NormalizeUserId(
    value
) {
    return (
        safeString(
            value ||
            "anonymous",
            150
        )
            .trim()
            .replace(
                /[^a-zA-Z0-9._-]/g,
                "_"
            )
            .slice(
                0,
                90
            ) ||
        "anonymous"
    );
}

function security8UserFile(
    userId
) {
    return path.join(
        SECURITY_USERS_ROOT_8,
        `${security8NormalizeUserId(userId)}.json`
    );
}

function security8SessionFile(
    sessionId
) {
    const safe =
        safeString(
            sessionId,
            250
        ).replace(
            /[^a-zA-Z0-9._-]/g,
            "_"
        );

    return path.join(
        SECURITY_SESSIONS_ROOT_8,
        `${safe}.json`
    );
}

function security8ApiKeyFile(
    keyId
) {
    const safe =
        safeString(
            keyId,
            250
        ).replace(
            /[^a-zA-Z0-9._-]/g,
            "_"
        );

    return path.join(
        SECURITY_KEYS_ROOT_8,
        `${safe}.json`
    );
}


/* ======================================================
   8.6 - RANDOM ID HELPERS
====================================================== */

function security8RandomHex(
    bytes = 32
) {
    return SECURITY_CRYPTO_8
        .randomBytes(
            bytes
        )
        .toString(
            "hex"
        );
}

function security8RandomBase64Url(
    bytes = 32
) {
    return SECURITY_CRYPTO_8
        .randomBytes(
            bytes
        )
        .toString(
            "base64url"
        );
}

function security8CreateId(
    prefix
) {
    return (
        `${prefix}_${Date.now()}_` +
        `${security8RandomBase64Url(9)}`
    );
}


/* ======================================================
   8.7 - CONSTANT-TIME COMPARE
====================================================== */

function security8SafeEqual(
    a,
    b
) {
    const first =
        Buffer.from(
            String(a || "")
        );

    const second =
        Buffer.from(
            String(b || "")
        );

    if (
        first.length !==
        second.length
    ) {
        return false;
    }

    return SECURITY_CRYPTO_8
        .timingSafeEqual(
            first,
            second
        );
}


/* ======================================================
   8.8 - HMAC SIGNING SECRET
====================================================== */

const SECURITY_TOKEN_SECRET_8 =
    safeString(
        process.env.TURKAI_TOKEN_SECRET ||
        process.env.JWT_SECRET ||
        "",
        500
    ) ||
    security8RandomHex(
        64
    );

function security8Sign(
    value
) {
    return SECURITY_CRYPTO_8
        .createHmac(
            "sha256",
            SECURITY_TOKEN_SECRET_8
        )
        .update(
            String(value)
        )
        .digest(
            "base64url"
        );
}


/* ======================================================
   8.9 - PASSWORD VALIDATION
====================================================== */

function security8ValidatePassword(
    password
) {
    const value =
        String(
            password ??
            ""
        );

    if (
        value.length <
        SECURITY_ENGINE_CONFIG_8
            .password
            .minLength
    ) {
        return {
            valid:
                false,

            error:
                `Parola en az ${SECURITY_ENGINE_CONFIG_8.password.minLength} karakter olmalı.`
        };
    }

    if (
        value.length >
        SECURITY_ENGINE_CONFIG_8
            .password
            .maxLength
    ) {
        return {
            valid:
                false,

            error:
                "Parola çok uzun."
        };
    }

    return {
        valid:
            true
    };
}


/* ======================================================
   8.10 - SCRYPT PASSWORD HASH
====================================================== */

async function security8HashPassword(
    password
) {
    const validation =
        security8ValidatePassword(
            password
        );

    if (
        !validation.valid
    ) {
        throw new Error(
            validation.error
        );
    }

    const salt =
        SECURITY_CRYPTO_8
            .randomBytes(
                SECURITY_ENGINE_CONFIG_8
                    .password
                    .scrypt
                    .saltLength
            );

    const options =
        SECURITY_ENGINE_CONFIG_8
            .password
            .scrypt;

    const derivedKey =
        await new Promise(
            (
                resolve,
                reject
            ) => {
                SECURITY_CRYPTO_8
                    .scrypt(
                        String(
                            password
                        ),
                        salt,
                        options.keyLength,
                        {
                            N:
                                options.N,

                            r:
                                options.r,

                            p:
                                options.p,

                            maxmem:
                                128 *
                                options.N *
                                options.r +
                                1024 *
                                1024
                        },
                        (
                            error,
                            key
                        ) => {
                            if (
                                error
                            ) {
                                reject(
                                    error
                                );
                            } else {
                                resolve(
                                    key
                                );
                            }
                        }
                    );
            }
        );

    return {
        algorithm:
            "scrypt",

        salt:
            salt.toString(
                "base64url"
            ),

        hash:
            Buffer.from(
                derivedKey
            ).toString(
                "base64url"
            ),

        params: {
            N:
                options.N,

            r:
                options.r,

            p:
                options.p,

            keyLength:
                options.keyLength
        }
    };
}


/* ======================================================
   8.11 - PASSWORD VERIFY
====================================================== */

async function security8VerifyPassword(
    password,
    stored
) {
    if (
        !stored?.salt ||
        !stored?.hash
    ) {
        return false;
    }

    const params =
        stored.params ||
        SECURITY_ENGINE_CONFIG_8
            .password
            .scrypt;

    const salt =
        Buffer.from(
            stored.salt,
            "base64url"
        );

    const expected =
        Buffer.from(
            stored.hash,
            "base64url"
        );

    const derived =
        await new Promise(
            (
                resolve,
                reject
            ) => {
                SECURITY_CRYPTO_8
                    .scrypt(
                        String(
                            password ??
                            ""
                        ),
                        salt,
                        Number(
                            params.keyLength ||
                            64
                        ),
                        {
                            N:
                                Number(
                                    params.N ||
                                    16384
                                ),

                            r:
                                Number(
                                    params.r ||
                                    8
                                ),

                            p:
                                Number(
                                    params.p ||
                                    1
                                ),

                            maxmem:
                                128 *
                                Number(
                                    params.N ||
                                    16384
                                ) *
                                Number(
                                    params.r ||
                                    8
                                ) +
                                1024 *
                                1024
                        },
                        (
                            error,
                            key
                        ) => {
                            if (
                                error
                            ) {
                                reject(
                                    error
                                );
                            } else {
                                resolve(
                                    key
                                );
                            }
                        }
                    );
            }
        );

    return security8SafeEqual(
        Buffer.from(
            derived
        ),
        expected
    );
}


/* ======================================================
   8.12 - EMAIL NORMALIZATION
====================================================== */

function security8NormalizeEmail(
    email
) {
    return safeString(
        email ||
        "",
        250
    )
        .trim()
        .toLowerCase();
}

function security8ValidateEmail(
    email
) {
    const value =
        security8NormalizeEmail(
            email
        );

    if (!value) {
        return false;
    }

    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(
        value
    );
}


/* ======================================================
   8.13 - USER RECORD
====================================================== */

function security8CreateUserRecord(
    options = {}
) {
    const userId =
        security8NormalizeUserId(
            options.userId
        );

    const email =
        security8NormalizeEmail(
            options.email
        );

    const displayName =
        safeString(
            options.displayName ||
            "",
            120
        ).trim();

    return {
        id:
            userId,

        email,

        displayName,

        provider:
            safeString(
                options.provider ||
                "local",
                50
            ),

        providerId:
            safeString(
                options.providerId ||
                "",
                250
            ),

        role:
            safeString(
                options.role ||
                "user",
                50
            ).toLowerCase(),

        status:
            "active",

        password:
            options.passwordHash ||
            null,

        permissions:
            Array.isArray(
                options.permissions
            )
                ? uniqueArray(
                    options.permissions
                )
                : [],

        emailVerified:
            Boolean(
                options.emailVerified
            ),

        createdAt:
            nowISO(),

        updatedAt:
            nowISO(),

        lastLoginAt:
            null,

        failedLoginAttempts:
            0,

        lockedUntil:
            null,

        metadata:
            isObject(
                options.metadata
            )
                ? clone(
                    options.metadata
                )
                : {}
    };
}

function security8ReadUser(
    userId
) {
    const normalized =
        security8NormalizeUserId(
            userId
        );

    const record =
        readJSON(
            security8UserFile(
                normalized
            ),
            null
        );

    return isObject(
        record
    )
        ? record
        : null;
}

function security8WriteUser(
    user
) {
    if (
        !user?.id
    ) {
        throw new Error(
            "Geçersiz kullanıcı."
        );
    }

    user.updatedAt =
        nowISO();

    writeJSON(
        security8UserFile(
            user.id
        ),
        user
    );

    return user;
}


/* ======================================================
   8.14 - USER FIND BY EMAIL
====================================================== */

function security8FindUserByEmail(
    email
) {
    const target =
        security8NormalizeEmail(
            email
        );

    if (!target) {
        return null;
    }

    if (
        !fs.existsSync(
            SECURITY_USERS_ROOT_8
        )
    ) {
        return null;
    }

    let entries = [];

    try {
        entries =
            fs.readdirSync(
                SECURITY_USERS_ROOT_8,
                {
                    withFileTypes:
                        true
                }
            );
    } catch {
        return null;
    }

    for (
        const entry of entries
    ) {
        if (
            !entry.isFile() ||
            !entry.name.endsWith(
                ".json"
            )
        ) {
            continue;
        }

        try {
            const user =
                readJSON(
                    path.join(
                        SECURITY_USERS_ROOT_8,
                        entry.name
                    ),
                    null
                );

            if (
                user &&
                security8NormalizeEmail(
                    user.email
                ) ===
                target
            ) {
                return user;
            }
        } catch {
            continue;
        }
    }

    return null;
}


/* ======================================================
   8.15 - USER CREATION
====================================================== */

async function security8RegisterUser(
    options = {}
) {
    const email =
        security8NormalizeEmail(
            options.email
        );

    if (
        !security8ValidateEmail(
            email
        )
    ) {
        throw new Error(
            "Geçerli bir e-posta adresi gerekli."
        );
    }

    const passwordCheck =
        security8ValidatePassword(
            options.password
        );

    if (
        !passwordCheck.valid
    ) {
        throw new Error(
            passwordCheck.error
        );
    }

    const existing =
        security8FindUserByEmail(
            email
        );

    if (
        existing
    ) {
        throw new Error(
            "Bu e-posta adresi zaten kayıtlı."
        );
    }

    const existingProfile =
        typeof getUser === "function"
            ? getUser(
                security8NormalizeUserId(
                    options.userId ||
                    ""
                )
            )
            : null;

    let userId =
        security8NormalizeUserId(
            options.userId
        );

    if (
        !userId ||
        userId ===
        "anonymous"
    ) {
        const emailPrefix =
            email
                .split("@")[0]
                .replace(
                    /[^a-zA-Z0-9_-]/g,
                    "_"
                )
                .slice(
                    0,
                    35
                );

        userId =
            `${emailPrefix}_${security8RandomBase64Url(5)}`;
    }

    let passwordHash;

    try {
        passwordHash =
            await security8HashPassword(
                options.password
            );
    } catch (error) {
        throw new Error(
            `Parola oluşturulamadı: ${error.message}`
        );
    }

    const user =
        security8CreateUserRecord({
            userId,

            email,

            displayName:
                options.displayName ||
                existingProfile?.displayName ||
                email.split("@")[0],

            provider:
                "local",

            role:
                "user",

            passwordHash,

            emailVerified:
                false
        });

    security8WriteUser(
        user
    );

    /*
       Part 1 user store ile köprü.
    */
    if (
        typeof ensureUser ===
        "function"
    ) {
        try {
            const baseUser =
                ensureUser(
                    user.id,
                    {
                        name:
                            user.displayName,

                        email:
                            user.email
                    }
                );

            if (
                baseUser
            ) {
                if (
                    baseUser.email ===
                    ""
                ) {
                    baseUser.email =
                        user.email;
                }

                if (
                    baseUser.name ===
                    ""
                ) {
                    baseUser.name =
                        user.displayName;
                }

                baseUser.auth =
                    true;
            }
        } catch {
            /*
               Ana kullanıcı store başarısız olursa
               security hesabını bozmuyoruz.
            */
        }
    }

    SECURITY_STATS_8.users +=
        1;

    writeJSON(
        SECURITY_STATS_FILE_8,
        SECURITY_STATS_8
    );

    SECURITY_ENGINE_STATE_8
        .registerSuccess +=
        1;

    security8Audit(
        "user.register",
        user.id,
        {
            provider:
                "local"
        }
    );

    return clone(
        user
    );
}


/* ======================================================
   8.16 - TOKEN ENCODE
====================================================== */

function security8Base64Json(
    value
) {
    return Buffer.from(
        JSON.stringify(
            value
        )
    ).toString(
        "base64url"
    );
}

function security8DecodeBase64Json(
    value
) {
    return JSON.parse(
        Buffer.from(
            value,
            "base64url"
        ).toString(
            "utf8"
        )
    );
}


/* ======================================================
   8.17 - ACCESS TOKEN
====================================================== */

function security8CreateAccessToken(
    user,
    sessionId
) {
    const issuedAt =
        Math.floor(
            Date.now() / 1000
        );

    const payload = {
        typ:
            "access",

        iss:
            SECURITY_ENGINE_CONFIG_8
                .token
                .issuer,

        aud:
            SECURITY_ENGINE_CONFIG_8
                .token
                .audience,

        sub:
            user.id,

        sid:
            sessionId,

        role:
            user.role,

        iat:
            issuedAt,

        exp:
            issuedAt +
            SECURITY_ENGINE_CONFIG_8
                .token
                .accessTTLSeconds,

        jti:
            security8CreateId(
                "at"
            )
    };

    const encoded =
        security8Base64Json(
            payload
        );

    const signature =
        security8Sign(
            encoded
        );

    return (
        `tk8.${encoded}.${signature}`
    );
}


/* ======================================================
   8.18 - REFRESH TOKEN
====================================================== */

function security8CreateRefreshToken(
    user,
    sessionId
) {
    const issuedAt =
        Math.floor(
            Date.now() / 1000
        );

    const payload = {
        typ:
            "refresh",

        iss:
            SECURITY_ENGINE_CONFIG_8
                .token
                .issuer,

        aud:
            SECURITY_ENGINE_CONFIG_8
                .token
                .audience,

        sub:
            user.id,

        sid:
            sessionId,

        iat:
            issuedAt,

        exp:
            issuedAt +
            SECURITY_ENGINE_CONFIG_8
                .token
                .refreshTTLSeconds,

        jti:
            security8CreateId(
                "rt"
            ),

        nonce:
            security8RandomBase64Url(
                18
            )
    };

    const encoded =
        security8Base64Json(
            payload
        );

    const signature =
        security8Sign(
            encoded
        );

    return (
        `tk8r.${encoded}.${signature}`
    );
}


/* ======================================================
   8.19 - TOKEN PARSER
====================================================== */

function security8VerifyToken(
    token,
    expectedType = "access"
) {
    const raw =
        safeString(
            token,
            10000
        ).trim();

    if (
        !raw
    ) {
        return {
            valid:
                false,

            reason:
                "missing-token"
        };
    }

    const pieces =
        raw.split(".");

    if (
        pieces.length !==
        3
    ) {
        return {
            valid:
                false,

            reason:
                "invalid-format"
        };
    }

    const prefix =
        pieces[0];

    const encoded =
        pieces[1];

    const signature =
        pieces[2];

    if (
        expectedType ===
        "access" &&
        prefix !==
        "tk8"
    ) {
        return {
            valid:
                false,

            reason:
                "wrong-token-type"
        };
    }

    if (
        expectedType ===
        "refresh" &&
        prefix !==
        "tk8r"
    ) {
        return {
            valid:
                false,

            reason:
                "wrong-token-type"
        };
    }

    const expectedSignature =
        security8Sign(
            encoded
        );

    if (
        !security8SafeEqual(
            signature,
            expectedSignature
        )
    ) {
        SECURITY_ENGINE_STATE_8
            .invalidTokens +=
            1;

        return {
            valid:
                false,

            reason:
                "invalid-signature"
        };
    }

    let payload;

    try {
        payload =
            security8DecodeBase64Json(
                encoded
            );
    } catch {
        SECURITY_ENGINE_STATE_8
            .invalidTokens +=
            1;

        return {
            valid:
                false,

            reason:
                "invalid-payload"
        };
    }

    const now =
        Math.floor(
            Date.now() / 1000
        );

    if (
        payload.iss !==
        SECURITY_ENGINE_CONFIG_8
            .token
            .issuer
    ) {
        return {
            valid:
                false,

            reason:
                "invalid-issuer"
        };
    }

    if (
        payload.aud !==
        SECURITY_ENGINE_CONFIG_8
            .token
            .audience
    ) {
        return {
            valid:
                false,

            reason:
                "invalid-audience"
        };
    }

    if (
        Number(
            payload.exp
        ) <=
        now
    ) {
        return {
            valid:
                false,

            reason:
                "expired"
        };
    }

    if (
        !payload.sub ||
        !payload.sid
    ) {
        return {
            valid:
                false,

            reason:
                "invalid-subject"
        };
    }

    return {
        valid:
            true,

        payload
    };
}


/* ======================================================
   8.20 - BEARER TOKEN
====================================================== */

function security8ExtractBearer(
    req
) {
    const header =
        safeString(
            req.headers?.authorization ||
            "",
            10000
        );

    if (
        /^Bearer\s+/i.test(
            header
        )
    ) {
        return header
            .replace(
                /^Bearer\s+/i,
                ""
            )
            .trim();
    }

    return (
        safeString(
            req.body?.accessToken ||
            req.query?.accessToken ||
            "",
            10000
        ).trim() ||
        null
    );
}


/* ======================================================
   8.21 - SECURITY SESSION MODEL
====================================================== */

function security8CreateSession(
    user,
    req,
    metadata = {}
) {
    const sessionId =
        security8CreateId(
            "sec_session"
        );

    const createdAt =
        nowISO();

    const session = {
        id:
            sessionId,

        userId:
            user.id,

        role:
            user.role,

        status:
            "active",

        createdAt,

        lastSeenAt:
            createdAt,

        expiresAt:
            new Date(
                Date.now() +
                SECURITY_ENGINE_CONFIG_8
                    .token
                    .refreshTTLSeconds *
                1000
            ).toISOString(),

        revokedAt:
            null,

        refreshJti:
            null,

        userAgent:
            safeString(
                req?.headers?.["user-agent"] ||
                "",
                500
            ),

        ip:
            safeString(
                req?.ip ||
                req?.socket?.remoteAddress ||
                "",
                100
            ),

        metadata:
            isObject(
                metadata
            )
                ? clone(
                    metadata
                )
                : {}
    };

    writeJSON(
        security8SessionFile(
            sessionId
        ),
        session
    );

    return session;
}


/* ======================================================
   8.22 - SESSION GET
====================================================== */

function security8GetSession(
    sessionId
) {
    const id =
        safeString(
            sessionId,
            250
        );

    if (
        SECURITY_ACCESS_SESSIONS_8.has(
            id
        )
    ) {
        return clone(
            SECURITY_ACCESS_SESSIONS_8.get(
                id
            )
        );
    }

    const session =
        readJSON(
            security8SessionFile(
                id
            ),
            null
        );

    if (
        !isObject(
            session
        )
    ) {
        return null;
    }

    SECURITY_ACCESS_SESSIONS_8.set(
        id,
        session
    );

    return clone(
        session
    );
}


/* ======================================================
   8.23 - SESSION SAVE
====================================================== */

function security8SaveSession(
    session
) {
    if (
        !session?.id
    ) {
        throw new Error(
            "Geçersiz security session."
        );
    }

    session.lastSeenAt =
        nowISO();

    SECURITY_ACCESS_SESSIONS_8.set(
        session.id,
        clone(
            session
        )
    );

    writeJSON(
        security8SessionFile(
            session.id
        ),
        session
    );

    return session;
}


/* ======================================================
   8.24 - SESSION REVOKE
====================================================== */

function security8RevokeSession(
    sessionId,
    reason = "logout"
) {
    const session =
        security8GetSession(
            sessionId
        );

    if (
        !session
    ) {
        return false;
    }

    session.status =
        "revoked";

    session.revokedAt =
        nowISO();

    session.revokeReason =
        safeString(
            reason,
            100
        );

    security8SaveSession(
        session
    );

    SECURITY_REFRESH_SESSIONS_8.delete(
        session.id
    );

    SECURITY_ENGINE_STATE_8
        .activeSessions =
        Math.max(
            0,
            SECURITY_ENGINE_STATE_8
                .activeSessions -
                1
        );

    return true;
}


/* ======================================================
   8.25 - TOKEN SESSION VALIDATION
====================================================== */

function security8AuthenticateRequest(
    req
) {
    const token =
        security8ExtractBearer(
            req
        );

    if (
        !token
    ) {
        return {
            authenticated:
                false,

            reason:
                "missing-token"
        };
    }

    const verification =
        security8VerifyToken(
            token,
            "access"
        );

    if (
        !verification.valid
    ) {
        return {
            authenticated:
                false,

            reason:
                verification.reason
        };
    }

    const payload =
        verification.payload;

    const session =
        security8GetSession(
            payload.sid
        );

    if (
        !session
    ) {
        return {
            authenticated:
                false,

            reason:
                "session-not-found"
        };
    }

    if (
        session.status !==
        "active"
    ) {
        return {
            authenticated:
                false,

            reason:
                "session-inactive"
        };
    }

    if (
        session.userId !==
        payload.sub
    ) {
        return {
            authenticated:
                false,

            reason:
                "session-user-mismatch"
        };
    }

    const user =
        security8ReadUser(
            payload.sub
        );

    if (
        !user
    ) {
        return {
            authenticated:
                false,

            reason:
                "user-not-found"
        };
    }

    if (
        user.status !==
        "active"
    ) {
        return {
            authenticated:
                false,

            reason:
                "user-inactive"
        };
    }

    session.lastSeenAt =
        nowISO();

    SECURITY_ACCESS_SESSIONS_8.set(
        session.id,
        clone(
            session
        )
    );

    req.turkAIAuth = {
        user,
        session,
        tokenPayload:
            payload
    };

    return {
        authenticated:
            true,

        user,
        session,
        tokenPayload:
            payload
    };
}


/* ======================================================
   8.26 - AUTH MIDDLEWARE
====================================================== */

function security8RequireAuth(
    req,
    res,
    next
) {
    const result =
        security8AuthenticateRequest(
            req
        );

    if (
        !result.authenticated
    ) {
        SECURITY_ENGINE_STATE_8
            .invalidTokens +=
            1;

        return res.status(
            401
        ).json({
            success:
                false,

            error:
                "Kimlik doğrulama gerekli.",

            reason:
                result.reason
        });
    }

    return next();
}


/* ======================================================
   8.27 - ROLE HIERARCHY
====================================================== */

const SECURITY_ROLES_8 = {
    guest: 0,
    user: 10,
    pro: 20,
    plus: 30,
    moderator: 40,
    admin: 80,
    developer: 90,
    owner: 100
};

function security8RoleLevel(
    role
) {
    const normalized =
        safeString(
            role ||
            "guest",
            50
        ).toLowerCase();

    return (
        SECURITY_ROLES_8[
            normalized
        ] ??
        0
    );
}

function security8HasRole(
    user,
    minimumRole
) {
    return (
        security8RoleLevel(
            user?.role
        ) >=
        security8RoleLevel(
            minimumRole
        )
    );
}


/* ======================================================
   8.28 - PERMISSION SYSTEM
====================================================== */

const SECURITY_PERMISSIONS_8 = {
    "chat.use":
        "Sohbet kullanımı",

    "chat.advanced":
        "Gelişmiş sohbet",

    "research.use":
        "Araştırma",

    "memory.use":
        "Hafıza",

    "files.use":
        "Dosyalar",

    "media.generate":
        "Medya üretimi",

    "tasks.use":
        "Görevler",

    "billing.view":
        "Ödeme bilgileri",

    "billing.manage":
        "Abonelik yönetimi",

    "api.use":
        "API kullanımı",

    "api.manage":
        "API anahtarı yönetimi",

    "developer.use":
        "Developer araçları",

    "admin.users":
        "Kullanıcı yönetimi",

    "admin.security":
        "Güvenlik yönetimi"
};

function security8HasPermission(
    user,
    permission
) {
    if (
        security8HasRole(
            user,
            "owner"
        )
    ) {
        return true;
    }

    if (
        security8HasRole(
            user,
            "developer"
        ) &&
        (
            permission.startsWith(
                "developer."
            ) ||
            permission.startsWith(
                "api."
            )
        )
    ) {
        return true;
    }

    return Array.isArray(
        user?.permissions
    ) &&
        user.permissions.includes(
            permission
        );
}

function security8RequirePermission(
    permission
) {
    return (
        req,
        res,
        next
    ) => {
        const auth =
            security8AuthenticateRequest(
                req
            );

        if (
            !auth.authenticated
        ) {
            return res.status(
                401
            ).json({
                success:
                    false,

                error:
                    "Kimlik doğrulama gerekli."
            });
        }

        if (
            !security8HasPermission(
                auth.user,
                permission
            )
        ) {
            return res.status(
                403
            ).json({
                success:
                    false,

                error:
                    "Bu işlem için yetkiniz yok.",

                permission
            });
        }

        return next();
    };
}


/* ======================================================
   8.29 - ROLE MIDDLEWARE
====================================================== */

function security8RequireRole(
    role
) {
    return (
        req,
        res,
        next
    ) => {
        const auth =
            security8AuthenticateRequest(
                req
            );

        if (
            !auth.authenticated
        ) {
            return res.status(
                401
            ).json({
                success:
                    false,

                error:
                    "Kimlik doğrulama gerekli."
            });
        }

        if (
            !security8HasRole(
                auth.user,
                role
            )
        ) {
            return res.status(
                403
            ).json({
                success:
                    false,

                error:
                    "Yetersiz rol."
            });
        }

        return next();
    };
}


/* ======================================================
   8.30 - LOGIN
====================================================== */

async function security8Login(
    email,
    password,
    req
) {
    const normalizedEmail =
        security8NormalizeEmail(
            email
        );

    const user =
        security8FindUserByEmail(
            normalizedEmail
        );

    if (
        !user
    ) {
        SECURITY_ENGINE_STATE_8
            .loginFailed +=
            1;

        throw new Error(
            "E-posta veya parola hatalı."
        );
    }

    if (
        user.status !==
        "active"
    ) {
        throw new Error(
            "Kullanıcı hesabı aktif değil."
        );
    }

    if (
        user.lockedUntil &&
        Date.parse(
            user.lockedUntil
        ) >
        Date.now()
    ) {
        throw new Error(
            "Hesap geçici olarak kilitlendi."
        );
    }

    const valid =
        await security8VerifyPassword(
            password,
            user.password
        );

    if (
        !valid
    ) {
        user.failedLoginAttempts =
            Number(
                user.failedLoginAttempts
            ) + 1;

        if (
            user.failedLoginAttempts >=
            8
        ) {
            user.lockedUntil =
                new Date(
                    Date.now() +
                    15 *
                    60 *
                    1000
                ).toISOString();

            user.failedLoginAttempts =
                0;
        }

        security8WriteUser(
            user
        );

        SECURITY_ENGINE_STATE_8
            .loginFailed +=
            1;

        throw new Error(
            "E-posta veya parola hatalı."
        );
    }

    user.failedLoginAttempts =
        0;

    user.lockedUntil =
        null;

    user.lastLoginAt =
        nowISO();

    security8WriteUser(
        user
    );

    const session =
        security8CreateSession(
            user,
            req,
            {
                loginMethod:
                    "local"
            }
        );

    const accessToken =
        security8CreateAccessToken(
            user,
            session.id
        );

    const refreshToken =
        security8CreateRefreshToken(
            user,
            session.id
        );

    const refreshVerification =
        security8VerifyToken(
            refreshToken,
            "refresh"
        );

    session.refreshJti =
        refreshVerification
            ?.payload
            ?.jti ||
        null;

    security8SaveSession(
        session
    );

    SECURITY_REFRESH_SESSIONS_8.set(
        session.id,
        refreshToken
    );

    SECURITY_ENGINE_STATE_8
        .loginSuccess +=
        1;

    SECURITY_ENGINE_STATE_8
        .activeSessions +=
        1;

    SECURITY_ENGINE_STATE_8
        .lastLoginAt =
        nowISO();

    SECURITY_STATS_8.sessions +=
        1;

    writeJSON(
        SECURITY_STATS_FILE_8,
        SECURITY_STATS_8
    );

    security8Audit(
        "user.login",
        user.id,
        {
            method:
                "local",

            sessionId:
                session.id
        },
        req
    );

    return {
        user:
            security8PublicUser(
                user
            ),

        accessToken,

        refreshToken,

        tokenType:
            "Bearer",

        expiresIn:
            SECURITY_ENGINE_CONFIG_8
                .token
                .accessTTLSeconds,

        session:
            clone(
                session
            )
    };
}


/* ======================================================
   8.31 - PUBLIC USER
====================================================== */

function security8PublicUser(
    user
) {
    if (!user) {
        return null;
    }

    return {
        id:
            user.id,

        email:
            user.email,

        displayName:
            user.displayName,

        provider:
            user.provider,

        role:
            user.role,

        status:
            user.status,

        permissions:
            Array.isArray(
                user.permissions
            )
                ? clone(
                    user.permissions
                )
                : [],

        emailVerified:
            Boolean(
                user.emailVerified
            ),

        createdAt:
            user.createdAt,

        lastLoginAt:
            user.lastLoginAt
    };
}


/* ======================================================
   8.32 - REFRESH TOKEN ROTATION
====================================================== */

async function security8Refresh(
    refreshToken,
    req
) {
    const verification =
        security8VerifyToken(
            refreshToken,
            "refresh"
        );

    if (
        !verification.valid
    ) {
        SECURITY_ENGINE_STATE_8
            .invalidTokens +=
            1;

        throw new Error(
            "Refresh token geçersiz veya süresi dolmuş."
        );
    }

    const payload =
        verification.payload;

    const storedRefresh =
        SECURITY_REFRESH_SESSIONS_8.get(
            payload.sid
        );

    const session =
        security8GetSession(
            payload.sid
        );

    if (
        !session ||
        session.status !==
        "active"
    ) {
        throw new Error(
            "Oturum aktif değil."
        );
    }

    if (
        storedRefresh
    ) {
        const same =
            security8SafeEqual(
                storedRefresh,
                refreshToken
            );

        if (!same) {
            security8RevokeSession(
                payload.sid,
                "refresh-token-reuse"
            );

            security8Audit(
                "security.refresh_reuse",
                payload.sub,
                {
                    sessionId:
                        payload.sid
                },
                req
            );

            throw new Error(
                "Refresh token güvenlik kontrolü başarısız."
            );
        }
    }

    const user =
        security8ReadUser(
            payload.sub
        );

    if (
        !user
    ) {
        throw new Error(
            "Kullanıcı bulunamadı."
        );
    }

    if (
        user.status !==
        "active"
    ) {
        throw new Error(
            "Kullanıcı hesabı aktif değil."
        );
    }

    const newAccessToken =
        security8CreateAccessToken(
            user,
            session.id
        );

    const newRefreshToken =
        security8CreateRefreshToken(
            user,
            session.id
        );

    const newRefreshVerification =
        security8VerifyToken(
            newRefreshToken,
            "refresh"
        );

    session.refreshJti =
        newRefreshVerification
            ?.payload
            ?.jti ||
        null;

    security8SaveSession(
        session
    );

    SECURITY_REFRESH_SESSIONS_8.set(
        session.id,
        newRefreshToken
    );

    SECURITY_ENGINE_STATE_8
        .refreshSuccess +=
        1;

    security8Audit(
        "user.refresh",
        user.id,
        {
            sessionId:
                session.id
        },
        req
    );

    return {
        user:
            security8PublicUser(
                user
            ),

        accessToken:
            newAccessToken,

        refreshToken:
            newRefreshToken,

        tokenType:
            "Bearer",

        expiresIn:
            SECURITY_ENGINE_CONFIG_8
                .token
                .accessTTLSeconds
    };
}


/* ======================================================
   8.33 - LOGOUT
====================================================== */

function security8Logout(
    req,
    userId = null,
    sessionId = null
) {
    let targetSession =
        sessionId;

    if (
        !targetSession &&
        req.turkAIAuth?.session?.id
    ) {
        targetSession =
            req.turkAIAuth.session.id;
    }

    if (
        targetSession
    ) {
        security8RevokeSession(
            targetSession,
            "logout"
        );
    }

    if (
        userId
    ) {
        security8Audit(
            "user.logout",
            userId,
            {
                sessionId:
                    targetSession
            },
            req
        );
    }

    SECURITY_ENGINE_STATE_8
        .logoutSuccess +=
        1;

    return {
        success:
            true,

        sessionId:
            targetSession
    };
}


/* ======================================================
   8.34 - GOOGLE ID TOKEN VERIFICATION
====================================================== */

async function security8VerifyGoogleCredential(
    credential
) {
    if (
        !SECURITY_ENGINE_CONFIG_8
            .google
            .enabled
    ) {
        throw new Error(
            "Google giriş sistemi kapalı."
        );
    }

    const clientId =
        safeString(
            process.env.GOOGLE_CLIENT_ID ||
            "",
            500
        );

    if (
        !clientId
    ) {
        throw new Error(
            "GOOGLE_CLIENT_ID yapılandırılmamış."
        );
    }

    const token =
        safeString(
            credential,
            10000
        );

    if (!token) {
        throw new Error(
            "Google credential bulunamadı."
        );
    }

    const url =
        `${SECURITY_ENGINE_CONFIG_8.google.tokenInfoURL}?id_token=${encodeURIComponent(token)}`;

    const response =
        await marketFetchJSON4(
            url,
            {
                timeoutMs:
                    10000
            }
        );

    if (
        response.aud !==
        clientId
    ) {
        throw new Error(
            "Google token audience doğrulaması başarısız."
        );
    }

    if (
        response.email_verified !==
        "true" &&
        response.email_verified !==
        true
    ) {
        throw new Error(
            "Google e-postası doğrulanmış değil."
        );
    }

    if (
        !response.sub ||
        !response.email
    ) {
        throw new Error(
            "Google kullanıcı bilgileri eksik."
        );
    }

    return {
        providerId:
            response.sub,

        email:
            security8NormalizeEmail(
                response.email
            ),

        displayName:
            safeString(
                response.name ||
                response.given_name ||
                response.email.split("@")[0],
                120
            ),

        picture:
            safeString(
                response.picture ||
                "",
                1000
            ),

        locale:
            safeString(
                response.locale ||
                "",
                30
            )
    };
}


/* ======================================================
   8.35 - GOOGLE LOGIN
====================================================== */

async function security8GoogleLogin(
    credential,
    req
) {
    const google =
        await security8VerifyGoogleCredential(
            credential
        );

    let user =
        security8FindUserByEmail(
            google.email
        );

    if (
        !user
    ) {
        const generatedId =
            `google_${google.providerId}`;

        user =
            security8CreateUserRecord({
                userId:
                    generatedId,

                email:
                    google.email,

                displayName:
                    google.displayName,

                provider:
                    "google",

                providerId:
                    google.providerId,

                role:
                    "user",

                passwordHash:
                    null,

                emailVerified:
                    true,

                metadata: {
                    picture:
                        google.picture,

                    locale:
                        google.locale
                }
            });

        security8WriteUser(
            user
        );

        SECURITY_STATS_8.users +=
            1;

        writeJSON(
            SECURITY_STATS_FILE_8,
            SECURITY_STATS_8
        );
    } else {
        user.provider =
            "google";

        user.providerId =
            google.providerId;

        user.emailVerified =
            true;

        user.displayName =
            google.displayName;

        user.metadata =
            {
                ...(user.metadata || {}),
                picture:
                    google.picture,
                locale:
                    google.locale
            };

        security8WriteUser(
            user
        );
    }

    user.lastLoginAt =
        nowISO();

    security8WriteUser(
        user
    );

    const session =
        security8CreateSession(
            user,
            req,
            {
                loginMethod:
                    "google"
            }
        );

    const accessToken =
        security8CreateAccessToken(
            user,
            session.id
        );

    const refreshToken =
        security8CreateRefreshToken(
            user,
            session.id
        );

    const verification =
        security8VerifyToken(
            refreshToken,
            "refresh"
        );

    session.refreshJti =
        verification
            ?.payload
            ?.jti ||
        null;

    security8SaveSession(
        session
    );

    SECURITY_REFRESH_SESSIONS_8.set(
        session.id,
        refreshToken
    );

    SECURITY_ENGINE_STATE_8
        .googleLogins +=
        1;

    SECURITY_ENGINE_STATE_8
        .loginSuccess +=
        1;

    SECURITY_ENGINE_STATE_8
        .activeSessions +=
        1;

    SECURITY_ENGINE_STATE_8
        .lastLoginAt =
        nowISO();

    security8Audit(
        "user.google_login",
        user.id,
        {
            providerId:
                google.providerId,

            sessionId:
                session.id
        },
        req
    );

    return {
        user:
            security8PublicUser(
                user
            ),

        accessToken,

        refreshToken,

        tokenType:
            "Bearer",

        expiresIn:
            SECURITY_ENGINE_CONFIG_8
                .token
                .accessTTLSeconds,

        session:
            clone(
                session
            )
    };
}


/* ======================================================
   8.36 - API KEY HASH
====================================================== */

function security8HashApiKey(
    key
) {
    return SECURITY_CRYPTO_8
        .createHash(
            "sha256"
        )
        .update(
            String(key)
        )
        .digest(
            "hex"
        );
}


/* ======================================================
   8.37 - API KEY RECORD
====================================================== */

function security8CreateApiKeyRecord(
    user,
    options = {}
) {
    const rawKey =
        `${SECURITY_ENGINE_CONFIG_8.apiKeys.prefix}${security8RandomBase64Url(SECURITY_ENGINE_CONFIG_8.apiKeys.keyBytes)}`;

    const keyId =
        security8CreateId(
            "key"
        );

    const created =
        nowISO();

    const record = {
        id:
            keyId,

        userId:
            user.id,

        name:
            safeString(
                options.name ||
                "TürkAI API Key",
                120
            ),

        prefix:
            rawKey.slice(
                0,
                16
            ),

        keyHash:
            security8HashApiKey(
                rawKey
            ),

        status:
            "active",

        createdAt:
            created,

        lastUsedAt:
            null,

        revokedAt:
            null,

        expiresAt:
            options.expiresAt
                ? task6DateISO(
                    options.expiresAt
                )
                : null,

        rateLimit:
            clamp(
                Number(
                    options.rateLimit
                ) ||
                SECURITY_ENGINE_CONFIG_8
                    .apiKeys
                    .defaultRateLimit,
                1,
                10000
            ),

        permissions:
            Array.isArray(
                options.permissions
            )
                ? uniqueArray(
                    options.permissions
                        .filter(
                            permission =>
                                Object.prototype.hasOwnProperty.call(
                                    SECURITY_PERMISSIONS_8,
                                    permission
                                )
                        )
                )
                : [
                    "chat.use",
                    "research.use",
                    "memory.use"
                ],

        metadata:
            isObject(
                options.metadata
            )
                ? clone(
                    options.metadata
                )
                : {}
    };

    writeJSON(
        security8ApiKeyFile(
            keyId
        ),
        record
    );

    SECURITY_API_KEY_CACHE_8.set(
        record.keyHash,
        clone(
            record
        )
    );

    SECURITY_ENGINE_STATE_8
        .apiKeysCreated +=
        1;

    SECURITY_ENGINE_STATE_8
        .activeApiKeys +=
        1;

    SECURITY_STATS_8.apiKeys +=
        1;

    writeJSON(
        SECURITY_STATS_FILE_8,
        SECURITY_STATS_8
    );

    security8Audit(
        "api_key.created",
        user.id,
        {
            keyId,
            name:
                record.name
        }
    );

    return {
        record:
            security8PublicApiKey(
                record
            ),

        secret:
            rawKey
    };
}


/* ======================================================
   8.38 - PUBLIC API KEY
====================================================== */

function security8PublicApiKey(
    record
) {
    return {
        id:
            record.id,

        userId:
            record.userId,

        name:
            record.name,

        prefix:
            record.prefix,

        status:
            record.status,

        createdAt:
            record.createdAt,

        lastUsedAt:
            record.lastUsedAt,

        expiresAt:
            record.expiresAt,

        rateLimit:
            record.rateLimit,

        permissions:
            clone(
                record.permissions ||
                []
            )
    };
}


/* ======================================================
   8.39 - API KEY VALIDATION
====================================================== */

function security8ValidateApiKey(
    key
) {
    const raw =
        safeString(
            key,
            1000
        ).trim();

    if (
        !raw
    ) {
        return {
            valid:
                false,

            reason:
                "missing"
        };
    }

    if (
        !raw.startsWith(
            SECURITY_ENGINE_CONFIG_8
                .apiKeys
                .prefix
        )
    ) {
        return {
            valid:
                false,

            reason:
                "invalid-prefix"
        };
    }

    const hash =
        security8HashApiKey(
            raw
        );

    let record =
        SECURITY_API_KEY_CACHE_8.get(
            hash
        );

    if (!record) {
        const files =
            fs.existsSync(
                SECURITY_KEYS_ROOT_8
            )
                ? fs.readdirSync(
                    SECURITY_KEYS_ROOT_8,
                    {
                        withFileTypes:
                            true
                    }
                )
                : [];

        for (
            const file of files
        ) {
            if (
                !file.isFile() ||
                !file.name.endsWith(
                    ".json"
                )
            ) {
                continue;
            }

            const item =
                readJSON(
                    path.join(
                        SECURITY_KEYS_ROOT_8,
                        file.name
                    ),
                    null
                );

            if (
                item &&
                item.keyHash ===
                    hash
            ) {
                record =
                    item;

                SECURITY_API_KEY_CACHE_8.set(
                    hash,
                    clone(item)
                );

                break;
            }
        }
    }

    if (
        !record
    ) {
        SECURITY_ENGINE_STATE_8
            .invalidApiKeys +=
            1;

        return {
            valid:
                false,

            reason:
                "not-found"
        };
    }

    if (
        record.status !==
        "active"
    ) {
        return {
            valid:
                false,

            reason:
                "revoked"
        };
    }

    if (
        record.expiresAt &&
        Date.parse(
            record.expiresAt
        ) <=
        Date.now()
    ) {
        return {
            valid:
                false,

            reason:
                "expired"
        };
    }

    record.lastUsedAt =
        nowISO();

    writeJSON(
        security8ApiKeyFile(
            record.id
        ),
        record
    );

    SECURITY_API_KEY_CACHE_8.set(
        hash,
        clone(record)
    );

    return {
        valid:
            true,

        record
    };
}


/* ======================================================
   8.40 - API KEY EXTRACTOR
====================================================== */

function security8ExtractApiKey(
    req
) {
    return (
        safeString(
            req.headers?.["x-turkai-api-key"] ||
            req.headers?.["x-api-key"] ||
            req.query?.apiKey ||
            "",
            1000
        ).trim() ||
        null
    );
}


/* ======================================================
   8.41 - API KEY AUTH
====================================================== */

function security8AuthenticateApiKey(
    req
) {
    const key =
        security8ExtractApiKey(
            req
        );

    if (!key) {
        return {
            authenticated:
                false,

            reason:
                "missing-api-key"
        };
    }

    const validation =
        security8ValidateApiKey(
            key
        );

    if (
        !validation.valid
    ) {
        return {
            authenticated:
                false,

            reason:
                validation.reason
        };
    }

    const user =
        security8ReadUser(
            validation.record.userId
        );

    if (
        !user ||
        user.status !==
        "active"
    ) {
        return {
            authenticated:
                false,

            reason:
                "user-inactive"
        };
    }

    req.turkAIApiAuth = {
        apiKey:
            validation.record,

        user
    };

    return {
        authenticated:
            true,

        user,

        apiKey:
            validation.record
    };
}


/* ======================================================
   8.42 - API KEY MIDDLEWARE
====================================================== */

function security8RequireApiKey(
    req,
    res,
    next
) {
    const result =
        security8AuthenticateApiKey(
            req
        );

    if (
        !result.authenticated
    ) {
        return res.status(
            401
        ).json({
            success:
                false,

            error:
                "Geçerli TürkAI API anahtarı gerekli.",

            reason:
                result.reason
        });
    }

    if (
        !security8HasPermission(
            result.user,
            "api.use"
        ) &&
        !(
            Array.isArray(
                result.apiKey.permissions
            ) &&
            result.apiKey.permissions.includes(
                "chat.use"
            )
        )
    ) {
        return res.status(
            403
        ).json({
            success:
                false,

            error:
                "API kullanım yetkisi bulunmuyor."
        });
    }

    return next();
}


/* ======================================================
   8.43 - API KEY LIST
====================================================== */

function security8ListUserApiKeys(
    userId
) {
    const normalized =
        security8NormalizeUserId(
            userId
        );

    const keys = [];

    if (
        !fs.existsSync(
            SECURITY_KEYS_ROOT_8
        )
    ) {
        return keys;
    }

    const files =
        fs.readdirSync(
            SECURITY_KEYS_ROOT_8,
            {
                withFileTypes:
                    true
            }
        );

    for (
        const file of files
    ) {
        if (
            !file.isFile() ||
            !file.name.endsWith(
                ".json"
            )
        ) {
            continue;
        }

        const record =
            readJSON(
                path.join(
                    SECURITY_KEYS_ROOT_8,
                    file.name
                ),
                null
            );

        if (
            record?.userId ===
            normalized
        ) {
            keys.push(
                security8PublicApiKey(
                    record
                )
            );
        }
    }

    return keys;
}


/* ======================================================
   8.44 - API KEY REVOKE
====================================================== */

function security8RevokeApiKey(
    userId,
    keyId
) {
    const record =
        readJSON(
            security8ApiKeyFile(
                keyId
            ),
            null
        );

    if (
        !record
    ) {
        throw new Error(
            "API anahtarı bulunamadı."
        );
    }

    if (
        record.userId !==
        security8NormalizeUserId(
            userId
        )
    ) {
        throw new Error(
            "Bu API anahtarı size ait değil."
        );
    }

    if (
        record.status ===
        "revoked"
    ) {
        return {
            success:
                true,

            alreadyRevoked:
                true,

            key:
                security8PublicApiKey(
                    record
                )
        };
    }

    record.status =
        "revoked";

    record.revokedAt =
        nowISO();

    writeJSON(
        security8ApiKeyFile(
            keyId
        ),
        record
    );

    SECURITY_API_KEY_CACHE_8.delete(
        record.keyHash
    );

    SECURITY_ENGINE_STATE_8
        .apiKeysRevoked +=
        1;

    SECURITY_ENGINE_STATE_8
        .activeApiKeys =
        Math.max(
            0,
            SECURITY_ENGINE_STATE_8
                .activeApiKeys -
                1
        );

    security8Audit(
        "api_key.revoked",
        record.userId,
        {
            keyId
        }
    );

    return {
        success:
            true,

        key:
            security8PublicApiKey(
                record
            )
    };
}


/* ======================================================
   8.45 - RATE LIMIT KEY
====================================================== */

function security8ClientIdentity(
    req,
    prefix = "global"
) {
    const userId =
        req.turkAIAuth?.user?.id ||
        req.turkAIApiAuth?.user?.id ||
        "";

    const ip =
        safeString(
            req.ip ||
            req.socket?.remoteAddress ||
            "unknown",
            100
        );

    return (
        `${prefix}:${userId || "anonymous"}:${ip}`
    );
}


/* ======================================================
   8.46 - RATE LIMIT CORE
====================================================== */

function security8CheckRateLimit(
    map,
    key,
    windowMs,
    max
) {
    const now =
        Date.now();

    let item =
        map.get(
            key
        );

    if (
        !item ||
        now -
            item.startedAt >=
            windowMs
    ) {
        item = {
            startedAt:
                now,

            count:
                0
        };
    }

    item.count += 1;

    map.set(
        key,
        item
    );

    const allowed =
        item.count <=
        max;

    const remaining =
        Math.max(
            0,
            max -
                item.count
        );

    const resetAt =
        item.startedAt +
        windowMs;

    return {
        allowed,

        count:
            item.count,

        remaining,

        resetAt,

        retryAfterSeconds:
            Math.max(
                1,
                Math.ceil(
                    (
                        resetAt -
                        now
                    ) /
                    1000
                )
            )
    };
}


/* ======================================================
   8.47 - RATE LIMIT MIDDLEWARE
====================================================== */

function security8GlobalRateLimit(
    req,
    res,
    next
) {
    if (
        !SECURITY_ENGINE_CONFIG_8
            .rateLimit
            .enabled
    ) {
        return next();
    }

    const pathName =
        req.path || "";

    /*
       Health endpointleri tamamen kilitlemiyoruz.
    */
    if (
        pathName.startsWith(
            "/api/health"
        ) ||
        pathName ===
        "/favicon.ico"
    ) {
        return next();
    }

    const key =
        security8ClientIdentity(
            req,
            "global"
        );

    const result =
        security8CheckRateLimit(
            SECURITY_RATE_LIMITS_8,
            key,

            SECURITY_ENGINE_CONFIG_8
                .rateLimit
                .globalWindowMs,

            SECURITY_ENGINE_CONFIG_8
                .rateLimit
                .globalMax
        );

    res.setHeader(
        "X-RateLimit-Limit",
        SECURITY_ENGINE_CONFIG_8
            .rateLimit
            .globalMax
    );

    res.setHeader(
        "X-RateLimit-Remaining",
        result.remaining
    );

    res.setHeader(
        "X-RateLimit-Reset",
        Math.ceil(
            result.resetAt /
            1000
        )
    );

    if (
        !result.allowed
    ) {
        SECURITY_ENGINE_STATE_8
            .rateLimitHits +=
            1;

        return res.status(
            429
        ).json({
            success:
                false,

            error:
                "Çok fazla istek gönderildi.",

            retryAfterSeconds:
                result.retryAfterSeconds
        });
    }

    return next();
}


/* ======================================================
   8.48 - AUTH RATE LIMIT
====================================================== */

function security8AuthRateLimit(
    req,
    res,
    next
) {
    const key =
        security8ClientIdentity(
            req,
            "auth"
        );

    const result =
        security8CheckRateLimit(
            SECURITY_AUTH_RATE_LIMITS_8,
            key,

            SECURITY_ENGINE_CONFIG_8
                .rateLimit
                .authWindowMs,

            SECURITY_ENGINE_CONFIG_8
                .rateLimit
                .authMax
        );

    if (
        !result.allowed
    ) {
        SECURITY_ENGINE_STATE_8
            .rateLimitHits +=
            1;

        return res.status(
            429
        ).json({
            success:
                false,

            error:
                "Çok fazla giriş denemesi.",

            retryAfterSeconds:
                result.retryAfterSeconds
        });
    }

    return next();
}


/* ======================================================
   8.49 - API RATE LIMIT
====================================================== */

function security8ApiRateLimit(
    req,
    res,
    next
) {
    const apiKey =
        req.turkAIApiAuth?.apiKey;

    const limit =
        Number(
            apiKey?.rateLimit
        ) ||
        SECURITY_ENGINE_CONFIG_8
            .rateLimit
            .apiMax;

    const key =
        security8ClientIdentity(
            req,
            `api:${apiKey?.id || "unknown"}`
        );

    const result =
        security8CheckRateLimit(
            SECURITY_API_RATE_LIMITS_8,
            key,

            SECURITY_ENGINE_CONFIG_8
                .rateLimit
                .apiWindowMs,

            limit
        );

    if (
        !result.allowed
    ) {
        SECURITY_ENGINE_STATE_8
            .rateLimitHits +=
            1;

        return res.status(
            429
        ).json({
            success:
                false,

            error:
                "API kullanım limiti aşıldı.",

            retryAfterSeconds:
                result.retryAfterSeconds
        });
    }

    return next();
}


/* ======================================================
   8.50 - AUDIT
====================================================== */

function security8Audit(
    action,
    userId = null,
    data = {},
    req = null
) {
    if (
        !SECURITY_ENGINE_CONFIG_8
            .audit
            .enabled
    ) {
        return null;
    }

    const event = {
        id:
            security8CreateId(
                "audit"
            ),

        action:
            safeString(
                action,
                150
            ),

        userId:
            userId
                ? security8NormalizeUserId(
                    userId
                )
                : null,

        timestamp:
            nowISO(),

        ip:
            safeString(
                req?.ip ||
                req?.socket?.remoteAddress ||
                "",
                100
            ),

        userAgent:
            safeString(
                req?.headers?.["user-agent"] ||
                "",
                500
            ),

        data:
            isObject(
                data
            )
                ? clone(data)
                : {}
    };

    SECURITY_AUDIT_8.unshift(
        event
    );

    if (
        SECURITY_AUDIT_8.length >
        SECURITY_ENGINE_CONFIG_8
            .audit
            .historyLimit
    ) {
        SECURITY_AUDIT_8 =
            SECURITY_AUDIT_8.slice(
                0,
                SECURITY_ENGINE_CONFIG_8
                    .audit
                    .historyLimit
            );
    }

    SECURITY_STATS_8
        .auditEvents +=
        1;

    SECURITY_ENGINE_STATE_8
        .auditEvents +=
        1;

    SECURITY_ENGINE_STATE_8
        .lastSecurityEventAt =
        nowISO();

    writeJSON(
        SECURITY_AUDIT_FILE_8,
        SECURITY_AUDIT_8
    );

    writeJSON(
        SECURITY_STATS_FILE_8,
        SECURITY_STATS_8
    );

    return event;
}


/* ======================================================
   8.51 - CHANGE PASSWORD
====================================================== */

async function security8ChangePassword(
    userId,
    oldPassword,
    newPassword
) {
    const user =
        security8ReadUser(
            userId
        );

    if (
        !user
    ) {
        throw new Error(
            "Kullanıcı bulunamadı."
        );
    }

    if (
        !user.password
    ) {
        throw new Error(
            "Bu hesap parola ile giriş kullanmıyor."
        );
    }

    const oldValid =
        await security8VerifyPassword(
            oldPassword,
            user.password
        );

    if (
        !oldValid
    ) {
        throw new Error(
            "Mevcut parola hatalı."
        );
    }

    const validation =
        security8ValidatePassword(
            newPassword
        );

    if (
        !validation.valid
    ) {
        throw new Error(
            validation.error
        );
    }

    user.password =
        await security8HashPassword(
            newPassword
        );

    user.updatedAt =
        nowISO();

    security8WriteUser(
        user
    );

    /*
       Parola değişince aktif oturumları temizlemek
       için güvenlik gereği tüm refresh sessionları
       iptal ediyoruz.
    */
    security8RevokeAllUserSessions(
        user.id,
        "password-change"
    );

    SECURITY_ENGINE_STATE_8
        .passwordChanges +=
        1;

    security8Audit(
        "user.password_changed",
        user.id
    );

    return {
        success:
            true
    };
}


/* ======================================================
   8.52 - REVOKE ALL USER SESSIONS
====================================================== */

function security8RevokeAllUserSessions(
    userId,
    reason = "security"
) {
    const normalized =
        security8NormalizeUserId(
            userId
        );

    let revoked =
        0;

    if (
        fs.existsSync(
            SECURITY_SESSIONS_ROOT_8
        )
    ) {
        const files =
            fs.readdirSync(
                SECURITY_SESSIONS_ROOT_8,
                {
                    withFileTypes:
                        true
                }
            );

        for (
            const file of files
        ) {
            if (
                !file.isFile() ||
                !file.name.endsWith(
                    ".json"
                )
            ) {
                continue;
            }

            const session =
                readJSON(
                    path.join(
                        SECURITY_SESSIONS_ROOT_8,
                        file.name
                    ),
                    null
                );

            if (
                session?.userId ===
                    normalized &&
                session.status ===
                    "active"
            ) {
                security8RevokeSession(
                    session.id,
                    reason
                );

                revoked +=
                    1;
            }
        }
    }

    return revoked;
}


/* ======================================================
   8.53 - LIST USER SESSIONS
====================================================== */

function security8ListUserSessions(
    userId
) {
    const normalized =
        security8NormalizeUserId(
            userId
        );

    const sessions = [];

    if (
        !fs.existsSync(
            SECURITY_SESSIONS_ROOT_8
        )
    ) {
        return sessions;
    }

    const files =
        fs.readdirSync(
            SECURITY_SESSIONS_ROOT_8,
            {
                withFileTypes:
                    true
            }
        );

    for (
        const file of files
    ) {
        if (
            !file.isFile() ||
            !file.name.endsWith(
                ".json"
            )
        ) {
            continue;
        }

        const session =
            readJSON(
                path.join(
                    SECURITY_SESSIONS_ROOT_8,
                    file.name
                ),
                null
            );

        if (
            session?.userId ===
            normalized
        ) {
            sessions.push({
                id:
                    session.id,

                status:
                    session.status,

                createdAt:
                    session.createdAt,

                lastSeenAt:
                    session.lastSeenAt,

                expiresAt:
                    session.expiresAt,

                revokedAt:
                    session.revokedAt,

                userAgent:
                    session.userAgent,

                ip:
                    session.ip,

                metadata:
                    session.metadata
            });
        }
    }

    return sessions;
}


/* ======================================================
   8.54 - SECURITY USER INFO
====================================================== */

function security8GetCurrentUser(
    req
) {
    const auth =
        security8AuthenticateRequest(
            req
        );

    if (
        !auth.authenticated
    ) {
        return null;
    }

    return {
        user:
            security8PublicUser(
                auth.user
            ),

        session: {
            id:
                auth.session.id,

            status:
                auth.session.status,

            createdAt:
                auth.session.createdAt,

            expiresAt:
                auth.session.expiresAt,

            lastSeenAt:
                auth.session.lastSeenAt
        },

        permissions:
            Object.keys(
                SECURITY_PERMISSIONS_8
            ).filter(
                permission =>
                    security8HasPermission(
                        auth.user,
                        permission
                    )
            )
    };
}


/* ======================================================
   8.55 - REGISTER ROUTE
====================================================== */

app.post(
    "/api/auth/register",
    security8AuthRateLimit,
    async (
        req,
        res
    ) => {
        SECURITY_ENGINE_STATE_8
            .requests +=
            1;

        try {
            const user =
                await security8RegisterUser(
                    {
                        email:
                            req.body?.email,

                        password:
                            req.body?.password,

                        displayName:
                            req.body?.displayName,

                        userId:
                            req.body?.userId
                    }
                );

            SECURITY_ENGINE_STATE_8
                .successfulRequests +=
                1;

            return res.status(
                201
            ).json({
                success:
                    true,

                user:
                    security8PublicUser(
                        user
                    )
            });

        } catch (error) {
            SECURITY_ENGINE_STATE_8
                .failedRequests +=
                1;

            SECURITY_ENGINE_STATE_8
                .registerFailed +=
                1;

            security8Audit(
                "user.register_failed",
                null,
                {
                    email:
                        security8NormalizeEmail(
                            req.body?.email
                        )
                },
                req
            );

            return res.status(
                400
            ).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    }
);


