/* ======================================================
   8.77 - GENERIC SECURITY CHECK MIDDLEWARE
====================================================== */

function security8RequireAuthOrApiKey(
    req,
    res,
    next
) {
    const auth =
        security8AuthenticateRequest(
            req
        );

    if (
        auth.authenticated
    ) {
        return next();
    }

    const api =
        security8AuthenticateApiKey(
            req
        );

    if (
        api.authenticated
    ) {
        return next();
    }

    return res.status(
        401
    ).json({
        success:
            false,

        error:
            "Kimlik doğrulama veya API anahtarı gerekli."
    });
}


