/* ======================================================
   9.63 - CLEANUP OLD EXPORTS
====================================================== */

async function conversation9CleanupExports() {
    const retentionMs =
        24 *
        60 *
        60 *
        1000;

    const now =
        Date.now();

    let removed =
        0;

    if (
        !fs.existsSync(
            CONVERSATION_EXPORT_ROOT_9
        )
    ) {
        return {
            success:
                true,

            removed:
                0
        };
    }

    const entries =
        await fs.promises.readdir(
            CONVERSATION_EXPORT_ROOT_9,
            {
                withFileTypes:
                    true
            }
        );

    for (
        const entry
        of entries
    ) {
        if (
            !entry.isFile()
        ) {
            continue;
        }

        const fullPath =
            path.join(
                CONVERSATION_EXPORT_ROOT_9,
                entry.name
            );

        try {
            const stat =
                await fs.promises.stat(
                    fullPath
                );

            if (
                now -
                stat.mtimeMs >
                retentionMs
            ) {
                await fs.promises.unlink(
                    fullPath
                );

                removed +=
                    1;
            }
        } catch {
            continue;
        }
    }

    return {
        success:
            true,

        removed,

        checkedAt:
            nowISO()
    };
}

const CONVERSATION_EXPORT_CLEANUP_TIMER_9 =
    setInterval(
        async () => {
            try {
                await conversation9CleanupExports();
            } catch (error) {
                conversation9SetError(
                    "export-cleanup",
                    error
                );
            }
        },
        60 * 60 * 1000
    );

