/* ======================================================
   9.65 - AI CHAT BRIDGE
====================================================== */

async function conversation9BridgeAIChat(
    userId,
    conversationId,
    userMessage,
    options = {}
) {
    const normalizedUser =
        conversation9NormalizeUserId(
            userId
        );

    let conversation =
        conversation9Read(
            normalizedUser,
            conversationId
        );

    if (
        !conversation
    ) {
        conversation =
            conversation9Create({
                userId:
                    normalizedUser,

                title:
                    options.title ||
                    conversation9GenerateTitle(
                        userMessage
                    ),

                folder:
                    options.folder ||
                    "Genel"
            });
    }

    const userMessageResult =
        conversation9AddMessage(
            normalizedUser,
            conversation.id,
            {
                role:
                    "user",

                content:
                    userMessage,

                model:
                    options.model,

                provider:
                    options.provider,

                attachments:
                    options.attachments,

                metadata:
                    {
                        source:
                            "ai-bridge"
                    }
            }
        );

    /*
       AI üretimini Part 2'ye bırakıyoruz.
       Buradaki katman yalnızca kalıcı konuşma
       geçmişini yönetiyor.
    */

    return {
        success:
            true,

        conversationId:
            conversation.id,

        userMessage:
            userMessageResult.message,

        history:
            conversation9GetMessages(
                normalizedUser,
                conversation.id,
                {
                    limit:
                        options.historyLimit ||
                        40
                }
            )
    };
}

