/* ======================================================
   10.4 - USER HELPERS
====================================================== */

function code10NormalizeUserId(
    userId
) {
    return (
        safeString(
            userId ||
            "anonymous",
            150
        )
            .trim()
            .replace(
                /[^a-zA-Z0-9._-]/g,
                "_"
            )
            .slice(
                0,
                90
            ) ||
        "anonymous"
    );
}

function code10UserDirectory(
    userId
) {
    const normalized =
        code10NormalizeUserId(
            userId
        );

    const directory =
        path.join(
            CODE_USERS_ROOT_10,
            normalized
        );

    fs.mkdirSync(
        directory,
        {
            recursive:
                true
        }
    );

    return directory;
}

function code10UserProjectIndexFile(
    userId
) {
    return path.join(
        code10UserDirectory(
            userId
        ),
        "projects.json"
    );
}

function code10UserSnippetFile(
    userId
) {
    return path.join(
        code10UserDirectory(
            userId
        ),
        "snippets.json"
    );
}


/* ======================================================
   10.5 - SAFE NAME HELPERS
====================================================== */

function code10SafeName(
    value,
    fallback = "untitled",
    max = 120
) {
    const source =
        safeString(
            value ||
            "",
            max
        ).trim();

    const cleaned =
        source
            .replace(
                /[<>:"/\\|?*\x00-\x1F]/g,
                "_"
            )
            .replace(
                /\.\./g,
                "_"
            )
            .replace(
                /\s+/g,
                " "
            )
            .slice(
                0,
                max
            )
            .trim();

    return (
        cleaned ||
        fallback
    );
}

function code10SafeFileName(
    value
) {
    return code10SafeName(
        value,
        "untitled.txt",
        CODE_ENGINE_CONFIG_10
            .limits
            .maxFileNameLength
    );
}

function code10SafeProjectName(
    value
) {
    return code10SafeName(
        value,
        "Yeni Proje",
        CODE_ENGINE_CONFIG_10
            .limits
            .maxProjectNameLength
    );
}


