/* ======================================================
   10.8 - LANGUAGE MAPS
====================================================== */

const CODE_EXTENSION_MAP_10 =
    new Map();

const CODE_ALIAS_MAP_10 =
    new Map();

for (
    const language
    of Object.values(
        CODE_LANGUAGES_10
    )
) {
    for (
        const extension
        of language.extensions
    ) {
        CODE_EXTENSION_MAP_10.set(
            extension,
            language.id
        );
    }

    for (
        const alias
        of language.aliases
    ) {
        CODE_ALIAS_MAP_10.set(
            normalizeText(
                alias
            ),
            language.id
        );
    }
}


/* ======================================================
   10.9 - LANGUAGE DETECTION
====================================================== */

function code10DetectLanguage(
    code = "",
    fileName = "",
    hint = ""
) {
    const cacheKey =
        `${fileName}|${hint}|${String(code).slice(0, 500)}`;

    if (
        CODE_LANGUAGE_CACHE_10.has(
            cacheKey
        )
    ) {
        return clone(
            CODE_LANGUAGE_CACHE_10.get(
                cacheKey
            )
        );
    }

    let languageId =
        null;

    const extension =
        path.extname(
            safeString(
                fileName,
                250
            )
        ).toLowerCase();

    if (
        extension &&
        CODE_EXTENSION_MAP_10.has(
            extension
        )
    ) {
        languageId =
            CODE_EXTENSION_MAP_10.get(
                extension
            );
    }

    if (
        !languageId &&
        hint
    ) {
        languageId =
            CODE_ALIAS_MAP_10.get(
                normalizeText(
                    hint
                )
            ) ||
            null;
    }

    const text =
        safeString(
            code,
            CODE_ENGINE_CONFIG_10
                .limits
                .maxCodeLength
        );

    if (
        !languageId
    ) {
        if (
            /<!doctype\s+html|<html[\s>]|<body[\s>]|<div[\s>]/i.test(
                text
            )
        ) {
            languageId =
                "html";
        } else if (
            /(^|\n)\s*import\s+[\w*{}, ]+\s+from\s+['"]/m.test(
                text
            ) ||
            /\bconst\s+\w+\s*=\s*(require|import)\(/.test(
                text
            )
        ) {
            languageId =
                "javascript";
        } else if (
            /\bdef\s+\w+\s*\(/.test(
                text
            ) ||
            /\bimport\s+\w+/.test(
                text
            ) &&
            /:\s*\n/.test(
                text
            )
        ) {
            languageId =
                "python";
        } else if (
            /\bpublic\s+static\s+void\s+main\b/.test(
                text
            ) &&
            /\bclass\s+\w+/.test(
                text
            )
        ) {
            languageId =
                "java";
        } else if (
            /#include\s*[<"]/.test(
                text
            ) &&
            /\bstd::/.test(
                text
            )
        ) {
            languageId =
                "cpp";
        } else if (
            /\bpackage\s+\w+/.test(
                text
            ) &&
            /\bfunc\s+\w+\s*\(/.test(
                text
            )
        ) {
            languageId =
                "go";
        } else if (
            /\bfn\s+\w+\s*\(/.test(
                text
            ) &&
            /\blet\s+mut\b/.test(
                text
            )
        ) {
            languageId =
                "rust";
        } else if (
            /\bSELECT\b/i.test(
                text
            ) &&
            /\bFROM\b/i.test(
                text
            )
        ) {
            languageId =
                "sql";
        } else if (
            /\b(Get-|Set-|Write-|New-|Start-|Stop-)[A-Za-z]/.test(
                text
            ) &&
            /\$\w+/.test(
                text
            )
        ) {
            languageId =
                "powershell";
        } else if (
            /(^|\n)\s*#!\/bin\/(bash|sh)/.test(
                text
            ) ||
            /(^|\n)\s*(echo|printf)\s+['"]/.test(
                text
            )
        ) {
            languageId =
                "shell";
        } else if (
            /^\s*[\[{]/.test(
                text
            ) &&
            /["'][^"']+["']\s*:/.test(
                text
            )
        ) {
            languageId =
                "json";
        } else if (
            /[.#]?[a-zA-Z_-]+\s*\{[^}]*:[^}]*\}/s.test(
                text
            )
        ) {
            languageId =
                "css";
        }
    }

    const result = languageId
        ? {
            detected:
                true,

            language:
                languageId,

            name:
                CODE_LANGUAGES_10[
                    languageId
                ]?.name ||
                languageId,

            confidence:
                extension &&
                CODE_EXTENSION_MAP_10.has(
                    extension
                )
                    ? 0.99
                    : hint
                        ? 0.95
                        : 0.70
        }
        : {
            detected:
                false,

            language:
                null,

            name:
                "Bilinmiyor",

            confidence:
                0
        };

    CODE_LANGUAGE_CACHE_10.set(
        cacheKey,
        clone(
            result
        )
    );

    if (
        CODE_LANGUAGE_CACHE_10.size >
        500
    ) {
        const first =
            CODE_LANGUAGE_CACHE_10
                .keys()
                .next()
                .value;

        if (first) {
            CODE_LANGUAGE_CACHE_10.delete(
                first
            );
        }
    }

    CODE_ENGINE_STATE_10
        .languageDetections +=
        1;

    return result;
}


/* ======================================================
   10.10 - LINE ANALYSIS
====================================================== */

function code10CountLines(
    code
) {
    if (!code) {
        return 0;
    }

    return String(
        code
    ).split(
        /\r?\n/
    ).length;
}

function code10CountNonEmptyLines(
    code
) {
    if (!code) {
        return 0;
    }

    return String(
        code
    )
        .split(/\r?\n/)
        .filter(
            line =>
                line.trim().length > 0
        )
        .length;
}

function code10CountComments(
    code,
    language
) {
    if (!code) {
        return 0;
    }

    const definition =
        CODE_LANGUAGES_10[
            language
        ];

    if (!definition) {
        return 0;
    }

    const lines =
        String(
            code
        ).split(
            /\r?\n/
        );

    let count =
        0;

    const single =
        definition.comment;

    const multiStart =
        definition.multilineCommentStart;

    const multiEnd =
        definition.multilineCommentEnd;

    let insideMulti =
        false;

    for (
        const line
        of lines
    ) {
        const trimmed =
            line.trim();

        if (
            !trimmed
        ) {
            continue;
        }

        if (
            multiStart &&
            trimmed.startsWith(
                multiStart
            )
        ) {
            count += 1;
            insideMulti =
                !(
                    multiEnd &&
                    trimmed.includes(
                        multiEnd,
                        multiStart.length
                    )
                );

            continue;
        }

        if (
            insideMulti
        ) {
            count += 1;

            if (
                multiEnd &&
                trimmed.includes(
                    multiEnd
                )
            ) {
                insideMulti =
                    false;
            }

            continue;
        }

        if (
            single &&
            trimmed.startsWith(
                single
            )
        ) {
            count += 1;
        }
    }

    return count;
}


/* ======================================================
   10.11 - BRACKET BALANCE
====================================================== */

function code10CheckBrackets(
    code
) {
    const source =
        String(
            code || ""
        );

    const stack = [];

    const pairs = {
        ")": "(",
        "]": "[",
        "}": "{"
    };

    const opening =
        new Set([
            "(",
            "[",
            "{"
        ]);

    const closing =
        new Set([
            ")",
            "]",
            "}"
        ]);

    let inSingle =
        false;

    let inDouble =
        false;

    let inTemplate =
        false;

    let escaped =
        false;

    let line =
        1;

    for (
        let index = 0;
        index < source.length;
        index++
    ) {
        const char =
            source[index];

        if (
            char === "\n"
        ) {
            line += 1;
        }

        if (
            escaped
        ) {
            escaped =
                false;

            continue;
        }

        if (
            char === "\\"
        ) {
            escaped =
                true;

            continue;
        }

        if (
            !inDouble &&
            !inTemplate &&
            char === "'"
        ) {
            inSingle =
                !inSingle;

            continue;
        }

        if (
            !inSingle &&
            !inTemplate &&
            char === '"'
        ) {
            inDouble =
                !inDouble;

            continue;
        }

        if (
            !inSingle &&
            !inDouble &&
            char === "`"
        ) {
            inTemplate =
                !inTemplate;

            continue;
        }

        if (
            inSingle ||
            inDouble ||
            inTemplate
        ) {
            continue;
        }

        if (
            opening.has(
                char
            )
        ) {
            stack.push({
                char,
                line,
                index
            });

            continue;
        }

        if (
            closing.has(
                char
            )
        ) {
            const last =
                stack.pop();

            if (
                !last ||
                last.char !==
                    pairs[char]
            ) {
                return {
                    balanced:
                        false,

                    error:
                        "Kapanmayan veya yanlış eşleşen parantez.",

                    line,

                    index,

                    expected:
                        last
                            ? pairs[char]
                            : null,

                    found:
                        char
                };
            }
        }
    }

    if (
        stack.length
    ) {
        const last =
            stack[
                stack.length - 1
            ];

        return {
            balanced:
                false,

            error:
                "Kapanmamış parantez bulundu.",

            line:
                last.line,

            index:
                last.index,

            expected:
                last.char
        };
    }

    return {
        balanced:
            true,

        error:
            null
    };
}


/* ======================================================
   10.12 - QUOTE BALANCE
====================================================== */

function code10CheckQuotes(
    code
) {
    const source =
        String(
            code || ""
        );

    let single =
        false;

    let double =
        false;

    let template =
        false;

    let escaped =
        false;

    for (
        let i = 0;
        i < source.length;
        i++
    ) {
        const char =
            source[i];

        if (
            escaped
        ) {
            escaped =
                false;

            continue;
        }

        if (
            char === "\\"
        ) {
            escaped =
                true;

            continue;
        }

        if (
            char === "'" &&
            !double &&
            !template
        ) {
            single =
                !single;

            continue;
        }

        if (
            char === '"' &&
            !single &&
            !template
        ) {
            double =
                !double;

            continue;
        }

        if (
            char === "`" &&
            !single &&
            !double
        ) {
            template =
                !template;
        }
    }

    return {
        balanced:
            !single &&
            !double &&
            !template,

        single,

        double,

        template
    };
}


