/* ======================================================
   10.14 - SECURITY SCAN
====================================================== */

function code10SecurityScan(
    code,
    language = null
) {
    CODE_ENGINE_STATE_10
        .securityScans +=
        1;

    const source =
        safeString(
            code,
            CODE_ENGINE_CONFIG_10
                .limits
                .maxCodeLength
        );

    const findings =
        [];

    for (
        const pattern
        of CODE_SECURITY_PATTERNS_10
    ) {
        if (
            !pattern.regex.test(
                source
            )
        ) {
            continue;
        }

        const match =
            source.match(
                pattern.regex
            );

        let line =
            null;

        if (
            match?.index !==
            undefined
        ) {
            line =
                code10CountLines(
                    source.slice(
                        0,
                        match.index
                    )
                );
        }

        findings.push({
            id:
                pattern.id,

            severity:
                pattern.severity,

            title:
                pattern.title,

            line,

            language:
                language || null,

            recommendation:
                pattern.recommendation
        });
    }

    const severityOrder = {
        critical:
            5,

        high:
            4,

        medium:
            3,

        low:
            2,

        info:
            1
    };

    findings.sort(
        (
            a,
            b
        ) =>
            (
                severityOrder[
                    b.severity
                ] || 0
            ) -
            (
                severityOrder[
                    a.severity
                ] || 0
            )
    );

    const summary = {
        total:
            findings.length,

        critical:
            findings.filter(
                item =>
                    item.severity ===
                    "critical"
            ).length,

        high:
            findings.filter(
                item =>
                    item.severity ===
                    "high"
            ).length,

        medium:
            findings.filter(
                item =>
                    item.severity ===
                    "medium"
            ).length,

        low:
            findings.filter(
                item =>
                    item.severity ===
                    "low"
            ).length
    };

    return {
        safe:
            summary.critical === 0 &&
            summary.high === 0,

        language:
            language || null,

        summary,

        findings
    };
}


/* ======================================================
   10.15 - TODO / FIXME SCAN
====================================================== */

function code10FindMarkers(
    code
) {
    const source =
        String(
            code || ""
        );

    const lines =
        source.split(
            /\r?\n/
        );

    const results =
        [];

    lines.forEach(
        (
            line,
            index
        ) => {
            const match =
                line.match(
                    /\b(TODO|FIXME|BUG|HACK|NOTE)\b/i
                );

            if (
                !match
            ) {
                return;
            }

            results.push({
                type:
                    match[1]
                        .toUpperCase(),

                line:
                    index + 1,

                text:
                    line.trim()
            });
        }
    );

    return results;
}


/* ======================================================
   10.16 - CODE QUALITY SCORE
====================================================== */

function code10CalculateQuality(
    code,
    syntax,
    security,
    language
) {
    const source =
        String(
            code || ""
        );

    let score =
        100;

    if (
        source.length ===
        0
    ) {
        return 0;
    }

    if (
        syntax &&
        syntax.brackets &&
        !syntax.brackets.balanced
    ) {
        score -= 35;
    }

    if (
        syntax &&
        syntax.quotes &&
        !syntax.quotes.balanced
    ) {
        score -= 25;
    }

    const securityFindings =
        security?.findings ||
        [];

    for (
        const finding
        of securityFindings
    ) {
        if (
            finding.severity ===
            "critical"
        ) {
            score -= 30;
        } else if (
            finding.severity ===
            "high"
        ) {
            score -= 18;
        } else if (
            finding.severity ===
            "medium"
        ) {
            score -= 8;
        } else {
            score -= 3;
        }
    }

    const lines =
        code10CountLines(
            source
        );

    if (
        lines > 1500
    ) {
        score -= 10;
    } else if (
        lines > 1000
    ) {
        score -= 5;
    }

    const markers =
        code10FindMarkers(
            source
        );

    if (
        markers.length > 20
    ) {
        score -= 10;
    } else if (
        markers.length > 10
    ) {
        score -= 5;
    }

    const finalScore =
        Math.max(
            0,
            Math.min(
                100,
                score
            )
        );

    let label =
        "iyi";

    if (
        finalScore < 40
    ) {
        label =
            "kritik";
    } else if (
        finalScore < 60
    ) {
        label =
            "geliştirilmeli";
    } else if (
        finalScore < 80
    ) {
        label =
            "orta";
    }

    return {
        score:
            finalScore,

        label,

        language:
            language || null,

        lineCount:
            lines,

        markerCount:
            markers.length
    };
}


/* ======================================================
   10.17 - FULL CODE ANALYSIS
====================================================== */

function code10Analyze(
    code,
    options = {}
) {
    CODE_ENGINE_STATE_10
        .analyses +=
        1;

    const source =
        safeString(
            code || "",
            CODE_ENGINE_CONFIG_10
                .limits
                .maxCodeLength
        );

    const languageInfo =
        code10DetectLanguage(
            source,
            options.fileName ||
            "",
            options.language ||
            ""
        );

    const language =
        options.language ||
        languageInfo.language ||
        null;

    const brackets =
        code10CheckBrackets(
            source
        );

    const quotes =
        code10CheckQuotes(
            source
        );

    const security =
        code10SecurityScan(
            source,
            language
        );

    const markers =
        code10FindMarkers(
            source
        );

    const quality =
        code10CalculateQuality(
            source,
            {
                brackets,
                quotes
            },
            security,
            language
        );

    const result = {
        success:
            true,

        language:
            languageInfo,

        statistics: {
            characters:
                source.length,

            lines:
                code10CountLines(
                    source
                ),

            nonEmptyLines:
                code10CountNonEmptyLines(
                    source
                ),

            comments:
                code10CountComments(
                    source,
                    language
                ),

            markerCount:
                markers.length
        },

        syntax: {
            brackets,
            quotes
        },

        security,

        markers,

        quality,

        analyzedAt:
            nowISO()
    };

    CODE_ENGINE_STATE_10
        .lastAnalysisAt =
        nowISO();

    CODE_GLOBAL_STATS_10
        .analyses +=
        1;

    writeJSON(
        CODE_GLOBAL_STATS_FILE_10,
        CODE_GLOBAL_STATS_10
    );

    return result;
}


/* ======================================================
   10.18 - SIMPLE FORMATTER
====================================================== */

function code10NormalizeLine(
    line
) {
    return String(
        line || ""
    )
        .replace(
            /\t/g,
            "    "
        )
        .replace(
            /[ \t]+$/g,
            ""
        );
}

function code10IndentDelta(
    line
) {
    let delta =
        0;

    const trimmed =
        line.trim();

    if (
        /^[}\])]/.test(
            trimmed
        )
    ) {
        delta -= 1;
    }

    const opens =
        (
            trimmed.match(
                /[{[(]/g
            ) ||
            []
        ).length;

    const closes =
        (
            trimmed.match(
                /[}\])]/g
            ) ||
            []
        ).length;

    delta +=
        opens -
        closes;

    return delta;
}

function code10FormatJavaScriptLike(
    code
) {
    const lines =
        String(
            code || ""
        )
            .replace(
                /\r\n/g,
                "\n"
            )
            .split(
                "\n"
            );

    const output =
        [];

    let level =
        0;

    for (
        const rawLine
        of lines
    ) {
        const normalized =
            code10NormalizeLine(
                rawLine
            );

        if (
            !normalized.trim()
        ) {
            output.push(
                ""
            );

            continue;
        }

        const trimmed =
            normalized.trim();

        if (
            /^[}\])]/.test(
                trimmed
            )
        ) {
            level =
                Math.max(
                    0,
                    level - 1
                );
        }

        output.push(
            " ".repeat(
                Math.max(
                    0,
                    level *
                    CODE_ENGINE_CONFIG_10
                        .formatter
                        .indentSize
                )
            ) +
            trimmed
        );

        const delta =
            code10IndentDelta(
                trimmed
            );

        if (
            delta > 0
        ) {
            level +=
                delta;
        }
    }

    return output.join(
        "\n"
    );
}

function code10Format(
    code,
    language = null
) {
    if (
        !CODE_ENGINE_CONFIG_10
            .formatter
            .enabled
    ) {
        return {
            success:
                false,

            code:
                String(
                    code || ""
                ),

            changed:
                false,

            reason:
                "formatter-disabled"
        };
    }

    const source =
        safeString(
            code || "",
            CODE_ENGINE_CONFIG_10
                .formatter
                .maxOutputLength
        );

    const detected =
        code10DetectLanguage(
            source,
            "",
            language || ""
        );

    const finalLanguage =
        language ||
        detected.language;

    let formatted =
        source;

    if (
        [
            "javascript",
            "typescript",
            "java",
            "c",
            "cpp",
            "csharp",
            "go",
            "rust",
            "php",
            "kotlin",
            "swift",
            "css",
            "scss"
        ].includes(
            finalLanguage
        )
    ) {
        formatted =
            code10FormatJavaScriptLike(
                source
            );
    }

    return {
        success:
            true,

        language:
            finalLanguage,

        changed:
            formatted !==
            source,

        originalLength:
            source.length,

        formattedLength:
            formatted.length,

        code:
            formatted
    };
}


