/* ======================================================
   10.20 - SNIPPET LIST
====================================================== */

function code10ListSnippets(
    userId,
    options = {}
) {
    const normalized =
        code10NormalizeUserId(
            userId
        );

    let snippets =
        readJSON(
            code10UserSnippetFile(
                normalized
            ),
            []
        );

    if (
        !Array.isArray(
            snippets
        )
    ) {
        snippets = [];
    }

    const query =
        normalizeText(
            safeString(
                options.search ||
                "",
                300
            )
        );

    if (
        query
    ) {
        snippets =
            snippets.filter(
                snippet => {
                    const haystack =
                        normalizeText(
                            [
                                snippet.title,
                                snippet.description,
                                snippet.language,
                                ...(snippet.tags || []),
                                snippet.code
                            ].join(" ")
                        );

                    return haystack.includes(
                        query
                    );
                }
            );
    }

    if (
        options.language
    ) {
        snippets =
            snippets.filter(
                snippet =>
                    snippet.language ===
                    options.language
            );
    }

    if (
        options.favorite !==
        undefined
    ) {
        snippets =
            snippets.filter(
                snippet =>
                    Boolean(
                        snippet.favorite
                    ) ===
                    Boolean(
                        options.favorite
                    )
            );
    }

    return snippets
        .sort(
            (
                a,
                b
            ) =>
                Date.parse(
                    b.updatedAt
                ) -
                Date.parse(
                    a.updatedAt
                )
        )
        .slice(
            0,
            clamp(
                Number(
                    options.limit
                ) || 100,
                1,
                CODE_ENGINE_CONFIG_10
                    .limits
                    .maxSnippetsPerUser
            )
        )
        .map(
            snippet =>
                clone(
                    snippet
                )
        );
}


/* ======================================================
   10.21 - SNIPPET SAVE
====================================================== */

function code10SaveSnippet(
    userId,
    options = {}
) {
    const normalized =
        code10NormalizeUserId(
            userId
        );

    const snippets =
        readJSON(
            code10UserSnippetFile(
                normalized
            ),
            []
        );

    const safeSnippets =
        Array.isArray(
            snippets
        )
            ? snippets
            : [];

    if (
        safeSnippets.length >=
        CODE_ENGINE_CONFIG_10
            .limits
            .maxSnippetsPerUser
    ) {
        throw new Error(
            "Snippet limiti doldu."
        );
    }

    const snippet =
        code10CreateSnippet(
            normalized,
            options
        );

    safeSnippets.unshift(
        snippet
    );

    writeJSON(
        code10UserSnippetFile(
            normalized
        ),
        safeSnippets
    );

    CODE_ENGINE_STATE_10
        .snippetsCreated +=
        1;

    CODE_GLOBAL_STATS_10
        .snippets +=
        1;

    writeJSON(
        CODE_GLOBAL_STATS_FILE_10,
        CODE_GLOBAL_STATS_10
    );

    return clone(
        snippet
    );
}


/* ======================================================
   10.22 - SNIPPET DELETE
====================================================== */

function code10DeleteSnippet(
    userId,
    snippetId
) {
    const normalized =
        code10NormalizeUserId(
            userId
        );

    const snippets =
        readJSON(
            code10UserSnippetFile(
                normalized
            ),
            []
        );

    if (
        !Array.isArray(
            snippets
        )
    ) {
        throw new Error(
            "Snippet listesi bulunamadı."
        );
    }

    const index =
        snippets.findIndex(
            snippet =>
                snippet?.id ===
                snippetId
        );

    if (
        index ===
        -1
    ) {
        throw new Error(
            "Snippet bulunamadı."
        );
    }

    const removed =
        snippets.splice(
            index,
            1
        )[0];

    writeJSON(
        code10UserSnippetFile(
            normalized
        ),
        snippets
    );

    CODE_ENGINE_STATE_10
        .snippetsDeleted +=
        1;

    return clone(
        removed
    );
}


