/* ======================================================
   10.41 - CODE API: ANALYZE
====================================================== */

app.post(
    "/api/code/analyze",
    (
        req,
        res
    ) => {
        try {
            const code =
                safeString(
                    req.body?.code ||
                    "",
                    CODE_ENGINE_CONFIG_10
                        .limits
                        .maxCodeLength
                );

            const cacheKey =
                `${req.body?.fileName || ""}|${req.body?.language || ""}|${code.length}|${code.slice(0, 200)}`;

            if (
                CODE_ANALYSIS_CACHE_10.has(
                    cacheKey
                )
            ) {
                return res.json({
                    success:
                        true,

                    cached:
                        true,

                    analysis:
                        clone(
                            CODE_ANALYSIS_CACHE_10.get(
                                cacheKey
                            )
                        )
                });
            }

            const analysis =
                code10Analyze(
                    code,
                    {
                        fileName:
                            req.body?.fileName,

                        language:
                            req.body?.language
                    }
                );

            CODE_ANALYSIS_CACHE_10.set(
                cacheKey,
                clone(
                    analysis
                )
            );

            if (
                CODE_ANALYSIS_CACHE_10.size >
                300
            ) {
                const first =
                    CODE_ANALYSIS_CACHE_10
                        .keys()
                        .next()
                        .value;

                if (
                    first
                ) {
                    CODE_ANALYSIS_CACHE_10.delete(
                        first
                    );
                }
            }

            CODE_ENGINE_STATE_10
                .successfulRequests +=
                1;

            res.json({
                success:
                    true,

                cached:
                    false,

                analysis
            });

        } catch (error) {
            CODE_ENGINE_STATE_10
                .failedRequests +=
                1;

            CODE_ENGINE_STATE_10
                .lastError = {
                    type:
                        "analysis",

                    message:
                        error.message,

                    at:
                        nowISO()
                };

            res.status(
                400
            ).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    }
);


