/* ======================================================
   10.49 - PROJECT LIST ROUTE
====================================================== */

app.get(
    "/api/code/projects",
    (
        req,
        res
    ) => {
        try {
            const userId =
                code10NormalizeUserId(
                    req.query?.userId ||
                    "anonymous"
                );

            let projects =
                code10ReadUserProjectIndex(
                    userId
                );

            const search =
                normalizeText(
                    safeString(
                        req.query?.search ||
                        "",
                        300
                    )
                );

            if (
                search
            ) {
                projects =
                    projects.filter(
                        project => {
                            const haystack =
                                normalizeText(
                                    [
                                        project.name,
                                        project.description,
                                        project.language,
                                        project.framework,
                                        ...(project.tags || [])
                                    ].join(
                                        " "
                                    )
                                );

                            return haystack.includes(
                                search
                            );
                        }
                    );
            }

            if (
                req.query?.language
            ) {
                projects =
                    projects.filter(
                        project =>
                            project.language ===
                            req.query.language
                    );
            }

            const limit =
                clamp(
                    Number(
                        req.query?.limit
                    ) || 100,
                    1,
                    1000
                );

            res.json({
                success:
                    true,

                projects:
                    projects.slice(
                        0,
                        limit
                    ),

                count:
                    Math.min(
                        projects.length,
                        limit
                    )
            });

        } catch (error) {
            res.status(
                500
            ).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    }
);


