/* ======================================================
   10.61 - CODE STATS
====================================================== */

app.get(
    "/api/code/stats",
    (
        req,
        res
    ) => {
        try {
            const userId =
                code10NormalizeUserId(
                    req.query?.userId ||
                    "anonymous"
                );

            const projects =
                code10ReadUserProjectIndex(
                    userId
                );

            const snippets =
                code10ListSnippets(
                    userId,
                    {
                        limit:
                            CODE_ENGINE_CONFIG_10
                                .limits
                                .maxSnippetsPerUser
                    }
                );

            let files =
                0;

            let codeLines =
                0;

            const languages = {};

            for (
                const project
                of projects
            ) {
                files +=
                    Number(
                        project.fileCount ||
                        0
                    );

                const full =
                    code10ReadProject(
                        userId,
                        project.id
                    );

                if (
                    !full
                ) {
                    continue;
                }

                for (
                    const file
                    of full.files
                ) {
                    codeLines +=
                        Number(
                            file.lineCount ||
                            0
                        );

                    const language =
                        file.language ||
                        "unknown";

                    languages[
                        language
                    ] =
                        Number(
                            languages[
                                language
                            ] || 0
                        ) + 1;
                }
            }

            res.json({
                success:
                    true,

                userId,

                projects:
                    projects.length,

                files,

                snippets:
                    snippets.length,

                codeLines,

                languages,

                engine:
                    clone(
                        CODE_ENGINE_STATE_10
                    )
            });

        } catch (error) {
            res.status(
                500
            ).json({
                success:
                    false,

                error:
                    error.message
            });
        }
    }
);


