/* ------------------------------------------------------------
   11.9 - COLLECTION MODEL
------------------------------------------------------------ */

function knowledge11CreateCollection({
  userId11,
  collectionId11 = null,
  name11 = "Genel",
  description11 = ""
} = {}) {
  const collections11 =
    knowledge11DefaultCollections();

  const safeUser11 =
    knowledge11SafeUserId(userId11);

  const id11 =
    knowledge11NormalizeId(
      collectionId11 ||
      `col-${createShortId()}`
    );

  if (!id11) {
    throw new Error("Geçersiz koleksiyon kimliği");
  }

  const key11 =
    `${safeUser11}:${id11}`;

  if (collections11[key11]) {
    return collections11[key11];
  }

  const collection11 = {
    id: id11,
    key: key11,
    userId: safeUser11,
    name: cleanText(
      safeString(name11, "Genel")
    ).slice(0, 120),
    description: cleanText(
      safeString(description11, "")
    ).slice(0, 500),
    documentCount: 0,
    chunkCount: 0,
    createdAt: nowISO(),
    updatedAt: nowISO()
  };

  collections11[key11] = collection11;

  knowledge11WriteFileJSON(
    KNOWLEDGE_COLLECTION_STORE_11,
    collections11
  );

  knowledge11AppendHistory({
    type: "collection_created",
    userId: safeUser11,
    collectionId: id11
  });

  return collection11;
}

function knowledge11FindCollection(
  userId11,
  collectionId11
) {
  const collections11 =
    knowledge11DefaultCollections();

  const safeUser11 =
    knowledge11SafeUserId(userId11);

  const safeCollection11 =
    knowledge11NormalizeId(
      collectionId11,
      "default"
    );

  const key11 =
    `${safeUser11}:${safeCollection11}`;

  return (
    collections11[key11] ||
    null
  );
}

function knowledge11EnsureCollection(
  userId11,
  collectionId11 = "default",
  collectionName11 = "Genel"
) {
  const found11 =
    knowledge11FindCollection(
      userId11,
      collectionId11
    );

  if (found11) return found11;

  return knowledge11CreateCollection({
    userId11,
    collectionId11,
    name11: collectionName11
  });
}

function knowledge11RecountCollections() {
  const collections11 =
    knowledge11DefaultCollections();

  const documents11 =
    knowledge11DefaultDocuments();

  const chunks11 =
    knowledge11DefaultChunks();

  for (const key11 of Object.keys(collections11)) {
    const collection11 =
      collections11[key11];

    collection11.documentCount = 0;
    collection11.chunkCount = 0;
  }

  for (const documentId11 of Object.keys(documents11)) {
    const document11 =
      documents11[documentId11];

    if (!document11 || document11.deletedAt) {
      continue;
    }

    const collectionKey11 =
      `${document11.userId}:${document11.collectionId}`;

    if (!collections11[collectionKey11]) {
      collections11[collectionKey11] =
        knowledge11CreateCollection({
          userId11: document11.userId,
          collectionId11: document11.collectionId,
          name11: "Otomatik Koleksiyon"
        });
    }

    if (collections11[collectionKey11]) {
      collections11[collectionKey11]
        .documentCount += 1;
    }
  }

  for (const chunkId11 of Object.keys(chunks11)) {
    const chunk11 = chunks11[chunkId11];

    if (!chunk11 || chunk11.deletedAt) {
      continue;
    }

    const collectionKey11 =
      `${chunk11.userId}:${chunk11.collectionId}`;

    if (collections11[collectionKey11]) {
      collections11[collectionKey11]
        .chunkCount += 1;
    }
  }

  for (const key11 of Object.keys(collections11)) {
    collections11[key11].updatedAt = nowISO();
  }

  knowledge11WriteFileJSON(
    KNOWLEDGE_COLLECTION_STORE_11,
    collections11
  );

  return collections11;
}

/* ------------------------------------------------------------
   11.10 - DOCUMENT MODEL
------------------------------------------------------------ */

function knowledge11MakeDocument({
  userId11,
  collectionId11,
  title11,
  text11,
  sourceType11 = "text",
  sourceName11 = "",
  sourceUrl11 = "",
  mimeType11 = "text/plain",
  tags11 = [],
  metadata11 = {},
  language11 = "tr",
  pinned11 = false
} = {}) {
  const safeUser11 =
    knowledge11SafeUserId(userId11);

  const normalizedText11 =
    knowledge11NormalizeText(text11);

  const checksum11 =
    knowledge11Hash(normalizedText11);

  const documentId11 =
    `doc-${knowledge11CreateShortHash(
      `${safeUser11}:${collectionId11}:${checksum11}:${title11}`
    )}`;

  return {
    id: documentId11,
    userId: safeUser11,
    collectionId: knowledge11NormalizeId(
      collectionId11,
      "default"
    ),
    title: cleanText(
      safeString(title11, "Adsız belge")
    ).slice(0, 300),
    sourceType: safeString(
      sourceType11,
      "text"
    ).slice(0, 40),
    sourceName: cleanText(
      safeString(sourceName11, "")
    ).slice(0, 300),
    sourceUrl: safeString(
      sourceUrl11,
      ""
    ).slice(0, 1000),
    mimeType: safeString(
      mimeType11,
      "text/plain"
    ).slice(0, 120),
    language: safeString(
      language11,
      "tr"
    ).slice(0, 20),
    tags: uniqueArray(
      knowledge11Array(tags11)
        .map((tag11) =>
          cleanText(
            safeString(tag11, "")
          ).toLocaleLowerCase("tr-TR")
        )
        .filter(Boolean)
        .slice(0, 50)
    ),
    metadata: isObject(metadata11)
      ? clone(metadata11)
      : {},
    pinned: Boolean(pinned11),
    checksum: checksum11,
    charCount: normalizedText11.length,
    wordCount:
      normalizedText11
        ? normalizedText11.split(/\s+/).length
        : 0,
    createdAt: nowISO(),
    updatedAt: nowISO(),
    indexedAt: null,
    deletedAt: null
  };
}

/* ------------------------------------------------------------
   11.11 - DOCUMENT TEXT STORAGE
------------------------------------------------------------ */

function knowledge11DocumentTextPath(
  documentId11
) {
  const safeId11 =
    knowledge11NormalizeId(documentId11);

  return path11.join(
    KNOWLEDGE_DOCS_11,
    `${safeId11}.txt`
  );
}

function knowledge11SaveDocumentText(
  documentId11,
  text11
) {
  const filePath11 =
    knowledge11DocumentTextPath(
      documentId11
    );

  fs11.writeFileSync(
    filePath11,
    text11,
    "utf8"
  );

  return filePath11;
}

function knowledge11LoadDocumentText(
  document11
) {
  if (!document11) return "";

  const filePath11 =
    knowledge11DocumentTextPath(
      document11.id
    );

  try {
    if (fs11.existsSync(filePath11)) {
      return fs11.readFileSync(
        filePath11,
        "utf8"
      );
    }
  } catch (_) {}

  return "";
}

/* ------------------------------------------------------------
   11.12 - TOKEN FREQUENCY
------------------------------------------------------------ */

function knowledge11TokenFrequency(
  value11
) {
  const freq11 = {};
  const tokens11 =
    knowledge11UsefulTokens(value11);

  for (const token11 of tokens11) {
    freq11[token11] =
      (freq11[token11] || 0) + 1;
  }

  return freq11;
}

/* ------------------------------------------------------------
   11.13 - CHUNK CREATION
------------------------------------------------------------ */

function knowledge11BuildDocumentChunks(
  document11,
  text11
) {
  const settings11 =
    knowledge11GetSettings();

  const chunks11 =
    knowledge11ChunkText(
      text11,
      settings11.maxChunkTokens,
      settings11.overlapTokens
    );

  const output11 = {};

  for (const part11 of chunks11) {
    const chunkId11 =
      `chk-${knowledge11CreateShortHash(
        `${document11.id}:${part11.index}:${part11.text}`
      )}`;

    const normalizedTokens11 =
      knowledge11UsefulTokens(
        part11.text
      );

    output11[chunkId11] = {
      id: chunkId11,
      documentId: document11.id,
      userId: document11.userId,
      collectionId: document11.collectionId,
      index: part11.index,
      text: part11.text,
      tokenCount: part11.tokenCount,
      normalizedTokens: normalizedTokens11,
      tokenFrequency:
        knowledge11TokenFrequency(
          part11.text
        ),
      startToken: part11.startToken,
      endToken: part11.endToken,
      createdAt: nowISO(),
      deletedAt: null
    };
  }

  return output11;
}

/* ------------------------------------------------------------
   11.14 - INDEX BUILDING
------------------------------------------------------------ */

function knowledge11RebuildIndex() {
  const documents11 =
    knowledge11DefaultDocuments();

  const chunks11 =
    knowledge11DefaultChunks();

  const tokenIndex11 = {};

  for (const chunkId11 of Object.keys(chunks11)) {
    const chunk11 =
      chunks11[chunkId11];

    if (!chunk11 || chunk11.deletedAt) {
      continue;
    }

    const frequencies11 =
      isObject(chunk11.tokenFrequency)
        ? chunk11.tokenFrequency
        : knowledge11TokenFrequency(
            chunk11.text
          );

    chunk11.tokenFrequency =
      frequencies11;

    chunk11.normalizedTokens =
      Object.keys(frequencies11);

    for (const token11 of Object.keys(frequencies11)) {
      if (!tokenIndex11[token11]) {
        tokenIndex11[token11] = {
          df: 0,
          postings: {}
        };
      }

      tokenIndex11[token11].df += 1;

      tokenIndex11[token11]
        .postings[chunkId11] =
        frequencies11[token11];
    }
  }

  knowledge11WriteFileJSON(
    KNOWLEDGE_CHUNK_STORE_11,
    chunks11
  );

  knowledge11WriteFileJSON(
    KNOWLEDGE_TOKEN_INDEX_11,
    tokenIndex11
  );

  let indexedTokens11 = 0;

  for (const token11 of Object.keys(tokenIndex11)) {
    indexedTokens11 +=
      Object.keys(
        tokenIndex11[token11].postings || {}
      ).length;
  }

  const settingsStats11 =
    knowledge11GetStats();

  settingsStats11.documents =
    Object.keys(documents11)
      .filter(
        (id11) =>
          !documents11[id11]?.deletedAt
      ).length;

  settingsStats11.activeDocuments =
    settingsStats11.documents;

  settingsStats11.archivedDocuments =
    Object.keys(documents11)
      .filter(
        (id11) =>
          Boolean(
            documents11[id11]?.deletedAt
          )
      ).length;

  settingsStats11.chunks =
    Object.keys(chunks11)
      .filter(
        (id11) =>
          !chunks11[id11]?.deletedAt
      ).length;

  settingsStats11.indexedTokens =
    indexedTokens11;

  settingsStats11.collections =
    Object.keys(
      knowledge11DefaultCollections()
    ).length;

  settingsStats11.lastRebuild =
    nowISO();

  knowledge11SaveStats(
    settingsStats11
  );

  knowledge11RecountCollections();

  knowledge11AppendHistory({
    type: "index_rebuilt",
    documents: settingsStats11.documents,
    chunks: settingsStats11.chunks,
    indexedTokens: indexedTokens11
  });

  return {
    success: true,
    documents: settingsStats11.documents,
    chunks: settingsStats11.chunks,
    indexedTokens: indexedTokens11,
    rebuiltAt: settingsStats11.lastRebuild
  };
}

/* ------------------------------------------------------------
   11.15 - STARTUP INDEX REPAIR
------------------------------------------------------------ */

(function knowledge11StartupRepair() {
  try {
    const documents11 =
      knowledge11DefaultDocuments();

    const chunks11 =
      knowledge11DefaultChunks();

    const index11 =
      knowledge11DefaultTokenIndex();

    const needsRepair11 =
      Object.keys(documents11).length > 0 &&
      (
        Object.keys(chunks11).length === 0 ||
        Object.keys(index11).length === 0
      );

    if (needsRepair11) {
      knowledge11RebuildIndex();
    } else {
      knowledge11RecountCollections();
    }
  } catch (error11) {
    systemLog?.(
      "knowledge11_startup_repair_error",
      {
        error:
          error11?.message ||
          String(error11)
      }
    );
  }
})();

/* ------------------------------------------------------------
   11.16 - ADD DOCUMENT
------------------------------------------------------------ */

function knowledge11AddDocument({
  userId11,
  collectionId11 = "default",
  title11 = "Yeni belge",
  text11 = "",
  sourceType11 = "text",
  sourceName11 = "",
  sourceUrl11 = "",
  mimeType11 = "text/plain",
  tags11 = [],
  metadata11 = {},
  language11 = "tr",
  pinned11 = false
} = {}) {
  const safeUser11 =
    knowledge11SafeUserId(userId11);

  const settings11 =
    knowledge11GetSettings();

  let normalizedText11 =
    knowledge11NormalizeText(text11);

  if (!normalizedText11) {
    throw new Error(
      "Knowledge Base belgesi boş olamaz."
    );
  }

  if (
    normalizedText11.length >
    settings11.maxDocumentChars
  ) {
    normalizedText11 =
      normalizedText11.slice(
        0,
        settings11.maxDocumentChars
      );
  }

  const collection11 =
    knowledge11EnsureCollection(
      safeUser11,
      collectionId11,
      collectionId11 === "default"
        ? "Genel"
        : "Knowledge Collection"
    );

  const documents11 =
    knowledge11DefaultDocuments();

  const checksum11 =
    knowledge11Hash(
      normalizedText11
    );

  /* Duplicate control */
  const duplicate11 =
    Object.values(documents11)
      .find(
        (doc11) =>
          doc11 &&
          !doc11.deletedAt &&
          doc11.userId === safeUser11 &&
          doc11.collectionId ===
            collection11.id &&
          doc11.checksum ===
            checksum11
      );

  if (duplicate11) {
    return {
      duplicate: true,
      document: duplicate11
    };
  }

  const document11 =
    knowledge11MakeDocument({
      userId11: safeUser11,
      collectionId11:
        collection11.id,
      title11,
      text11:
        normalizedText11,
      sourceType11,
      sourceName11,
      sourceUrl11,
      mimeType11,
      tags11,
      metadata11,
      language11,
      pinned11
    });

  knowledge11SaveDocumentText(
    document11.id,
    normalizedText11
  );

  const chunksForDocument11 =
    knowledge11BuildDocumentChunks(
      document11,
      normalizedText11
    );

  const chunks11 =
    knowledge11DefaultChunks();

  for (
    const chunkId11 of
    Object.keys(chunksForDocument11)
  ) {
    chunks11[chunkId11] =
      chunksForDocument11[chunkId11];
  }

  document11.indexedAt =
    nowISO();

  documents11[document11.id] =
    document11;

  knowledge11WriteFileJSON(
    KNOWLEDGE_DOCUMENT_STORE_11,
    documents11
  );

  knowledge11WriteFileJSON(
    KNOWLEDGE_CHUNK_STORE_11,
    chunks11
  );

  knowledge11RebuildIndex();

  const stats11 =
    knowledge11GetStats();

  stats11.documentsAdded += 1;

  knowledge11SaveStats(
    stats11
  );

  knowledge11AppendHistory({
    type: "document_added",
    documentId: document11.id,
    userId: safeUser11,
    collectionId:
      collection11.id,
    sourceType:
      document11.sourceType,
    chunkCount:
      Object.keys(
        chunksForDocument11
      ).length
  });

  return {
    duplicate: false,
    document: {
      ...document11,
      text: normalizedText11,
      chunkCount:
        Object.keys(
          chunksForDocument11
        ).length
    }
  };
}

/* ------------------------------------------------------------
   11.17 - UPDATE DOCUMENT
------------------------------------------------------------ */

function knowledge11UpdateDocument(
  documentId11,
  userId11,
  updates11 = {}
) {
  const documents11 =
    knowledge11DefaultDocuments();

  const document11 =
    documents11[
      knowledge11NormalizeId(
        documentId11
      )
    ];

  if (!document11) {
    throw new Error(
      "Belge bulunamadı."
    );
  }

  const safeUser11 =
    knowledge11SafeUserId(userId11);

  if (
    document11.userId !== safeUser11
  ) {
    throw new Error(
      "Bu belgeye erişim izni yok."
    );
  }

  const existingText11 =
    knowledge11LoadDocumentText(
      document11
    );

  const nextText11 =
    Object.prototype.hasOwnProperty.call(
      updates11,
      "text"
    )
      ? knowledge11NormalizeText(
          updates11.text
        )
      : existingText11;

  if (!nextText11) {
    throw new Error(
      "Belge metni boş olamaz."
    );
  }

  const nextTitle11 =
    Object.prototype.hasOwnProperty.call(
      updates11,
      "title"
    )
      ? cleanText(
          safeString(
            updates11.title,
            document11.title
          )
        ).slice(0, 300)
      : document11.title;

  const changedText11 =
    knowledge11Hash(
      nextText11
    ) !== document11.checksum;

  document11.title =
    nextTitle11;

  document11.tags =
    Object.prototype.hasOwnProperty.call(
      updates11,
      "tags"
    )
      ? uniqueArray(
          knowledge11Array(
            updates11.tags
          )
            .map((tag11) =>
              cleanText(
                safeString(tag11, "")
              )
            )
            .filter(Boolean)
        ).slice(0, 50)
      : document11.tags;

  if (
    Object.prototype.hasOwnProperty.call(
      updates11,
      "sourceName"
    )
  ) {
    document11.sourceName =
      cleanText(
        safeString(
          updates11.sourceName,
          document11.sourceName
        )
      ).slice(0, 300);
  }

  if (
    Object.prototype.hasOwnProperty.call(
      updates11,
      "sourceUrl"
    )
  ) {
    document11.sourceUrl =
      safeString(
        updates11.sourceUrl,
        document11.sourceUrl
      ).slice(0, 1000);
  }

  if (
    Object.prototype.hasOwnProperty.call(
      updates11,
      "pinned"
    )
  ) {
    document11.pinned =
      Boolean(
        updates11.pinned
      );
  }

  if (changedText11) {
    document11.checksum =
      knowledge11Hash(
        nextText11
      );

    document11.charCount =
      nextText11.length;

    document11.wordCount =
      nextText11
        ? nextText11.split(/\s+/).length
        : 0;

    knowledge11SaveDocumentText(
      document11.id,
      nextText11
    );

    const chunks11 =
      knowledge11DefaultChunks();

    for (
      const chunkId11 of
      Object.keys(chunks11)
    ) {
      if (
        chunks11[chunkId11]?.documentId ===
        document11.id
      ) {
        delete chunks11[chunkId11];
      }
    }

    const regeneratedChunks11 =
      knowledge11BuildDocumentChunks(
        document11,
        nextText11
      );

    for (
      const chunkId11 of
      Object.keys(regeneratedChunks11)
    ) {
      chunks11[chunkId11] =
        regeneratedChunks11[
          chunkId11
        ];
    }

    knowledge11WriteFileJSON(
      KNOWLEDGE_CHUNK_STORE_11,
      chunks11
    );

    document11.indexedAt =
      nowISO();
  }

  document11.updatedAt =
    nowISO();

  documents11[
    document11.id
  ] = document11;

  knowledge11WriteFileJSON(
    KNOWLEDGE_DOCUMENT_STORE_11,
    documents11
  );

  knowledge11RebuildIndex();

  knowledge11AppendHistory({
    type: "document_updated",
    documentId: document11.id,
    userId: safeUser11,
    textChanged: changedText11
  });

  return {
    success: true,
    document: document11
  };
}

/* ------------------------------------------------------------
   11.18 - DELETE DOCUMENT
------------------------------------------------------------ */

function knowledge11DeleteDocument(
  documentId11,
  userId11,
  hardDelete11 = false
) {
  const documents11 =
    knowledge11DefaultDocuments();

  const safeId11 =
    knowledge11NormalizeId(
      documentId11
    );

  const document11 =
    documents11[safeId11];

  if (!document11) {
    throw new Error(
      "Belge bulunamadı."
    );
  }

  const safeUser11 =
    knowledge11SafeUserId(userId11);

  if (
    document11.userId !== safeUser11
  ) {
    throw new Error(
      "Bu belgeye erişim izni yok."
    );
  }

  const chunks11 =
    knowledge11DefaultChunks();

  for (
    const chunkId11 of
    Object.keys(chunks11)
  ) {
    if (
      chunks11[chunkId11]?.documentId ===
      document11.id
    ) {
      if (hardDelete11) {
        delete chunks11[chunkId11];
      } else {
        chunks11[chunkId11].deletedAt =
          nowISO();
      }
    }
  }

  if (hardDelete11) {
    delete documents11[
      document11.id
    ];

    const filePath11 =
      knowledge11DocumentTextPath(
        document11.id
      );

    try {
      if (
        fs11.existsSync(
          filePath11
        )
      ) {
        fs11.unlinkSync(
          filePath11
        );
      }
    } catch (_) {}
  } else {
    document11.deletedAt =
      nowISO();
    document11.updatedAt =
      nowISO();
  }

  knowledge11WriteFileJSON(
    KNOWLEDGE_DOCUMENT_STORE_11,
    documents11
  );

  knowledge11WriteFileJSON(
    KNOWLEDGE_CHUNK_STORE_11,
    chunks11
  );

  knowledge11RebuildIndex();

  const stats11 =
    knowledge11GetStats();

  stats11.documentsDeleted += 1;

  knowledge11SaveStats(
    stats11
  );

  knowledge11AppendHistory({
    type: hardDelete11
      ? "document_hard_deleted"
      : "document_deleted",
    documentId: document11.id,
    userId: safeUser11
  });

  return {
    success: true,
    hardDelete:
      Boolean(hardDelete11),
    documentId:
      document11.id
  };
}

/* ------------------------------------------------------------
   11.19 - ACCESS CONTROL
------------------------------------------------------------ */

function knowledge11CanReadDocument(
  document11,
  userId11
) {
  if (!document11) return false;

  if (document11.deletedAt) {
    return false;
  }

  const safeUser11 =
    knowledge11SafeUserId(userId11);

  if (
    document11.userId ===
    safeUser11
  ) {
    return true;
  }

  if (
    document11.userId ===
    "global"
  ) {
    return true;
  }

  return false;
}

/* ------------------------------------------------------------
   11.20 - BM25-LIKE SEARCH
------------------------------------------------------------ */

function knowledge11Search({
  userId11 = "guest",
  query11 = "",
  collectionId11 = null,
  topK11 = 8,
  tags11 = [],
  includeArchived11 = false,
  minScore11 = 0
} = {}) {
  const settings11 =
    knowledge11GetSettings();

  const queryTokens11 =
    knowledge11UsefulTokens(
      query11
    );

  if (
    queryTokens11.length === 0
  ) {
    return {
      query:
        knowledge11NormalizeText(
          query11
        ),
      results: [],
      total: 0,
      tookMs: 0
    };
  }

  const start11 =
    Date.now();

  const documents11 =
    knowledge11DefaultDocuments();

  const chunks11 =
    knowledge11DefaultChunks();

  const tokenIndex11 =
    knowledge11DefaultTokenIndex();

  const safeUser11 =
    knowledge11SafeUserId(userId11);

  const normalizedCollection11 =
    collectionId11
      ? knowledge11NormalizeId(
          collectionId11
        )
      : null;

  const requestedTags11 =
    knowledge11Array(tags11)
      .map((tag11) =>
        cleanText(
          safeString(tag11, "")
        ).toLocaleLowerCase(
          "tr-TR"
        )
      )
      .filter(Boolean);

  const activeChunkEntries11 =
    Object.values(chunks11)
      .filter(
        (chunk11) =>
          chunk11 &&
          knowledge11CanReadDocument(
            documents11[
              chunk11.documentId
            ],
            safeUser11
          ) &&
          (
            includeArchived11 ||
            !chunk11.deletedAt
          ) &&
          (
            !normalizedCollection11 ||
            chunk11.collectionId ===
              normalizedCollection11
          )
      );

  const totalChunks11 =
    activeChunkEntries11.length;

  const avgLength11 =
    totalChunks11 > 0
      ? activeChunkEntries11.reduce(
          (
            sum11,
            chunk11
          ) =>
            sum11 +
            toNumber(
              chunk11.tokenCount,
              1
            ),
          0
        ) /
        totalChunks11
      : 1;

  const k1_11 = 1.2;
  const b_11 = 0.75;

  const queryCounts11 = {};

  for (
    const token11 of
    queryTokens11
  ) {
    queryCounts11[token11] =
      (queryCounts11[token11] || 0) + 1;
  }

  const candidateIds11 =
    new Set();

  for (
    const token11 of
    Object.keys(queryCounts11)
  ) {
    const entry11 =
      tokenIndex11[
        token11
      ];

    if (!entry11) {
      continue;
    }

    for (
      const chunkId11 of
      Object.keys(
        entry11.postings || {}
      )
    ) {
      candidateIds11.add(
        chunkId11
      );
    }
  }

  const candidates11 =
    activeChunkEntries11
      .filter(
        (chunk11) =>
          candidateIds11.has(
            chunk11.id
          )
      );

  const results11 = [];

  for (
    const chunk11 of
    candidates11
  ) {
    const document11 =
      documents11[
        chunk11.documentId
      ];

    if (!document11) {
      continue;
    }

    let score11 = 0;

    const length11 =
      Math.max(
        1,
        toNumber(
          chunk11.tokenCount,
          1
        )
      );

    const denominator11 =
      k1_11 *
      (
        1 -
        b_11 +
        b_11 *
        (
          length11 /
          Math.max(
            avgLength11,
            1
          )
        )
      );

    const frequencyMap11 =
      isObject(
        chunk11.tokenFrequency
      )
        ? chunk11.tokenFrequency
        : knowledge11TokenFrequency(
            chunk11.text
          );

    for (
      const token11 of
      Object.keys(queryCounts11)
    ) {
      const tf11 =
        toNumber(
          frequencyMap11[
            token11
          ],
          0
        );

      if (tf11 <= 0) {
        continue;
      }

      const df11 =
        toNumber(
          tokenIndex11[
            token11
          ]?.df,
          0
        );

      const idf11 =
        Math.log(
          (
            totalChunks11 + 1
          ) /
          (
            df11 + 0.5
          )
        );

      const tfScore11 =
        (
          tf11 *
          (
            k1_11 + 1
          )
        ) /
        (
          tf11 +
          denominator11
        );

      score11 +=
        idf11 *
        tfScore11;
    }

    const title11 =
      document11.title
        .toLocaleLowerCase(
          "tr-TR"
        );

    const query11Normalized =
      knowledge11NormalizeText(
        query11
      ).toLocaleLowerCase(
        "tr-TR"
      );

    if (
      title11 &&
      query11Normalized &&
      title11.includes(
        query11Normalized
      )
    ) {
      score11 +=
        settings11.titleBoost;
    }

    if (
      query11Normalized &&
      document11.tags?.some(
        (tag11) =>
          query11Normalized.includes(
            safeString(
              tag11,
              ""
            )
          )
      )
    ) {
      score11 +=
        settings11.tagBoost;
    }

    const lowerChunk11 =
      chunk11.text
        .toLocaleLowerCase(
          "tr-TR"
        );

    if (
      query11Normalized.length >= 5 &&
      lowerChunk11.includes(
        query11Normalized
      )
    ) {
      score11 +=
        settings11.phraseBoost;
    }

    if (
      document11.sourceType ===
      "research"
    ) {
      score11 +=
        settings11.sourceBoost;
    }

    if (
      score11 <
      toNumber(
        minScore11,
        0
      )
    ) {
      continue;
    }

    const preview11 =
      chunk11.text.length > 700
        ? `${chunk11.text.slice(
            0,
            700
          )}…`
        : chunk11.text;

    results11.push({
      score:
        Number(
          score11.toFixed(6)
        ),
      chunkId:
        chunk11.id,
      documentId:
        document11.id,
      documentTitle:
        document11.title,
      collectionId:
        document11.collectionId,
      sourceType:
        document11.sourceType,
      sourceName:
        document11.sourceName,
      sourceUrl:
        document11.sourceUrl,
      tags:
        document11.tags || [],
      chunkIndex:
        chunk11.index,
      text:
        chunk11.text,
      preview:
        preview11,
      citation:
        `[KB:${document11.id}:${chunk11.index + 1}]`
    });
  }

  results11.sort(
    (a11, b11) =>
      b11.score -
      a11.score
  );

  const limited11 =
    results11.slice(
      0,
      clamp(
        toInteger(
          topK11,
          settings11.defaultTopK
        ),
        1,
        settings11.maxTopK
      )
    );

  const stats11 =
    knowledge11GetStats();

  stats11.searches += 1;
  stats11.lastSearch =
    nowISO();

  knowledge11SaveStats(
    stats11
  );

  knowledge11AppendHistory({
    type: "search",
    userId:
      safeUser11,
    query:
      knowledge11NormalizeText(
        query11
      ).slice(0, 500),
    collectionId:
      normalizedCollection11,
    results:
      limited11.length,
    durationMs:
      Date.now() - start11
  });

  return {
    query:
      knowledge11NormalizeText(
        query11
      ),
    tokens:
      queryTokens11,
    results:
      limited11,
    total:
      limited11.length,
    searchedChunks:
      activeChunkEntries11.length,
    tookMs:
      Date.now() - start11
  };
}

/* ------------------------------------------------------------
   11.21 - SEARCH CACHE
------------------------------------------------------------ */

function knowledge11CacheKey({
  userId11,
  query11,
  collectionId11,
  topK11,
  tags11
}) {
  return knowledge11Hash(
    JSON.stringify({
      userId11:
        knowledge11SafeUserId(
          userId11
        ),
      query11:
        knowledge11NormalizeText(
          query11
        ).toLocaleLowerCase(
          "tr-TR"
        ),
      collectionId11:
        collectionId11 || null,
      topK11,
      tags11:
        knowledge11Array(
          tags11
        ).sort()
    })
  );
}

function knowledge11SearchCached(
  params11
) {
  const settings11 =
    knowledge11GetSettings();

  if (!settings11.cacheEnabled) {
    return knowledge11Search(
      params11
    );
  }

  const cache11 =
    knowledge11ReadFileJSON(
      KNOWLEDGE_SEARCH_CACHE_11,
      {}
    );

  const key11 =
    knowledge11CacheKey(
      params11
    );

  const cached11 =
    cache11[key11];

  if (
    cached11 &&
    (
      Date.now() -
      toNumber(
        cached11.createdAtMs,
        0
      )
    ) <
      settings11.cacheTtlMs
  ) {
    const stats11 =
      knowledge11GetStats();

    stats11.cacheHits += 1;

    knowledge11SaveStats(
      stats11
    );

    return {
      ...cached11.result,
      cached: true
    };
  }

  const stats11 =
    knowledge11GetStats();

  stats11.cacheMisses += 1;

  knowledge11SaveStats(
    stats11
  );

  const result11 =
    knowledge11Search(
      params11
    );

  cache11[key11] = {
    createdAtMs:
      Date.now(),
    result:
      result11
  };

  const cacheKeys11 =
    Object.keys(
      cache11
    );

  if (cacheKeys11.length > 300) {
    cacheKeys11
      .sort(
        (a11, b11) =>
          toNumber(
            cache11[
              a11
            ]?.createdAtMs,
            0
          ) -
          toNumber(
            cache11[
              b11
            ]?.createdAtMs,
            0
          )
      )
      .slice(
        0,
        cacheKeys11.length - 300
      )
      .forEach(
        (keyRemove11) =>
          delete cache11[
            keyRemove11
          ]
      );
  }

  knowledge11WriteFileJSON(
    KNOWLEDGE_SEARCH_CACHE_11,
    cache11
  );

  return {
    ...result11,
    cached: false
  };
}

/* ------------------------------------------------------------
   11.22 - RAG CONTEXT BUILDER
------------------------------------------------------------ */

function knowledge11BuildContext({
  userId11 = "guest",
  query11 = "",
  collectionId11 = null,
  topK11 = 8,
  maxContextChars11 = 12000,
  tags11 = []
} = {}) {
  const settings11 =
    knowledge11GetSettings();

  const effectiveMax11 =
    clamp(
      toInteger(
        maxContextChars11,
        settings11.defaultMaxContextChars
      ),
      1000,
      settings11.maxContextChars
    );

  const search11 =
    knowledge11SearchCached({
      userId11,
      query11,
      collectionId11,
      topK11,
      tags11
    });

  const blocks11 = [];
  let usedChars11 = 0;

  for (
    const result11 of
    search11.results
  ) {
    const sourceHeader11 =
      [
        result11.citation,
        result11.documentTitle,
        result11.sourceName
          ? `Kaynak: ${result11.sourceName}`
          : null,
        result11.sourceUrl
          ? `URL: ${result11.sourceUrl}`
          : null
      ]
        .filter(Boolean)
        .join(" | ");

    const block11 =
      `${sourceHeader11}\n${result11.text}`;

    if (
      usedChars11 +
      block11.length >
      effectiveMax11
    ) {
      const remaining11 =
        effectiveMax11 -
        usedChars11;

      if (remaining11 > 250) {
        blocks11.push(
          block11.slice(
            0,
            remaining11
          )
        );
      }

      break;
    }

    blocks11.push(
      block11
    );

    usedChars11 +=
      block11.length + 2;
  }

  const context11 =
    blocks11.join(
      "\n\n---\n\n"
    );

  return {
    query:
      knowledge11NormalizeText(
        query11
      ),
    context:
      context11,
    results:
      search11.results,
    citations:
      search11.results.map(
        (result11) => ({
          citation:
            result11.citation,
          documentId:
            result11.documentId,
          documentTitle:
            result11.documentTitle,
          sourceName:
            result11.sourceName,
          sourceUrl:
            result11.sourceUrl,
          score:
            result11.score
        })
      ),
    contextChars:
      context11.length,
    resultCount:
      search11.results.length,
    cached:
      Boolean(
        search11.cached
      ),
    tookMs:
      search11.tookMs
  };
}

