/* ------------------------------------------------------------
   11.24 - FILE BRIDGE
   Part 5 varsa mevcut file context sistemini kullanabilir.
------------------------------------------------------------ */

async function knowledge11ImportFromFileBridge({
  userId11 = "guest",
  fileId11 = "",
  collectionId11 = "default",
  title11 = ""
} = {}) {
  const safeFileId11 =
    knowledge11NormalizeId(
      fileId11
    );

  if (!safeFileId11) {
    throw new Error(
      "Geçerli bir fileId gerekli."
    );
  }

  let bridgeResult11 = null;

  try {
    if (
      typeof getAIFileContext5 ===
      "function"
    ) {
      bridgeResult11 =
        await Promise.resolve(
          getAIFileContext5({
            userId:
              knowledge11SafeUserId(
                userId11
              ),
            fileIds: [
              safeFileId11
            ]
          })
        );
    }
  } catch (error11) {
    systemLog?.(
      "knowledge11_file_bridge_error",
      {
        error:
          error11?.message ||
          String(error11)
      }
    );
  }

  let extractedText11 = "";
  let resolvedTitle11 =
    safeString(
      title11,
      ""
    );

  if (
    typeof bridgeResult11 ===
    "string"
  ) {
    extractedText11 =
      bridgeResult11;
  } else if (
    isObject(
      bridgeResult11
    )
  ) {
    extractedText11 =
      safeString(
        bridgeResult11.text ||
        bridgeResult11.content ||
        bridgeResult11.context ||
        bridgeResult11.extractedText,
        ""
      );

    resolvedTitle11 =
      resolvedTitle11 ||
      safeString(
        bridgeResult11.title ||
        bridgeResult11.name ||
        bridgeResult11.fileName,
        ""
      );
  }

  if (!extractedText11) {
    throw new Error(
      "Part 5 file bridge üzerinden metin alınamadı."
    );
  }

  return knowledge11AddDocument({
    userId11,
    collectionId11,
    title11:
      resolvedTitle11 ||
      `Dosya ${safeFileId11}`,
    text11:
      extractedText11,
    sourceType11:
      "file",
    sourceName11:
      resolvedTitle11 ||
      safeFileId11,
    mimeType11:
      "text/plain",
    metadata11: {
      fileId:
        safeFileId11
    }
  });
}

/* ------------------------------------------------------------
   11.25 - DOCUMENT LIST
------------------------------------------------------------ */

function knowledge11ListDocuments({
  userId11 = "guest",
  collectionId11 = null,
  includeArchived11 = false,
  search11 = "",
  page11 = 1,
  limit11 = 30
} = {}) {
  const safeUser11 =
    knowledge11SafeUserId(
      userId11
    );

  const documents11 =
    knowledge11DefaultDocuments();

  let entries11 =
    Object.values(
      documents11
    ).filter(
      (document11) =>
        document11 &&
        (
          document11.userId ===
          safeUser11 ||
          document11.userId ===
          "global"
        ) &&
        (
          includeArchived11 ||
          !document11.deletedAt
        )
    );

  if (collectionId11) {
    const safeCollection11 =
      knowledge11NormalizeId(
        collectionId11
      );

    entries11 =
      entries11.filter(
        (document11) =>
          document11.collectionId ===
          safeCollection11
      );
  }

  const searchText11 =
    knowledge11NormalizeText(
      search11
    ).toLocaleLowerCase(
      "tr-TR"
    );

  if (searchText11) {
    entries11 =
      entries11.filter(
        (document11) => {
          const haystack11 =
            [
              document11.title,
              document11.sourceName,
              document11.sourceUrl,
              ...(document11.tags || [])
            ]
              .join(" ")
              .toLocaleLowerCase(
                "tr-TR"
              );

          return haystack11.includes(
            searchText11
          );
        }
      );
  }

  entries11.sort(
    (a11, b11) =>
      (
        b11.pinned ? 1 : 0
      ) -
      (
        a11.pinned ? 1 : 0
      ) ||
      String(
        b11.updatedAt || ""
      ).localeCompare(
        String(
          a11.updatedAt || ""
        )
      )
  );

  const pageSafe11 =
    Math.max(
      1,
      toInteger(
        page11,
        1
      )
    );

  const limitSafe11 =
    clamp(
      toInteger(
        limit11,
        30
      ),
      1,
      100
    );

  const start11 =
    (
      pageSafe11 - 1
    ) *
    limitSafe11;

  return {
    items:
      entries11.slice(
        start11,
        start11 +
          limitSafe11
      ),
    total:
      entries11.length,
    page:
      pageSafe11,
    limit:
      limitSafe11,
    pages:
      Math.max(
        1,
        Math.ceil(
          entries11.length /
          limitSafe11
        )
      )
  };
}

/* ------------------------------------------------------------
   11.26 - GET SINGLE DOCUMENT WITH TEXT
------------------------------------------------------------ */

function knowledge11GetDocument(
  documentId11,
  userId11,
  includeText11 = false
) {
  const documents11 =
    knowledge11DefaultDocuments();

  const document11 =
    documents11[
      knowledge11NormalizeId(
        documentId11
      )
    ];

  if (
    !document11
  ) {
    return null;
  }

  if (
    !knowledge11CanReadDocument(
      document11,
      userId11
    )
  ) {
    return null;
  }

  const output11 = {
    ...document11
  };

  if (includeText11) {
    output11.text =
      knowledge11LoadDocumentText(
        document11
      );
  }

  return output11;
}

