/* ------------------------------------------------------------
   11.28 - KNOWLEDGE EXPORT
------------------------------------------------------------ */

function knowledge11ExportUserData({
  userId11 = "guest",
  collectionId11 = null
} = {}) {
  const safeUser11 =
    knowledge11SafeUserId(
      userId11
    );

  const documents11 =
    knowledge11DefaultDocuments();

  const chunks11 =
    knowledge11DefaultChunks();

  const outputDocuments11 = {};
  const outputChunks11 = {};

  for (
    const documentId11 of
    Object.keys(documents11)
  ) {
    const document11 =
      documents11[
        documentId11
      ];

    if (
      !document11 ||
      (
        document11.userId !==
        safeUser11 &&
        document11.userId !==
        "global"
      )
    ) {
      continue;
    }

    if (
      collectionId11 &&
      document11.collectionId !==
        knowledge11NormalizeId(
          collectionId11
        )
    ) {
      continue;
    }

    outputDocuments11[
      documentId11
    ] = {
      ...document11,
      text:
        knowledge11LoadDocumentText(
          document11
        )
    };
  }

  for (
    const chunkId11 of
    Object.keys(chunks11)
  ) {
    const chunk11 =
      chunks11[
        chunkId11
      ];

    if (
      outputDocuments11[
        chunk11?.documentId
      ]
    ) {
      outputChunks11[
        chunkId11
      ] = chunk11;
    }
  }

  const export11 = {
    format:
      "turkai-knowledge-v1",
    exportedAt:
      nowISO(),
    userId:
      safeUser11,
    collectionId:
      collectionId11
        ? knowledge11NormalizeId(
            collectionId11
          )
        : null,
    documents:
      outputDocuments11,
    chunks:
      outputChunks11
  };

  const exportName11 =
    `knowledge-${safeUser11}-${Date.now()}.json`;

  const exportPath11 =
    path11.join(
      KNOWLEDGE_EXPORT_11,
      exportName11
    );

  knowledge11WriteFileJSON(
    exportPath11,
    export11
  );

  knowledge11AppendHistory({
    type:
      "knowledge_exported",
    userId:
      safeUser11,
    file:
      exportName11
  });

  return {
    ...export11,
    exportFile:
      exportPath11,
    exportName:
      exportName11
  };
}

/* ------------------------------------------------------------
   11.29 - IMPORT DATA
------------------------------------------------------------ */

function knowledge11ImportUserData({
  userId11 = "guest",
  payload11
} = {}) {
  const safeUser11 =
    knowledge11SafeUserId(
      userId11
    );

  if (
    !isObject(
      payload11
    )
  ) {
    throw new Error(
      "Geçersiz Knowledge Base import verisi."
    );
  }

  const importedDocuments11 =
    isObject(
      payload11.documents
    )
      ? payload11.documents
      : {};

  let importedCount11 = 0;

  for (
    const key11 of
    Object.keys(
      importedDocuments11
    )
  ) {
    const source11 =
      importedDocuments11[
        key11
      ];

    if (
      !source11
    ) {
      continue;
    }

    try {
      knowledge11AddDocument({
        userId11:
          safeUser11,
        collectionId11:
          source11.collectionId ||
          "default",
        title11:
          source11.title ||
          "İçe aktarılan belge",
        text11:
          source11.text ||
          "",
        sourceType11:
          source11.sourceType ||
          "import",
        sourceName11:
          source11.sourceName ||
          "",
        sourceUrl11:
          source11.sourceUrl ||
          "",
        mimeType11:
          source11.mimeType ||
          "text/plain",
        tags11:
          source11.tags ||
          [],
        metadata11:
          source11.metadata ||
          {},
        language11:
          source11.language ||
          "tr",
        pinned11:
          Boolean(
            source11.pinned
          )
      });

      importedCount11 += 1;
    } catch (_) {}
  }

  return {
    success: true,
    imported:
      importedCount11
  };
}

/* ------------------------------------------------------------
   11.30 - ORPHAN CLEANUP
------------------------------------------------------------ */

function knowledge11Cleanup() {
  const documents11 =
    knowledge11DefaultDocuments();

  const chunks11 =
    knowledge11DefaultChunks();

  let removedChunks11 = 0;
  let removedFiles11 = 0;

  for (
    const chunkId11 of
    Object.keys(chunks11)
  ) {
    const chunk11 =
      chunks11[
        chunkId11
      ];

    if (
      !chunk11 ||
      !documents11[
        chunk11.documentId
      ]
    ) {
      delete chunks11[
        chunkId11
      ];
      removedChunks11 += 1;
    }
  }

  try {
    const files11 =
      fs11.readdirSync(
        KNOWLEDGE_DOCS_11
      );

    for (
      const fileName11 of
      files11
    ) {
      if (
        !fileName11.endsWith(
          ".txt"
        )
      ) {
        continue;
      }

      const documentId11 =
        fileName11.slice(
          0,
          -4
        );

      if (
        !documents11[
          documentId11
        ]
      ) {
        try {
          fs11.unlinkSync(
            path11.join(
              KNOWLEDGE_DOCS_11,
              fileName11
            )
          );

          removedFiles11 += 1;
        } catch (_) {}
      }
    }
  } catch (_) {}

  knowledge11WriteFileJSON(
    KNOWLEDGE_CHUNK_STORE_11,
    chunks11
  );

  knowledge11RebuildIndex();

  knowledge11AppendHistory({
    type:
      "knowledge_cleanup",
    removedChunks:
      removedChunks11,
    removedFiles:
      removedFiles11
  });

  return {
    success: true,
    removedChunks:
      removedChunks11,
    removedFiles:
      removedFiles11
  };
}

/* ------------------------------------------------------------
   11.31 - HEALTH CHECK
------------------------------------------------------------ */

function knowledge11Health() {
  const stats11 =
    knowledge11GetStats();

  const documents11 =
    knowledge11DefaultDocuments();

  const chunks11 =
    knowledge11DefaultChunks();

  const collections11 =
    knowledge11DefaultCollections();

  return {
    ok: true,
    module:
      "knowledge-base-rag",
    version:
      "11.0.0",
    enabled:
      Boolean(
        knowledge11GetSettings()
          .enabled
      ),
    storage: {
      root:
        KNOWLEDGE_ROOT_11,
      documents:
        Object.keys(
          documents11
        ).length,
      chunks:
        Object.keys(
          chunks11
        ).length,
      collections:
        Object.keys(
          collections11
        ).length
    },
    stats:
      stats11,
    checkedAt:
      nowISO()
  };
}

/* ------------------------------------------------------------
   11.32 - API MIDDLEWARE HELPERS
------------------------------------------------------------ */

function knowledge11RequestUser(req11) {
  return knowledge11SafeUserId(
    req11.user?.id ||
    req11.body?.userId ||
    req11.query?.userId ||
    "guest"
  );
}

function knowledge11HttpError(
  res11,
  status11,
  message11,
  extra11 = {}
) {
  return res11.status(
    status11
  ).json({
    success: false,
    error:
      safeString(
        message11,
        "Knowledge Base hatası"
      ),
    ...extra11
  });
}

/* ------------------------------------------------------------
   11.33 - COLLECTION ROUTES
   Specific paths FIRST.
------------------------------------------------------------ */

app.get(
  "/api/knowledge/collections",
  (req11, res11) => {
    try {
      const userId11 =
        knowledge11RequestUser(
          req11
        );

      const collections11 =
        knowledge11DefaultCollections();

      const items11 =
        Object.values(
          collections11
        )
        .filter(
          (collection11) =>
            collection11.userId ===
            userId11
        )
        .sort(
          (a11, b11) =>
            String(
              a11.name || ""
            ).localeCompare(
              String(
                b11.name || ""
              ),
              "tr"
            )
        );

      res11.json({
        success: true,
        items:
          items11,
        total:
          items11.length
      });
    } catch (error11) {
      knowledge11HttpError(
        res11,
        500,
        error11.message
      );
    }
  }
);

app.post(
  "/api/knowledge/collections",
  (req11, res11) => {
    try {
      const userId11 =
        knowledge11RequestUser(
          req11
        );

      const body11 =
        req11.body || {};

      const collection11 =
        knowledge11CreateCollection({
          userId11,
          collectionId11:
            body11.id ||
            body11.collectionId,
          name11:
            body11.name ||
            "Yeni Koleksiyon",
          description11:
            body11.description ||
            ""
        });

      res11.json({
        success: true,
        collection:
          collection11
      });
    } catch (error11) {
      knowledge11HttpError(
        res11,
        400,
        error11.message
      );
    }
  }
);

app.delete(
  "/api/knowledge/collections/:collectionId",
  (req11, res11) => {
    try {
      const userId11 =
        knowledge11RequestUser(
          req11
        );

      const safeUser11 =
        knowledge11SafeUserId(
          userId11
        );

      const collectionId11 =
        knowledge11NormalizeId(
          req11.params.collectionId
        );

      const collections11 =
        knowledge11DefaultCollections();

      const key11 =
        `${safeUser11}:${collectionId11}`;

      if (!collections11[key11]) {
        return knowledge11HttpError(
          res11,
          404,
          "Koleksiyon bulunamadı."
        );
      }

      const documents11 =
        knowledge11DefaultDocuments();

      const hasDocuments11 =
        Object.values(
          documents11
        ).some(
          (document11) =>
            document11 &&
            document11.userId ===
              safeUser11 &&
            document11.collectionId ===
              collectionId11 &&
            !document11.deletedAt
        );

      if (hasDocuments11) {
        return knowledge11HttpError(
          res11,
          409,
          "Koleksiyonda belge bulunuyor. Önce belgeleri sil."
        );
      }

      delete collections11[key11];

      knowledge11WriteFileJSON(
        KNOWLEDGE_COLLECTION_STORE_11,
        collections11
      );

      knowledge11AppendHistory({
        type:
          "collection_deleted",
        userId:
          safeUser11,
        collectionId:
          collectionId11
      });

      res11.json({
        success: true
      });
    } catch (error11) {
      knowledge11HttpError(
        res11,
        500,
        error11.message
      );
    }
  }
);

