/* ------------------------------------------------------------
   12.5 - SAFE JSON HELPERS
------------------------------------------------------------ */

function media12ReadJSON(
  filePath12,
  fallback12
) {
  try {
    if (
      !fs12.existsSync(
        filePath12
      )
    ) {
      return fallback12;
    }

    const raw12 =
      fs12.readFileSync(
        filePath12,
        "utf8"
      );

    if (!raw12.trim()) {
      return fallback12;
    }

    return JSON.parse(
      raw12
    );
  } catch (error12) {
    systemLog?.(
      "media12_read_json_error",
      {
        file:
          filePath12,
        error:
          error12?.message ||
          String(error12)
      }
    );

    return fallback12;
  }
}

function media12WriteJSON(
  filePath12,
  value12
) {
  try {
    const parent12 =
      path12.dirname(
        filePath12
      );

    fs12.mkdirSync(
      parent12,
      {
        recursive:
          true
      }
    );

    const temp12 =
      `${filePath12}.${process.pid}.${Date.now()}.tmp`;

    fs12.writeFileSync(
      temp12,
      JSON.stringify(
        value12,
        null,
        2
      ),
      "utf8"
    );

    fs12.renameSync(
      temp12,
      filePath12
    );

    return true;
  } catch (error12) {
    systemLog?.(
      "media12_write_json_error",
      {
        file:
          filePath12,
        error:
          error12?.message ||
          String(error12)
      }
    );

    return false;
  }
}

/* ------------------------------------------------------------
   12.6 - STARTUP CONFIG
------------------------------------------------------------ */

function knowledge12PersistConfig() {
  const config12 = {
    imageProvider:
      MEDIA_IMAGE_PROVIDER_12,

    videoProvider:
      MEDIA_VIDEO_PROVIDER_12,

    imageConfigured:
      Boolean(
        MEDIA_IMAGE_API_URL_12
      ),

    videoConfigured:
      Boolean(
        MEDIA_VIDEO_CREATE_URL_12
      ),

    updatedAt:
      nowISO()
  };

  media12WriteJSON(
    MEDIA_GENERATION_CONFIG_STORE_12,
    config12
  );
}

/* ------------------------------------------------------------
   12.7 - BASIC HELPERS
------------------------------------------------------------ */

function media12SafeString(
  value12,
  fallback12 = ""
) {
  return safeString(
    value12,
    fallback12
  )
    .normalize("NFKC")
    .replace(/\u0000/g, "")
    .trim();
}

function media12SafeId(
  value12,
  fallback12 = ""
) {
  const clean12 =
    media12SafeString(
      value12,
      fallback12
    )
      .replace(
        /[^a-zA-Z0-9_\-:.]/g,
        "-"
      )
      .replace(
        /-+/g,
        "-"
      )
      .replace(
        /^-+|-+$/g,
        ""
      );

  return clean12.slice(
    0,
    180
  );
}

function media12Hash(
  value12
) {
  return crypto12
    .createHash(
      "sha256"
    )
    .update(
      Buffer.from(
        media12SafeString(
          value12,
          ""
        ),
        "utf8"
      )
    )
    .digest("hex");
}

function media12ShortHash(
  value12
) {
  return media12Hash(
    value12
  ).slice(
    0,
    16
  );
}

function media12GetUserId(
  req12
) {
  return normalizeUserId(
    media12SafeString(
      req12?.user?.id ||
      req12?.body?.userId ||
      req12?.query?.userId ||
      "guest"
    )
  );
}

function media12NowMs() {
  return Date.now();
}

/* ------------------------------------------------------------
   12.8 - PROMPT NORMALIZATION
------------------------------------------------------------ */

function media12NormalizePrompt(
  value12,
  maxChars12
) {
  return media12SafeString(
    value12,
    ""
  )
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+/g, " ")
    .slice(
      0,
      maxChars12
    );
}

/* ------------------------------------------------------------
   12.9 - BASIC PROMPT SAFETY
------------------------------------------------------------ */

function media12CheckPromptSafety(
  prompt12
) {
  const normalized12 =
    media12NormalizePrompt(
      prompt12,
      Math.max(
        MEDIA_CONFIG_12.maxImagePromptChars,
        MEDIA_CONFIG_12.maxVideoPromptChars
      )
    )
      .toLocaleLowerCase(
        "tr-TR"
      );

  if (!normalized12) {
    return {
      allowed: false,
      reason:
        "Prompt boş olamaz."
    };
  }

  const blockedPatterns12 = [
    /\b(cinsel|pornografik|açık\s*cinsel)\b/u,
    /\b(explicit\s*sex|porn|nsfw)\b/iu,
    /\b(gore|aşırı\s*kanlı|vahşet)\b/iu
  ];

  for (
    const pattern12 of
    blockedPatterns12
  ) {
    if (
      pattern12.test(
        normalized12
      )
    ) {
      return {
        allowed: false,
        reason:
          "Bu prompt medya üretim politikaları nedeniyle işlenemiyor."
      };
    }
  }

  return {
    allowed: true,
    reason: null
  };
}

/* ------------------------------------------------------------
   12.10 - PLAN LIMITS
   Part 7 ile uyumlu güvenli fallback
------------------------------------------------------------ */

const MEDIA_PLAN_LIMITS_12 = {
  free: {
    imagePerDay: 0,
    videoPerDay: 0
  },

  pro: {
    imagePerDay: 2,
    videoPerDay: 0
  },

  plus: {
    imagePerDay: 4,
    videoPerDay: 2
  },

  ultra: {
    imagePerDay: 10,
    videoPerDay: 5
  },

  developer: {
    imagePerDay: 1000,
    videoPerDay: 1000
  },

  owner: {
    imagePerDay: 1000,
    videoPerDay: 1000
  }
};

function media12ResolveUserPlan(
  userId12
) {
  try {
    const user12 =
      typeof getUser ===
      "function"
        ? getUser(
            userId12
          )
        : null;

    const possiblePlan12 =
      user12?.plan ||
      user12?.planId ||
      user12?.subscription?.plan ||
      user12?.subscription?.planId ||
      "free";

    const plan12 =
      media12SafeString(
        possiblePlan12,
        "free"
      )
        .toLocaleLowerCase(
          "tr-TR"
        );

    if (
      MEDIA_PLAN_LIMITS_12[
        plan12
      ]
    ) {
      return plan12;
    }

    if (
      plan12 ===
      "plus"
    ) {
      return "plus";
    }

    if (
      plan12 ===
      "pro"
    ) {
      return "pro";
    }

    if (
      plan12 ===
      "ultra"
    ) {
      return "ultra";
    }

    if (
      plan12 ===
      "developer"
    ) {
      return "developer";
    }

    if (
      plan12 ===
      "owner"
    ) {
      return "owner";
    }

    return "free";
  } catch (_) {
    return "free";
  }
}

/* ------------------------------------------------------------
   12.11 - DAILY USAGE
------------------------------------------------------------ */

function media12DefaultUsage() {
  return {
    image: {},
    video: {},
    total: {},
    updatedAt:
      nowISO()
  };
}

function media12GetUsage() {
  return media12ReadJSON(
    MEDIA_GENERATION_USAGE_STORE_12,
    media12DefaultUsage()
  );
}

function media12TodayKey() {
  return todayKey();
}

function media12GetDailyCount(
  usage12,
  userId12,
  type12
) {
  const day12 =
    media12TodayKey();

  return toInteger(
    usage12?.[
      type12
    ]?.[
      userId12
    ]?.[
      day12
    ],
    0
  );
}

function media12IncrementUsage(
  userId12,
  type12
) {
  const usage12 =
    media12GetUsage();

  const day12 =
    media12TodayKey();

  if (!usage12[type12]) {
    usage12[type12] = {};
  }

  if (
    !usage12[type12][
      userId12
    ]
  ) {
    usage12[type12][
      userId12
    ] = {};
  }

  usage12[type12][
    userId12
  ][day12] =
    media12GetDailyCount(
      usage12,
      userId12,
      type12
    ) + 1;

  if (
    !usage12.total
  ) {
    usage12.total = {};
  }

  if (
    !usage12.total[
      userId12
    ]
  ) {
    usage12.total[
      userId12
    ] = {};
  }

  usage12.total[
    userId12
  ][day12] =
    toInteger(
      usage12.total[
        userId12
      ][day12],
      0
    ) + 1;

  usage12.updatedAt =
    nowISO();

  media12WriteJSON(
    MEDIA_GENERATION_USAGE_STORE_12,
    usage12
  );

  return {
    daily:
      usage12[type12][
        userId12
      ][day12],

    total:
      usage12.total[
        userId12
      ][day12]
  };
}

function media12CheckQuota(
  userId12,
  type12
) {
  const plan12 =
    media12ResolveUserPlan(
      userId12
    );

  const limits12 =
    MEDIA_PLAN_LIMITS_12[
      plan12
    ] ||
    MEDIA_PLAN_LIMITS_12.free;

  const limit12 =
    type12 ===
    "image"
      ? limits12.imagePerDay
      : limits12.videoPerDay;

  const usage12 =
    media12GetUsage();

  const current12 =
    media12GetDailyCount(
      usage12,
      userId12,
      type12
    );

  return {
    allowed:
      current12 <
      limit12,

    plan:
      plan12,

    type:
      type12,

    current:
      current12,

    limit:
      limit12,

    remaining:
      Math.max(
        0,
        limit12 -
          current12
      )
  };
}

/* ------------------------------------------------------------
   12.12 - JOB MODEL
------------------------------------------------------------ */

function media12DefaultJobs() {
  return {};
}

function media12GetJobs() {
  return media12ReadJSON(
    MEDIA_GENERATION_JOB_STORE_12,
    media12DefaultJobs()
  );
}

function media12SaveJobs(
  jobs12
) {
  const keys12 =
    Object.keys(
      jobs12
    );

  if (
    keys12.length >
    MEDIA_CONFIG_12.maxJobs
  ) {
    keys12
      .sort(
        (a12, b12) =>
          String(
            jobs12[a12]?.createdAt ||
            ""
          ).localeCompare(
            String(
              jobs12[b12]?.createdAt ||
              ""
            )
          )
      )
      .slice(
        0,
        keys12.length -
          MEDIA_CONFIG_12.maxJobs
      )
      .forEach(
        (oldId12) =>
          delete jobs12[
            oldId12
          ]
      );
  }

  return media12WriteJSON(
    MEDIA_GENERATION_JOB_STORE_12,
    jobs12
  );
}

function media12CreateJob({
  userId12,
  type12,
  prompt12,
  options12 = {}
}) {
  const jobs12 =
    media12GetJobs();

  const jobId12 =
    `job-${type12}-${media12ShortHash(
      `${userId12}:${Date.now()}:${Math.random()}`
    )}`;

  const job12 = {
    id:
      jobId12,

    userId:
      userId12,

    type:
      type12,

    status:
      "queued",

    progress:
      0,

    prompt:
      prompt12,

    options:
      isObject(
        options12
      )
        ? clone(
            options12
          )
        : {},

    provider:
      type12 ===
      "image"
        ? MEDIA_IMAGE_PROVIDER_12
        : MEDIA_VIDEO_PROVIDER_12,

    providerJobId:
      null,

    result:
      null,

    error:
      null,

    attempts:
      0,

    createdAt:
      nowISO(),

    startedAt:
      null,

    completedAt:
      null,

    updatedAt:
      nowISO()
  };

  jobs12[
    jobId12
  ] = job12;

  media12SaveJobs(
    jobs12
  );

  media12AppendHistory({
    type:
      "job_created",
    jobId:
      jobId12,
    userId:
      userId12,
    mediaType:
      type12
  });

  return job12;
}

function media12UpdateJob(
  jobId12,
  updates12 = {}
) {
  const jobs12 =
    media12GetJobs();

  const id12 =
    media12SafeId(
      jobId12
    );

  if (
    !jobs12[id12]
  ) {
    return null;
  }

  jobs12[id12] = {
    ...jobs12[id12],
    ...updates12,
    updatedAt:
      nowISO()
  };

  media12SaveJobs(
    jobs12
  );

  return jobs12[id12];
}

function media12GetJob(
  jobId12,
  userId12 = null
) {
  const jobs12 =
    media12GetJobs();

  const id12 =
    media12SafeId(
      jobId12
    );

  const job12 =
    jobs12[id12];

  if (!job12) {
    return null;
  }

  if (
    userId12 &&
    job12.userId !==
      userId12
  ) {
    return null;
  }

  return job12;
}

/* ------------------------------------------------------------
   12.13 - ASSET MODEL
------------------------------------------------------------ */

function media12GetAssets() {
  return media12ReadJSON(
    MEDIA_GENERATION_ASSET_STORE_12,
    {}
  );
}

function media12SaveAssets(
  assets12
) {
  const ids12 =
    Object.keys(
      assets12
    );

  if (
    ids12.length >
    MEDIA_CONFIG_12.maxAssets
  ) {
    ids12
      .sort(
        (a12, b12) =>
          String(
            assets12[a12]?.createdAt ||
            ""
          ).localeCompare(
            String(
              assets12[b12]?.createdAt ||
              ""
            )
          )
      )
      .slice(
        0,
        ids12.length -
          MEDIA_CONFIG_12.maxAssets
      )
      .forEach(
        (oldId12) =>
          delete assets12[
            oldId12
          ]
      );
  }

  return media12WriteJSON(
    MEDIA_GENERATION_ASSET_STORE_12,
    assets12
  );
}

function media12CreateAsset({
  userId12,
  type12,
  jobId12,
  filePath12,
  mimeType12,
  fileSize12,
  provider12,
  model12,
  prompt12,
  metadata12 = {}
}) {
  const assets12 =
    media12GetAssets();

  const extension12 =
    path12.extname(
      filePath12
    )
      .replace(
        ".",
        ""
      )
      .toLowerCase();

  const assetId12 =
    `asset-${type12}-${media12ShortHash(
      `${filePath12}:${jobId12}:${Date.now()}`
    )}`;

  const asset12 = {
    id:
      assetId12,

    userId:
      userId12,

    type:
      type12,

    jobId:
      jobId12,

    filename:
      path12.basename(
        filePath12
      ),

    extension:
      extension12,

    mimeType:
      mimeType12,

    fileSize:
      toNumber(
        fileSize12,
        0
      ),

    provider:
      provider12,

    model:
      model12,

    prompt:
      prompt12,

    path:
      filePath12,

    url:
      `/api/generation/assets/${assetId12}/download`,

    metadata:
      isObject(
        metadata12
      )
        ? clone(
            metadata12
          )
        : {},

    createdAt:
      nowISO()
  };

  assets12[
    assetId12
  ] = asset12;

  media12SaveAssets(
    assets12
  );

  media12AppendHistory({
    type:
      "asset_created",
    assetId:
      assetId12,
    userId:
      userId12,
    mediaType:
      type12
  });

  return asset12;
}

/* ------------------------------------------------------------
   12.14 - MEDIA MIME HELPERS
------------------------------------------------------------ */

function media12MimeFromExtension(
  extension12
) {
  const ext12 =
    media12SafeString(
      extension12,
      ""
    ).toLowerCase();

  const map12 = {
    png:
      "image/png",
    jpg:
      "image/jpeg",
    jpeg:
      "image/jpeg",
    webp:
      "image/webp",

    mp4:
      "video/mp4",
    webm:
      "video/webm"
  };

  return (
    map12[ext12] ||
    "application/octet-stream"
  );
}

/* ------------------------------------------------------------
   12.15 - GENERIC HTTP
------------------------------------------------------------ */

async function media12FetchJSON(
  url12,
  options12 = {},
  timeout12 =
    MEDIA_CONFIG_12.requestTimeoutMs
) {
  const controller12 =
    new AbortController();

  const timer12 =
    setTimeout(
      () =>
        controller12.abort(),
      timeout12
    );

  try {
    const response12 =
      await fetch(
        url12,
        {
          ...options12,
          signal:
            controller12.signal
        }
      );

    const rawText12 =
      await response12.text();

    let parsed12 =
      null;

    try {
      parsed12 =
        rawText12
          ? JSON.parse(
              rawText12
            )
          : {};
    } catch (_) {
      parsed12 = {
        raw:
          rawText12
      };
    }

    if (
      !response12.ok
    ) {
      const error12 =
        new Error(
          `Provider HTTP ${response12.status}`
        );

      error12.status =
        response12.status;

      error12.data =
        parsed12;

      throw error12;
    }

    return parsed12;
  } finally {
    clearTimeout(
      timer12
    );
  }
}

/* ------------------------------------------------------------
   12.16 - GENERIC BINARY DOWNLOAD
------------------------------------------------------------ */

async function media12DownloadBinary(
  url12
) {
  const controller12 =
    new AbortController();

  const timer12 =
    setTimeout(
      () =>
        controller12.abort(),
      MEDIA_CONFIG_12.requestTimeoutMs
    );

  try {
    const response12 =
      await fetch(
        url12,
        {
          signal:
            controller12.signal
        }
      );

    if (
      !response12.ok
    ) {
      throw new Error(
        `Dosya indirme hatası: HTTP ${response12.status}`
      );
    }

    const contentLength12 =
      toNumber(
        response12.headers.get(
          "content-length"
        ),
        0
      );

    if (
      contentLength12 >
      MEDIA_CONFIG_12.maxDownloadBytes
    ) {
      throw new Error(
        "Provider çıktısı izin verilen maksimum boyutu aşıyor."
      );
    }

    const arrayBuffer12 =
      await response12.arrayBuffer();

    const buffer12 =
      Buffer.from(
        arrayBuffer12
      );

    if (
      buffer12.length >
      MEDIA_CONFIG_12.maxDownloadBytes
    ) {
      throw new Error(
        "Provider çıktısı izin verilen maksimum boyutu aşıyor."
      );
    }

    return {
      buffer:
        buffer12,

      contentType:
        response12.headers.get(
          "content-type"
        ) ||
        "application/octet-stream"
    };
  } finally {
    clearTimeout(
      timer12
    );
  }
}

/* ------------------------------------------------------------
   12.17 - IMAGE PROVIDER
   Generic JSON contract:
   {
     image_url / url / output_url
     OR
     b64_json / image_base64
   }
------------------------------------------------------------ */

async function media12GenerateImageGeneric(
  prompt12,
  options12 = {}
) {
  if (
    !MEDIA_IMAGE_API_URL_12
  ) {
    throw new Error(
      "Image provider yapılandırılmamış. TURKAI_IMAGE_API_URL gerekli."
    );
  }

  const headers12 = {
    "content-type":
      "application/json"
  };

  if (
    MEDIA_IMAGE_API_KEY_12
  ) {
    headers12.authorization =
      `Bearer ${MEDIA_IMAGE_API_KEY_12}`;
  }

  const payload12 = {
    model:
      options12.model ||
      MEDIA_IMAGE_MODEL_12,

    prompt:
      prompt12,

    width:
      toInteger(
        options12.width,
        MEDIA_CONFIG_12.imageDefaultWidth
      ),

    height:
      toInteger(
        options12.height,
        MEDIA_CONFIG_12.imageDefaultHeight
      ),

    size:
      options12.size ||
      "1024x1024",

    quality:
      options12.quality ||
      "standard",

    response_format:
      "b64_json"
  };

  const response12 =
    await media12FetchJSON(
      MEDIA_IMAGE_API_URL_12,
      {
        method:
          "POST",
        headers:
          headers12,
        body:
          JSON.stringify(
            payload12
          )
      }
    );

  const item12 =
    response12?.data?.[0] ||
    response12?.output?.[0] ||
    response12?.result?.[0] ||
    response12;

  const base6412 =
    item12?.b64_json ||
    item12?.image_base64 ||
    item12?.base64 ||
    null;

  if (
    base6412
  ) {
    const buffer12 =
      Buffer.from(
        base6412,
        "base64"
      );

    return {
      mode:
        "buffer",

      buffer:
        buffer12,

      mimeType:
        item12?.mime_type ||
        "image/png",

      providerResponse:
        response12
    };
  }

  const url12 =
    item12?.url ||
    item12?.image_url ||
    item12?.output_url ||
    response12?.url ||
    response12?.image_url ||
    null;

  if (
    url12
  ) {
    return {
      mode:
        "url",

      url:
        url12,

      mimeType:
        item12?.mime_type ||
        "image/png",

      providerResponse:
        response12
    };
  }

  throw new Error(
    "Image provider geçerli bir görsel çıktısı döndürmedi."
  );
}

/* ------------------------------------------------------------
   12.18 - IMAGE PROVIDER ADAPTER
------------------------------------------------------------ */

async function media12GenerateImage(
  prompt12,
  options12 = {}
) {
  const provider12 =
    (
      options12.provider ||
      MEDIA_IMAGE_PROVIDER_12
    )
      .toLocaleLowerCase(
        "tr-TR"
      );

  if (
    provider12 ===
    "generic"
  ) {
    return media12GenerateImageGeneric(
      prompt12,
      options12
    );
  }

  if (
    provider12 ===
      "openai-compatible" ||
    provider12 ===
      "openai"
  ) {
    return media12GenerateImageGeneric(
      prompt12,
      options12
    );
  }

  return media12GenerateImageGeneric(
    prompt12,
    options12
  );
}

/* ------------------------------------------------------------
   12.19 - SAVE IMAGE RESULT
------------------------------------------------------------ */

async function media12SaveImageResult({
  job12,
  generated12
}) {
  const extension12 =
    generated12.mimeType ===
    "image/jpeg"
      ? "jpg"
      : generated12.mimeType ===
          "image/webp"
        ? "webp"
        : "png";

  const fileName12 =
    `${job12.id}.${extension12}`;

  const filePath12 =
    path12.join(
      MEDIA_GENERATION_IMAGE_12,
      fileName12
    );

  let buffer12;

  if (
    generated12.mode ===
    "buffer"
  ) {
    buffer12 =
      generated12.buffer;
  } else if (
    generated12.mode ===
    "url"
  ) {
    const downloaded12 =
      await media12DownloadBinary(
        generated12.url
      );

    buffer12 =
      downloaded12.buffer;
  } else {
    throw new Error(
      "Image çıktısı tanınamadı."
    );
  }

  if (
    !Buffer.isBuffer(
      buffer12
    ) ||
    buffer12.length === 0
  ) {
    throw new Error(
      "Image provider boş dosya döndürdü."
    );
  }

  if (
    buffer12.length >
    MEDIA_CONFIG_12.maxDownloadBytes
  ) {
    throw new Error(
      "Image dosyası çok büyük."
    );
  }

  fs12.writeFileSync(
    filePath12,
    buffer12
  );

  return {
    filePath:
      filePath12,

    fileSize:
      buffer12.length,

    mimeType:
      generated12.mimeType ||
      "image/png",

    metadata: {
      providerUrl:
        generated12.url ||
        null
    }
  };
}

/* ------------------------------------------------------------
   12.20 - VIDEO CREATE PROVIDER
   Generic async contract
------------------------------------------------------------ */

async function media12CreateVideoGeneric(
  prompt12,
  options12 = {}
) {
  if (
    !MEDIA_VIDEO_CREATE_URL_12
  ) {
    throw new Error(
      "Video provider yapılandırılmamış. TURKAI_VIDEO_CREATE_URL gerekli."
    );
  }

  const headers12 = {
    "content-type":
      "application/json"
  };

  if (
    MEDIA_VIDEO_API_KEY_12
  ) {
    headers12.authorization =
      `Bearer ${MEDIA_VIDEO_API_KEY_12}`;
  }

  const duration12 =
    clamp(
      toInteger(
        options12.duration,
        MEDIA_CONFIG_12.videoDefaultSeconds
      ),
      1,
      MEDIA_CONFIG_12.videoMaxSeconds
    );

  const payload12 = {
    model:
      options12.model ||
      MEDIA_VIDEO_MODEL_12,

    prompt:
      prompt12,

    duration:
      duration12,

    seconds:
      duration12,

    aspect_ratio:
      options12.aspectRatio ||
      "16:9",

    resolution:
      options12.resolution ||
      "720p"
  };

  const response12 =
    await media12FetchJSON(
      MEDIA_VIDEO_CREATE_URL_12,
      {
        method:
          "POST",
        headers:
          headers12,
        body:
          JSON.stringify(
            payload12
          )
      }
    );

  const providerJobId12 =
    response12?.id ||
    response12?.job_id ||
    response12?.jobId ||
    response12?.request_id ||
    response12?.requestId ||
    null;

  if (
    !providerJobId12
  ) {
    const directVideoUrl12 =
      response12?.video_url ||
      response12?.output_url ||
      response12?.url ||
      response12?.output?.url ||
      null;

    if (
      directVideoUrl12
    ) {
      return {
        completed:
          true,

        providerJobId:
          null,

        videoUrl:
          directVideoUrl12,

        providerResponse:
          response12
      };
    }

    throw new Error(
      "Video provider bir job kimliği veya video URL'si döndürmedi."
    );
  }

  const statusUrl12 =
    response12?.status_url ||
    response12?.statusUrl ||
    (
      MEDIA_VIDEO_STATUS_URL_12
        ? MEDIA_VIDEO_STATUS_URL_12
            .replace(
              /:id/g,
              encodeURIComponent(
                providerJobId12
              )
            )
        : null
    );

  return {
    completed:
      false,

    providerJobId:
      String(
        providerJobId12
      ),

    statusUrl:
      statusUrl12,

    providerResponse:
      response12
  };
}

/* ------------------------------------------------------------
   12.21 - VIDEO STATUS PROVIDER
------------------------------------------------------------ */

async function media12GetVideoStatus(
  providerJobId12,
  statusUrl12 = null
) {
  const finalUrl12 =
    statusUrl12 ||
    (
      MEDIA_VIDEO_STATUS_URL_12
        ? MEDIA_VIDEO_STATUS_URL_12
            .replace(
              /:id/g,
              encodeURIComponent(
                providerJobId12
              )
            )
        : ""
    );

  if (
    !finalUrl12
  ) {
    throw new Error(
      "Video status URL yapılandırılmamış."
    );
  }

  const headers12 = {};

  if (
    MEDIA_VIDEO_API_KEY_12
  ) {
    headers12.authorization =
      `Bearer ${MEDIA_VIDEO_API_KEY_12}`;
  }

  return media12FetchJSON(
    finalUrl12,
    {
      method:
        "GET",
      headers:
        headers12
    }
  );
}

/* ------------------------------------------------------------
   12.22 - VIDEO STATUS NORMALIZATION
------------------------------------------------------------ */

function media12NormalizeVideoStatus(
  providerResponse12
) {
  const response12 =
    providerResponse12 ||
    {};

  const rawStatus12 =
    media12SafeString(
      response12.status ||
      response12.state ||
      response12.phase ||
      "",
      ""
    )
      .toLocaleLowerCase(
        "tr-TR"
      );

  const videoUrl12 =
    response12.video_url ||
    response12.videoUrl ||
    response12.output_url ||
    response12.outputUrl ||
    response12.url ||
    response12.output?.url ||
    response12.result?.url ||
    response12.data?.url ||
    null;

  const statusMap12 = {
    queued:
      "processing",
    pending:
      "processing",
    running:
      "processing",
    processing:
      "processing",
    in_progress:
      "processing",
    generating:
      "processing",

    completed:
      "completed",
    complete:
      "completed",
    succeeded:
      "completed",
    success:
      "completed",
    done:
      "completed",

    failed:
      "failed",
    error:
      "failed",
    cancelled:
      "cancelled",
    canceled:
      "cancelled"
  };

  const normalizedStatus12 =
    statusMap12[
      rawStatus12
    ] ||
    (
      videoUrl12
        ? "completed"
        : "processing"
    );

  return {
    status:
      normalizedStatus12,

    progress:
      clamp(
        toInteger(
          response12.progress ||
          response12.percent ||
          response12.percentage,
          normalizedStatus12 ===
            "completed"
            ? 100
            : 0
        ),
        0,
        100
      ),

    videoUrl:
      videoUrl12,

    error:
      response12.error ||
      response12.message ||
      null,

    raw:
      response12
  };
}

/* ------------------------------------------------------------
   12.23 - SAVE VIDEO RESULT
------------------------------------------------------------ */

async function media12SaveVideoResult({
  job12,
  videoUrl12
}) {
  if (
    !videoUrl12
  ) {
    throw new Error(
      "Video URL bulunamadı."
    );
  }

  const downloaded12 =
    await media12DownloadBinary(
      videoUrl12
    );

  const mimeType12 =
    downloaded12.contentType
      .toLocaleLowerCase(
        "tr-TR"
      );

  let extension12 =
    "mp4";

  if (
    mimeType12.includes(
      "webm"
    )
  ) {
    extension12 =
      "webm";
  }

  const fileName12 =
    `${job12.id}.${extension12}`;

  const filePath12 =
    path12.join(
      MEDIA_GENERATION_VIDEO_12,
      fileName12
    );

  fs12.writeFileSync(
    filePath12,
    downloaded12.buffer
  );

  return {
    filePath:
      filePath12,

    fileSize:
      downloaded12.buffer.length,

    mimeType:
      mimeType12 ||
      media12MimeFromExtension(
        extension12
      ),

    metadata: {
      providerVideoUrl:
        videoUrl12
    }
  };
}

/* ------------------------------------------------------------
   12.24 - VIDEO CREATE ADAPTER
------------------------------------------------------------ */

async function media12CreateVideo(
  prompt12,
  options12 = {}
) {
  const provider12 =
    (
      options12.provider ||
      MEDIA_VIDEO_PROVIDER_12
    )
      .toLocaleLowerCase(
        "tr-TR"
      );

  if (
    provider12 ===
      "generic" ||
    provider12 ===
      "openai-compatible" ||
    provider12 ===
      "openai"
  ) {
    return media12CreateVideoGeneric(
      prompt12,
      options12
    );
  }

  return media12CreateVideoGeneric(
    prompt12,
    options12
  );
}

/* ------------------------------------------------------------
   12.25 - WORKER STATE
------------------------------------------------------------ */

const MEDIA_WORKER_12 = {
  running: false,
  activeJobs: 0,
  processed: 0,
  failed: 0,
  startedAt: null,
  lastRunAt: null
};

/* ------------------------------------------------------------
   12.26 - RUN IMAGE JOB
------------------------------------------------------------ */

async function media12RunImageJob(
  job12
) {
  media12UpdateJob(
    job12.id,
    {
      status:
        "processing",
      progress:
        10,
      startedAt:
        nowISO(),
      attempts:
        toInteger(
          job12.attempts,
          0
        ) + 1
    }
  );

  try {
    const generated12 =
      await media12GenerateImage(
        job12.prompt,
        job12.options
      );

    media12UpdateJob(
      job12.id,
      {
        progress:
          70
      }
    );

    const saved12 =
      await media12SaveImageResult({
        job12,
        generated12
      });

    const asset12 =
      media12CreateAsset({
        userId12:
          job12.userId,

        type12:
          "image",

        jobId12:
          job12.id,

        filePath12:
          saved12.filePath,

        mimeType12:
          saved12.mimeType,

        fileSize12:
          saved12.fileSize,

        provider12:
          MEDIA_IMAGE_PROVIDER_12,

        model12:
          job12.options?.model ||
          MEDIA_IMAGE_MODEL_12,

        prompt12:
          job12.prompt,

        metadata12:
          saved12.metadata
      });

    media12IncrementUsage(
      job12.userId,
      "image"
    );

    const complete12 =
      media12UpdateJob(
        job12.id,
        {
          status:
            "completed",

          progress:
            100,

          result: {
            assetId:
              asset12.id,

            url:
              asset12.url,

            mimeType:
              asset12.mimeType,

            fileSize:
              asset12.fileSize
          },

          completedAt:
            nowISO()
        }
      );

    MEDIA_WORKER_12.processed +=
      1;

    media12AppendHistory({
      type:
        "image_completed",
      jobId:
        job12.id,
      assetId:
        asset12.id,
      userId:
        job12.userId
    });

    return complete12;
  } catch (error12) {
    MEDIA_WORKER_12.failed +=
      1;

    const failed12 =
      media12UpdateJob(
        job12.id,
        {
          status:
            "failed",

          progress:
            0,

          error:
            error12?.message ||
            String(error12)
        }
      );

    media12AppendHistory({
      type:
        "image_failed",
      jobId:
        job12.id,
      userId:
        job12.userId,
      error:
        error12?.message ||
        String(error12)
    });

    return failed12;
  }
}

/* ------------------------------------------------------------
   12.27 - RUN VIDEO JOB
------------------------------------------------------------ */

async function media12RunVideoJob(
  job12
) {
  media12UpdateJob(
    job12.id,
    {
      status:
        "processing",
      progress:
        5,
      startedAt:
        nowISO(),
      attempts:
        toInteger(
          job12.attempts,
          0
        ) + 1
    }
  );

  try {
    const created12 =
      await media12CreateVideo(
        job12.prompt,
        job12.options
      );

    if (
      created12.completed &&
      created12.videoUrl
    ) {
      media12UpdateJob(
        job12.id,
        {
          progress:
            80
        }
      );

      const saved12 =
        await media12SaveVideoResult({
          job12,
          videoUrl12:
            created12.videoUrl
        });

      const asset12 =
        media12CreateAsset({
          userId12:
            job12.userId,

          type12:
            "video",

          jobId12:
            job12.id,

          filePath12:
            saved12.filePath,

          mimeType12:
            saved12.mimeType,

          fileSize12:
            saved12.fileSize,

          provider12:
            MEDIA_VIDEO_PROVIDER_12,

          model12:
            job12.options?.model ||
            MEDIA_VIDEO_MODEL_12,

          prompt12:
            job12.prompt,

          metadata12:
            saved12.metadata
        });

      media12IncrementUsage(
        job12.userId,
        "video"
      );

      return media12UpdateJob(
        job12.id,
        {
          status:
            "completed",

          progress:
            100,

          result: {
            assetId:
              asset12.id,

            url:
              asset12.url,

            mimeType:
              asset12.mimeType,

            fileSize:
              asset12.fileSize
          },

          completedAt:
            nowISO()
        }
      );
    }

    media12UpdateJob(
      job12.id,
      {
        providerJobId:
          created12.providerJobId,

        statusUrl:
          created12.statusUrl ||
          null,

        progress:
          10
      }
    );

    const startedPoll12 =
      Date.now();

    let latest12 =
      null;

    while (
      Date.now() -
        startedPoll12 <
      MEDIA_CONFIG_12.videoPollTimeoutMs
    ) {
      await new Promise(
        (resolve12) =>
          setTimeout(
            resolve12,
            MEDIA_CONFIG_12.videoPollIntervalMs
          )
      );

      latest12 =
        await media12GetVideoStatus(
          created12.providerJobId,
          created12.statusUrl
        );

      const normalized12 =
        media12NormalizeVideoStatus(
          latest12
        );

      media12UpdateJob(
        job12.id,
        {
          progress:
            Math.max(
              10,
              Math.min(
                90,
                normalized12.progress
              )
            )
        }
      );

      if (
        normalized12.status ===
        "failed"
      ) {
        throw new Error(
          normalized12.error ||
          "Video provider üretimi başarısız oldu."
        );
      }

      if (
        normalized12.status ===
        "cancelled"
      ) {
        throw new Error(
          "Video üretim görevi iptal edildi."
        );
      }

      if (
        normalized12.status ===
          "completed" &&
        normalized12.videoUrl
      ) {
        const saved12 =
          await media12SaveVideoResult({
            job12,

            videoUrl12:
              normalized12.videoUrl
          });

        const asset12 =
          media12CreateAsset({
            userId12:
              job12.userId,

            type12:
              "video",

            jobId12:
              job12.id,

            filePath12:
              saved12.filePath,

            mimeType12:
              saved12.mimeType,

            fileSize12:
              saved12.fileSize,

            provider12:
              MEDIA_VIDEO_PROVIDER_12,

            model12:
              job12.options?.model ||
              MEDIA_VIDEO_MODEL_12,

            prompt12:
              job12.prompt,

            metadata12:
              saved12.metadata
          });

        media12IncrementUsage(
          job12.userId,
          "video"
        );

        return media12UpdateJob(
          job12.id,
          {
            status:
              "completed",

            progress:
              100,

            result: {
              assetId:
                asset12.id,

              url:
                asset12.url,

              mimeType:
                asset12.mimeType,

              fileSize:
                asset12.fileSize
            },

            completedAt:
              nowISO()
          }
        );
      }
    }

    throw new Error(
      "Video provider zaman aşımına uğradı."
    );
  } catch (error12) {
    MEDIA_WORKER_12.failed +=
      1;

    media12AppendHistory({
      type:
        "video_failed",
      jobId:
        job12.id,
      userId:
        job12.userId,
      error:
        error12?.message ||
        String(error12)
    });

    return media12UpdateJob(
      job12.id,
      {
        status:
          "failed",

        progress:
          0,

        error:
          error12?.message ||
          String(error12),

        completedAt:
          nowISO()
      }
    );
  }
}

/* ------------------------------------------------------------
   12.28 - WORKER PICK NEXT JOB
------------------------------------------------------------ */

function media12PickNextJob() {
  const jobs12 =
    media12GetJobs();

  return Object.values(
    jobs12
  )
    .filter(
      (job12) =>
        job12 &&
        job12.status ===
          "queued"
    )
    .sort(
      (a12, b12) =>
        String(
          a12.createdAt ||
          ""
        ).localeCompare(
          String(
            b12.createdAt ||
            ""
          )
        )
    )[0] || null;
}

/* ------------------------------------------------------------
   12.29 - WORKER TICK
------------------------------------------------------------ */

async function media12WorkerTick() {
  if (
    MEDIA_WORKER_12.running
  ) {
    return;
  }

  MEDIA_WORKER_12.running =
    true;

  MEDIA_WORKER_12.startedAt =
    MEDIA_WORKER_12.startedAt ||
    nowISO();

  try {
    const job12 =
      media12PickNextJob();

    if (!job12) {
      return;
    }

    MEDIA_WORKER_12.activeJobs =
      1;

    if (
      job12.type ===
      "image"
    ) {
      await media12RunImageJob(
        job12
      );
    } else if (
      job12.type ===
      "video"
    ) {
      await media12RunVideoJob(
        job12
      );
    } else {
      media12UpdateJob(
        job12.id,
        {
          status:
            "failed",
          error:
            "Bilinmeyen medya türü."
        }
      );
    }
  } catch (error12) {
    systemLog?.(
      "media12_worker_error",
      {
        error:
          error12?.message ||
          String(error12)
      }
    );
  } finally {
    MEDIA_WORKER_12.activeJobs =
      0;

    MEDIA_WORKER_12.lastRunAt =
      nowISO();

    MEDIA_WORKER_12.running =
      false;
  }
}

/* ------------------------------------------------------------
   12.30 - CREATE GENERATION REQUEST
------------------------------------------------------------ */

function media12ValidateGenerationRequest({
  userId12,
  type12,
  prompt12
}) {
  const safety12 =
    media12CheckPromptSafety(
      prompt12
    );

  if (
    !safety12.allowed
  ) {
    return {
      valid: false,
      reason:
        safety12.reason
    };
  }

  const quota12 =
    media12CheckQuota(
      userId12,
      type12
    );

  if (
    !quota12.allowed
  ) {
    if (
      quota12.limit ===
      0
    ) {
      return {
        valid: false,
        reason:
          `${type12 === "image" ? "Görsel" : "Video"} üretimi mevcut planda kapalı.`,
        quota:
          quota12
      };
    }

    return {
      valid: false,
      reason:
        "Günlük medya üretim limitine ulaşıldı.",
      quota:
        quota12
    };
  }

  return {
    valid: true,
    quota:
      quota12
  };
}

/* ------------------------------------------------------------
   12.31 - CREATE IMAGE JOB
------------------------------------------------------------ */

function media12QueueImage({
  userId12,
  prompt12,
  options12 = {}
}) {
  const normalizedPrompt12 =
    media12NormalizePrompt(
      prompt12,
      MEDIA_CONFIG_12.maxImagePromptChars
    );

  const validation12 =
    media12ValidateGenerationRequest({
      userId12,
      type12:
        "image",
      prompt12:
        normalizedPrompt12
    });

  if (
    !validation12.valid
  ) {
    const error12 =
      new Error(
        validation12.reason
      );

    error12.quota =
      validation12.quota ||
      null;

    throw error12;
  }

  return media12CreateJob({
    userId12,
    type12:
      "image",
    prompt12:
      normalizedPrompt12,
    options12
  });
}

/* ------------------------------------------------------------
   12.32 - CREATE VIDEO JOB
------------------------------------------------------------ */

function media12QueueVideo({
  userId12,
  prompt12,
  options12 = {}
}) {
  const normalizedPrompt12 =
    media12NormalizePrompt(
      prompt12,
      MEDIA_CONFIG_12.maxVideoPromptChars
    );

  const validation12 =
    media12ValidateGenerationRequest({
      userId12,
      type12:
        "video",
      prompt12:
        normalizedPrompt12
    });

  if (
    !validation12.valid
  ) {
    const error12 =
      new Error(
        validation12.reason
      );

    error12.quota =
      validation12.quota ||
      null;

    throw error12;
  }

  return media12CreateJob({
    userId12,
    type12:
      "video",
    prompt12:
      normalizedPrompt12,
    options12
  });
}

/* ------------------------------------------------------------
   12.33 - LIST USER JOBS
------------------------------------------------------------ */

function media12ListJobs({
  userId12 = "guest",
  type12 = null,
  status12 = null,
  limit12 = 30
} = {}) {
  const jobs12 =
    media12GetJobs();

  let items12 =
    Object.values(
      jobs12
    )
      .filter(
        (job12) =>
          job12 &&
          job12.userId ===
            userId12
      );

  if (
    type12
  ) {
    items12 =
      items12.filter(
        (job12) =>
          job12.type ===
          type12
      );
  }

  if (
    status12
  ) {
    items12 =
      items12.filter(
        (job12) =>
          job12.status ===
          status12
      );
  }

  items12.sort(
    (a12, b12) =>
      String(
        b12.createdAt ||
        ""
      ).localeCompare(
        String(
          a12.createdAt ||
          ""
        )
      )
  );

  const safeLimit12 =
    clamp(
      toInteger(
        limit12,
        30
      ),
      1,
      100
    );

  return {
    items:
      items12.slice(
        0,
        safeLimit12
      ),

    total:
      items12.length
  };
}

/* ------------------------------------------------------------
   12.34 - LIST USER ASSETS
------------------------------------------------------------ */

function media12ListAssets({
  userId12 = "guest",
  type12 = null,
  limit12 = 50
} = {}) {
  const assets12 =
    media12GetAssets();

  let items12 =
    Object.values(
      assets12
    )
      .filter(
        (asset12) =>
          asset12 &&
          asset12.userId ===
            userId12
      );

  if (
    type12
  ) {
    items12 =
      items12.filter(
        (asset12) =>
          asset12.type ===
          type12
      );
  }

  items12.sort(
    (a12, b12) =>
      String(
        b12.createdAt ||
        ""
      ).localeCompare(
        String(
          a12.createdAt ||
          ""
        )
      )
  );

  const safeLimit12 =
    clamp(
      toInteger(
        limit12,
        50
      ),
      1,
      200
    );

  return {
    items:
      items12.slice(
        0,
        safeLimit12
      ),

    total:
      items12.length
  };
}

/* ------------------------------------------------------------
   12.35 - GET ASSET
------------------------------------------------------------ */

function media12GetAsset(
  assetId12,
  userId12
) {
  const assets12 =
    media12GetAssets();

  const id12 =
    media12SafeId(
      assetId12
    );

  const asset12 =
    assets12[id12];

  if (
    !asset12
  ) {
    return null;
  }

  if (
    asset12.userId !==
    userId12
  ) {
    return null;
  }

  return asset12;
}

/* ------------------------------------------------------------
   12.36 - DELETE ASSET
------------------------------------------------------------ */

function media12DeleteAsset(
  assetId12,
  userId12
) {
  const assets12 =
    media12GetAssets();

  const id12 =
    media12SafeId(
      assetId12
    );

  const asset12 =
    assets12[id12];

  if (
    !asset12
  ) {
    throw new Error(
      "Medya bulunamadı."
    );
  }

  if (
    asset12.userId !==
    userId12
  ) {
    throw new Error(
      "Bu medya dosyasına erişim izni yok."
    );
  }

  try {
    if (
      asset12.path &&
      fs12.existsSync(
        asset12.path
      )
    ) {
      fs12.unlinkSync(
        asset12.path
      );
    }
  } catch (_) {}

  delete assets12[id12];

  media12SaveAssets(
    assets12
  );

  media12AppendHistory({
    type:
      "asset_deleted",
    assetId:
      id12,
    userId:
      userId12
  });

  return {
    success: true,
    assetId:
      id12
  };
}

/* ------------------------------------------------------------
   12.37 - HISTORY
------------------------------------------------------------ */

function media12GetHistory() {
  return media12ReadJSON(
    MEDIA_GENERATION_HISTORY_STORE_12,
    []
  );
}

function media12AppendHistory(
  event12
) {
  const history12 =
    media12GetHistory();

  history12.push({
    id:
      createId(),
    timestamp:
      nowISO(),
    ...event12
  });

  if (
    history12.length >
    MEDIA_CONFIG_12.maxHistory
  ) {
    history12.splice(
      0,
      history12.length -
        MEDIA_CONFIG_12.maxHistory
    );
  }

  media12WriteJSON(
    MEDIA_GENERATION_HISTORY_STORE_12,
    history12
  );
}

function media12UserHistory({
  userId12 = "guest",
  limit12 = 50
} = {}) {
  const history12 =
    media12GetHistory();

  const items12 =
    history12
      .filter(
        (item12) =>
          item12?.userId ===
          userId12
      )
      .sort(
        (a12, b12) =>
          String(
            b12.timestamp ||
            ""
          ).localeCompare(
            String(
              a12.timestamp ||
              ""
            )
          )
      );

  return {
    items:
      items12.slice(
        0,
        clamp(
          toInteger(
            limit12,
            50
          ),
          1,
          200
        )
      ),

    total:
      items12.length
  };
}

/* ------------------------------------------------------------
   12.38 - EXPORT USER ASSET INDEX
------------------------------------------------------------ */

function media12ExportUserIndex(
  userId12
) {
  const assets12 =
    media12GetAssets();

  const jobs12 =
    media12GetJobs();

  const userAssets12 =
    Object.values(
      assets12
    ).filter(
      (asset12) =>
        asset12?.userId ===
        userId12
    );

  const userJobs12 =
    Object.values(
      jobs12
    ).filter(
      (job12) =>
        job12?.userId ===
        userId12
    );

  const payload12 = {
    format:
      "turkai-media-v1",

    exportedAt:
      nowISO(),

    userId:
      userId12,

    assets:
      userAssets12,

    jobs:
      userJobs12
  };

  const fileName12 =
    `media-${userId12}-${Date.now()}.json`;

  const filePath12 =
    path12.join(
      MEDIA_GENERATION_EXPORT_12,
      fileName12
    );

  media12WriteJSON(
    filePath12,
    payload12
  );

  return {
    success:
      true,

    fileName:
      fileName12,

    filePath:
      filePath12,

    data:
      payload12
  };
}

/* ------------------------------------------------------------
   12.39 - GENERATION STATUS
------------------------------------------------------------ */

function media12Status() {
  const jobs12 =
    media12GetJobs();

  const assets12 =
    media12GetAssets();

  const usage12 =
    media12GetUsage();

  const jobValues12 =
    Object.values(
      jobs12
    );

  return {
    success:
      true,

    module:
      "media-generation",

    version:
      MEDIA_CONFIG_12.version,

    enabled:
      MEDIA_CONFIG_12.enabled,

    providers: {
      image:
        MEDIA_IMAGE_PROVIDER_12,

      video:
        MEDIA_VIDEO_PROVIDER_12,

      imageConfigured:
        Boolean(
          MEDIA_IMAGE_API_URL_12
        ),

      videoConfigured:
        Boolean(
          MEDIA_VIDEO_CREATE_URL_12
        )
    },

    jobs: {
      total:
        jobValues12.length,

      queued:
        jobValues12.filter(
          (job12) =>
            job12.status ===
            "queued"
        ).length,

      processing:
        jobValues12.filter(
          (job12) =>
            job12.status ===
            "processing"
        ).length,

      completed:
        jobValues12.filter(
          (job12) =>
            job12.status ===
            "completed"
        ).length,

      failed:
        jobValues12.filter(
          (job12) =>
            job12.status ===
            "failed"
        ).length
    },

    assets:
      Object.keys(
        assets12
      ).length,

    worker:
      clone(
        MEDIA_WORKER_12
      ),

    usageDays:
      Object.keys(
        usage12
      ).length,

    checkedAt:
      nowISO()
  };
}

