/* ------------------------------------------------------------
   12.45 - CANCEL QUEUED JOB
------------------------------------------------------------ */

app.post(
  "/api/generation/jobs/:jobId/cancel",
  (req12, res12) => {
    try {
      const userId12 =
        media12GetUserId(
          req12
        );

      const job12 =
        media12GetJob(
          req12.params.jobId,
          userId12
        );

      if (!job12) {
        return media12Error(
          res12,
          404,
          "Üretim görevi bulunamadı."
        );
      }

      if (
        job12.status !==
        "queued"
      ) {
        return media12Error(
          res12,
          409,
          "Sadece sıradaki görevler iptal edilebilir."
        );
      }

      const updated12 =
        media12UpdateJob(
          job12.id,
          {
            status:
              "cancelled",

            completedAt:
              nowISO()
          }
        );

      media12AppendHistory({
        type:
          "job_cancelled",
        jobId:
          job12.id,
        userId:
          userId12
      });

      res12.json({
        success:
          true,

        job:
          updated12
      });
    } catch (error12) {
      media12Error(
        res12,
        500,
        error12.message
      );
    }
  }
);

