/* ------------------------------------------------------------
   12.48 - ASSET DOWNLOAD API
------------------------------------------------------------ */

app.get(
  "/api/generation/assets/:assetId/download",
  (req12, res12) => {
    try {
      const asset12 =
        media12GetAsset(
          req12.params.assetId,
          media12GetUserId(
            req12
          )
        );

      if (!asset12) {
        return media12Error(
          res12,
          404,
          "Medya bulunamadı."
        );
      }

      if (
        !asset12.path ||
        !fs12.existsSync(
          asset12.path
        )
      ) {
        return media12Error(
          res12,
          404,
          "Medya dosyası artık mevcut değil."
        );
      }

      res12.setHeader(
        "Content-Type",
        asset12.mimeType ||
          media12MimeFromExtension(
            asset12.extension
          )
      );

      res12.setHeader(
        "Content-Length",
        String(
          asset12.fileSize ||
          fs12.statSync(
            asset12.path
          ).size
        )
      );

      res12.setHeader(
        "Content-Disposition",
        `inline; filename="${encodeURIComponent(
          asset12.filename
        )}"`
      );

      fs12.createReadStream(
        asset12.path
      ).pipe(
        res12
      );
    } catch (error12) {
      media12Error(
        res12,
        500,
        error12.message
      );
    }
  }
);

