/* ------------------------------------------------------------
   12.58 - OLD TEMP FILE CLEANER
------------------------------------------------------------ */

function media12CleanupTemp() {
  let removed12 = 0;

  try {
    const files12 =
      fs12.readdirSync(
        MEDIA_GENERATION_TEMP_12
      );

    const now12 =
      Date.now();

    for (
      const fileName12 of
      files12
    ) {
      const fullPath12 =
        path12.join(
          MEDIA_GENERATION_TEMP_12,
          fileName12
        );

      try {
        const stat12 =
          fs12.statSync(
            fullPath12
          );

        if (
          now12 -
            stat12.mtimeMs >
          24 * 60 * 60 * 1000
        ) {
          fs12.unlinkSync(
            fullPath12
          );

          removed12 +=
            1;
        }
      } catch (_) {}
    }
  } catch (_) {}

  return {
    success:
      true,

    removed:
      removed12
  };
}

const MEDIA_CLEANUP_TIMER_12 =
  setInterval(
    () => {
      try {
        media12CleanupTemp();
      } catch (error12) {
        systemLog?.(
          "media12_cleanup_error",
          {
            error:
              error12?.message ||
              String(error12)
          }
        );
      }
    },
    30 * 60 * 1000
  );

if (
  MEDIA_CLEANUP_TIMER_12?.unref
) {
  MEDIA_CLEANUP_TIMER_12.unref();
}

/* ------------------------------------------------------------
   12.59 - PERIODIC USAGE CLEANUP
------------------------------------------------------------ */

function media12CleanupUsage() {
  const usage12 =
    media12GetUsage();

  const keepDays12 =
    60;

  const cutoff12 =
    Date.now() -
    keepDays12 *
      24 *
      60 *
      60 *
      1000;

  for (
    const type12 of [
      "image",
      "video"
    ]
  ) {
    if (
      !usage12[type12]
    ) {
      continue;
    }

    for (
      const userId12 of
      Object.keys(
        usage12[type12]
      )
    ) {
      const days12 =
        usage12[type12][
          userId12
        ];

      for (
        const day12 of
        Object.keys(
          days12
        )
      ) {
        const timestamp12 =
          new Date(
            `${day12}T00:00:00.000Z`
          ).getTime();

        if (
          Number.isFinite(
            timestamp12
          ) &&
          timestamp12 <
            cutoff12
        ) {
          delete days12[
            day12
          ];
        }
      }
    }
  }

  usage12.updatedAt =
    nowISO();

  media12WriteJSON(
    MEDIA_GENERATION_USAGE_STORE_12,
    usage12
  );

  return {
    success:
      true
  };
}

const MEDIA_USAGE_CLEANUP_TIMER_12 =
  setInterval(
    () => {
      try {
        media12CleanupUsage();
      } catch (error12) {
        systemLog?.(
          "media12_usage_cleanup_error",
          {
            error:
              error12?.message ||
              String(error12)
          }
        );
      }
    },
    6 * 60 * 60 * 1000
  );

if (
  MEDIA_USAGE_CLEANUP_TIMER_12?.unref
) {
  MEDIA_USAGE_CLEANUP_TIMER_12.unref();
}

