/* ------------------------------------------------------------
   13.5 - JSON HELPERS
------------------------------------------------------------ */

function voice13ReadJSON(
  filePath13,
  fallback13
) {
  try {
    if (
      !fs13.existsSync(
        filePath13
      )
    ) {
      return fallback13;
    }

    const raw13 =
      fs13.readFileSync(
        filePath13,
        "utf8"
      );

    if (
      !raw13.trim()
    ) {
      return fallback13;
    }

    return JSON.parse(
      raw13
    );
  } catch (error13) {
    systemLog?.(
      "voice13_read_error",
      {
        file:
          filePath13,
        error:
          error13?.message ||
          String(error13)
      }
    );

    return fallback13;
  }
}

function voice13WriteJSON(
  filePath13,
  value13
) {
  try {
    fs13.mkdirSync(
      path13.dirname(
        filePath13
      ),
      {
        recursive:
          true
      }
    );

    const temp13 =
      `${filePath13}.${process.pid}.${Date.now()}.tmp`;

    fs13.writeFileSync(
      temp13,
      JSON.stringify(
        value13,
        null,
        2
      ),
      "utf8"
    );

    fs13.renameSync(
      temp13,
      filePath13
    );

    return true;
  } catch (error13) {
    systemLog?.(
      "voice13_write_error",
      {
        file:
          filePath13,
        error:
          error13?.message ||
          String(error13)
      }
    );

    return false;
  }
}

/* ------------------------------------------------------------
   13.6 - GENERAL HELPERS
------------------------------------------------------------ */

function voice13SafeString(
  value13,
  fallback13 = ""
) {
  return safeString(
    value13,
    fallback13
  )
    .normalize("NFKC")
    .replace(
      /\u0000/g,
      ""
    )
    .trim();
}

function voice13SafeId(
  value13,
  fallback13 = ""
) {
  return voice13SafeString(
    value13,
    fallback13
  )
    .replace(
      /[^a-zA-Z0-9_\-:.]/g,
      "-"
    )
    .replace(
      /-+/g,
      "-"
    )
    .replace(
      /^-+|-+$/g,
      ""
    )
    .slice(
      0,
      180
    );
}

function voice13Hash(
  value13
) {
  return crypto13
    .createHash(
      "sha256"
    )
    .update(
      Buffer.from(
        voice13SafeString(
          value13,
          ""
        ),
        "utf8"
      )
    )
    .digest("hex");
}

function voice13ShortHash(
  value13
) {
  return voice13Hash(
    value13
  ).slice(
    0,
    18
  );
}

function voice13UserId(
  req13
) {
  return normalizeUserId(
    voice13SafeString(
      req13?.user?.id ||
      req13?.body?.userId ||
      req13?.query?.userId ||
      "guest"
    )
  );
}

/* ------------------------------------------------------------
   13.7 - USER PLAN / LIMITS
------------------------------------------------------------ */

const VOICE_PLAN_LIMITS_13 = {
  free: {
    sttPerDay:
      0,
    ttsPerDay:
      0
  },

  pro: {
    sttPerDay:
      30,
    ttsPerDay:
      50
  },

  plus: {
    sttPerDay:
      100,
    ttsPerDay:
      200
  },

  ultra: {
    sttPerDay:
      500,
    ttsPerDay:
      1000
  },

  developer: {
    sttPerDay:
      10000,
    ttsPerDay:
      10000
  },

  owner: {
    sttPerDay:
      10000,
    ttsPerDay:
      10000
  }
};

function voice13ResolvePlan(
  userId13
) {
  try {
    const user13 =
      typeof getUser ===
      "function"
        ? getUser(
            userId13
          )
        : null;

    const rawPlan13 =
      user13?.plan ||
      user13?.planId ||
      user13?.subscription?.plan ||
      user13?.subscription?.planId ||
      "free";

    const plan13 =
      voice13SafeString(
        rawPlan13,
        "free"
      ).toLocaleLowerCase(
        "tr-TR"
      );

    return (
      VOICE_PLAN_LIMITS_13[
        plan13
      ]
        ? plan13
        : "free"
    );
  } catch (_) {
    return "free";
  }
}

/* ------------------------------------------------------------
   13.8 - DAILY USAGE
------------------------------------------------------------ */

function voice13DefaultUsage() {
  return {
    stt: {},
    tts: {},
    updatedAt:
      nowISO()
  };
}

function voice13GetUsage() {
  return voice13ReadJSON(
    VOICE_USAGE_STORE_13,
    voice13DefaultUsage()
  );
}

function voice13Today() {
  return todayKey();
}

function voice13DailyCount(
  userId13,
  type13
) {
  const usage13 =
    voice13GetUsage();

  return toInteger(
    usage13?.[
      type13
    ]?.[
      userId13
    ]?.[
      voice13Today()
    ],
    0
  );
}

function voice13CheckQuota(
  userId13,
  type13
) {
  const plan13 =
    voice13ResolvePlan(
      userId13
    );

  const limits13 =
    VOICE_PLAN_LIMITS_13[
      plan13
    ] ||
    VOICE_PLAN_LIMITS_13.free;

  const limit13 =
    type13 ===
    "stt"
      ? limits13.sttPerDay
      : limits13.ttsPerDay;

  const current13 =
    voice13DailyCount(
      userId13,
      type13
    );

  return {
    allowed:
      current13 <
      limit13,

    plan:
      plan13,

    type:
      type13,

    current:
      current13,

    limit:
      limit13,

    remaining:
      Math.max(
        0,
        limit13 -
          current13
      )
  };
}

function voice13IncrementUsage(
  userId13,
  type13
) {
  const usage13 =
    voice13GetUsage();

  const day13 =
    voice13Today();

  if (
    !usage13[type13]
  ) {
    usage13[type13] = {};
  }

  if (
    !usage13[type13][
      userId13
    ]
  ) {
    usage13[type13][
      userId13
    ] = {};
  }

  usage13[type13][
    userId13
  ][day13] =
    voice13DailyCount(
      userId13,
      type13
    ) + 1;

  usage13.updatedAt =
    nowISO();

  voice13WriteJSON(
    VOICE_USAGE_STORE_13,
    usage13
  );

  return {
    current:
      usage13[type13][
        userId13
      ][day13],

    remaining:
      voice13CheckQuota(
        userId13,
        type13
      ).remaining
  };
}

/* ------------------------------------------------------------
   13.9 - AUDIO MIME HELPERS
------------------------------------------------------------ */

function voice13Mime(
  extension13
) {
  const ext13 =
    voice13SafeString(
      extension13,
      ""
    ).toLowerCase();

  const map13 = {
    mp3:
      "audio/mpeg",

    wav:
      "audio/wav",

    ogg:
      "audio/ogg",

    webm:
      "audio/webm",

    m4a:
      "audio/mp4",

    flac:
      "audio/flac"
  };

  return (
    map13[
      ext13
    ] ||
    "application/octet-stream"
  );
}

function voice13ExtensionFromMime(
  mime13,
  fallback13 = "mp3"
) {
  const value13 =
    voice13SafeString(
      mime13,
      ""
    ).toLowerCase();

  if (
    value13.includes(
      "mpeg"
    )
  ) {
    return "mp3";
  }

  if (
    value13.includes(
      "wav"
    )
  ) {
    return "wav";
  }

  if (
    value13.includes(
      "ogg"
    )
  ) {
    return "ogg";
  }

  if (
    value13.includes(
      "webm"
    )
  ) {
    return "webm";
  }

  if (
    value13.includes(
      "flac"
    )
  ) {
    return "flac";
  }

  if (
    value13.includes(
      "mp4"
    )
  ) {
    return "m4a";
  }

  return fallback13;
}

/* ------------------------------------------------------------
   13.10 - AUDIO FILE VALIDATION
------------------------------------------------------------ */

function voice13ValidateBuffer(
  buffer13
) {
  if (
    !Buffer.isBuffer(
      buffer13
    )
  ) {
    return {
      valid: false,
      reason:
        "Ses verisi geçersiz."
    };
  }

  if (
    buffer13.length ===
    0
  ) {
    return {
      valid: false,
      reason:
        "Ses dosyası boş."
    };
  }

  if (
    buffer13.length >
    VOICE_CONFIG_13.maxAudioBytes
  ) {
    return {
      valid: false,
      reason:
        "Ses dosyası izin verilen boyutu aşıyor."
    };
  }

  return {
    valid:
      true
  };
}

/* ------------------------------------------------------------
   13.11 - STT JOB MODEL
------------------------------------------------------------ */

function voice13GetJobs() {
  return voice13ReadJSON(
    VOICE_JOB_STORE_13,
    {}
  );
}

function voice13SaveJobs(
  jobs13
) {
  const keys13 =
    Object.keys(
      jobs13
    );

  if (
    keys13.length >
    VOICE_CONFIG_13.maxJobs
  ) {
    keys13
      .sort(
        (a13, b13) =>
          String(
            jobs13[a13]?.createdAt ||
            ""
          ).localeCompare(
            String(
              jobs13[b13]?.createdAt ||
              ""
            )
          )
      )
      .slice(
        0,
        keys13.length -
          VOICE_CONFIG_13.maxJobs
      )
      .forEach(
        (oldId13) =>
          delete jobs13[
            oldId13
          ]
      );
  }

  return voice13WriteJSON(
    VOICE_JOB_STORE_13,
    jobs13
  );
}

function voice13CreateJob({
  userId13,
  type13,
  input13 = {},
  options13 = {}
}) {
  const jobs13 =
    voice13GetJobs();

  const jobId13 =
    `voice-${type13}-${voice13ShortHash(
      `${userId13}:${type13}:${Date.now()}:${Math.random()}`
    )}`;

  const job13 = {
    id:
      jobId13,

    userId:
      userId13,

    type:
      type13,

    status:
      "queued",

    progress:
      0,

    input:
      isObject(
        input13
      )
        ? clone(
            input13
          )
        : {},

    options:
      isObject(
        options13
      )
        ? clone(
            options13
          )
        : {},

    provider:
      type13 ===
      "stt"
        ? VOICE_STT_PROVIDER_13
        : VOICE_TTS_PROVIDER_13,

    providerJobId:
      null,

    result:
      null,

    error:
      null,

    createdAt:
      nowISO(),

    startedAt:
      null,

    completedAt:
      null,

    updatedAt:
      nowISO()
  };

  jobs13[
    jobId13
  ] = job13;

  voice13SaveJobs(
    jobs13
  );

  voice13AppendHistory({
    type:
      "job_created",

    userId:
      userId13,

    jobId:
      jobId13,

    voiceType:
      type13
  });

  return job13;
}

function voice13GetJob(
  jobId13,
  userId13 = null
) {
  const jobs13 =
    voice13GetJobs();

  const safeId13 =
    voice13SafeId(
      jobId13
    );

  const job13 =
    jobs13[
      safeId13
    ];

  if (
    !job13
  ) {
    return null;
  }

  if (
    userId13 &&
    job13.userId !==
      userId13
  ) {
    return null;
  }

  return job13;
}

function voice13UpdateJob(
  jobId13,
  updates13 = {}
) {
  const jobs13 =
    voice13GetJobs();

  const safeId13 =
    voice13SafeId(
      jobId13
    );

  if (
    !jobs13[
      safeId13
    ]
  ) {
    return null;
  }

  jobs13[
    safeId13
  ] = {
    ...jobs13[
      safeId13
    ],

    ...updates13,

    updatedAt:
      nowISO()
  };

  voice13SaveJobs(
    jobs13
  );

  return jobs13[
    safeId13
  ];
}

/* ------------------------------------------------------------
   13.12 - VOICE ASSETS
------------------------------------------------------------ */

function voice13GetAssets() {
  return voice13ReadJSON(
    VOICE_ASSET_STORE_13,
    {}
  );
}

function voice13SaveAssets(
  assets13
) {
  const keys13 =
    Object.keys(
      assets13
    );

  if (
    keys13.length >
    VOICE_CONFIG_13.maxAssets
  ) {
    keys13
      .sort(
        (a13, b13) =>
          String(
            assets13[a13]?.createdAt ||
            ""
          ).localeCompare(
            String(
              assets13[b13]?.createdAt ||
              ""
            )
          )
      )
      .slice(
        0,
        keys13.length -
          VOICE_CONFIG_13.maxAssets
      )
      .forEach(
        (oldId13) =>
          delete assets13[
            oldId13
          ]
      );
  }

  return voice13WriteJSON(
    VOICE_ASSET_STORE_13,
    assets13
  );
}

function voice13CreateAsset({
  userId13,
  type13,
  jobId13,
  filePath13,
  mimeType13,
  size13,
  language13,
  metadata13 = {}
}) {
  const assets13 =
    voice13GetAssets();

  const extension13 =
    path13.extname(
      filePath13
    )
      .replace(
        ".",
        ""
      )
      .toLowerCase();

  const assetId13 =
    `voiceasset-${voice13ShortHash(
      `${userId13}:${jobId13}:${filePath13}:${Date.now()}`
    )}`;

  const asset13 = {
    id:
      assetId13,

    userId:
      userId13,

    type:
      type13,

    jobId:
      jobId13,

    filename:
      path13.basename(
        filePath13
      ),

    extension:
      extension13,

    mimeType:
      mimeType13 ||
      voice13Mime(
        extension13
      ),

    size:
      toNumber(
        size13,
        0
      ),

    language:
      language13 ||
      VOICE_CONFIG_13.defaultLanguage,

    path:
      filePath13,

    url:
      `/api/voice/assets/${assetId13}/download`,

    metadata:
      isObject(
        metadata13
      )
        ? clone(
            metadata13
          )
        : {},

    createdAt:
      nowISO()
  };

  assets13[
    assetId13
  ] = asset13;

  voice13SaveAssets(
    assets13
  );

  voice13AppendHistory({
    type:
      "asset_created",

    userId:
      userId13,

    assetId:
      assetId13,

    voiceType:
      type13
  });

  return asset13;
}

/* ------------------------------------------------------------
   13.13 - HISTORY
------------------------------------------------------------ */

function voice13GetHistory() {
  return voice13ReadJSON(
    VOICE_HISTORY_STORE_13,
    []
  );
}

function voice13AppendHistory(
  event13
) {
  const history13 =
    voice13GetHistory();

  history13.push({
    id:
      createId(),

    timestamp:
      nowISO(),

    ...event13
  });

  if (
    history13.length >
    VOICE_CONFIG_13.maxHistory
  ) {
    history13.splice(
      0,
      history13.length -
        VOICE_CONFIG_13.maxHistory
    );
  }

  voice13WriteJSON(
    VOICE_HISTORY_STORE_13,
    history13
  );
}

/* ------------------------------------------------------------
   13.14 - TTS CACHE
------------------------------------------------------------ */

function voice13GetCache() {
  return voice13ReadJSON(
    VOICE_CACHE_STORE_13,
    {}
  );
}

function voice13CacheKey({
  text13,
  voice13,
  language13,
  format13
}) {
  return voice13Hash(
    JSON.stringify({
      text:
        voice13SafeString(
          text13,
          ""
        ),

      voice:
        voice13SafeString(
          voice13,
          "default"
        ),

      language:
        voice13SafeString(
          language13,
          "tr"
        ),

      format:
        voice13SafeString(
          format13,
          "mp3"
        )
    })
  );
}

function voice13GetCached(
  key13
) {
  if (
    !VOICE_CONFIG_13.cacheEnabled
  ) {
    return null;
  }

  const cache13 =
    voice13GetCache();

  const item13 =
    cache13[
      key13
    ];

  if (
    !item13
  ) {
    return null;
  }

  if (
    Date.now() -
      toNumber(
        item13.createdAtMs,
        0
      ) >
    VOICE_CONFIG_13.cacheTtlMs
  ) {
    delete cache13[
      key13
    ];

    voice13WriteJSON(
      VOICE_CACHE_STORE_13,
      cache13
    );

    return null;
  }

  if (
    !item13.path ||
    !fs13.existsSync(
      item13.path
    )
  ) {
    delete cache13[
      key13
    ];

    voice13WriteJSON(
      VOICE_CACHE_STORE_13,
      cache13
    );

    return null;
  }

  return item13;
}

function voice13SaveCache(
  key13,
  item13
) {
  if (
    !VOICE_CONFIG_13.cacheEnabled
  ) {
    return;
  }

  const cache13 =
    voice13GetCache();

  cache13[
    key13
  ] = {
    ...item13,
    createdAtMs:
      Date.now()
  };

  const keys13 =
    Object.keys(
      cache13
    );

  if (
    keys13.length >
    1000
  ) {
    keys13
      .sort(
        (a13, b13) =>
          toNumber(
            cache13[a13]?.createdAtMs,
            0
          ) -
          toNumber(
            cache13[b13]?.createdAtMs,
            0
          )
      )
      .slice(
        0,
        keys13.length -
          1000
      )
      .forEach(
        (keyRemove13) =>
          delete cache13[
            keyRemove13
          ]
      );
  }

  voice13WriteJSON(
    VOICE_CACHE_STORE_13,
    cache13
  );
}

/* ------------------------------------------------------------
   13.15 - GENERIC HTTP
------------------------------------------------------------ */

async function voice13FetchJSON(
  url13,
  options13 = {},
  timeout13 =
    VOICE_CONFIG_13.requestTimeoutMs
) {
  const controller13 =
    new AbortController();

  const timer13 =
    setTimeout(
      () =>
        controller13.abort(),
      timeout13
    );

  try {
    const response13 =
      await fetch(
        url13,
        {
          ...options13,
          signal:
            controller13.signal
        }
      );

    const raw13 =
      await response13.text();

    let json13 =
      null;

    try {
      json13 =
        raw13
          ? JSON.parse(
              raw13
            )
          : {};
    } catch (_) {
      json13 = {
        raw:
          raw13
      };
    }

    if (
      !response13.ok
    ) {
      const error13 =
        new Error(
          `Voice provider HTTP ${response13.status}`
        );

      error13.status =
        response13.status;

      error13.data =
        json13;

      throw error13;
    }

    return json13;
  } finally {
    clearTimeout(
      timer13
    );
  }
}

/* ------------------------------------------------------------
   13.16 - GENERIC BINARY FETCH
------------------------------------------------------------ */

async function voice13FetchBinary(
  url13,
  options13 = {}
) {
  const controller13 =
    new AbortController();

  const timer13 =
    setTimeout(
      () =>
        controller13.abort(),
      VOICE_CONFIG_13.requestTimeoutMs
    );

  try {
    const response13 =
      await fetch(
        url13,
        {
          ...options13,
          signal:
            controller13.signal
        }
      );

    if (
      !response13.ok
    ) {
      throw new Error(
        `Audio provider HTTP ${response13.status}`
      );
    }

    const length13 =
      toNumber(
        response13.headers.get(
          "content-length"
        ),
        0
      );

    if (
      length13 >
      VOICE_CONFIG_13.maxOutputAudioBytes
    ) {
      throw new Error(
        "Ses çıktısı çok büyük."
      );
    }

    const arrayBuffer13 =
      await response13.arrayBuffer();

    const buffer13 =
      Buffer.from(
        arrayBuffer13
      );

    if (
      buffer13.length >
      VOICE_CONFIG_13.maxOutputAudioBytes
    ) {
      throw new Error(
        "Ses çıktısı çok büyük."
      );
    }

    return {
      buffer:
        buffer13,

      contentType:
        response13.headers.get(
          "content-type"
        ) ||
        "application/octet-stream"
    };
  } finally {
    clearTimeout(
      timer13
    );
  }
}

/* ------------------------------------------------------------
   13.17 - GENERIC STT PROVIDER
   Multipart gönderimi için FormData + Blob kullanır.
------------------------------------------------------------ */

async function voice13STTGeneric(
  audioPath13,
  options13 = {}
) {
  if (
    !VOICE_STT_API_URL_13
  ) {
    throw new Error(
      "STT provider yapılandırılmamış. TURKAI_STT_API_URL gerekli."
    );
  }

  if (
    typeof FormData ===
      "undefined" ||
    typeof Blob ===
      "undefined"
  ) {
    throw new Error(
      "Node ortamı FormData/Blob desteği sağlamıyor."
    );
  }

  const audioBuffer13 =
    fs13.readFileSync(
      audioPath13
    );

  const validation13 =
    voice13ValidateBuffer(
      audioBuffer13
    );

  if (
    !validation13.valid
  ) {
    throw new Error(
      validation13.reason
    );
  }

  const form13 =
    new FormData();

  const fileName13 =
    path13.basename(
      audioPath13
    );

  const extension13 =
    path13.extname(
      fileName13
    )
      .replace(
        ".",
        ""
      )
      .toLowerCase();

  const blob13 =
    new Blob(
      [
        audioBuffer13
      ],
      {
        type:
          voice13Mime(
            extension13
          )
      }
    );

  form13.append(
    "file",
    blob13,
    fileName13
  );

  form13.append(
    "model",
    options13.model ||
      VOICE_STT_MODEL_13
  );

  if (
    options13.language
  ) {
    form13.append(
      "language",
      options13.language
    );
  }

  if (
    options13.prompt
  ) {
    form13.append(
      "prompt",
      options13.prompt
    );
  }

  if (
    options13.responseFormat
  ) {
    form13.append(
      "response_format",
      options13.responseFormat
    );
  }

  const headers13 = {};

  if (
    VOICE_STT_API_KEY_13
  ) {
    headers13.authorization =
      `Bearer ${VOICE_STT_API_KEY_13}`;
  }

  const controller13 =
    new AbortController();

  const timer13 =
    setTimeout(
      () =>
        controller13.abort(),
      VOICE_CONFIG_13.requestTimeoutMs
    );

  try {
    const response13 =
      await fetch(
        VOICE_STT_API_URL_13,
        {
          method:
            "POST",

          headers:
            headers13,

          body:
            form13,

          signal:
            controller13.signal
        }
      );

    const raw13 =
      await response13.text();

    let data13 =
      null;

    try {
      data13 =
        raw13
          ? JSON.parse(
              raw13
            )
          : {};
    } catch (_) {
      data13 = {
        text:
          raw13
      };
    }

    if (
      !response13.ok
    ) {
      throw new Error(
        `STT provider HTTP ${response13.status}`
      );
    }

    const text13 =
      data13?.text ||
      data13?.transcript ||
      data13?.result?.text ||
      data13?.output_text ||
      "";

    if (
      !voice13SafeString(
        text13,
        ""
      )
    ) {
      throw new Error(
        "STT provider transkripsiyon döndürmedi."
      );
    }

    return {
      text:
        voice13SafeString(
          text13,
          ""
        ),

      language:
        data13?.language ||
        options13.language ||
        VOICE_CONFIG_13.defaultLanguage,

      duration:
        toNumber(
          data13?.duration,
          0
        ),

      segments:
        Array.isArray(
          data13?.segments
        )
          ? data13.segments
          : [],

      providerResponse:
        data13
    };
  } finally {
    clearTimeout(
      timer13
    );
  }
}

/* ------------------------------------------------------------
   13.18 - STT PROVIDER ADAPTER
------------------------------------------------------------ */

async function voice13Transcribe(
  audioPath13,
  options13 = {}
) {
  const provider13 =
    voice13SafeString(
      options13.provider ||
      VOICE_STT_PROVIDER_13,
      "generic"
    ).toLowerCase();

  if (
    provider13 ===
      "generic" ||
    provider13 ===
      "openai-compatible" ||
    provider13 ===
      "openai"
  ) {
    return voice13STTGeneric(
      audioPath13,
      options13
    );
  }

  return voice13STTGeneric(
    audioPath13,
    options13
  );
}

/* ------------------------------------------------------------
   13.19 - GENERIC TTS PROVIDER
------------------------------------------------------------ */

async function voice13TTSGeneric(
  text13,
  options13 = {}
) {
  if (
    !VOICE_TTS_API_URL_13
  ) {
    throw new Error(
      "TTS provider yapılandırılmamış. TURKAI_TTS_API_URL gerekli."
    );
  }

  const payload13 = {
    model:
      options13.model ||
      VOICE_TTS_MODEL_13,

    input:
      text13,

    text:
      text13,

    voice:
      options13.voice ||
      VOICE_CONFIG_13.defaultVoice,

    language:
      options13.language ||
      VOICE_CONFIG_13.defaultLanguage,

    response_format:
      options13.format ||
      VOICE_CONFIG_13.defaultFormat,

    speed:
      clamp(
        Number(
          options13.speed ??
          1
        ),
        0.5,
        2
      )
  };

  const headers13 = {
    "content-type":
      "application/json"
  };

  if (
    VOICE_TTS_API_KEY_13
  ) {
    headers13.authorization =
      `Bearer ${VOICE_TTS_API_KEY_13}`;
  }

  const response13 =
    await fetch(
      VOICE_TTS_API_URL_13,
      {
        method:
          "POST",

        headers:
          headers13,

        body:
          JSON.stringify(
            payload13
          )
      }
    );

  if (
    !response13.ok
  ) {
    const errorText13 =
      await response13.text();

    throw new Error(
      `TTS provider HTTP ${response13.status}: ${errorText13.slice(
        0,
        500
      )}`
    );
  }

  const contentType13 =
    response13.headers.get(
      "content-type"
    ) ||
    "application/octet-stream";

  const arrayBuffer13 =
    await response13.arrayBuffer();

  const buffer13 =
    Buffer.from(
      arrayBuffer13
    );

  if (
    buffer13.length >
    VOICE_CONFIG_13.maxOutputAudioBytes
  ) {
    throw new Error(
      "TTS çıktısı çok büyük."
    );
  }

  return {
    mode:
      "buffer",

    buffer:
      buffer13,

    mimeType:
      contentType13,

    provider:
      VOICE_TTS_PROVIDER_13
  };
}

/* ------------------------------------------------------------
   13.20 - TTS ADAPTER
------------------------------------------------------------ */

async function voice13Synthesize(
  text13,
  options13 = {}
) {
  const provider13 =
    voice13SafeString(
      options13.provider ||
      VOICE_TTS_PROVIDER_13,
      "generic"
    ).toLowerCase();

  if (
    provider13 ===
      "generic" ||
    provider13 ===
      "openai-compatible" ||
    provider13 ===
      "openai"
  ) {
    return voice13TTSGeneric(
      text13,
      options13
    );
  }

  return voice13TTSGeneric(
    text13,
    options13
  );
}

/* ------------------------------------------------------------
   13.21 - STT JOB EXECUTION
------------------------------------------------------------ */

async function voice13RunSTTJob(
  job13
) {
  const inputPath13 =
    voice13SafeString(
      job13.input?.path,
      ""
    );

  if (
    !inputPath13 ||
    !fs13.existsSync(
      inputPath13
    )
  ) {
    throw new Error(
      "STT giriş ses dosyası bulunamadı."
    );
  }

  voice13UpdateJob(
    job13.id,
    {
      status:
        "processing",

      progress:
        10,

      startedAt:
        nowISO()
    }
  );

  try {
    const result13 =
      await voice13Transcribe(
        inputPath13,
        job13.options
      );

    voice13UpdateJob(
      job13.id,
      {
        progress:
          80
      }
    );

    const finalText13 =
      voice13SafeString(
        result13.text,
        ""
      );

    if (
      !finalText13
    ) {
      throw new Error(
        "Transkripsiyon boş geldi."
      );
    }

    voice13IncrementUsage(
      job13.userId,
      "stt"
    );

    const complete13 =
      voice13UpdateJob(
        job13.id,
        {
          status:
            "completed",

          progress:
            100,

          result: {
            text:
              finalText13,

            language:
              result13.language ||
              VOICE_CONFIG_13.defaultLanguage,

            duration:
              result13.duration ||
              0,

            segments:
              result13.segments ||
              []
          },

          completedAt:
            nowISO()
        }
      );

    voice13AppendHistory({
      type:
        "stt_completed",

      userId:
        job13.userId,

      jobId:
        job13.id,

      textLength:
        finalText13.length
    });

    return complete13;
  } catch (error13) {
    const failed13 =
      voice13UpdateJob(
        job13.id,
        {
          status:
            "failed",

          progress:
            0,

          error:
            error13?.message ||
            String(error13),

          completedAt:
            nowISO()
        }
      );

    voice13AppendHistory({
      type:
        "stt_failed",

      userId:
        job13.userId,

      jobId:
        job13.id,

      error:
        error13?.message ||
        String(error13)
    });

    return failed13;
  }
}

/* ------------------------------------------------------------
   13.22 - TTS JOB EXECUTION
------------------------------------------------------------ */

async function voice13RunTTSJob(
  job13
) {
  const text13 =
    voice13SafeString(
      job13.input?.text,
      ""
    );

  if (
    !text13
  ) {
    throw new Error(
      "TTS metni boş."
    );
  }

  voice13UpdateJob(
    job13.id,
    {
      status:
        "processing",

      progress:
        10,

      startedAt:
        nowISO()
    }
  );

  try {
    const options13 =
      job13.options ||
      {};

    const cacheKey13 =
      voice13CacheKey({
        text13,

        voice13:
          options13.voice ||
          VOICE_CONFIG_13.defaultVoice,

        language13:
          options13.language ||
          VOICE_CONFIG_13.defaultLanguage,

        format13:
          options13.format ||
          VOICE_CONFIG_13.defaultFormat
      });

    const cached13 =
      voice13GetCached(
        cacheKey13
      );

    if (
      cached13
    ) {
      const stat13 =
        fs13.statSync(
          cached13.path
        );

      const asset13 =
        voice13CreateAsset({
          userId13:
            job13.userId,

          type13:
            "tts",

          jobId13:
            job13.id,

          filePath13:
            cached13.path,

          mimeType13:
            cached13.mimeType,

          size13:
            stat13.size,

          language13:
            options13.language ||
            VOICE_CONFIG_13.defaultLanguage,

          metadata13: {
            cached:
              true,

            cacheKey:
              cacheKey13
          }
        });

      voice13IncrementUsage(
        job13.userId,
        "tts"
      );

      return voice13UpdateJob(
        job13.id,
        {
          status:
            "completed",

          progress:
            100,

          result: {
            assetId:
              asset13.id,

            url:
              asset13.url,

            cached:
              true
          },

          completedAt:
            nowISO()
        }
      );
    }

    const result13 =
      await voice13Synthesize(
        text13,
        options13
      );

    voice13UpdateJob(
      job13.id,
      {
        progress:
          75
      }
    );

    let buffer13 =
      null;

    let mimeType13 =
      result13.mimeType ||
      voice13Mime(
        options13.format ||
        VOICE_CONFIG_13.defaultFormat
      );

    if (
      result13.mode ===
        "buffer" &&
      Buffer.isBuffer(
        result13.buffer
      )
    ) {
      buffer13 =
        result13.buffer;
    } else if (
      result13.mode ===
        "url" &&
      result13.url
    ) {
      const downloaded13 =
        await voice13FetchBinary(
          result13.url
        );

      buffer13 =
        downloaded13.buffer;

      mimeType13 =
        downloaded13.contentType ||
        mimeType13;
    }

    if (
      !Buffer.isBuffer(
        buffer13
      ) ||
      buffer13.length ===
        0
    ) {
      throw new Error(
        "TTS provider ses çıktısı döndürmedi."
      );
    }

    const extension13 =
      voice13ExtensionFromMime(
        mimeType13,
        options13.format ||
        "mp3"
      );

    const fileName13 =
      `${job13.id}.${extension13}`;

    const filePath13 =
      path13.join(
        VOICE_OUTPUT_13,
        fileName13
      );

    fs13.writeFileSync(
      filePath13,
      buffer13
    );

    voice13SaveCache(
      cacheKey13,
      {
        path:
          filePath13,

        mimeType:
          mimeType13,

        textLength:
          text13.length
      }
    );

    const asset13 =
      voice13CreateAsset({
        userId13:
          job13.userId,

        type13:
          "tts",

        jobId13:
          job13.id,

        filePath13:
          filePath13,

        mimeType13:
          mimeType13,

        size13:
          buffer13.length,

        language13:
          options13.language ||
          VOICE_CONFIG_13.defaultLanguage,

        metadata13: {
          cached:
            false,

          textLength:
            text13.length
        }
      });

    voice13IncrementUsage(
      job13.userId,
      "tts"
    );

    const complete13 =
      voice13UpdateJob(
        job13.id,
        {
          status:
            "completed",

          progress:
            100,

          result: {
            assetId:
              asset13.id,

            url:
              asset13.url,

            mimeType:
              asset13.mimeType,

            size:
              asset13.size,

            cached:
              false
          },

          completedAt:
            nowISO()
        }
      );

    voice13AppendHistory({
      type:
        "tts_completed",

      userId:
        job13.userId,

      jobId:
        job13.id,

      assetId:
        asset13.id,

      textLength:
        text13.length
    });

    return complete13;
  } catch (error13) {
    const failed13 =
      voice13UpdateJob(
        job13.id,
        {
          status:
            "failed",

          progress:
            0,

          error:
            error13?.message ||
            String(error13),

          completedAt:
            nowISO()
        }
      );

    voice13AppendHistory({
      type:
        "tts_failed",

      userId:
        job13.userId,

      jobId:
        job13.id,

      error:
        error13?.message ||
        String(error13)
    });

    return failed13;
  }
}

/* ------------------------------------------------------------
   13.23 - VOICE WORKER
------------------------------------------------------------ */

const VOICE_WORKER_13 = {
  running:
    false,

  activeJobs:
    0,

  processed:
    0,

  failed:
    0,

  startedAt:
    null,

  lastRunAt:
    null
};

function voice13PickNextJob() {
  const jobs13 =
    voice13GetJobs();

  return Object.values(
    jobs13
  )
    .filter(
      (job13) =>
        job13 &&
        job13.status ===
          "queued"
    )
    .sort(
      (a13, b13) =>
        String(
          a13.createdAt ||
          ""
        ).localeCompare(
          String(
            b13.createdAt ||
            ""
          )
        )
    )[0] ||
    null;
}

async function voice13WorkerTick() {
  if (
    VOICE_WORKER_13.running
  ) {
    return;
  }

  VOICE_WORKER_13.running =
    true;

  VOICE_WORKER_13.startedAt =
    VOICE_WORKER_13.startedAt ||
    nowISO();

  try {
    const job13 =
      voice13PickNextJob();

    if (
      !job13
    ) {
      return;
    }

    VOICE_WORKER_13.activeJobs =
      1;

    if (
      job13.type ===
      "stt"
    ) {
      await voice13RunSTTJob(
        job13
      );
    } else if (
      job13.type ===
      "tts"
    ) {
      await voice13RunTTSJob(
        job13
      );
    } else {
      voice13UpdateJob(
        job13.id,
        {
          status:
            "failed",

          error:
            "Bilinmeyen voice job türü."
        }
      );

      VOICE_WORKER_13.failed +=
        1;
    }

    VOICE_WORKER_13.processed +=
      1;
  } catch (error13) {
    VOICE_WORKER_13.failed +=
      1;

    systemLog?.(
      "voice13_worker_error",
      {
        error:
          error13?.message ||
          String(error13)
      }
    );
  } finally {
    VOICE_WORKER_13.activeJobs =
      0;

    VOICE_WORKER_13.lastRunAt =
      nowISO();

    VOICE_WORKER_13.running =
      false;
  }
}

/* ------------------------------------------------------------
   13.24 - TEXT TO SPEECH QUEUE
------------------------------------------------------------ */

function voice13QueueTTS({
  userId13,
  text13,
  options13 = {}
}) {
  const normalized13 =
    voice13SafeString(
      text13,
      ""
    );

  if (
    !normalized13
  ) {
    throw new Error(
      "TTS metni boş olamaz."
    );
  }

  if (
    normalized13.length >
    VOICE_CONFIG_13.maxTextChars
  ) {
    throw new Error(
      `TTS metni en fazla ${VOICE_CONFIG_13.maxTextChars} karakter olabilir.`
    );
  }

  if (
    normalized13.length >
    VOICE_CONFIG_13.ttsMaxCharacters
  ) {
    throw new Error(
      `Tek TTS isteği en fazla ${VOICE_CONFIG_13.ttsMaxCharacters} karakter olabilir.`
    );
  }

  const quota13 =
    voice13CheckQuota(
      userId13,
      "tts"
    );

  if (
    !quota13.allowed
  ) {
    const error13 =
      new Error(
        quota13.limit ===
        0
          ? "TTS mevcut planda kapalı."
          : "Günlük TTS limitine ulaşıldı."
      );

    error13.quota =
      quota13;

    throw error13;
  }

  return voice13CreateJob({
    userId13,

    type13:
      "tts",

    input13: {
      text:
        normalized13
    },

    options13: {
      model:
        options13.model ||
        VOICE_TTS_MODEL_13,

      provider:
        options13.provider ||
        VOICE_TTS_PROVIDER_13,

      voice:
        options13.voice ||
        VOICE_CONFIG_13.defaultVoice,

      language:
        options13.language ||
        VOICE_CONFIG_13.defaultLanguage,

      format:
        options13.format ||
        VOICE_CONFIG_13.defaultFormat,

      speed:
        options13.speed ??
        1
    }
  });
}

/* ------------------------------------------------------------
   13.25 - SPEECH TO TEXT QUEUE
------------------------------------------------------------ */

function voice13QueueSTT({
  userId13,
  audioPath13,
  options13 = {}
}) {
  const quota13 =
    voice13CheckQuota(
      userId13,
      "stt"
    );

  if (
    !quota13.allowed
  ) {
    const error13 =
      new Error(
        quota13.limit ===
        0
          ? "STT mevcut planda kapalı."
          : "Günlük STT limitine ulaşıldı."
      );

    error13.quota =
      quota13;

    throw error13;
  }

  if (
    !audioPath13 ||
    !fs13.existsSync(
      audioPath13
    )
  ) {
    throw new Error(
      "Ses dosyası bulunamadı."
    );
  }

  const stat13 =
    fs13.statSync(
      audioPath13
    );

  if (
    stat13.size >
    VOICE_CONFIG_13.maxAudioBytes
  ) {
    throw new Error(
      "Ses dosyası çok büyük."
    );
  }

  return voice13CreateJob({
    userId13,

    type13:
      "stt",

    input13: {
      path:
        audioPath13
    },

    options13: {
      model:
        options13.model ||
        VOICE_STT_MODEL_13,

      provider:
        options13.provider ||
        VOICE_STT_PROVIDER_13,

      language:
        options13.language ||
        VOICE_CONFIG_13.defaultLanguage,

      prompt:
        options13.prompt ||
        "",

      responseFormat:
        options13.responseFormat ||
        "json"
    }
  });
}

/* ------------------------------------------------------------
   13.26 - INPUT AUDIO SAVE
------------------------------------------------------------ */

function voice13SaveInputBuffer({
  userId13,
  buffer13,
  extension13 = "webm"
}) {
  const validation13 =
    voice13ValidateBuffer(
      buffer13
    );

  if (
    !validation13.valid
  ) {
    throw new Error(
      validation13.reason
    );
  }

  const safeExt13 =
    voice13SafeString(
      extension13,
      "webm"
    )
      .replace(
        ".",
        ""
      )
      .toLowerCase();

  if (
    !VOICE_CONFIG_13.inputFormats.includes(
      safeExt13
    )
  ) {
    throw new Error(
      `Desteklenmeyen ses formatı: ${safeExt13}`
    );
  }

  const fileName13 =
    `input-${voice13ShortHash(
      `${userId13}:${Date.now()}:${Math.random()}`
    )}.${safeExt13}`;

  const filePath13 =
    path13.join(
      VOICE_INPUT_13,
      fileName13
    );

  fs13.writeFileSync(
    filePath13,
    buffer13
  );

  return {
    filePath:
      filePath13,

    fileName:
      fileName13,

    extension:
      safeExt13,

    size:
      buffer13.length,

    mimeType:
      voice13Mime(
        safeExt13
      )
  };
}

/* ------------------------------------------------------------
   13.27 - BASE64 INPUT SUPPORT
------------------------------------------------------------ */

function voice13DecodeBase64(
  input13
) {
  const raw13 =
    voice13SafeString(
      input13,
      ""
    );

  if (
    !raw13
  ) {
    throw new Error(
      "Base64 ses verisi boş."
    );
  }

  const match13 =
    raw13.match(
      /^data:([^;]+);base64,(.+)$/s
    );

  if (
    match13
  ) {
    return {
      mimeType:
        match13[1],

      buffer:
        Buffer.from(
          match13[2],
          "base64"
        )
    };
  }

  return {
    mimeType:
      "audio/webm",

    buffer:
      Buffer.from(
        raw13,
        "base64"
      )
  };
}

/* ------------------------------------------------------------
   13.28 - LIST JOBS
------------------------------------------------------------ */

function voice13ListJobs({
  userId13 = "guest",
  type13 = null,
  status13 = null,
  limit13 = 50
} = {}) {
  const jobs13 =
    voice13GetJobs();

  let items13 =
    Object.values(
      jobs13
    )
      .filter(
        (job13) =>
          job13 &&
          job13.userId ===
            userId13
      );

  if (
    type13
  ) {
    items13 =
      items13.filter(
        (job13) =>
          job13.type ===
          type13
      );
  }

  if (
    status13
  ) {
    items13 =
      items13.filter(
        (job13) =>
          job13.status ===
          status13
      );
  }

  items13.sort(
    (a13, b13) =>
      String(
        b13.createdAt ||
        ""
      ).localeCompare(
        String(
          a13.createdAt ||
          ""
        )
      )
  );

  const safeLimit13 =
    clamp(
      toInteger(
        limit13,
        50
      ),
      1,
      200
    );

  return {
    items:
      items13.slice(
        0,
        safeLimit13
      ),

    total:
      items13.length
  };
}

