/* ------------------------------------------------------------
   13.30 - ASSET GET
------------------------------------------------------------ */

function voice13GetAsset(
  assetId13,
  userId13
) {
  const assets13 =
    voice13GetAssets();

  const asset13 =
    assets13[
      voice13SafeId(
        assetId13
      )
    ];

  if (
    !asset13
  ) {
    return null;
  }

  if (
    asset13.userId !==
    userId13
  ) {
    return null;
  }

  return asset13;
}

/* ------------------------------------------------------------
   13.31 - DELETE ASSET
------------------------------------------------------------ */

function voice13DeleteAsset(
  assetId13,
  userId13
) {
  const assets13 =
    voice13GetAssets();

  const safeId13 =
    voice13SafeId(
      assetId13
    );

  const asset13 =
    assets13[
      safeId13
    ];

  if (
    !asset13
  ) {
    throw new Error(
      "Ses asset'i bulunamadı."
    );
  }

  if (
    asset13.userId !==
    userId13
  ) {
    throw new Error(
      "Bu ses dosyasına erişim izni yok."
    );
  }

  try {
    if (
      asset13.path &&
      fs13.existsSync(
        asset13.path
      )
    ) {
      fs13.unlinkSync(
        asset13.path
      );
    }
  } catch (_) {}

  delete assets13[
    safeId13
  ];

  voice13SaveAssets(
    assets13
  );

  voice13AppendHistory({
    type:
      "asset_deleted",

    userId:
      userId13,

    assetId:
      safeId13
  });

  return {
    success:
      true,

    assetId:
      safeId13
  };
}

/* ------------------------------------------------------------
   13.32 - STATUS
------------------------------------------------------------ */

function voice13Status() {
  const jobs13 =
    voice13GetJobs();

  const assets13 =
    voice13GetAssets();

  const jobValues13 =
    Object.values(
      jobs13
    );

  return {
    success:
      true,

    module:
      "voice-engine",

    version:
      VOICE_CONFIG_13.version,

    enabled:
      VOICE_CONFIG_13.enabled,

    providers: {
      stt:
        VOICE_STT_PROVIDER_13,

      tts:
        VOICE_TTS_PROVIDER_13,

      sttConfigured:
        Boolean(
          VOICE_STT_API_URL_13
        ),

      ttsConfigured:
        Boolean(
          VOICE_TTS_API_URL_13
        )
    },

    jobs: {
      total:
        jobValues13.length,

      queued:
        jobValues13.filter(
          (job13) =>
            job13.status ===
            "queued"
        ).length,

      processing:
        jobValues13.filter(
          (job13) =>
            job13.status ===
            "processing"
        ).length,

      completed:
        jobValues13.filter(
          (job13) =>
            job13.status ===
            "completed"
        ).length,

      failed:
        jobValues13.filter(
          (job13) =>
            job13.status ===
            "failed"
        ).length
    },

    assets:
      Object.keys(
        assets13
      ).length,

    worker:
      clone(
        VOICE_WORKER_13
      ),

    checkedAt:
      nowISO()
  };
}

/* ------------------------------------------------------------
   13.33 - HTTP ERROR
------------------------------------------------------------ */

function voice13Error(
  res13,
  status13,
  message13,
  extra13 = {}
) {
  return res13
    .status(
      status13
    )
    .json({
      success:
        false,

      error:
        voice13SafeString(
          message13,
          "Voice işlemi başarısız."
        ),

      ...extra13
    });
}

/* ------------------------------------------------------------
   13.34 - TTS API
------------------------------------------------------------ */

app.post(
  "/api/voice/tts",
  (req13, res13) => {
    try {
      const userId13 =
        voice13UserId(
          req13
        );

      const body13 =
        req13.body ||
        {};

      const job13 =
        voice13QueueTTS({
          userId13,

          text13:
            body13.text ||
            body13.input ||
            "",

          options13: {
            model:
              body13.model ||
              VOICE_TTS_MODEL_13,

            provider:
              body13.provider ||
              VOICE_TTS_PROVIDER_13,

            voice:
              body13.voice ||
              VOICE_CONFIG_13.defaultVoice,

            language:
              body13.language ||
              VOICE_CONFIG_13.defaultLanguage,

            format:
              body13.format ||
              VOICE_CONFIG_13.defaultFormat,

            speed:
              body13.speed ??
              1
          }
        });

      res13.status(
        202
      ).json({
        success:
          true,

        queued:
          true,

        job:
          job13,

        quota:
          voice13CheckQuota(
            userId13,
            "tts"
          )
      });

      setImmediate(
        () =>
          voice13WorkerTick()
      );
    } catch (error13) {
      voice13Error(
        res13,
        error13?.quota
          ? 429
          : 400,

        error13?.message ||
          String(error13),

        {
          quota:
            error13?.quota ||
            null
        }
      );
    }
  }
);

/* ------------------------------------------------------------
   13.35 - STT FROM BASE64
------------------------------------------------------------ */

app.post(
  "/api/voice/stt",
  (req13, res13) => {
    try {
      const userId13 =
        voice13UserId(
          req13
        );

      const body13 =
        req13.body ||
        {};

      const decoded13 =
        voice13DecodeBase64(
          body13.audio ||
          body13.audioBase64 ||
          ""
        );

      const ext13 =
        voice13ExtensionFromMime(
          decoded13.mimeType,
          body13.extension ||
            "webm"
        );

      const saved13 =
        voice13SaveInputBuffer({
          userId13,

          buffer13:
            decoded13.buffer,

          extension13:
            ext13
        });

      const job13 =
        voice13QueueSTT({
          userId13,

          audioPath13:
            saved13.filePath,

          options13: {
            model:
              body13.model ||
              VOICE_STT_MODEL_13,

            provider:
              body13.provider ||
              VOICE_STT_PROVIDER_13,

            language:
              body13.language ||
              VOICE_CONFIG_13.defaultLanguage,

            prompt:
              body13.prompt ||
              "",

            responseFormat:
              "json"
          }
        });

      res13.status(
        202
      ).json({
        success:
          true,

        queued:
          true,

        input: {
          filename:
            saved13.fileName,

          mimeType:
            saved13.mimeType,

          size:
            saved13.size
        },

        job:
          job13,

        quota:
          voice13CheckQuota(
            userId13,
            "stt"
          )
      });

      setImmediate(
        () =>
          voice13WorkerTick()
      );
    } catch (error13) {
      voice13Error(
        res13,
        error13?.quota
          ? 429
          : 400,

        error13?.message ||
          String(error13),

        {
          quota:
            error13?.quota ||
            null
        }
      );
    }
  }
);

/* ------------------------------------------------------------
   13.36 - STT FROM FILE PATH
   Internal/admin integrations can use this endpoint.
------------------------------------------------------------ */

app.post(
  "/api/voice/stt/file",
  (req13, res13) => {
    try {
      const userId13 =
        voice13UserId(
          req13
        );

      const body13 =
        req13.body ||
        {};

      const filePath13 =
        voice13SafeString(
          body13.path ||
          body13.filePath,
          ""
        );

      if (
        !filePath13
      ) {
        return voice13Error(
          res13,
          400,
          "Ses dosyası yolu gerekli."
        );
      }

      const resolved13 =
        path13.resolve(
          filePath13
        );

      const root13 =
        path13.resolve(
          VOICE_INPUT_13
        );

      if (
        resolved13 !== root13 &&
        !resolved13.startsWith(
          `${root13}${path13.sep}`
        )
      ) {
        return voice13Error(
          res13,
          403,
          "Bu ses dosyasına erişim izni yok."
        );
      }

      const job13 =
        voice13QueueSTT({
          userId13,

          audioPath13:
            resolved13,

          options13: {
            model:
              body13.model ||
              VOICE_STT_MODEL_13,

            provider:
              body13.provider ||
              VOICE_STT_PROVIDER_13,

            language:
              body13.language ||
              VOICE_CONFIG_13.defaultLanguage,

            prompt:
              body13.prompt ||
              ""
          }
        });

      res13.status(
        202
      ).json({
        success:
          true,

        queued:
          true,

        job:
          job13
      });

      setImmediate(
        () =>
          voice13WorkerTick()
      );
    } catch (error13) {
      voice13Error(
        res13,
        error13?.quota
          ? 429
          : 400,

        error13?.message ||
          String(error13)
      );
    }
  }
);

