/* ------------------------------------------------------------
   13.39 - CANCEL JOB
------------------------------------------------------------ */

app.post(
  "/api/voice/jobs/:jobId/cancel",
  (req13, res13) => {
    try {
      const userId13 =
        voice13UserId(
          req13
        );

      const job13 =
        voice13GetJob(
          req13.params.jobId,
          userId13
        );

      if (
        !job13
      ) {
        return voice13Error(
          res13,
          404,
          "Voice görevi bulunamadı."
        );
      }

      if (
        job13.status !==
        "queued"
      ) {
        return voice13Error(
          res13,
          409,
          "Sadece kuyruğa alınmış görevler iptal edilebilir."
        );
      }

      const updated13 =
        voice13UpdateJob(
          job13.id,
          {
            status:
              "cancelled",

            completedAt:
              nowISO()
          }
        );

      voice13AppendHistory({
        type:
          "job_cancelled",

        userId:
          userId13,

        jobId:
          job13.id
      });

      res13.json({
        success:
          true,

        job:
          updated13
      });
    } catch (error13) {
      voice13Error(
        res13,
        500,
        error13.message
      );
    }
  }
);

