/* ------------------------------------------------------------
   13.42 - ASSET DOWNLOAD
------------------------------------------------------------ */

app.get(
  "/api/voice/assets/:assetId/download",
  (req13, res13) => {
    try {
      const asset13 =
        voice13GetAsset(
          req13.params.assetId,
          voice13UserId(
            req13
          )
        );

      if (
        !asset13
      ) {
        return voice13Error(
          res13,
          404,
          "Ses asset'i bulunamadı."
        );
      }

      if (
        !asset13.path ||
        !fs13.existsSync(
          asset13.path
        )
      ) {
        return voice13Error(
          res13,
          404,
          "Ses dosyası mevcut değil."
        );
      }

      const stat13 =
        fs13.statSync(
          asset13.path
        );

      res13.setHeader(
        "Content-Type",
        asset13.mimeType ||
          voice13Mime(
            asset13.extension
          )
      );

      res13.setHeader(
        "Content-Length",
        String(
          stat13.size
        )
      );

      res13.setHeader(
        "Content-Disposition",
        `inline; filename="${encodeURIComponent(
          asset13.filename
        )}"`
      );

      fs13.createReadStream(
        asset13.path
      ).pipe(
        res13
      );
    } catch (error13) {
      voice13Error(
        res13,
        500,
        error13.message
      );
    }
  }
);

