/* ------------------------------------------------------------
   13.49 - SOCKET.IO EVENTS
------------------------------------------------------------ */

if (
  typeof io !==
    "undefined" &&
  io
) {
  io.on(
    "connection",
    (
      socket13
    ) => {
      socket13.on(
        "voice:job",
        (
          payload13 = {}
        ) => {
          try {
            const userId13 =
              normalizeUserId(
                payload13.userId ||
                socket13.userId ||
                "guest"
              );

            const job13 =
              voice13GetJob(
                payload13.jobId,
                userId13
              );

            if (
              !job13
            ) {
              socket13.emit(
                "voice:error",
                {
                  error:
                    "Voice görevi bulunamadı."
                }
              );

              return;
            }

            socket13.emit(
              "voice:job:result",
              {
                success:
                  true,

                job:
                  job13
              }
            );
          } catch (error13) {
            socket13.emit(
              "voice:error",
              {
                error:
                  error13?.message ||
                  String(error13)
              }
            );
          }
        }
      );

      socket13.on(
        "voice:quota",
        (
          payload13 = {}
        ) => {
          try {
            const userId13 =
              normalizeUserId(
                payload13.userId ||
                socket13.userId ||
                "guest"
              );

            socket13.emit(
              "voice:quota:result",
              {
                success:
                  true,

                plan:
                  voice13ResolvePlan(
                    userId13
                  ),

                stt:
                  voice13CheckQuota(
                    userId13,
                    "stt"
                  ),

                tts:
                  voice13CheckQuota(
                    userId13,
                    "tts"
                  )
              }
            );
          } catch (error13) {
            socket13.emit(
              "voice:error",
              {
                error:
                  error13?.message ||
                  String(error13)
              }
            );
          }
        }
      );
    }
  );
}

