/* ------------------------------------------------------------
   13.51 - CLEANUP OLD TEMP / INPUT FILES
------------------------------------------------------------ */

function voice13CleanupTempFiles() {
  const roots13 = [
    VOICE_TEMP_13,
    VOICE_INPUT_13
  ];

  const cutoff13 =
    Date.now() -
    24 *
      60 *
      60 *
      1000;

  let removed13 =
    0;

  for (
    const root13 of
    roots13
  ) {
    try {
      const files13 =
        fs13.readdirSync(
          root13
        );

      for (
        const name13 of
        files13
      ) {
        const fullPath13 =
          path13.join(
            root13,
            name13
          );

        try {
          const stat13 =
            fs13.statSync(
              fullPath13
            );

          if (
            stat13.mtimeMs <
            cutoff13
          ) {
            fs13.unlinkSync(
              fullPath13
            );

            removed13 +=
              1;
          }
        } catch (_) {}
      }
    } catch (_) {}
  }

  return {
    success:
      true,

    removed:
      removed13
  };
}

const VOICE_CLEANUP_TIMER_13 =
  setInterval(
    () => {
      try {
        voice13CleanupTempFiles();
      } catch (error13) {
        systemLog?.(
          "voice13_cleanup_error",
          {
            error:
              error13?.message ||
              String(error13)
          }
        );
      }
    },
    30 * 60 * 1000
  );

if (
  VOICE_CLEANUP_TIMER_13?.unref
) {
  VOICE_CLEANUP_TIMER_13.unref();
}

/* ------------------------------------------------------------
   13.52 - OLD USAGE CLEANUP
------------------------------------------------------------ */

function voice13CleanupUsage() {
  const usage13 =
    voice13GetUsage();

  const cutoff13 =
    Date.now() -
    60 *
      24 *
      60 *
      60 *
      1000;

  for (
    const type13 of [
      "stt",
      "tts"
    ]
  ) {
    if (
      !usage13[
        type13
      ]
    ) {
      continue;
    }

    for (
      const userId13 of
      Object.keys(
        usage13[
          type13
        ]
      )
    ) {
      const days13 =
        usage13[
          type13
        ][
          userId13
        ];

      for (
        const day13 of
        Object.keys(
          days13
        )
      ) {
        const timestamp13 =
          new Date(
            `${day13}T00:00:00.000Z`
          ).getTime();

        if (
          Number.isFinite(
            timestamp13
          ) &&
          timestamp13 <
            cutoff13
        ) {
          delete days13[
            day13
          ];
        }
      }
    }
  }

  usage13.updatedAt =
    nowISO();

  voice13WriteJSON(
    VOICE_USAGE_STORE_13,
    usage13
  );
}

const VOICE_USAGE_CLEANUP_TIMER_13 =
  setInterval(
    () => {
      try {
        voice13CleanupUsage();
      } catch (error13) {
        systemLog?.(
          "voice13_usage_cleanup_error",
          {
            error:
              error13?.message ||
              String(error13)
          }
        );
      }
    },
    6 * 60 * 60 * 1000
  );

if (
  VOICE_USAGE_CLEANUP_TIMER_13?.unref
) {
  VOICE_USAGE_CLEANUP_TIMER_13.unref();
}

