/* ------------------------------------------------------------
   14.4 - JSON HELPERS
------------------------------------------------------------ */

function notification14ReadJSON(
  filePath14,
  fallback14
) {
  try {
    if (
      !fs14.existsSync(
        filePath14
      )
    ) {
      return fallback14;
    }

    const raw14 =
      fs14.readFileSync(
        filePath14,
        "utf8"
      );

    if (
      !raw14.trim()
    ) {
      return fallback14;
    }

    return JSON.parse(
      raw14
    );
  } catch (error14) {
    systemLog?.(
      "notification14_read_error",
      {
        file:
          filePath14,

        error:
          error14?.message ||
          String(
            error14
          )
      }
    );

    return fallback14;
  }
}

function notification14WriteJSON(
  filePath14,
  value14
) {
  try {
    fs14.mkdirSync(
      path14.dirname(
        filePath14
      ),
      {
        recursive:
          true
      }
    );

    const temp14 =
      `${filePath14}.${process.pid}.${Date.now()}.tmp`;

    fs14.writeFileSync(
      temp14,
      JSON.stringify(
        value14,
        null,
        2
      ),
      "utf8"
    );

    fs14.renameSync(
      temp14,
      filePath14
    );

    return true;
  } catch (error14) {
    systemLog?.(
      "notification14_write_error",
      {
        file:
          filePath14,

        error:
          error14?.message ||
          String(
            error14
          )
      }
    );

    return false;
  }
}

/* ------------------------------------------------------------
   14.5 - BASIC HELPERS
------------------------------------------------------------ */

function notification14SafeString(
  value14,
  fallback14 = ""
) {
  return safeString(
    value14,
    fallback14
  )
    .normalize("NFKC")
    .replace(
      /\u0000/g,
      ""
    )
    .trim();
}

function notification14SafeId(
  value14,
  fallback14 = ""
) {
  return notification14SafeString(
    value14,
    fallback14
  )
    .replace(
      /[^a-zA-Z0-9_\-:.]/g,
      "-"
    )
    .replace(
      /-+/g,
      "-"
    )
    .replace(
      /^-+|-+$/g,
      ""
    )
    .slice(
      0,
      180
    );
}

function notification14UserId(
  req14
) {
  return normalizeUserId(
    notification14SafeString(
      req14?.user?.id ||
      req14?.body?.userId ||
      req14?.query?.userId ||
      "guest"
    )
  );
}

function notification14Hash(
  value14
) {
  return crypto14
    .createHash(
      "sha256"
    )
    .update(
      Buffer.from(
        notification14SafeString(
          value14,
          ""
        ),
        "utf8"
      )
    )
    .digest("hex");
}

function notification14ShortHash(
  value14
) {
  return notification14Hash(
    value14
  ).slice(
    0,
    18
  );
}

function notification14Now() {
  return nowISO();
}

/* ------------------------------------------------------------
   14.6 - EVENT BUS
------------------------------------------------------------ */

const TURKAI_EVENT_BUS_14 =
  new EventEmitter14();

TURKAI_EVENT_BUS_14.setMaxListeners(
  200
);

function notification14EmitEvent(
  eventName14,
  payload14 = {}
) {
  const event14 = {
    id:
      `evt-${notification14ShortHash(
        `${eventName14}:${Date.now()}:${Math.random()}`
      )}`,

    name:
      notification14SafeString(
        eventName14,
        "unknown"
      ).slice(
        0,
        150
      ),

    timestamp:
      notification14Now(),

    payload:
      isObject(
        payload14
      )
        ? clone(
            payload14
          )
        : {}
  };

  TURKAI_EVENT_BUS_14.emit(
    "event",
    event14
  );

  TURKAI_EVENT_BUS_14.emit(
    event14.name,
    event14
  );

  notification14StoreEvent(
    event14
  );

  return event14;
}

/* ------------------------------------------------------------
   14.7 - EVENT HISTORY
------------------------------------------------------------ */

function notification14GetEvents() {
  return notification14ReadJSON(
    NOTIFICATION_EVENT_STORE_14,
    []
  );
}

function notification14StoreEvent(
  event14
) {
  try {
    const events14 =
      notification14GetEvents();

    events14.push(
      event14
    );

    if (
      events14.length >
      NOTIFICATION_CONFIG_14.maxEvents
    ) {
      events14.splice(
        0,
        events14.length -
          NOTIFICATION_CONFIG_14.maxEvents
      );
    }

    notification14WriteJSON(
      NOTIFICATION_EVENT_STORE_14,
      events14
    );
  } catch (error14) {
    systemLog?.(
      "notification14_event_store_error",
      {
        error:
          error14?.message ||
          String(
            error14
          )
      }
    );
  }
}

function notification14ListEvents({
  name14 = null,
  limit14 = 100
} = {}) {
  let events14 =
    notification14GetEvents();

  if (
    name14
  ) {
    const normalizedName14 =
      notification14SafeString(
        name14,
        ""
      );

    events14 =
      events14.filter(
        (event14) =>
          event14.name ===
          normalizedName14
      );
  }

  events14.sort(
    (a14, b14) =>
      String(
        b14.timestamp ||
        ""
      ).localeCompare(
        String(
          a14.timestamp ||
          ""
        )
      )
  );

  return {
    items:
      events14.slice(
        0,
        clamp(
          toInteger(
            limit14,
            100
          ),
          1,
          500
        )
      ),

    total:
      events14.length
  };
}

/* ------------------------------------------------------------
   14.8 - NOTIFICATION STORE
------------------------------------------------------------ */

function notification14GetStore() {
  return notification14ReadJSON(
    NOTIFICATION_MASTER_STORE_14,
    {}
  );
}

function notification14SaveStore(
  store14
) {
  const keys14 =
    Object.keys(
      store14
    );

  if (
    keys14.length >
    NOTIFICATION_CONFIG_14.maxNotifications
  ) {
    keys14.sort(
      (a14, b14) =>
        String(
          store14[a14]?.createdAt ||
          ""
        ).localeCompare(
          String(
            store14[b14]?.createdAt ||
            ""
          )
        )
    );

    const deleteCount14 =
      keys14.length -
      NOTIFICATION_CONFIG_14.maxNotifications;

    for (
      const oldId14 of
      keys14.slice(
        0,
        deleteCount14
      )
    ) {
      delete store14[
        oldId14
      ];
    }
  }

  return notification14WriteJSON(
    NOTIFICATION_MASTER_STORE_14,
    store14
  );
}

/* ------------------------------------------------------------
   14.9 - PER USER DIRECTORY
------------------------------------------------------------ */

function notification14UserFile(
  userId14
) {
  const safeUser14 =
    notification14SafeId(
      userId14,
      "guest"
    );

  return path14.join(
    NOTIFICATION_USER_14,
    `${safeUser14}.json`
  );
}

function notification14GetUserCache(
  userId14
) {
  return notification14ReadJSON(
    notification14UserFile(
      userId14
    ),
    {
      userId:
        userId14,

      items: [],

      unread:
        0,

      updatedAt:
        notification14Now()
    }
  );
}

function notification14SaveUserCache(
  userId14,
  cache14
) {
  cache14.userId =
    userId14;

  cache14.updatedAt =
    notification14Now();

  return notification14WriteJSON(
    notification14UserFile(
      userId14
    ),
    cache14
  );
}

/* ------------------------------------------------------------
   14.10 - PREFERENCES
------------------------------------------------------------ */

function notification14GetAllPreferences() {
  return notification14ReadJSON(
    NOTIFICATION_PREFERENCE_STORE_14,
    {}
  );
}

function notification14DefaultPreferences() {
  return {
    ...NOTIFICATION_CONFIG_14
      .defaultPreferences
  };
}

function notification14GetPreferences(
  userId14
) {
  const all14 =
    notification14GetAllPreferences();

  return {
    ...notification14DefaultPreferences(),

    ...(isObject(
      all14[
        userId14
      ]
    )
      ? all14[
          userId14
        ]
      : {})
  };
}

function notification14SavePreferences(
  userId14,
  preferences14
) {
  const all14 =
    notification14GetAllPreferences();

  all14[
    userId14
  ] = {
    ...notification14DefaultPreferences(),

    ...(isObject(
      preferences14
    )
      ? preferences14
      : {})
  };

  notification14WriteJSON(
    NOTIFICATION_PREFERENCE_STORE_14,
    all14
  );

  return all14[
    userId14
  ];
}

function notification14TypeEnabled(
  userId14,
  type14
) {
  const preferences14 =
    notification14GetPreferences(
      userId14
    );

  if (
    preferences14.enabled ===
    false
  ) {
    return false;
  }

  const typeKey14 =
    notification14SafeString(
      type14,
      "system"
    );

  if (
    Object.prototype.hasOwnProperty.call(
      preferences14,
      typeKey14
    )
  ) {
    return (
      preferences14[
        typeKey14
      ] !== false
    );
  }

  return true;
}

/* ------------------------------------------------------------
   14.11 - NOTIFICATION MODEL
------------------------------------------------------------ */

function notification14Create({
  userId14 = "guest",
  type14 = "info",
  title14 = "TürkAI",
  body14 = "",
  priority14 = "normal",
  link14 = "",
  icon14 = "",
  payload14 = {},
  source14 = "system",
  persistent14 = true,
  expiresAt14 = null,
  dedupeKey14 = null
} = {}) {
  const safeUser14 =
    notification14SafeString(
      userId14,
      "guest"
    );

  const safeType14 =
    notification14SafeString(
      type14,
      "info"
    );

  if (
    !NOTIFICATION_CONFIG_14.supportedTypes.includes(
      safeType14
    )
  ) {
    throw new Error(
      `Desteklenmeyen bildirim türü: ${safeType14}`
    );
  }

  if (
    !notification14TypeEnabled(
      safeUser14,
      safeType14
    )
  ) {
    return {
      suppressed:
        true,

      reason:
        "Kullanıcı bildirim tercihi nedeniyle engellendi."
    };
  }

  const safeTitle14 =
    notification14SafeString(
      title14,
      "TürkAI"
    ).slice(
      0,
      NOTIFICATION_CONFIG_14.maxTitleChars
    );

  const safeBody14 =
    notification14SafeString(
      body14,
      ""
    ).slice(
      0,
      NOTIFICATION_CONFIG_14.maxBodyChars
    );

  let cleanPayload14 =
    isObject(
      payload14
    )
      ? clone(
          payload14
        )
      : {};

  try {
    const payloadString14 =
      JSON.stringify(
        cleanPayload14
      );

    if (
      Buffer.byteLength(
        payloadString14,
        "utf8"
      ) >
      NOTIFICATION_CONFIG_14.maxPayloadBytes
    ) {
      cleanPayload14 = {
        truncated:
          true,

        preview:
          payloadString14.slice(
            0,
            5000
          )
      };
    }
  } catch (_) {
    cleanPayload14 = {};
  }

  const dedupe14 =
    dedupeKey14
      ? notification14SafeString(
          dedupeKey14,
          ""
        ).slice(
          0,
          300
        )
      : null;

  const store14 =
    notification14GetStore();

  if (
    dedupe14
  ) {
    const existing14 =
      Object.values(
        store14
      )
      .find(
        (item14) =>
          item14 &&
          item14.userId ===
            safeUser14 &&
          item14.dedupeKey ===
            dedupe14 &&
          !item14.read &&
          (
            !item14.expiresAt ||
            new Date(
              item14.expiresAt
            ).getTime() >
              Date.now()
          )
      );

    if (
      existing14
    ) {
      return {
        suppressed:
          true,

        duplicate:
          true,

        notification:
          existing14
      };
    }
  }

  const notificationId14 =
    `ntf-${notification14ShortHash(
      `${safeUser14}:${safeType14}:${safeTitle14}:${Date.now()}:${Math.random()}`
    )}`;

  const notification14 = {
    id:
      notificationId14,

    userId:
      safeUser14,

    type:
      safeType14,

    title:
      safeTitle14,

    body:
      safeBody14,

    priority:
      notification14SafeString(
        priority14,
        "normal"
      ),

    link:
      notification14SafeString(
        link14,
        ""
      ).slice(
        0,
        NOTIFICATION_CONFIG_14.maxLinkChars
      ),

    icon:
      notification14SafeString(
        icon14,
        ""
      ).slice(
        0,
        120
      ),

    payload:
      cleanPayload14,

    source:
      notification14SafeString(
        source14,
        "system"
      ).slice(
        0,
        120
      ),

    persistent:
      Boolean(
        persistent14
      ),

    read:
      false,

    readAt:
      null,

    clicked:
      false,

    clickedAt:
      null,

    dedupeKey:
      dedupe14,

    expiresAt:
      expiresAt14
        ? new Date(
            expiresAt14
          ).toISOString()
        : null,

    createdAt:
      notification14Now(),

    updatedAt:
      notification14Now()
  };

  if (
    notification14.persistent
  ) {
    store14[
      notificationId14
    ] =
      notification14;

    notification14SaveStore(
      store14
    );
  }

  const userCache14 =
    notification14GetUserCache(
      safeUser14
    );

  userCache14.items =
    Array.isArray(
      userCache14.items
    )
      ? userCache14.items
      : [];

  userCache14.items.unshift(
    notification14
  );

  if (
    userCache14.items.length >
    500
  ) {
    userCache14.items.splice(
      500
    );
  }

  userCache14.unread =
    userCache14.items.filter(
      (item14) =>
        item14 &&
        item14.read === false
    ).length;

  notification14SaveUserCache(
    safeUser14,
    userCache14
  );

  notification14AppendHistory({
    action:
      "created",

    userId:
      safeUser14,

    notificationId:
      notificationId14,

    type:
      safeType14,

    source:
      notification14.source
  });

  notification14EmitRealtime(
    safeUser14,
    notification14
  );

  return {
    suppressed:
      false,

    notification:
      notification14
  };
}

/* ------------------------------------------------------------
   14.12 - HISTORY
------------------------------------------------------------ */

function notification14GetHistory() {
  return notification14ReadJSON(
    NOTIFICATION_HISTORY_STORE_14,
    []
  );
}

function notification14AppendHistory(
  event14
) {
  const history14 =
    notification14GetHistory();

  history14.push({
    id:
      `nh-${notification14ShortHash(
        `${Date.now()}:${Math.random()}`
      )}`,

    timestamp:
      notification14Now(),

    ...event14
  });

  if (
    history14.length >
    NOTIFICATION_CONFIG_14.maxHistory
  ) {
    history14.splice(
      0,
      history14.length -
        NOTIFICATION_CONFIG_14.maxHistory
    );
  }

  notification14WriteJSON(
    NOTIFICATION_HISTORY_STORE_14,
    history14
  );
}

/* ------------------------------------------------------------
   14.13 - REALTIME SOCKET DELIVERY
------------------------------------------------------------ */

function notification14EmitRealtime(
  userId14,
  notification14
) {
  try {
    if (
      typeof io ===
        "undefined" ||
      !io
    ) {
      return;
    }

    const room14 =
      `user:${userId14}`;

    io.to(
      room14
    ).emit(
      "notification:new",
      {
        success:
          true,

        notification:
          notification14
      }
    );

    io.emit(
      "turkai:event",
      {
        type:
          "notification",

        userId:
          userId14,

        notification:
          notification14
      }
    );
  } catch (error14) {
    systemLog?.(
      "notification14_realtime_error",
      {
        error:
          error14?.message ||
          String(
            error14
          )
      }
    );
  }
}

/* ------------------------------------------------------------
   14.14 - FIND / READ
------------------------------------------------------------ */

function notification14GetOne(
  userId14,
  notificationId14
) {
  const store14 =
    notification14GetStore();

  const safeId14 =
    notification14SafeId(
      notificationId14
    );

  const item14 =
    store14[
      safeId14
    ];

  if (
    !item14
  ) {
    return null;
  }

  if (
    item14.userId !==
    userId14
  ) {
    return null;
  }

  if (
    item14.expiresAt &&
    new Date(
      item14.expiresAt
    ).getTime() <=
      Date.now()
  ) {
    return null;
  }

  return item14;
}

function notification14MarkRead(
  userId14,
  notificationId14,
  clicked14 = false
) {
  const store14 =
    notification14GetStore();

  const safeId14 =
    notification14SafeId(
      notificationId14
    );

  const item14 =
    store14[
      safeId14
    ];

  if (
    !item14
  ) {
    throw new Error(
      "Bildirim bulunamadı."
    );
  }

  if (
    item14.userId !==
    userId14
  ) {
    throw new Error(
      "Bu bildirime erişim izni yok."
    );
  }

  item14.read =
    true;

  item14.readAt =
    notification14Now();

  if (
    clicked14
  ) {
    item14.clicked =
      true;

    item14.clickedAt =
      notification14Now();
  }

  item14.updatedAt =
    notification14Now();

  store14[
    safeId14
  ] =
    item14;

  notification14SaveStore(
    store14
  );

  notification14SyncUserCache(
    userId14
  );

  notification14AppendHistory({
    action:
      clicked14
        ? "clicked"
        : "read",

    userId:
      userId14,

    notificationId:
      safeId14
  });

  notification14EmitEvent(
    clicked14
      ? "notification.clicked"
      : "notification.read",
    {
      userId:
        userId14,

      notificationId:
        safeId14
    }
  );

  return item14;
}

/* ------------------------------------------------------------
   14.15 - UNREAD ALL
------------------------------------------------------------ */

function notification14UnreadCount(
  userId14
) {
  const store14 =
    notification14GetStore();

  return Object.values(
    store14
  ).filter(
    (item14) =>
      item14 &&
      item14.userId ===
        userId14 &&
      item14.read ===
        false &&
      (
        !item14.expiresAt ||
        new Date(
          item14.expiresAt
        ).getTime() >
          Date.now()
      )
  ).length;
}

function notification14MarkAllRead(
  userId14
) {
  const store14 =
    notification14GetStore();

  let changed14 =
    0;

  for (
    const id14 of
    Object.keys(
      store14
    )
  ) {
    const item14 =
      store14[
        id14
      ];

    if (
      !item14 ||
      item14.userId !==
        userId14 ||
      item14.read
    ) {
      continue;
    }

    item14.read =
      true;

    item14.readAt =
      notification14Now();

    item14.updatedAt =
      notification14Now();

    changed14 +=
      1;
  }

  notification14SaveStore(
    store14
  );

  notification14SyncUserCache(
    userId14
  );

  notification14AppendHistory({
    action:
      "read_all",

    userId:
      userId14,

    count:
      changed14
  });

  notification14EmitEvent(
    "notification.all_read",
    {
      userId:
        userId14,

      count:
        changed14
    }
  );

  return {
    success:
      true,

    changed:
      changed14,

    unread:
      0
  };
}

/* ------------------------------------------------------------
   14.16 - USER CACHE SYNC
------------------------------------------------------------ */

function notification14SyncUserCache(
  userId14
) {
  const store14 =
    notification14GetStore();

  const userItems14 =
    Object.values(
      store14
    )
      .filter(
        (item14) =>
          item14 &&
          item14.userId ===
            userId14 &&
          (
            !item14.expiresAt ||
            new Date(
              item14.expiresAt
            ).getTime() >
              Date.now()
          )
      )
      .sort(
        (a14, b14) =>
          String(
            b14.createdAt ||
            ""
          ).localeCompare(
            String(
              a14.createdAt ||
              ""
            )
          )
      )
      .slice(
        0,
        500
      );

  const cache14 = {
    userId:
      userId14,

    items:
      userItems14,

    unread:
      userItems14.filter(
        (item14) =>
          item14.read ===
          false
      ).length,

    updatedAt:
      notification14Now()
  };

  notification14SaveUserCache(
    userId14,
    cache14
  );

  return cache14;
}

/* ------------------------------------------------------------
   14.17 - LIST USER NOTIFICATIONS
------------------------------------------------------------ */

function notification14List({
  userId14 = "guest",
  unreadOnly14 = false,
  type14 = null,
  source14 = null,
  page14 = 1,
  limit14 = 30
} = {}) {
  const cache14 =
    notification14GetUserCache(
      userId14
    );

  let items14 =
    Array.isArray(
      cache14.items
    )
      ? cache14.items
      : [];

  if (
    unreadOnly14
  ) {
    items14 =
      items14.filter(
        (item14) =>
          item14.read ===
          false
      );
  }

  if (
    type14
  ) {
    items14 =
      items14.filter(
        (item14) =>
          item14.type ===
          type14
      );
  }

  if (
    source14
  ) {
    items14 =
      items14.filter(
        (item14) =>
          item14.source ===
          source14
      );
  }

  const safePage14 =
    Math.max(
      1,
      toInteger(
        page14,
        1
      )
    );

  const safeLimit14 =
    clamp(
      toInteger(
        limit14,
        NOTIFICATION_CONFIG_14.defaultPageSize
      ),
      1,
      NOTIFICATION_CONFIG_14.maxPageSize
    );

  const start14 =
    (
      safePage14 -
      1
    ) *
    safeLimit14;

  return {
    items:
      items14.slice(
        start14,
        start14 +
          safeLimit14
      ),

    total:
      items14.length,

    page:
      safePage14,

    limit:
      safeLimit14,

    pages:
      Math.max(
        1,
        Math.ceil(
          items14.length /
          safeLimit14
        )
      ),

    unread:
      items14.filter(
        (item14) =>
          !item14.read
      ).length
  };
}

/* ------------------------------------------------------------
   14.18 - DELETE NOTIFICATION
------------------------------------------------------------ */

function notification14Delete(
  userId14,
  notificationId14
) {
  const store14 =
    notification14GetStore();

  const safeId14 =
    notification14SafeId(
      notificationId14
    );

  const item14 =
    store14[
      safeId14
    ];

  if (
    !item14
  ) {
    throw new Error(
      "Bildirim bulunamadı."
    );
  }

  if (
    item14.userId !==
    userId14
  ) {
    throw new Error(
      "Bu bildirimi silemezsin."
    );
  }

  delete store14[
    safeId14
  ];

  notification14SaveStore(
    store14
  );

  notification14SyncUserCache(
    userId14
  );

  notification14AppendHistory({
    action:
      "deleted",

    userId:
      userId14,

    notificationId:
      safeId14
  });

  notification14EmitEvent(
    "notification.deleted",
    {
      userId:
        userId14,

      notificationId:
        safeId14
    }
  );

  return {
    success:
      true,

    notificationId:
      safeId14
  };
}

/* ------------------------------------------------------------
   14.19 - CLEAR READ
------------------------------------------------------------ */

function notification14ClearRead(
  userId14
) {
  const store14 =
    notification14GetStore();

  let deleted14 =
    0;

  for (
    const id14 of
    Object.keys(
      store14
    )
  ) {
    const item14 =
      store14[
        id14
      ];

    if (
      item14 &&
      item14.userId ===
        userId14 &&
      item14.read ===
        true
    ) {
      delete store14[
        id14
      ];

      deleted14 +=
        1;
    }
  }

  notification14SaveStore(
    store14
  );

  notification14SyncUserCache(
    userId14
  );

  notification14AppendHistory({
    action:
      "clear_read",

    userId:
      userId14,

    count:
      deleted14
  });

  return {
    success:
      true,

    deleted:
      deleted14
  };
}

/* ------------------------------------------------------------
   14.20 - EXPIRATION CLEANUP
------------------------------------------------------------ */

function notification14CleanupExpired() {
  const store14 =
    notification14GetStore();

  let removed14 =
    0;

  const now14 =
    Date.now();

  for (
    const id14 of
    Object.keys(
      store14
    )
  ) {
    const item14 =
      store14[
        id14
      ];

    if (
      !item14
    ) {
      continue;
    }

    let expired14 =
      false;

    if (
      item14.expiresAt
    ) {
      const expiresMs14 =
        new Date(
          item14.expiresAt
        ).getTime();

      if (
        Number.isFinite(
          expiresMs14
        ) &&
        expiresMs14 <=
          now14
      ) {
        expired14 =
          true;
      }
    }

    const createdMs14 =
      new Date(
        item14.createdAt ||
        0
      ).getTime();

    if (
      Number.isFinite(
        createdMs14
      ) &&
      createdMs14 <
        now14 -
          NOTIFICATION_CONFIG_14.retentionDays *
            24 *
            60 *
            60 *
            1000
    ) {
      expired14 =
        true;
    }

    if (
      expired14
    ) {
      delete store14[
        id14
      ];

      removed14 +=
        1;
    }
  }

  if (
    removed14 >
    0
  ) {
    notification14SaveStore(
      store14
    );
  }

  return {
    success:
      true,

    removed:
      removed14
  };
}

/* ------------------------------------------------------------
   14.21 - USER SUMMARY
------------------------------------------------------------ */

function notification14Summary(
  userId14
) {
  const store14 =
    notification14GetStore();

  const items14 =
    Object.values(
      store14
    ).filter(
      (item14) =>
        item14 &&
        item14.userId ===
          userId14 &&
        (
          !item14.expiresAt ||
          new Date(
            item14.expiresAt
          ).getTime() >
            Date.now()
        )
    );

  const byType14 = {};

  for (
    const item14 of
    items14
  ) {
    byType14[
      item14.type
    ] =
      (
        byType14[
          item14.type
        ] ||
        0
      ) + 1;
  }

  return {
    total:
      items14.length,

    unread:
      items14.filter(
        (item14) =>
          !item14.read
      ).length,

    read:
      items14.filter(
        (item14) =>
          item14.read
      ).length,

    byType:
      byType14,

    latest:
      items14
        .sort(
          (a14, b14) =>
            String(
              b14.createdAt ||
              ""
            ).localeCompare(
              String(
                a14.createdAt ||
                ""
              )
            )
        )
        .slice(
          0,
          5
        )
  };
}

/* ------------------------------------------------------------
   14.22 - BULK READ
------------------------------------------------------------ */

function notification14BulkRead(
  userId14,
  ids14
) {
  const store14 =
    notification14GetStore();

  const safeIds14 =
    ensureArray(
      ids14
    )
      .map(
        (id14) =>
          notification14SafeId(
            id14
          )
      )
      .filter(Boolean)
      .slice(
        0,
        500
      );

  let changed14 =
    0;

  for (
    const id14 of
    safeIds14
  ) {
    const item14 =
      store14[
        id14
      ];

    if (
      !item14 ||
      item14.userId !==
        userId14 ||
      item14.read
    ) {
      continue;
    }

    item14.read =
      true;

    item14.readAt =
      notification14Now();

    item14.updatedAt =
      notification14Now();

    changed14 +=
      1;
  }

  notification14SaveStore(
    store14
  );

  notification14SyncUserCache(
    userId14
  );

  return {
    success:
      true,

    changed:
      changed14,

    unread:
      notification14UnreadCount(
        userId14
      )
  };
}

