/* ------------------------------------------------------------
   14.24 - INTERNAL INTEGRATION LISTENER
------------------------------------------------------------ */

TURKAI_EVENT_BUS_14.on(
  "event",
  (event14) => {
    try {
      const payload14 =
        event14.payload ||
        {};

      const userId14 =
        notification14SafeString(
          payload14.userId ||
          payload14.ownerId ||
          payload14.userId14 ||
          "",
          ""
        );

      if (
        !userId14
      ) {
        return;
      }

      /*
       * Burada event -> notification dönüşümü yapılır.
       * Aynı event birden fazla modülden gelse bile
       * dedupeKey kullanımı tekrarları azaltır.
       */

      if (
        event14.name ===
        "task.overdue"
      ) {
        notification14NotifyTask({
          userId14,

          title14:
            "Geciken görev",

          body14:
            payload14.title ||
            "Bir görevin zamanı geçti.",

          taskId14:
            payload14.taskId ||
            null,

          taskStatus14:
            "overdue",

          link14:
            payload14.link ||
            "/tasks"
        });
      }

      if (
        event14.name ===
        "task.completed"
      ) {
        notification14NotifyTask({
          userId14,

          title14:
            "Görev tamamlandı",

          body14:
            payload14.title
              ? `“${payload14.title}” tamamlandı.`
              : "Görev başarıyla tamamlandı.",

          taskId14:
            payload14.taskId ||
            null,

          taskStatus14:
            "completed",

          link14:
            payload14.link ||
            "/tasks"
        });
      }

      if (
        event14.name ===
        "ai.completed"
      ) {
        notification14NotifyAI({
          userId14,

          title14:
            payload14.title ||
            "TürkAI işlemi tamamlandı",

          body14:
            payload14.body ||
            "Yapay zekâ işlemi başarıyla tamamlandı.",

          conversationId14:
            payload14.conversationId ||
            null,

          link14:
            payload14.link ||
            ""
        });
      }

      if (
        event14.name ===
        "research.completed"
      ) {
        notification14NotifyResearch({
          userId14,

          query14:
            payload14.query ||
            "",

          resultCount14:
            payload14.resultCount ||
            0,

          link14:
            payload14.link ||
            ""
        });
      }

      if (
        event14.name ===
        "security.alert"
      ) {
        notification14NotifySecurity({
          userId14,

          title14:
            payload14.title ||
            "Güvenlik uyarısı",

          body14:
            payload14.body ||
            "Bir güvenlik olayı algılandı.",

          severity14:
            payload14.severity ||
            "medium",

          link14:
            payload14.link ||
            ""
        });
      }
    } catch (error14) {
      systemLog?.(
        "notification14_event_listener_error",
        {
          error:
            error14?.message ||
            String(
              error14
            )
        }
      );
    }
  }
);

