/* ------------------------------------------------------------
   14.29 - SOCKET ROOM HELPERS
------------------------------------------------------------ */

function notification14SocketJoin(
  socket14,
  userId14
) {
  const safeUser14 =
    notification14SafeString(
      userId14,
      "guest"
    );

  const room14 =
    `user:${safeUser14}`;

  try {
    socket14.join(
      room14
    );

    socket14.userId =
      safeUser14;

    return room14;
  } catch (_) {
    return null;
  }
}

