app.put(
  "/api/notifications/preferences",
  (req14, res14) => {
    try {
      const userId14 =
        notification14UserId(
          req14
        );

      const incoming14 =
        req14.body ||
        {};

      const current14 =
        notification14GetPreferences(
          userId14
        );

      const allowedKeys14 = [
        "enabled",
        "sound",
        "task",
        "ai",
        "media",
        "voice",
        "research",
        "security",
        "billing",
        "system"
      ];

      for (
        const key14 of
        allowedKeys14
      ) {
        if (
          Object.prototype.hasOwnProperty.call(
            incoming14,
            key14
          )
        ) {
          current14[
            key14
          ] =
            Boolean(
              incoming14[
                key14
              ]
            );
        }
      }

      const saved14 =
        notification14SavePreferences(
          userId14,
          current14
        );

      notification14EmitEvent(
        "notification.preferences_updated",
        {
          userId:
            userId14
        }
      );

      res14.json({
        success:
          true,

        preferences:
          saved14
      });
    } catch (error14) {
      notification14Error(
        res14,
        400,
        error14.message
      );
    }
  }
);

