const MONITORING_CONFIG_15 = {
  version:
    "15.0.0",

  enabled:
    true,

  sampleIntervalMs:
    15000,

  maxAuditEntries:
    20000,

  maxErrorEntries:
    10000,

  maxMetricSamples:
    5000,

  maxRequestEntries:
    10000,

  maxAlerts:
    5000,

  retentionDays:
    30,

  requestSlowMs:
    2500,

  requestCriticalMs:
    10000,

  memoryWarningPercent:
    85,

  memoryCriticalPercent:
    95,

  maxLogReadBytes:
    2 * 1024 * 1024
};

function monitoring15ReadJSON(
  filePath15,
  fallback15
) {
  try {
    if (
      !fs15.existsSync(
        filePath15
      )
    ) {
      return fallback15;
    }

    const raw15 =
      fs15.readFileSync(
        filePath15,
        "utf8"
      );

    if (
      !raw15.trim()
    ) {
      return fallback15;
    }

    return JSON.parse(
      raw15
    );
  } catch (error15) {
    try {
      systemLog?.(
        "monitoring15_read_error",
        {
          file:
            filePath15,

          error:
            error15?.message ||
            String(
              error15
            )
        }
      );
    } catch (_) {}

    return fallback15;
  }
}

function monitoring15WriteJSON(
  filePath15,
  value15
) {
  try {
    fs15.mkdirSync(
      path15.dirname(
        filePath15
      ),
      {
        recursive:
          true
      }
    );

    const temp15 =
      `${filePath15}.${process.pid}.${Date.now()}.tmp`;

    fs15.writeFileSync(
      temp15,
      JSON.stringify(
        value15,
        null,
        2
      ),
      "utf8"
    );

    fs15.renameSync(
      temp15,
      filePath15
    );

    return true;
  } catch (error15) {
    try {
      systemLog?.(
        "monitoring15_write_error",
        {
          file:
            filePath15,

          error:
            error15?.message ||
            String(
              error15
            )
        }
      );
    } catch (_) {}

    return false;
  }
}

/* ------------------------------------------------------------
   15.4 - BASIC HELPERS
------------------------------------------------------------ */

function monitoring15SafeString(
  value15,
  fallback15 = ""
) {
  return safeString(
    value15,
    fallback15
  )
    .normalize("NFKC")
    .replace(
      /\u0000/g,
      ""
    )
    .trim();
}

function monitoring15SafeId(
  value15,
  fallback15 = ""
) {
  return monitoring15SafeString(
    value15,
    fallback15
  )
    .replace(
      /[^a-zA-Z0-9_\-:.]/g,
      "-"
    )
    .replace(
      /-+/g,
      "-"
    )
    .replace(
      /^-+|-+$/g,
      ""
    )
    .slice(
      0,
      180
    );
}

function monitoring15Hash(
  value15
) {
  return crypto15
    .createHash(
      "sha256"
    )
    .update(
      Buffer.from(
        monitoring15SafeString(
          value15,
          ""
        ),
        "utf8"
      )
    )
    .digest("hex");
}

function monitoring15ShortHash(
  value15
) {
  return monitoring15Hash(
    value15
  ).slice(
    0,
    18
  );
}

function monitoring15UserId(
  req15
) {
  return normalizeUserId(
    monitoring15SafeString(
      req15?.user?.id ||
      req15?.body?.userId ||
      req15?.query?.userId ||
      "guest"
    )
  );
}

