/* ------------------------------------------------------------
   15.7 - EVENT LOOP LAG
------------------------------------------------------------ */

const MONITORING_LOOP_15 = {
  lastTickAt:
    Date.now(),

  currentLagMs:
    0,

  maxLagMs:
    0,

  averageLagMs:
    0,

  samples:
    0
};

const MONITORING_LOOP_TIMER_15 =
  setInterval(
    () => {
      const expected15 =
        MONITORING_LOOP_15.lastTickAt +
        MONITORING_CONFIG_LOOP_INTERVAL_15;

      const now15 =
        Date.now();

      const lag15 =
        Math.max(
          0,
          now15 -
            expected15
        );

      MONITORING_LOOP_15.currentLagMs =
        lag15;

      MONITORING_LOOP_15.maxLagMs =
        Math.max(
          MONITORING_LOOP_15.maxLagMs,
          lag15
        );

      MONITORING_LOOP_15.samples +=
        1;

      if (
        MONITORING_LOOP_15.samples ===
        1
      ) {
        MONITORING_LOOP_15.averageLagMs =
          lag15;
      } else {
        MONITORING_LOOP_15.averageLagMs =
          (
            MONITORING_LOOP_15.averageLagMs *
            (
              MONITORING_LOOP_15.samples -
              1
            ) +
            lag15
          ) /
          MONITORING_LOOP_15.samples;
      }

      MONITORING_LOOP_15.lastTickAt =
        now15;
    },
    1000
  );

const MONITORING_CONFIG_LOOP_INTERVAL_15 =
  1000;

if (
  MONITORING_LOOP_TIMER_15?.unref
) {
  MONITORING_LOOP_TIMER_15.unref();
}

