function monitoring15RecordError({
  error15,
  source15 = "unknown",
  requestId15 = null,
  route15 = null,
  userId15 = null,
  severity15 = "error",
  metadata15 = {}
} = {}) {
  const message15 =
    monitoring15SafeString(
      error15?.message ||
      error15 ||
      "Bilinmeyen hata",
      "Bilinmeyen hata"
    );

  const stack15 =
    monitoring15SafeString(
      error15?.stack ||
      "",
      ""
    ).slice(
      0,
      10000
    );

  const entry15 = {
    id:
      `err-${monitoring15ShortHash(
        `${Date.now()}:${message15}:${Math.random()}`
      )}`,

    timestamp:
      nowISO(),

    source:
      monitoring15SafeString(
        source15,
        "unknown"
      ).slice(
        0,
        200
      ),

    requestId:
      requestId15 ||
      null,

    route:
      route15 ||
      null,

    userId:
      userId15 ||
      null,

    severity:
      monitoring15SafeString(
        severity15,
        "error"
      ),

    message:
      message15.slice(
        0,
        5000
      ),

    stack:
      stack15,

    metadata:
      isObject(
        metadata15
      )
        ? clone(
            metadata15
          )
        : {}
  };

  const errors15 =
    monitoring15GetErrors();

  errors15.push(
    entry15
  );

  monitoring15SaveErrors(
    errors15
  );

  MONITORING_RUNTIME_15.failed +=
    1;

  MONITORING_RUNTIME_15.lastErrorAt =
    entry15.timestamp;

  return entry15;
}

