/* ------------------------------------------------------------
   15.13 - SYSTEM SNAPSHOT
------------------------------------------------------------ */

function monitoring15GetSystemSnapshot() {
  const memory15 =
    process.memoryUsage();

  const totalMemory15 =
    os15.totalmem();

  const freeMemory15 =
    os15.freemem();

  const usedSystemMemory15 =
    totalMemory15 -
    freeMemory15;

  const memoryPercent15 =
    totalMemory15 > 0
      ? (
          usedSystemMemory15 /
          totalMemory15
        ) *
        100
      : 0;

  const load15 =
    os15.loadavg();

  const cpuCount15 =
    os15.cpus().length;

  const heapPercent15 =
    memory15.heapTotal > 0
      ? (
          memory15.heapUsed /
          memory15.heapTotal
        ) *
        100
      : 0;

  const uptime15 =
    Math.max(
      0,
      Date.now() -
        MONITORING_START_TIME_15
    );

  return {
    timestamp:
      nowISO(),

    process: {
      pid:
        process.pid,

      node:
        process.version,

      platform:
        process.platform,

      arch:
        process.arch,

      uptimeSeconds:
        Math.floor(
          process.uptime()
        ),

      monitoringUptimeMs:
        uptime15,

      cwd:
        process.cwd()
    },

    memory: {
      rss:
        memory15.rss,

      heapTotal:
        memory15.heapTotal,

      heapUsed:
        memory15.heapUsed,

      external:
        memory15.external,

      arrayBuffers:
        memory15.arrayBuffers,

      systemTotal:
        totalMemory15,

      systemFree:
        freeMemory15,

      systemUsed:
        usedSystemMemory15,

      systemUsedPercent:
        Number(
          memoryPercent15.toFixed(
            2
          )
        ),

      heapUsedPercent:
        Number(
          heapPercent15.toFixed(
            2
          )
        )
    },

    cpu: {
      count:
        cpuCount15,

      load1:
        Number(
          (
            load15[0] ||
            0
          ).toFixed(
            3
          )
        ),

      load5:
        Number(
          (
            load15[1] ||
            0
          ).toFixed(
            3
          )
        ),

      load15:
        Number(
          (
            load15[2] ||
            0
          ).toFixed(
            3
          )
        )
    },

    eventLoop: {
      currentLagMs:
        Number(
          MONITORING_LOOP_15.currentLagMs.toFixed(
            2
          )
        ),

      averageLagMs:
        Number(
          MONITORING_LOOP_15.averageLagMs.toFixed(
            2
          )
        ),

      maxLagMs:
        Number(
          MONITORING_LOOP_15.maxLagMs.toFixed(
            2
          )
        )
    },

    runtime:
      clone(
        MONITORING_RUNTIME_15
      )
  };
}

/* ------------------------------------------------------------
   15.14 - MODULE DETECTION
------------------------------------------------------------ */

function monitoring15ModuleHealth() {
  const state15 =
    serverState || {};

  const modules15 = [];

  const known15 = [
    "ai",
    "research",
    "market",
    "files",
    "tasks",
    "security",
    "conversations",
    "coding",
    "knowledge",
    "mediaGeneration",
    "voice",
    "notifications"
  ];

  for (
    const name15 of
    known15
  ) {
    const module15 =
      state15[
        name15
      ];

    let status15 =
      "missing";

    if (
      module15 &&
      typeof module15 ===
        "object"
    ) {
      status15 =
        module15.enabled ===
          false
          ? "disabled"
          : "loaded";
    }

    modules15.push({
      name:
        name15,

      status:
        status15,

      enabled:
        module15?.enabled !==
        false,

      version:
        module15?.version ||
        null
    });
  }

  return modules15;
}

/* ------------------------------------------------------------
   15.15 - DISK USAGE
------------------------------------------------------------ */

function monitoring15DirectorySize(
  root15
) {
  let total15 =
    0;

  let files15 =
    0;

  function walk15(
    current15
  ) {
    let entries15 = [];

    try {
      entries15 =
        fs15.readdirSync(
          current15,
          {
            withFileTypes:
              true
          }
        );
    } catch (_) {
      return;
    }

    for (
      const entry15 of
      entries15
    ) {
      const full15 =
        path15.join(
          current15,
          entry15.name
        );

      if (
        entry15.isDirectory()
      ) {
        walk15(
          full15
        );
      } else {
        try {
          const stat15 =
            fs15.statSync(
              full15
            );

          total15 +=
            stat15.size;

          files15 +=
            1;
        } catch (_) {}
      }
    }
  }

  walk15(
    root15
  );

  return {
    bytes:
      total15,

    files:
      files15
  };
}

function monitoring15StorageSnapshot() {
  const roots15 = {
    data:
      DATA_DIR,

    logs:
      LOG_DIR,

    uploads:
      UPLOAD_DIR,

    media:
      MEDIA_DIR,

    research:
      RESEARCH_DIR,

    weather:
      WEATHER_DIR,

    tasks:
      TASK_DIR,

    cache:
      CACHE_DIR,

    exports:
      EXPORT_DIR,

    monitoring:
      MONITORING_ROOT_15
  };

  const result15 = {};

  for (
    const key15 of
    Object.keys(
      roots15
    )
  ) {
    result15[
      key15
    ] =
      monitoring15DirectorySize(
        roots15[
          key15
        ]
      );
  }

  return result15;
}

/* ------------------------------------------------------------
   15.16 - HEALTH SCORE
------------------------------------------------------------ */

function monitoring15EvaluateHealth(
  snapshot15
) {
  const checks15 = [];
  let score15 =
    100;

  const memoryPercent15 =
    snapshot15.memory
      .systemUsedPercent;

  if (
    memoryPercent15 >=
    MONITORING_CONFIG_15.memoryCriticalPercent
  ) {
    score15 -=
      35;

    checks15.push({
      key:
        "memory",

      status:
        "critical",

      value:
        memoryPercent15
    });
  } else if (
    memoryPercent15 >=
    MONITORING_CONFIG_15.memoryWarningPercent
  ) {
    score15 -=
      15;

    checks15.push({
      key:
        "memory",

      status:
        "warning",

      value:
        memoryPercent15
    });
  } else {
    checks15.push({
      key:
        "memory",

      status:
        "ok",

      value:
        memoryPercent15
    });
  }

  if (
    snapshot15.eventLoop.currentLagMs >=
    MONITORING_CONFIG_15.requestCriticalMs
  ) {
    score15 -=
      30;

    checks15.push({
      key:
        "eventLoop",

      status:
        "critical",

      value:
        snapshot15.eventLoop.currentLagMs
    });
  } else if (
    snapshot15.eventLoop.currentLagMs >=
    MONITORING_CONFIG_15.requestSlowMs
  ) {
    score15 -=
      10;

    checks15.push({
      key:
        "eventLoop",

      status:
        "warning",

      value:
        snapshot15.eventLoop.currentLagMs
    });
  } else {
    checks15.push({
      key:
        "eventLoop",

      status:
        "ok",

      value:
        snapshot15.eventLoop.currentLagMs
    });
  }

  if (
    MONITORING_RUNTIME_15.active >
    500
  ) {
    score15 -=
      15;

    checks15.push({
      key:
        "activeRequests",

      status:
        "warning",

      value:
        MONITORING_RUNTIME_15.active
    });
  } else {
    checks15.push({
      key:
        "activeRequests",

      status:
        "ok",

      value:
        MONITORING_RUNTIME_15.active
    });
  }

  const finalScore15 =
    clamp(
      Math.round(
        score15
      ),
      0,
      100
    );

  let status15 =
    "healthy";

  if (
    finalScore15 <
    50
  ) {
    status15 =
      "critical";
  } else if (
    finalScore15 <
    75
  ) {
    status15 =
      "warning";
  }

  return {
    score:
      finalScore15,

    status:
      status15,

    checks:
      checks15
  };
}

/* ------------------------------------------------------------
   15.17 - COMPLETE SNAPSHOT
------------------------------------------------------------ */

function monitoring15Snapshot() {
  const system15 =
    monitoring15GetSystemSnapshot();

  const modules15 =
    monitoring15ModuleHealth();

  const storage15 =
    monitoring15StorageSnapshot();

  const health15 =
    monitoring15EvaluateHealth(
      system15
    );

  return {
    success:
      true,

    module:
      "admin-monitoring",

    version:
      MONITORING_CONFIG_15.version,

    system:
      system15,

    health:
      health15,

    modules:
      modules15,

    storage:
      storage15,

    timestamp:
      nowISO()
  };
}

/* ------------------------------------------------------------
   15.18 - STORE METRIC SAMPLE
------------------------------------------------------------ */

function monitoring15CollectMetric() {
  const snapshot15 =
    monitoring15Snapshot();

  const metrics15 =
    monitoring15GetMetrics();

  const sample15 = {
    timestamp:
      snapshot15.timestamp,

    healthScore:
      snapshot15.health.score,

    healthStatus:
      snapshot15.health.status,

    cpuLoad1:
      snapshot15.system.cpu.load1,

    cpuLoad5:
      snapshot15.system.cpu.load5,

    memoryUsedPercent:
      snapshot15.system.memory
        .systemUsedPercent,

    heapUsedPercent:
      snapshot15.system.memory
        .heapUsedPercent,

    eventLoopLagMs:
      snapshot15.system
        .eventLoop
        .currentLagMs,

    activeRequests:
      MONITORING_RUNTIME_15.active,

    requests:
      MONITORING_RUNTIME_15.requests,

    failures:
      MONITORING_RUNTIME_15.failed,

    slowRequests:
      MONITORING_RUNTIME_15.slow
  };

  metrics15.push(
    sample15
  );

  monitoring15SaveMetrics(
    metrics15
  );

  if (
    snapshot15.health.status ===
    "critical"
  ) {
    monitoring15CreateAlert({
      type15:
        "health",

      severity15:
        "critical",

      title15:
        "TürkAI sistem sağlığı kritik",

      message15:
        `Sağlık skoru ${snapshot15.health.score}/100 seviyesine düştü.`,

      metadata15: {
        health:
          snapshot15.health,

        memory:
          snapshot15.system.memory
            .systemUsedPercent,

        eventLoop:
          snapshot15.system
            .eventLoop
            .currentLagMs
      }
    });
  }

  if (
    snapshot15.system.memory
      .systemUsedPercent >=
    MONITORING_CONFIG_15.memoryCriticalPercent
  ) {
    monitoring15CreateAlert({
      type15:
        "memory",

      severity15:
        "critical",

      title15:
        "Bellek kullanımı kritik",

      message15:
        `Sistem belleği %${snapshot15.system.memory.systemUsedPercent} seviyesinde.`,

      metadata15: {
        percent:
          snapshot15.system.memory
            .systemUsedPercent
      }
    });
  }

  return sample15;
}

/* ------------------------------------------------------------
   15.19 - REQUEST MIDDLEWARE
------------------------------------------------------------ */

app.use(
  (
    req15,
    res15,
    next15
  ) => {
    const started15 =
      process.hrtime.bigint();

    MONITORING_RUNTIME_15.requests +=
      1;

    MONITORING_RUNTIME_15.active +=
      1;

    MONITORING_RUNTIME_15.lastRequestAt =
      nowISO();

    let inputBytes15 =
      0;

    try {
      inputBytes15 =
        toInteger(
          req15.headers[
            "content-length"
          ],
          0
        );
    } catch (_) {}

    MONITORING_RUNTIME_15.bytesIn +=
      inputBytes15;

    let finished15 =
      false;

    const finalize15 = () => {
      if (
        finished15
      ) {
        return;
      }

      finished15 =
        true;

      const diff15 =
        process.hrtime.bigint() -
        started15;

      const duration15 =
        Number(
          diff15
        ) /
        1e6;

      const route15 =
        req15.originalUrl ||
        req15.url ||
        "";

      const status15 =
        Number(
          res15.statusCode ||
          0
        );

      const slow15 =
        duration15 >=
        MONITORING_CONFIG_15.requestSlowMs;

      const critical15 =
        duration15 >=
        MONITORING_CONFIG_15.requestCriticalMs;

      if (
        status15 >=
        400
      ) {
        MONITORING_RUNTIME_15.failed +=
          1;
      } else {
        MONITORING_RUNTIME_15.completed +=
          1;
      }

      if (
        slow15
      ) {
        MONITORING_RUNTIME_15.slow +=
          1;

        MONITORING_RUNTIME_15.lastSlowRequestAt =
          nowISO();
      }

      if (
        critical15
      ) {
        MONITORING_RUNTIME_15.critical +=
          1;
      }

      MONITORING_RUNTIME_15.active =
        Math.max(
          0,
          MONITORING_RUNTIME_15.active -
            1
        );

      const responseLength15 =
        toInteger(
          res15.getHeader(
            "content-length"
          ),
          0
        );

      MONITORING_RUNTIME_15.bytesOut +=
        responseLength15;

      const requestRecord15 = {
        timestamp:
          nowISO(),

        requestId:
          req15.requestId ||
          null,

        method:
          req15.method,

        route:
          route15.slice(
            0,
            1000
          ),

        status:
          status15,

        durationMs:
          Number(
            duration15.toFixed(
              2
            )
          ),

        slow:
          slow15,

        critical:
          critical15,

        userId:
          req15.user?.id ||
          null
      };

      monitoring15RecordRequest(
        requestRecord15
      );

      if (
        critical15
      ) {
        monitoring15CreateAlert({
          type15:
            "request",

          severity15:
            "critical",

          title15:
            "Çok yavaş API isteği",

          message15:
            `${req15.method} ${route15} ${Math.round(duration15)} ms sürdü.`,

          metadata15:
            requestRecord15
        });
      }
    };

    res15.once(
      "finish",
      finalize15
    );

    res15.once(
      "close",
      finalize15
    );

    next15();
  }
);

/* ------------------------------------------------------------
   15.20 - ADMIN AUTHORIZATION
------------------------------------------------------------ */

function monitoring15IsPrivileged(
  req15
) {
  const role15 =
    monitoring15SafeString(
      req15?.user?.role ||
      "",
      ""
    ).toLowerCase();

  return [
    "admin",
    "developer",
    "owner"
  ].includes(
    role15
  );
}

function monitoring15RequireAdmin(
  req15,
  res15
) {
  if (
    monitoring15IsPrivileged(
      req15
    )
  ) {
    return true;
  }

  res15.status(
    403
  ).json({
    success:
      false,

    error:
      "Bu endpoint için admin/developer/owner yetkisi gerekli."
  });

  return false;
}

