/* ------------------------------------------------------------
   15.31 - LOG FILE LIST
------------------------------------------------------------ */

function monitoring15ListLogFiles() {
  const result15 = [];

  function walk15(
    current15
  ) {
    let entries15 = [];

    try {
      entries15 =
        fs15.readdirSync(
          current15,
          {
            withFileTypes:
              true
          }
        );
    } catch (_) {
      return;
    }

    for (
      const entry15 of
      entries15
    ) {
      const full15 =
        path15.join(
          current15,
          entry15.name
        );

      if (
        entry15.isDirectory()
      ) {
        walk15(
          full15
        );
        continue;
      }

      try {
        const stat15 =
          fs15.statSync(
            full15
          );

        result15.push({
          path:
            full15,

          relative:
            path15.relative(
              ROOT_DIR,
              full15
            ),

          size:
            stat15.size,

          modifiedAt:
            stat15.mtime.toISOString()
        });
      } catch (_) {}
    }
  }

  walk15(
    LOG_DIR
  );

  result15.sort(
    (a15, b15) =>
      String(
        b15.modifiedAt
      ).localeCompare(
        String(
          a15.modifiedAt
        )
      )
  );

  return result15;
}

