/* ------------------------------------------------------------
   15.33 - SAFE LOG READ
------------------------------------------------------------ */

function monitoring15ReadLog(
  relativePath15,
  lines15 = 200
) {
  const requested15 =
    monitoring15SafeString(
      relativePath15,
      ""
    );

  if (
    !requested15
  ) {
    throw new Error(
      "Log yolu gerekli."
    );
  }

  const rootResolved15 =
    path15.resolve(
      LOG_DIR
    );

  const targetResolved15 =
    path15.resolve(
      ROOT_DIR,
      requested15
    );

  if (
    targetResolved15 !==
      rootResolved15 &&
    !targetResolved15.startsWith(
      `${rootResolved15}${path15.sep}`
    )
  ) {
    throw new Error(
      "Geçersiz log yolu."
    );
  }

  if (
    !fs15.existsSync(
      targetResolved15
    )
  ) {
    throw new Error(
      "Log dosyası bulunamadı."
    );
  }

  const stat15 =
    fs15.statSync(
      targetResolved15
    );

  if (
    stat15.size >
    MONITORING_CONFIG_15.maxLogReadBytes
  ) {
    throw new Error(
      "Log dosyası çok büyük."
    );
  }

  const text15 =
    fs15.readFileSync(
      targetResolved15,
      "utf8"
    );

  const allLines15 =
    text15.split(
      /\r?\n/
    );

  const limit15 =
    clamp(
      toInteger(
        lines15,
        200
      ),
      1,
      2000
    );

  return {
    path:
      requested15,

    totalLines:
      allLines15.length,

    lines:
      allLines15.slice(
        -limit15
      )
  };
}

