/* ------------------------------------------------------------
   15.39 - CLEANUP OLD MONITORING DATA
------------------------------------------------------------ */

function monitoring15CleanupRetention() {
  const cutoff15 =
    Date.now() -
    MONITORING_CONFIG_15.retentionDays *
      24 *
      60 *
      60 *
      1000;

  let removedMetrics15 =
    0;

  let removedErrors15 =
    0;

  let removedAudit15 =
    0;

  let removedRequests15 =
    0;

  const metrics15 =
    monitoring15GetMetrics();

  const filteredMetrics15 =
    metrics15.filter(
      (item15) => {
        const ms15 =
          new Date(
            item15.timestamp ||
            0
          ).getTime();

        const keep15 =
          !Number.isFinite(
            ms15
          ) ||
          ms15 >=
            cutoff15;

        if (
          !keep15
        ) {
          removedMetrics15 +=
            1;
        }

        return keep15;
      }
    );

  const errors15 =
    monitoring15GetErrors();

  const filteredErrors15 =
    errors15.filter(
      (item15) => {
        const ms15 =
          new Date(
            item15.timestamp ||
            0
          ).getTime();

        const keep15 =
          !Number.isFinite(
            ms15
          ) ||
          ms15 >=
            cutoff15;

        if (
          !keep15
        ) {
          removedErrors15 +=
            1;
        }

        return keep15;
      }
    );

  const audit15 =
    monitoring15GetAudit();

  const filteredAudit15 =
    audit15.filter(
      (item15) => {
        const ms15 =
          new Date(
            item15.timestamp ||
            0
          ).getTime();

        const keep15 =
          !Number.isFinite(
            ms15
          ) ||
          ms15 >=
            cutoff15;

        if (
          !keep15
        ) {
          removedAudit15 +=
            1;
        }

        return keep15;
      }
    );

  const requests15 =
    monitoring15GetRequests();

  const filteredRequests15 =
    requests15.filter(
      (item15) => {
        const ms15 =
          new Date(
            item15.timestamp ||
            0
          ).getTime();

        const keep15 =
          !Number.isFinite(
            ms15
          ) ||
          ms15 >=
            cutoff15;

        if (
          !keep15
        ) {
          removedRequests15 +=
            1;
        }

        return keep15;
      }
    );

  monitoring15SaveMetrics(
    filteredMetrics15
  );

  monitoring15SaveErrors(
    filteredErrors15
  );

  monitoring15SaveAudit(
    filteredAudit15
  );

  monitoring15SaveRequests(
    filteredRequests15
  );

  return {
    success:
      true,

    removed: {
      metrics:
        removedMetrics15,

      errors:
        removedErrors15,

      audit:
        removedAudit15,

      requests:
        removedRequests15
    }
  };
}

const MONITORING_CLEANUP_TIMER_15 =
  setInterval(
    () => {
      try {
        monitoring15CleanupRetention();
      } catch (error15) {
        try {
          monitoring15RecordError({
            error15,

            source15:
              "monitoring.retention"
          });
        } catch (_) {}
      }
    },
    6 * 60 * 60 * 1000
  );

if (
  MONITORING_CLEANUP_TIMER_15?.unref
) {
  MONITORING_CLEANUP_TIMER_15.unref();
}

