/* ------------------------------------------------------------
   16.15 - TASK TOOL
------------------------------------------------------------ */

agent16RegisterTool({
  name:
    "tasks",

  description:
    "Görevleri listeler, oluşturur ve durumlarını yönetir.",

  category:
    "tasks",

  readOnly:
    false,

  plannerWeight:
    1.15,

  enabled:
    agent16HasState(
      "tasks"
    ),

  handler:
    async ({
      userId16,
      input16
    }) => {
      const action16 =
        agent16SafeString(
          input16.action,
          "list"
        ).toLowerCase();

      const taskState16 =
        serverState?.tasks;

      if (
        !taskState16
      ) {
        throw new Error(
          "Task engine aktif değil."
        );
      }

      if (
        action16 ===
        "list"
      ) {
        const fn16 =
          taskState16.list ||
          taskState16.getAll ||
          taskState16.upcoming;

        if (
          typeof fn16 !==
          "function"
        ) {
          throw new Error(
            "Task list fonksiyonu bulunamadı."
          );
        }

        return fn16({
          userId11:
            userId16,

          userId:
            userId16
        });
      }

      if (
        action16 ===
        "upcoming"
      ) {
        const fn16 =
          taskState16.upcoming ||
          taskState16.list;

        if (
          typeof fn16 !==
          "function"
        ) {
          throw new Error(
            "Upcoming task fonksiyonu bulunamadı."
          );
        }

        return fn16({
          userId11:
            userId16,

          userId:
            userId16
        });
      }

      if (
        action16 ===
        "create"
      ) {
        const fn16 =
          taskState16.create ||
          taskState16.add;

        if (
          typeof fn16 !==
          "function"
        ) {
          throw new Error(
            "Task create fonksiyonu bulunamadı."
          );
        }

        return fn16({
          userId11:
            userId16,

          userId:
            userId16,

          ...input16
        });
      }

      if (
        action16 ===
        "complete"
      ) {
        const fn16 =
          taskState16.complete;

        if (
          typeof fn16 !==
          "function"
        ) {
          throw new Error(
            "Task complete fonksiyonu bulunamadı."
          );
        }

        return fn16(
          input16.taskId ||
          input16.id,
          userId16
        );
      }

      throw new Error(
        `Desteklenmeyen task action: ${action16}`
      );
    }
});

