function agent16ExportUserHistory(
  userId16
) {
  const history16 =
    agent16GetHistory()
      .filter(
        (item16) =>
          item16?.userId ===
          userId16
      );

  const jobs16 =
    Object.values(
      agent16GetJobs()
    )
      .filter(
        (job16) =>
          job16?.userId ===
          userId16
      );

  const payload16 = {
    format:
      "turkai-agent-v1",

    exportedAt:
      nowISO(),

    userId:
      userId16,

    history:
      history16,

    jobs:
      jobs16
  };

  const fileName16 =
    `agent-${userId16}-${Date.now()}.json`;

  const filePath16 =
    path16.join(
      AGENT_EXPORT_16,
      fileName16
    );

  agent16WriteJSON(
    filePath16,
    payload16
  );

  return {
    success:
      true,

    fileName:
      fileName16,

    filePath:
      filePath16
  };
}

