/* ------------------------------------------------------------
   16.46 - CACHE CLEANUP
------------------------------------------------------------ */

function agent16CleanupCache() {
  const cache16 =
    agent16GetCache();

  const cutoff16 =
    Date.now() -
    AGENT_CONFIG_16.cacheTtlMs;

  let removed16 =
    0;

  for (
    const key16 of
    Object.keys(
      cache16
    )
  ) {
    if (
      toNumber(
        cache16[key16]?.createdAtMs,
        0
      ) <
      cutoff16
    ) {
      delete cache16[
        key16
      ];

      removed16 +=
        1;
    }
  }

  agent16WriteJSON(
    AGENT_CACHE_STORE_16,
    cache16
  );

  return {
    success:
      true,

    removed:
      removed16
  };
}

/* ------------------------------------------------------------
   16.47 - OLD JOB CLEANUP
------------------------------------------------------------ */

function agent16CleanupJobs() {
  const jobs16 =
    agent16GetJobs();

  const cutoff16 =
    Date.now() -
    30 *
      24 *
      60 *
      60 *
      1000;

  let removed16 =
    0;

  for (
    const id16 of
    Object.keys(
      jobs16
    )
  ) {
    const job16 =
      jobs16[
        id16
      ];

    const createdMs16 =
      new Date(
        job16?.createdAt ||
        0
      ).getTime();

    if (
      Number.isFinite(
        createdMs16
      ) &&
      createdMs16 <
        cutoff16 &&
      [
        "completed",
        "failed",
        "cancelled"
      ].includes(
        job16.status
      )
    ) {
      delete jobs16[
        id16
      ];

      removed16 +=
        1;
    }
  }

  agent16SaveJobs(
    jobs16
  );

  return {
    success:
      true,

    removed:
      removed16
  };
}

