/* ------------------------------------------------------------
   17.4 - JSON HELPERS
------------------------------------------------------------ */

function personalization17ReadJSON(
  filePath17,
  fallback17
) {
  try {
    if (
      !fs17.existsSync(
        filePath17
      )
    ) {
      return fallback17;
    }

    const raw17 =
      fs17.readFileSync(
        filePath17,
        "utf8"
      );

    if (
      !raw17.trim()
    ) {
      return fallback17;
    }

    return JSON.parse(
      raw17
    );
  } catch (error17) {
    try {
      systemLog?.(
        "personalization17_read_error",
        {
          file:
            filePath17,

          error:
            error17?.message ||
            String(
              error17
            )
        }
      );
    } catch (_) {}

    return fallback17;
  }
}

function personalization17WriteJSON(
  filePath17,
  value17
) {
  try {
    fs17.mkdirSync(
      path17.dirname(
        filePath17
      ),
      {
        recursive:
          true
      }
    );

    const temp17 =
      `${filePath17}.${process.pid}.${Date.now()}.tmp`;

    fs17.writeFileSync(
      temp17,
      JSON.stringify(
        value17,
        null,
        2
      ),
      "utf8"
    );

    fs17.renameSync(
      temp17,
      filePath17
    );

    return true;
  } catch (error17) {
    try {
      systemLog?.(
        "personalization17_write_error",
        {
          file:
            filePath17,

          error:
            error17?.message ||
            String(
              error17
            )
        }
      );
    } catch (_) {}

    return false;
  }
}

/* ------------------------------------------------------------
   17.5 - BASIC HELPERS
------------------------------------------------------------ */

function personalization17SafeString(
  value17,
  fallback17 = ""
) {
  return safeString(
    value17,
    fallback17
  )
    .normalize("NFKC")
    .replace(
      /\u0000/g,
      ""
    )
    .trim();
}

function personalization17SafeId(
  value17,
  fallback17 = ""
) {
  return personalization17SafeString(
    value17,
    fallback17
  )
    .replace(
      /[^a-zA-Z0-9_\-:.]/g,
      "-"
    )
    .replace(
      /-+/g,
      "-"
    )
    .replace(
      /^-+|-+$/g,
      ""
    )
    .slice(
      0,
      180
    );
}

function personalization17Hash(
  value17
) {
  return crypto17
    .createHash(
      "sha256"
    )
    .update(
      Buffer.from(
        personalization17SafeString(
          value17,
          ""
        ),
        "utf8"
      )
    )
    .digest("hex");
}

function personalization17ShortHash(
  value17
) {
  return personalization17Hash(
    value17
  ).slice(
    0,
    18
  );
}

function personalization17UserId(
  req17
) {
  return normalizeUserId(
    personalization17SafeString(
      req17?.user?.id ||
      req17?.body?.userId ||
      req17?.query?.userId ||
      "guest"
    )
  );
}

function personalization17NormalizeQuery(
  value17
) {
  return personalization17SafeString(
    value17,
    ""
  )
    .slice(
      0,
      20000
    );
}

/* ------------------------------------------------------------
   17.6 - TOKENIZER
------------------------------------------------------------ */

function personalization17Tokens(
  value17
) {
  const text17 =
    personalization17NormalizeQuery(
      value17
    )
      .toLocaleLowerCase(
        "tr-TR"
      );

  if (
    !text17
  ) {
    return [];
  }

  return text17
    .replace(
      /https?:\/\/\S+/giu,
      " "
    )
    .replace(
      /[^\p{L}\p{N}_\-]+/gu,
      " "
    )
    .split(
      /\s+/
    )
    .map(
      (item17) =>
        item17.trim()
    )
    .filter(
      (item17) =>
        item17.length >= 2
    );
}

function personalization17NormalizedTokens(
  value17
) {
  return personalization17Tokens(
    value17
  ).map(
    (token17) =>
      token17
        .replace(
          /ğ/g,
          "g"
        )
        .replace(
          /ü/g,
          "u"
        )
        .replace(
          /ş/g,
          "s"
        )
        .replace(
          /ı/g,
          "i"
        )
        .replace(
          /ö/g,
          "o"
        )
        .replace(
          /ç/g,
          "c"
        )
  );
}

function personalization17TokenOverlap(
  query17,
  target17
) {
  const querySet17 =
    new Set(
      personalization17NormalizedTokens(
        query17
      )
    );

  const targetSet17 =
    new Set(
      personalization17NormalizedTokens(
        target17
      )
    );

  if (
    querySet17.size ===
    0 ||
    targetSet17.size ===
    0
  ) {
    return 0;
  }

  let intersection17 =
    0;

  for (
    const token17 of
    querySet17
  ) {
    if (
      targetSet17.has(
        token17
      )
    ) {
      intersection17 +=
        1;
    }
  }

  const union17 =
    new Set([
      ...querySet17,
      ...targetSet17
    ]).size;

  return union17 >
    0
    ? intersection17 /
        union17
    : 0;
}

