app.get(
  "/api/personalization/memories",
  (req17, res17) => {
    try {
      const userId17 =
        personalization17UserId(
          req17
        );

      let items17 =
        personalization17GetUserMemories(
          userId17
        ).filter(
          (memory17) =>
            memory17 &&
            !memory17.deletedAt
        );

      if (
        req17.query.type
      ) {
        const type17 =
          personalization17SafeString(
            req17.query.type,
            ""
          ).toLowerCase();

        items17 =
          items17.filter(
            (memory17) =>
              memory17.type ===
              type17
          );
      }

      if (
        req17.query.projectId
      ) {
        const project17 =
          personalization17SafeId(
            req17.query.projectId
          );

        items17 =
          items17.filter(
            (memory17) =>
              memory17.projectId ===
              project17
          );
      }

      items17.sort(
        (a17, b17) =>
          String(
            b17.updatedAt ||
            ""
          ).localeCompare(
            String(
              a17.updatedAt ||
              ""
            )
          )
      );

      const limit17 =
        clamp(
          toInteger(
            req17.query.limit,
            50
          ),
          1,
          200
        );

      res17.json({
        success:
          true,

        items:
          items17.slice(
            0,
            limit17
          ),

        total:
          items17.length
      });
    } catch (error17) {
      personalization17Error(
        res17,
        500,
        error17.message
      );
    }
  }
);

