/* ------------------------------------------------------------
   18.4 - JSON HELPERS
------------------------------------------------------------ */

function developer18ReadJSON(
  filePath18,
  fallback18
) {
  try {
    if (
      !fs18.existsSync(
        filePath18
      )
    ) {
      return fallback18;
    }

    const raw18 =
      fs18.readFileSync(
        filePath18,
        "utf8"
      );

    if (
      !raw18.trim()
    ) {
      return fallback18;
    }

    return JSON.parse(
      raw18
    );
  } catch (error18) {
    try {
      systemLog?.(
        "developer18_read_error",
        {
          file:
            filePath18,

          error:
            error18?.message ||
            String(
              error18
            )
        }
      );
    } catch (_) {}

    return fallback18;
  }
}

function developer18WriteJSON(
  filePath18,
  value18
) {
  try {
    fs18.mkdirSync(
      path18.dirname(
        filePath18
      ),
      {
        recursive:
          true
      }
    );

    const temp18 =
      `${filePath18}.${process.pid}.${Date.now()}.tmp`;

    fs18.writeFileSync(
      temp18,
      JSON.stringify(
        value18,
        null,
        2
      ),
      "utf8"
    );

    fs18.renameSync(
      temp18,
      filePath18
    );

    return true;
  } catch (error18) {
    try {
      systemLog?.(
        "developer18_write_error",
        {
          file:
            filePath18,

          error:
            error18?.message ||
            String(
              error18
            )
        }
      );
    } catch (_) {}

    return false;
  }
}

/* ------------------------------------------------------------
   18.5 - BASIC HELPERS
------------------------------------------------------------ */

function developer18SafeString(
  value18,
  fallback18 = ""
) {
  return safeString(
    value18,
    fallback18
  )
    .normalize("NFKC")
    .replace(
      /\u0000/g,
      ""
    )
    .trim();
}

function developer18SafeId(
  value18,
  fallback18 = ""
) {
  return developer18SafeString(
    value18,
    fallback18
  )
    .replace(
      /[^a-zA-Z0-9_\-:.]/g,
      "-"
    )
    .replace(
      /-+/g,
      "-"
    )
    .replace(
      /^-+|-+$/g,
      ""
    )
    .slice(
      0,
      180
    );
}

function developer18Hash(
  value18
) {
  return crypto18
    .createHash(
      "sha256"
    )
    .update(
      Buffer.from(
        developer18SafeString(
          value18,
          ""
        ),
        "utf8"
      )
    )
    .digest("hex");
}

function developer18ShortHash(
  value18
) {
  return developer18Hash(
    value18
  ).slice(
    0,
    20
  );
}

function developer18UserId(
  req18
) {
  return normalizeUserId(
    developer18SafeString(
      req18?.user?.id ||
      req18?.body?.userId ||
      "developer",
      "developer"
    )
  );
}

/* ------------------------------------------------------------
   18.6 - API KEY STORE
------------------------------------------------------------ */

function developer18GetKeys() {
  return developer18ReadJSON(
    DEVELOPER_KEY_STORE_18,
    {}
  );
}

function developer18SaveKeys(
  keys18
) {
  return developer18WriteJSON(
    DEVELOPER_KEY_STORE_18,
    keys18
  );
}

/* ------------------------------------------------------------
   18.7 - RANDOM SECRET
------------------------------------------------------------ */

function developer18RandomToken() {
  return crypto18
    .randomBytes(
      32
    )
    .toString(
      "base64url"
    );
}

/* ------------------------------------------------------------
   18.8 - API KEY CREATION
------------------------------------------------------------ */

function developer18CreateKey({
  ownerId18,
  name18 = "TürkAI API Key",
  scopes18 = [],
  expiresAt18 = null
} = {}) {
  const safeOwner18 =
    developer18SafeId(
      ownerId18,
      "developer"
    );

  const keys18 =
    developer18GetKeys();

  const ownerCount18 =
    Object.values(
      keys18
    ).filter(
      (key18) =>
        key18 &&
        key18.ownerId ===
          safeOwner18 &&
        !key18.revokedAt
    ).length;

  if (
    ownerCount18 >=
    DEVELOPER_CONFIG_18
      .maxKeysPerOwner
  ) {
    throw new Error(
      "Maksimum API key sayısına ulaşıldı."
    );
  }

  const secret18 =
    developer18RandomToken();

  const rawKey18 =
    `${DEVELOPER_CONFIG_18.keyPrefix}${secret18}`;

  const keyHash18 =
    developer18Hash(
      rawKey18
    );

  const keyId18 =
    `key18-${developer18ShortHash(
      `${safeOwner18}:${Date.now()}:${Math.random()}`
    )}`;

  const normalizedScopes18 =
    uniqueArray(
      ensureArray(
        scopes18
      )
        .map(
          (scope18) =>
            developer18SafeString(
              scope18,
              ""
            )
        )
        .filter(
          (scope18) =>
            DEVELOPER_CONFIG_18
              .supportedScopes
              .includes(
                scope18
              )
        )
    );

  if (
    normalizedScopes18.length ===
    0
  ) {
    normalizedScopes18.push(
      "health:read"
    );
  }

  const key18 = {
    id:
      keyId18,

    ownerId:
      safeOwner18,

    name:
      developer18SafeString(
        name18,
        "TürkAI API Key"
      ).slice(
        0,
        200
      ),

    prefix:
      rawKey18.slice(
        0,
        18
      ),

    hash:
      keyHash18,

    scopes:
      normalizedScopes18,

    requestCount:
      0,

    lastUsedAt:
      null,

    expiresAt:
      expiresAt18
        ? new Date(
            expiresAt18
          ).toISOString()
        : null,

    revokedAt:
      null,

    createdAt:
      nowISO()
  };

  keys18[
    keyId18
  ] =
    key18;

  developer18SaveKeys(
    keys18
  );

  return {
    key:
      rawKey18,

    record:
      key18
  };
}

/* ------------------------------------------------------------
   18.9 - API KEY HASH VALIDATION
------------------------------------------------------------ */

function developer18ExtractApiKey(
  req18
) {
  const header18 =
    developer18SafeString(
      req18.headers?.[
        "x-turkai-api-key"
      ],
      ""
    );

  if (
    header18
  ) {
    return header18;
  }

  const authorization18 =
    developer18SafeString(
      req18.headers?.authorization,
      ""
    );

  if (
    /^Bearer\s+/iu.test(
      authorization18
    )
  ) {
    return authorization18
      .replace(
        /^Bearer\s+/iu,
        ""
      )
      .trim();
  }

  return "";
}

function developer18FindKey(
  rawKey18
) {
  if (
    !rawKey18
  ) {
    return null;
  }

  const hash18 =
    developer18Hash(
      rawKey18
    );

  const keys18 =
    developer18GetKeys();

  for (
    const keyId18 of
    Object.keys(
      keys18
    )
  ) {
    const key18 =
      keys18[
        keyId18
      ];

    if (
      !key18 ||
      key18.revokedAt
    ) {
      continue;
    }

    if (
      key18.expiresAt &&
      new Date(
        key18.expiresAt
      ).getTime() <=
        Date.now()
    ) {
      continue;
    }

    if (
      crypto18.timingSafeEqual(
        Buffer.from(
          String(
            key18.hash
          ),
          "utf8"
        ),
        Buffer.from(
          String(
            hash18
          ),
          "utf8"
        )
      ) &&
      rawKey18.startsWith(
        DEVELOPER_CONFIG_18
          .keyPrefix
      )
    ) {
      return key18;
    }
  }

  return null;
}

/* ------------------------------------------------------------
   18.10 - API KEY RATE LIMIT
------------------------------------------------------------ */

const DEVELOPER_RATE_BUCKETS_18 =
  new Map();

function developer18CheckRate(
  key18
) {
  const now18 =
    Date.now();

  const minute18 =
    Math.floor(
      now18 / 60000
    );

  const bucketId18 =
    `${key18.id}:${minute18}`;

  const current18 =
    DEVELOPER_RATE_BUCKETS_18.get(
      bucketId18
    ) || 0;

  if (
    current18 >=
    DEVELOPER_CONFIG_18
      .keyRatePerMinute
  ) {
    return {
      allowed:
        false,

      limit:
        DEVELOPER_CONFIG_18
          .keyRatePerMinute,

      remaining:
        0,

      resetSeconds:
        60 -
        Math.floor(
          (
            now18 %
            60000
          ) /
          1000
        )
    };
  }

  DEVELOPER_RATE_BUCKETS_18.set(
    bucketId18,
    current18 + 1
  );

  return {
    allowed:
      true,

    limit:
      DEVELOPER_CONFIG_18
        .keyRatePerMinute,

    remaining:
      Math.max(
        0,
        DEVELOPER_CONFIG_18
          .keyRatePerMinute -
          current18 -
          1
      ),

    resetSeconds:
      60 -
      Math.floor(
        (
          now18 %
          60000
        ) /
        1000
      )
  };
}

/* ------------------------------------------------------------
   18.11 - SCOPE CHECK
------------------------------------------------------------ */

function developer18HasScope(
  key18,
  scope18
) {
  if (
    !key18
  ) {
    return false;
  }

  return (
    Array.isArray(
      key18.scopes
    ) &&
    (
      key18.scopes.includes(
        scope18
      ) ||
      key18.scopes.includes(
        "*"
      )
    )
  );
}

/* ------------------------------------------------------------
   18.12 - API KEY REQUEST AUTH
------------------------------------------------------------ */

function developer18Authenticate(
  req18,
  scope18 = null
) {
  const rawKey18 =
    developer18ExtractApiKey(
      req18
    );

  const key18 =
    developer18FindKey(
      rawKey18
    );

  if (
    !key18
  ) {
    return {
      authenticated:
        false,

      error:
        "Geçersiz veya eksik TürkAI API anahtarı."
    };
  }

  const rate18 =
    developer18CheckRate(
      key18
    );

  if (
    !rate18.allowed
  ) {
    return {
      authenticated:
        false,

      rateLimited:
        true,

      rate:
        rate18
    };
  }

  if (
    scope18 &&
    !developer18HasScope(
      key18,
      scope18
    )
  ) {
    return {
      authenticated:
        false,

      forbidden:
        true,

      error:
        `Bu API key için ${scope18} scope'u yok.`
    };
  }

  const keys18 =
    developer18GetKeys();

  key18.requestCount =
    toInteger(
      key18.requestCount,
      0
    ) + 1;

  key18.lastUsedAt =
    nowISO();

  keys18[
    key18.id
  ] =
    key18;

  developer18SaveKeys(
    keys18
  );

  req18.developerApiKey =
    key18;

  return {
    authenticated:
      true,

    key:
      key18,

    rate:
      rate18
  };
}

/* ------------------------------------------------------------
   18.13 - ADMIN AUTH
------------------------------------------------------------ */

const DEVELOPER_MASTER_KEY_18 =
  developer18SafeString(
    process.env.TURKAI_MASTER_KEY,
    ""
  );

function developer18IsPrivileged(
  req18
) {
  const role18 =
    developer18SafeString(
      req18?.user?.role,
      ""
    ).toLowerCase();

  if (
    [
      "admin",
      "developer",
      "owner"
    ].includes(
      role18
    )
  ) {
    return true;
  }

  const supplied18 =
    developer18SafeString(
      req18.headers?.[
        "x-turkai-master-key"
      ],
      ""
    );

  if (
    DEVELOPER_MASTER_KEY_18 &&
    supplied18 &&
    crypto18.timingSafeEqual(
      Buffer.from(
        supplied18
      ),
      Buffer.from(
        DEVELOPER_MASTER_KEY_18
      )
    )
  ) {
    return true;
  }

  return false;
}

function developer18RequireAdmin(
  req18,
  res18
) {
  if (
    developer18IsPrivileged(
      req18
    )
  ) {
    return true;
  }

  res18.status(
    403
  ).json({
    success:
      false,

    error:
      "Developer yönetim yetkisi gerekli."
  });

  return false;
}

