/* ------------------------------------------------------------
   18.15 - WEBHOOK URL SECURITY
------------------------------------------------------------ */

function developer18IsPrivateIPv4(
  address18
) {
  const parts18 =
    address18
      .split(".")
      .map(
        (item18) =>
          Number(
            item18
          )
      );

  if (
    parts18.length !==
    4
  ) {
    return false;
  }

  const [
    a18,
    b18
  ] =
    parts18;

  return (
    a18 ===
      10 ||
    (
      a18 ===
        172 &&
      b18 >=
        16 &&
      b18 <=
        31
    ) ||
    (
      a18 ===
        192 &&
      b18 ===
        168
    ) ||
    a18 ===
      127 ||
    (
      a18 ===
        169 &&
      b18 ===
        254
    ) ||
    (
      a18 ===
        0
    )
  );
}

function developer18IsPrivateIPv6(
  address18
) {
  const lower18 =
    address18
      .toLowerCase();

  return (
    lower18 ===
      "::1" ||
    lower18.startsWith(
      "fc"
    ) ||
    lower18.startsWith(
      "fd"
    ) ||
    lower18.startsWith(
      "fe80:"
    )
  );
}

async function developer18ValidateWebhookURL(
  url18
) {
  let parsed18;

  try {
    parsed18 =
      new URL(
        url18
      );
  } catch (_) {
    throw new Error(
      "Webhook URL geçersiz."
    );
  }

  const protocol18 =
    parsed18.protocol
      .toLowerCase();

  const hostname18 =
    parsed18.hostname
      .toLowerCase();

  const localAllowed18 =
    [
      "localhost",
      "127.0.0.1",
      "::1"
    ].includes(
      hostname18
    );

  if (
    protocol18 !==
      "https:" &&
    !(
      localAllowed18 &&
      protocol18 ===
        "http:"
    )
  ) {
    throw new Error(
      "Webhook URL yalnızca HTTPS olmalıdır. Yerel geliştirme için localhost/127.0.0.1 HTTP kullanılabilir."
    );
  }

  if (
    net18.isIP(
      hostname18
    )
  ) {
    if (
      developer18IsPrivateIPv4(
        hostname18
      ) ||
      developer18IsPrivateIPv6(
        hostname18
      )
    ) {
      if (
        !localAllowed18
      ) {
        throw new Error(
          "Özel/internal IP adreslerine webhook gönderilemez."
        );
      }
    }

    return parsed18;
  }

  /*
   * Alan adını DNS ile çöz ve private IP'lere bağlanmayı engelle.
   */
  try {
    const records18 =
      await dns18.lookup(
        hostname18,
        {
          all:
            true
        }
      );

    for (
      const record18 of
      records18
    ) {
      const address18 =
        record18.address;

      if (
        record18.family ===
        4 &&
        developer18IsPrivateIPv4(
          address18
        )
      ) {
        throw new Error(
          "Webhook alan adı private IPv4 adresine çözülüyor."
        );
      }

      if (
        record18.family ===
        6 &&
        developer18IsPrivateIPv6(
          address18
        )
      ) {
        throw new Error(
          "Webhook alan adı private IPv6 adresine çözülüyor."
        );
      }
    }
  } catch (error18) {
    if (
      error18?.message?.includes(
        "private"
      )
    ) {
      throw error18;
    }

    throw new Error(
      "Webhook alan adı çözümlenemedi."
    );
  }

  return parsed18;
}

/* ------------------------------------------------------------
   18.16 - WEBHOOK CREATION
------------------------------------------------------------ */

async function developer18CreateWebhook({
  ownerId18,
  url18,
  events18 = [],
  secret18 = null,
  name18 = "TürkAI Webhook"
} = {}) {
  const safeOwner18 =
    developer18SafeId(
      ownerId18,
      "developer"
    );

  const webhooks18 =
    developer18GetWebhooks();

  const count18 =
    Object.values(
      webhooks18
    ).filter(
      (webhook18) =>
        webhook18 &&
        webhook18.ownerId ===
          safeOwner18 &&
        webhook18.active
    ).length;

  if (
    count18 >=
    DEVELOPER_CONFIG_18
      .maxWebhooksPerOwner
  ) {
    throw new Error(
      "Maksimum webhook sayısına ulaşıldı."
    );
  }

  const parsed18 =
    await developer18ValidateWebhookURL(
      url18
    );

  const eventList18 =
    uniqueArray(
      ensureArray(
        events18
      )
        .map(
          (event18) =>
            developer18SafeString(
              event18,
              ""
            )
        )
        .filter(Boolean)
        .slice(
          0,
          100
        )
    );

  const webhookId18 =
    `wh18-${developer18ShortHash(
      `${safeOwner18}:${parsed18.href}:${Date.now()}:${Math.random()}`
    )}`;

  const webhookSecret18 =
    developer18SafeString(
      secret18,
      ""
    ) ||
    developer18RandomToken();

  const webhook18 = {
    id:
      webhookId18,

    ownerId:
      safeOwner18,

    name:
      developer18SafeString(
        name18,
        "TürkAI Webhook"
      ).slice(
        0,
        180
      ),

    url:
      parsed18.href,

    secretHash:
      developer18Hash(
        webhookSecret18
      ),

    events:
      eventList18,

    active:
      true,

    successfulDeliveries:
      0,

    failedDeliveries:
      0,

    lastDeliveryAt:
      null,

    lastSuccessAt:
      null,

    lastError:
      null,

    createdAt:
      nowISO(),

    updatedAt:
      nowISO()
  };

  webhooks18[
    webhookId18
  ] =
    webhook18;

  developer18SaveWebhooks(
    webhooks18
  );

  return {
    secret:
      webhookSecret18,

    webhook:
      webhook18
  };
}

/* ------------------------------------------------------------
   18.17 - EVENT STORE
------------------------------------------------------------ */

function developer18GetEvents() {
  return developer18ReadJSON(
    DEVELOPER_EVENT_STORE_18,
    []
  );
}

function developer18SaveEvents(
  events18
) {
  if (
    events18.length >
    DEVELOPER_CONFIG_18
      .maxEvents
  ) {
    events18.splice(
      0,
      events18.length -
        DEVELOPER_CONFIG_18
          .maxEvents
    );
  }

  return developer18WriteJSON(
    DEVELOPER_EVENT_STORE_18,
    events18
  );
}

function developer18StoreEvent(
  event18
) {
  const events18 =
    developer18GetEvents();

  events18.push(
    event18
  );

  developer18SaveEvents(
    events18
  );

  return event18;
}

/* ------------------------------------------------------------
   18.18 - WEBHOOK SIGNATURE
------------------------------------------------------------ */

function developer18WebhookSignature(
  secret18,
  body18
) {
  return crypto18
    .createHmac(
      "sha256",
      secret18
    )
    .update(
      body18,
      "utf8"
    )
    .digest("hex");
}

/* ------------------------------------------------------------
   18.19 - WEBHOOK DELIVERY
------------------------------------------------------------ */

async function developer18DeliverWebhook(
  webhook18,
  event18,
  attempt18 = 1
) {
  if (
    !webhook18 ||
    !webhook18.active
  ) {
    return {
      delivered:
        false,

      skipped:
        true
    };
  }

  let parsed18;

  try {
    parsed18 =
      await developer18ValidateWebhookURL(
        webhook18.url
      );
  } catch (error18) {
    return {
      delivered:
        false,

      error:
        error18.message
    };
  }

  const body18 =
    JSON.stringify(
      {
        id:
          event18.id,

        event:
          event18.event,

        timestamp:
          event18.timestamp,

        data:
          event18.data
      }
    );

  const webhooks18 =
    developer18GetWebhooks();

  const secretAvailable18 =
    Boolean(
      webhook18.secretHash
    );

  /*
   * Secret'in kendisi store edilmediği için gerçek imza üretimi,
   * event gönderimi sırasında yeniden üretilemez.
   *
   * Bu nedenle bu sistem webhook kaydı oluşturulurken yalnızca
   * secret'ın hash'ini saklar ve secret response dışında
   * tekrar gösterilmez.
   *
   * Delivery için webhook secret'ın encrypted runtime cache
   * içinden gelmesi beklenir. Yoksa unsigned payload gönderilir.
   */

  let signature18 =
    null;

  const runtimeSecrets18 =
    globalThis
      .turkAIWebhookRuntimeSecrets18 || {};

  const runtimeSecret18 =
    runtimeSecrets18[
      webhook18.id
    ];

  if (
    runtimeSecret18
  ) {
    signature18 =
      developer18WebhookSignature(
        runtimeSecret18,
        body18
      );
  }

  const controller18 =
    new AbortController();

  const timer18 =
    setTimeout(
      () =>
        controller18.abort(),
      DEVELOPER_CONFIG_18
        .webhookTimeoutMs
    );

  try {
    const response18 =
      await fetch(
        parsed18.href,
        {
          method:
            "POST",

          redirect:
            "manual",

          headers: {
            "content-type":
              "application/json",

            "user-agent":
              "TurkAI-Webhook/18.0",

            "x-turkai-event-id":
              event18.id,

            "x-turkai-event":
              event18.event,

            ...(signature18
              ? {
                  "x-turkai-signature":
                    signature18
                }
              : {})
          },

          body:
            body18,

          signal:
            controller18.signal
        }
      );

    const rawResponse18 =
      await response18.text();

    const success18 =
      response18.status >=
        200 &&
      response18.status <
        300;

    const current18 =
      webhooks18[
        webhook18.id
      ];

    if (
      current18
    ) {
      current18.lastDeliveryAt =
        nowISO();

      if (
        success18
      ) {
        current18.successfulDeliveries +=
          1;

        current18.lastSuccessAt =
          nowISO();

        current18.lastError =
          null;
      } else {
        current18.failedDeliveries +=
          1;

        current18.lastError =
          `HTTP ${response18.status}: ${rawResponse18.slice(
            0,
            DEVELOPER_CONFIG_18
              .maxWebhookResponseChars
          )}`;
      }

      current18.updatedAt =
        nowISO();

      developer18SaveWebhooks(
        webhooks18
      );
    }

    if (
      !success18 &&
      attempt18 <
        DEVELOPER_CONFIG_18
          .webhookRetries
    ) {
      await new Promise(
        (resolve18) =>
          setTimeout(
            resolve18,
            attempt18 *
              750
          )
      );

      return developer18DeliverWebhook(
        current18 ||
          webhook18,
        event18,
        attempt18 +
          1
      );
    }

    return {
      delivered:
        success18,

      status:
        response18.status,

      response:
        rawResponse18.slice(
          0,
          DEVELOPER_CONFIG_18
            .maxWebhookResponseChars
        ),

      attempt:
        attempt18
    };
  } catch (error18) {
    const current18 =
      webhooks18[
        webhook18.id
      ];

    if (
      current18
    ) {
      current18.failedDeliveries +=
        1;

      current18.lastDeliveryAt =
        nowISO();

      current18.lastError =
        error18?.message ||
        String(
          error18
        );

      current18.updatedAt =
        nowISO();

      developer18SaveWebhooks(
        webhooks18
      );
    }

    if (
      attempt18 <
      DEVELOPER_CONFIG_18
        .webhookRetries
    ) {
      await new Promise(
        (resolve18) =>
          setTimeout(
            resolve18,
            attempt18 *
              750
          )
      );

      return developer18DeliverWebhook(
        current18 ||
          webhook18,
        event18,
        attempt18 +
          1
      );
    }

    return {
      delivered:
        false,

      error:
        error18?.message ||
        String(
          error18
        ),

      attempt:
        attempt18
    };
  } finally {
    clearTimeout(
      timer18
    );
  }
}

/* ------------------------------------------------------------
   18.20 - WEBHOOK EVENT DISPATCH
------------------------------------------------------------ */

async function developer18EmitEvent({
  event18,
  data18 = {},
  source18 = "turkai",
  ownerId18 = null
} = {}) {
  const normalizedEvent18 =
    developer18SafeString(
      event18,
      "system.event"
    );

  let cleanData18 =
    isObject(
      data18
    )
      ? clone(
          data18
        )
      : {};

  try {
    const bytes18 =
      Buffer.byteLength(
        JSON.stringify(
          cleanData18
        ),
        "utf8"
      );

    if (
      bytes18 >
      DEVELOPER_CONFIG_18
        .maxEventPayloadBytes
    ) {
      cleanData18 = {
        truncated:
          true
      };
    }
  } catch (_) {
    cleanData18 = {};
  }

  const eventRecord18 = {
    id:
      `dev-event-${developer18ShortHash(
        `${normalizedEvent18}:${Date.now()}:${Math.random()}`
      )}`,

    event:
      normalizedEvent18,

    source:
      developer18SafeString(
        source18,
        "turkai"
      ).slice(
        0,
        120
      ),

    ownerId:
      ownerId18
        ? developer18SafeId(
            ownerId18
          )
        : null,

    timestamp:
      nowISO(),

    data:
      cleanData18
  };

  developer18StoreEvent(
    eventRecord18
  );

  const webhooks18 =
    developer18GetWebhooks();

  const matched18 =
    Object.values(
      webhooks18
    ).filter(
      (webhook18) => {
        if (
          !webhook18 ||
          !webhook18.active
        ) {
          return false;
        }

        if (
          ownerId18 &&
          webhook18.ownerId !==
            developer18SafeId(
              ownerId18
            )
        ) {
          return false;
        }

        if (
          !Array.isArray(
            webhook18.events
          )
        ) {
          return false;
        }

        return (
          webhook18.events.includes(
            "*"
          ) ||
          webhook18.events.includes(
            normalizedEvent18
          )
        );
      }
    );

  const deliveries18 =
    await Promise.all(
      matched18.map(
        async (
          webhook18
        ) => ({
          webhookId:
            webhook18.id,

          ...(await developer18DeliverWebhook(
            webhook18,
            eventRecord18
          ))
        })
      )
    );

  return {
    success:
      true,

    event:
      eventRecord18,

    matchedWebhooks:
      matched18.length,

    deliveries:
      deliveries18
  };
}

/* ------------------------------------------------------------
   18.21 - BRIDGE EVENT BUS 14 -> WEBHOOKS
------------------------------------------------------------ */

if (
  typeof TURKAI_EVENT_BUS_14 !==
  "undefined"
) {
  TURKAI_EVENT_BUS_14.on(
    "event",
    (
      event18
    ) => {
      developer18EmitEvent({
        event18:
          event18?.name ||
          "turkai.event",

        data18:
          event18?.payload ||
          {},

        source18:
          "event-bus-14",

        ownerId18:
          event18?.payload?.userId ||
          null
      }).catch(
        (error18) => {
          try {
            systemLog?.(
              "developer18_webhook_bridge_error",
              {
                error:
                  error18?.message ||
                  String(
                    error18
                  )
              }
            );
          } catch (_) {}
        }
      );
    }
  );
}

/* ------------------------------------------------------------
   18.22 - USAGE STORE
------------------------------------------------------------ */

function developer18GetUsage() {
  return developer18ReadJSON(
    DEVELOPER_USAGE_STORE_18,
    {}
  );
}

function developer18SaveUsage(
  usage18
) {
  return developer18WriteJSON(
    DEVELOPER_USAGE_STORE_18,
    usage18
  );
}

function developer18RecordUsage({
  key18,
  route18,
  status18,
  durationMs18
}) {
  if (
    !key18
  ) {
    return;
  }

  const usage18 =
    developer18GetUsage();

  const day18 =
    todayKey();

  if (
    !usage18[
      day18
    ]
  ) {
    usage18[
      day18
    ] = {};
  }

  const bucketKey18 =
    `${key18.id}:${route18}`;

  if (
    !usage18[
      day18
    ][
      bucketKey18
    ]
  ) {
    usage18[
      day18
    ][
      bucketKey18
    ] = {
      keyId:
        key18.id,

      route:
        route18,

      requests:
        0,

      success:
        0,

      errors:
        0,

      totalDurationMs:
        0,

      lastAt:
        null
    };
  }

  const bucket18 =
    usage18[
      day18
    ][
      bucketKey18
    ];

  bucket18.requests +=
    1;

  bucket18.totalDurationMs +=
    toNumber(
      durationMs18,
      0
    );

  bucket18.lastAt =
    nowISO();

  if (
    status18 >=
      200 &&
    status18 <
      400
  ) {
    bucket18.success +=
      1;
  } else {
    bucket18.errors +=
      1;
  }

  /*
   * Günleri sınırlı tut.
   */
  const days18 =
    Object.keys(
      usage18
    );

  if (
    days18.length >
    90
  ) {
    days18
      .sort()
      .slice(
        0,
        days18.length -
          90
      )
      .forEach(
        (
          oldDay18
        ) =>
          delete usage18[
            oldDay18
          ]
      );
  }

  developer18SaveUsage(
    usage18
  );
}

