/* ------------------------------------------------------------
   18.31 - WEBHOOK UPDATE
------------------------------------------------------------ */

app.put(
  "/api/developer/webhooks/:webhookId",
  async (
    req18,
    res18
  ) => {
    try {
      if (
        !developer18RequireAdmin(
          req18,
          res18
        )
      ) {
        return;
      }

      const webhooks18 =
        developer18GetWebhooks();

      const webhookId18 =
        developer18SafeId(
          req18.params.webhookId
        );

      const webhook18 =
        webhooks18[
          webhookId18
        ];

      if (
        !webhook18
      ) {
        return developer18Error(
          res18,
          404,
          "Webhook bulunamadı."
        );
      }

      const body18 =
        req18.body ||
        {};

      if (
        Object.prototype.hasOwnProperty.call(
          body18,
          "url"
        )
      ) {
        const parsed18 =
          await developer18ValidateWebhookURL(
            body18.url
          );

        webhook18.url =
          parsed18.href;
      }

      if (
        Array.isArray(
          body18.events
        )
      ) {
        webhook18.events =
          uniqueArray(
            body18.events
              .map(
                (event18) =>
                  developer18SafeString(
                    event18,
                    ""
                  )
              )
              .filter(Boolean)
          ).slice(
            0,
            100
          );
      }

      if (
        Object.prototype.hasOwnProperty.call(
          body18,
          "name"
        )
      ) {
        webhook18.name =
          developer18SafeString(
            body18.name,
            webhook18.name
          ).slice(
            0,
            180
          );
      }

      if (
        Object.prototype.hasOwnProperty.call(
          body18,
          "active"
        )
      ) {
        webhook18.active =
          Boolean(
            body18.active
          );
      }

      webhook18.updatedAt =
        nowISO();

      webhooks18[
        webhookId18
      ] =
        webhook18;

      developer18SaveWebhooks(
        webhooks18
      );

      res18.json({
        success:
          true,

        webhook:
          webhook18
      });
    } catch (error18) {
      developer18Error(
        res18,
        400,
        error18.message
      );
    }
  }
);

