/* ------------------------------------------------------------
   18.35 - DEVELOPER USAGE
------------------------------------------------------------ */

app.get(
  "/api/developer/usage",
  (req18, res18) => {
    if (
      !developer18RequireAdmin(
        req18,
        res18
      )
    ) {
      return;
    }

    try {
      const usage18 =
        developer18GetUsage();

      const ownerId18 =
        developer18SafeId(
          req18.query.ownerId ||
          req18.user?.id ||
          "developer"
        );

      const filtered18 =
        {};

      for (
        const day18 of
        Object.keys(
          usage18
        )
      ) {
        const buckets18 =
          usage18[
            day18
          ] || {};

        const dayResult18 =
          {};

        for (
          const bucketId18 of
          Object.keys(
            buckets18
          )
        ) {
          const bucket18 =
            buckets18[
              bucketId18
            ];

          const keys18 =
            developer18GetKeys();

          const key18 =
            keys18[
              bucket18.keyId
            ];

          if (
            key18 &&
            key18.ownerId ===
              ownerId18
          ) {
            dayResult18[
              bucketId18
            ] =
              bucket18;
          }
        }

        if (
          Object.keys(
            dayResult18
          ).length >
          0
        ) {
          filtered18[
            day18
          ] =
            dayResult18;
        }
      }

      res18.json({
        success:
          true,

        ownerId:
          ownerId18,

        usage:
          filtered18,

        stats:
          developer18GetStats()
      });
    } catch (error18) {
      developer18Error(
        res18,
        500,
        error18.message
      );
    }
  }
);

/* ------------------------------------------------------------
   18.36 - DEVELOPER EVENT HISTORY
------------------------------------------------------------ */

app.get(
  "/api/developer/events",
  (req18, res18) => {
    try {
      if (
        !developer18RequireAdmin(
          req18,
          res18
        )
      ) {
        return;
      }

      let events18 =
        developer18GetEvents();

      if (
        req18.query.event
      ) {
        const eventName18 =
          developer18SafeString(
            req18.query.event,
            ""
          );

        events18 =
          events18.filter(
            (
              item18
            ) =>
              item18.event ===
              eventName18
          );
      }

      const ownerId18 =
        req18.query.ownerId
          ? developer18SafeId(
              req18.query.ownerId
            )
          : null;

      if (
        ownerId18
      ) {
        events18 =
          events18.filter(
            (
              item18
            ) =>
              item18.ownerId ===
              ownerId18
          );
      }

      events18.sort(
        (
          a18,
          b18
        ) =>
          String(
            b18.timestamp ||
            ""
          ).localeCompare(
            String(
              a18.timestamp ||
              ""
            )
          )
      );

      const limit18 =
        clamp(
          toInteger(
            req18.query.limit,
            100
          ),
          1,
          1000
        );

      res18.json({
        success:
          true,

        items:
          events18.slice(
            0,
            limit18
          ),

        total:
          events18.length
      });
    } catch (error18) {
      developer18Error(
        res18,
        500,
        error18.message
      );
    }
  }
);

