/* ============================================================
   19.10 STARTUP / READINESS CHECK
   ============================================================ */

function turkai19RunStartupCheck() {
  const modules19 =
    turkai19BuildModuleHealth();

  const availableCount19 =
    modules19.filter(
      (item19) => item19.available
    ).length;

  const expectedCount19 =
    modules19.length;

  const directories19 =
    turkai19BuildConfigDiagnostics()
      .filesystem;

  const essentialDirectories19 =
    [
      directories19.dataDir,
      directories19.configDir,
      directories19.uploadDir,
      directories19.mediaDir,
      directories19.logDir
    ];

  const filesystemOkay19 =
    essentialDirectories19.every(Boolean);

  /*
    Part 19, tüm modüllerin varlığını fatal hata saymaz.
    Bazı modüller konfigurasyona göre bilinçli olarak kapalı olabilir.
  */
  const degraded19 =
    !filesystemOkay19 ||
    availableCount19 === 0;

  const result19 = {
    ok: true,
    ready: !degraded19,
    degraded: degraded19,
    timestamp: nowISO(),
    part: 19,
    serverVersion:
      typeof SERVER_VERSION !== "undefined"
        ? SERVER_VERSION
        : "40.0.0",
    moduleCount: expectedCount19,
    availableModules: availableCount19,
    filesystemOkay: filesystemOkay19,
    modules: modules19,
    config: turkai19BuildConfigDiagnostics()
  };

  turkaiIntegrationState19.startupChecks++;
  turkaiIntegrationState19.lastHealthCheck =
    result19.timestamp;
  turkaiIntegrationState19.degraded =
    result19.degraded;

  turkaiIntegrationPersistState19();

  return result19;
}

const TURKAI_STARTUP_CHECK_19 =
  turkai19RunStartupCheck();


/* ============================================================
   19.11 SYSTEM HEALTH AGGREGATOR
   ============================================================ */

function turkai19SystemHealth() {
  let uptime19 = 0;

  try {
    uptime19 = process.uptime();
  } catch {
    uptime19 = 0;
  }

  let memory19 = {};

  try {
    memory19 = process.memoryUsage();
  } catch {
    memory19 = {};
  }

  let load19 = [];

  try {
    load19 = os19.loadavg();
  } catch {
    load19 = [];
  }

  const health19 =
    turkai19RunStartupCheck();

  return {
    status:
      health19.ready
        ? "ready"
        : "degraded",

    ok: true,

    server: {
      name:
        typeof SERVER_NAME !== "undefined"
          ? SERVER_NAME
          : "TürkAI Master Server",

      version:
        typeof SERVER_VERSION !== "undefined"
          ? SERVER_VERSION
          : "40.0.0",

      pid: process.pid,
      uptimeSeconds: uptime19,
      node: process.version,
      platform: process.platform,
      architecture: process.arch,
      timestamp: nowISO()
    },

    runtime: {
      rss: memory19.rss || 0,
      heapTotal: memory19.heapTotal || 0,
      heapUsed: memory19.heapUsed || 0,
      external: memory19.external || 0,
      arrayBuffers: memory19.arrayBuffers || 0,
      loadAverage: load19
    },

    integration: {
      ...turkaiIntegrationState19
    },

    modules: health19.modules,

    filesystem: health19.config.filesystem,

    providers: health19.config.configuredProviders
  };
}


