/* ============================================================
   19.13 ROUTE CATALOG
   ============================================================ */

function turkai19CollectRoutes() {
  const stack19 =
    turkai19GetRouterStack();

  const routes19 = [];

  for (const layer19 of stack19) {
    if (!turkai19IsRouteLayer(layer19)) {
      continue;
    }

    const route19 = layer19.route;

    const methods19 =
      route19.methods
        ? Object.keys(route19.methods)
          .filter(
            (method19) =>
              route19.methods[method19]
          )
          .map(
            (method19) =>
              method19.toUpperCase()
          )
        : [];

    routes19.push({
      path:
        typeof route19.path === "string"
          ? route19.path
          : String(route19.path),

      methods: methods19
    });
  }

  return routes19;
}

const TURKAI_ROUTE_COUNT_19 =
  turkai19CollectRoutes().length;


