/* ============================================================
   20.9 GRACEFUL SHUTDOWN WRAPPER
   ============================================================ */

async function turkai20Shutdown(
  reason20 = "unknown"
) {
  if (
    TURKAI_SHUTDOWN_STARTED_20
  ) {
    return false;
  }

  TURKAI_SHUTDOWN_STARTED_20 =
    true;

  try {
    TURKAI_STARTUP_RESULT_20.shutdownStartedAt =
      nowISO();

    TURKAI_STARTUP_RESULT_20.shutdownReason =
      reason20;
  } catch {}

  try {
    turkai20EmitStartupEvent(
      "server:shutdown:start",
      {
        reason:
          reason20,
        pid:
          process.pid,
        timestamp:
          nowISO()
      }
    );
  } catch {}

  /*
    Part 19 shutdown engine'i varsa onu kullan.
  */
  try {
    if (
      typeof turkai19GracefulShutdown ===
      "function"
    ) {
      await turkai19GracefulShutdown(
        reason20
      );
    } else {
      try {
        if (
          typeof io !== "undefined" &&
          io &&
          typeof io.close ===
            "function"
        ) {
          await new Promise(
            (resolve20) => {
              try {
                io.close(
                  () => resolve20()
                );
              } catch {
                resolve20();
              }

              setTimeout(
                resolve20,
                1000
              );
            }
          );
        }
      } catch {}

      try {
        if (
          httpServer &&
          typeof httpServer.close ===
            "function"
        ) {
          await new Promise(
            (resolve20) => {
              try {
                httpServer.close(
                  () => resolve20()
                );
              } catch {
                resolve20();
              }

              setTimeout(
                resolve20,
                3000
              );
            }
          );
        }
      } catch {}
    }
  } catch (error20) {
    console.warn(
      "[PART20] Graceful shutdown warning:",
      error20.message
    );
  }

  try {
    turkai20EmitStartupEvent(
      "server:shutdown:complete",
      {
        reason:
          reason20,
        timestamp:
          nowISO()
      }
    );
  } catch {}

  /*
    Signal ile kapanıyorsa process'i sonlandır.
  */
  if (
    reason20 === "SIGTERM" ||
    reason20 === "SIGINT" ||
    reason20 === "SIGQUIT"
  ) {
    setTimeout(
      () => {
        process.exit(0);
      },
      100
    ).unref?.();
  }

  return true;
}


/* ============================================================
   20.10 PROCESS SIGNALS
   ============================================================ */

try {
  process.on(
    "SIGTERM",
    () => {
      turkai20Shutdown(
        "SIGTERM"
      ).catch(() => {
        process.exit(1);
      });
    }
  );
} catch {}

try {
  process.on(
    "SIGINT",
    () => {
      turkai20Shutdown(
        "SIGINT"
      ).catch(() => {
        process.exit(1);
      });
    }
  );
} catch {}

try {
  process.on(
    "SIGQUIT",
    () => {
      turkai20Shutdown(
        "SIGQUIT"
      ).catch(() => {
        process.exit(1);
      });
    }
  );
} catch {}


/* ============================================================
   20.11 FINAL HTTP SERVER ERROR
   ============================================================ */

let turkai20ServerErrorHandled = false;

try {
  if (
    httpServer &&
    typeof httpServer.once ===
      "function"
  ) {
    httpServer.once(
      "error",
      (error20) => {
        turkai20ServerErrorHandled =
          true;

        TURKAI_STARTUP_RESULT_20 = {
          ...TURKAI_STARTUP_RESULT_20,

          ok: false,

          listening: false,

          error: {
            code:
              error20?.code ||
              "SERVER_ERROR",

            message:
              error20?.message ||
              String(error20)
          },

          timestamp:
            nowISO()
        };

        try {
          systemLog(
            "PART20_SERVER_ERROR",
            {
              code:
                error20?.code ||
                null,

              message:
                error20?.message ||
                String(error20)
            }
          );
        } catch {}

        /*
          Render / production ortamında adres kullanım hatası
          varsa process'in yanlış durumda çalışmasını engelliyoruz.
        */
        if (
          error20?.code ===
            "EADDRINUSE" ||
          error20?.code ===
            "EACCES"
        ) {
          setTimeout(
            () => {
              process.exit(1);
            },
            50
          );
        }
      }
    );
  }
} catch (error20) {
  console.warn(
    "[PART20] Server error listener failed:",
    error20.message
  );
}


/* ============================================================
   20.12 FINAL LISTEN FUNCTION
   ============================================================ */

function turkai20StartServer() {
  if (
    TURKAI_SERVER_STARTED_20 ||
    TURKAI_SERVER_STARTING_20
  ) {
    return false;
  }

  TURKAI_SERVER_STARTING_20 =
    true;

  TURKAI_STARTUP_RESULT_20 = {
    ...TURKAI_STARTUP_RESULT_20,

    ok: true,

    listening: false,

    port:
      TURKAI_STARTUP_PORT_20,

    host:
      TURKAI_STARTUP_HOST_20,

    environment:
      TURKAI_STARTUP_ENV_20,

    startingAt:
      nowISO(),

    timestamp:
      nowISO()
  };

  try {
    httpServer.listen(
      TURKAI_STARTUP_PORT_20,
      TURKAI_STARTUP_HOST_20,
      () => {
        TURKAI_SERVER_STARTING_20 =
          false;

        TURKAI_SERVER_STARTED_20 =
          true;

        const address20 =
          typeof httpServer.address ===
          "function"
            ? httpServer.address()
            : null;

        TURKAI_STARTUP_RESULT_20 = {
          ...TURKAI_STARTUP_RESULT_20,

          ok: true,

          listening: true,

          address:
            address20,

          timestamp:
            nowISO(),

          readyAt:
            nowISO()
        };

        try {
          if (
            serverState?.startup
          ) {
            serverState.startup.listening =
              true;

            serverState.startup.address =
              address20;
          }
        } catch {}

        /*
          Konsolda temiz ve anlaşılır startup mesajları.
        */
        console.log(
          "\n=================================================="
        );

        console.log(
          "            TÜRKAI MASTER SERVER 40.0"
        );

        console.log(
          "=================================================="
        );

        console.log(
          `Server : ${
            typeof SERVER_NAME !==
            "undefined"
              ? SERVER_NAME
              : "TürkAI Master Server"
          }`
        );

        console.log(
          `Version: ${
            typeof SERVER_VERSION !==
            "undefined"
              ? SERVER_VERSION
              : "40.0.0"
          }`
        );

        console.log(
          `Host   : ${TURKAI_STARTUP_HOST_20}`
        );

        console.log(
          `Port   : ${TURKAI_STARTUP_PORT_20}`
        );

        console.log(
          `Env    : ${TURKAI_STARTUP_ENV_20}`
        );

        console.log(
          `URL    : http://localhost:${TURKAI_STARTUP_PORT_20}`
        );

        console.log(
          `API    : http://localhost:${TURKAI_STARTUP_PORT_20}/api`
        );

        console.log(
          `Health : http://localhost:${TURKAI_STARTUP_PORT_20}/api/system/health`
        );

        console.log(
          "Status : READY"
        );

        console.log(
          "==================================================\n"
        );

        try {
          systemLog(
            "PART20_SERVER_READY",
            {
              version:
                typeof SERVER_VERSION !==
                "undefined"
                  ? SERVER_VERSION
                  : "40.0.0",

              host:
                TURKAI_STARTUP_HOST_20,

              port:
                TURKAI_STARTUP_PORT_20,

              environment:
                TURKAI_STARTUP_ENV_20,

              address:
                address20,

              routeCount:
                typeof turkai19CollectRoutes ===
                "function"
                  ? turkai19CollectRoutes()
                    .length
                  : null,

              timestamp:
                nowISO()
            }
          );
        } catch {}

        try {
          turkai20EmitStartupEvent(
            "server:ready",
            {
              version:
                typeof SERVER_VERSION !==
                "undefined"
                  ? SERVER_VERSION
                  : "40.0.0",

              host:
                TURKAI_STARTUP_HOST_20,

              port:
                TURKAI_STARTUP_PORT_20,

              address:
                address20,

              timestamp:
                nowISO()
            }
          );
        } catch {}

        try {
          if (
            typeof turkaiIntegrationPersistState19 ===
            "function"
          ) {
            turkaiIntegrationPersistState19();
          }
        } catch {}
      }
    );

    return true;
  } catch (error20) {
    TURKAI_SERVER_STARTING_20 =
      false;

    TURKAI_STARTUP_RESULT_20 = {
      ...TURKAI_STARTUP_RESULT_20,

      ok: false,

      listening: false,

      error: {
        code:
          error20?.code ||
          "LISTEN_FAILED",

        message:
          error20?.message ||
          String(error20)
      },

      timestamp:
        nowISO()
    };

    console.error(
      "[PART20] Server start failed:",
      error20
    );

    return false;
  }
}


